bool RejectInvalidTeleportItemCount(CCreature*, const ItemManip*) { return false; }

bool IsTransferSkillMatched(InfectedSkillType& infectedSkill, AbnormalStatusSlotType abnormalType) {
    // Current L2Server 0x00b055c4.
    L2_GUARD_FUNCTION();
    return infectedSkill.m_pChannellingSkillInfo == nullptr &&
        (infectedSkill.pSkillInfo->m_nSpecialLevel >= 0 || infectedSkill.pSkillInfo->m_nSpecialLevel < -4) &&
        infectedSkill.pSkillInfo->m_nAbnormalType == abnormalType;
}

bool IsInfectedSkillMatched(InfectedSkillType& infectedSkill, const int slotGroup) {
    // Current L2Server 0x00b05680.
    L2_GUARD_FUNCTION();
    if (infectedSkill.m_pChannellingSkillInfo != nullptr ||
        (infectedSkill.pSkillInfo->m_nSpecialLevel < 0 && infectedSkill.pSkillInfo->m_nSpecialLevel >= -4)) {
        return false;
    }

    const DebuffType debuff = infectedSkill.pSkillInfo->m_eDebuff;
    return (debuff == DB_GOOD && (slotGroup == 0 || slotGroup == 2)) ||
        ((debuff == DB_BAD || debuff == DB_PHYSICAL_MES) && (slotGroup == 1 || slotGroup == 2));
}

std::int32_t AddUserMapDensityOffset(std::int32_t value, std::uint32_t offset) noexcept {
    const std::uint32_t bits = static_cast<std::uint32_t>(value) + offset;
    std::int32_t result = 0;
    std::memcpy(&result, &bits, sizeof(result));
    return result;
}

std::int32_t UserMapDensityIndex(const FVector& position) noexcept {
    const std::int32_t x = AddUserMapDensityOffset(runtime::Win64CvttDoubleToInt32(position.x), 0x50000U) / 0x800;
    const std::int32_t y = AddUserMapDensityOffset(runtime::Win64CvttDoubleToInt32(position.y), 0x40000U) / 0x800;
    const std::uint32_t index = static_cast<std::uint32_t>(y) * 0x140U + static_cast<std::uint32_t>(x);
    std::int32_t result = 0;
    std::memcpy(&result, &index, sizeof(result));
    return result;
}

