const wchar_t* PrivateStoreAccountName(const std::array<char16_t, 15>& source, std::array<wchar_t, 16>& storage) {
#if defined(_WIN32)
    static_cast<void>(storage);
    return reinterpret_cast<const wchar_t*>(source.data());
#else
    std::size_t length = 0;
    while (length < source.size() && source[length] != u'\0') {
        ++length;
    }
    const std::wstring converted = ::Utf16ToWide(std::u16string_view(source.data(), length));
    const std::size_t copyLength = std::min(converted.size(), storage.size() - 1U);
    std::copy_n(converted.data(), copyLength, storage.data());
    storage[copyLength] = L'\0';
    return storage.data();
#endif
}

const wchar_t* PrivateStoreLogText(const char16_t* source, std::size_t capacity, std::array<wchar_t, 30>& storage) {
#if defined(_WIN32)
    static_cast<void>(capacity);
    static_cast<void>(storage);
    return reinterpret_cast<const wchar_t*>(source);
#else
    std::size_t length = 0;
    while (length < capacity && source[length] != u'\0') {
        ++length;
    }
    const std::wstring converted = ::Utf16ToWide(std::u16string_view(source, length));
    const std::size_t copyLength = std::min(converted.size(), storage.size() - 1U);
    std::copy_n(converted.data(), copyLength, storage.data());
    storage[copyLength] = L'\0';
    return storage.data();
#endif
}

void DeletePrivateStoreEntries(User::PrivateStoreMap& store) {
    for (auto& entry : store) {
        delete entry.second;
    }
    store.clear();
}

void AppendPrivateStoreClassLog(std::wstring& output, int classId) {
    // Current SetPrivateStoreList/SetPrivateStoreBuyList call the physical
    // Shared IntToXStr owner before applying the strict 200-code-unit cap.
    const std::wstring value = ::Utf16ToWide(::IntToXStr(classId));
    if (output.size() + value.size() < 200U) {
        output.append(value);
        output.push_back(L',');
    }
}

void FormatBotReportAddress(const std::uint32_t address, std::array<char16_t, 20>& output) {
    FormatUtf16To(
        output.data(), output.size(), u"%u.%u.%u.%u", address & 0xffU, (address >> 8U) & 0xffU, (address >> 16U) & 0xffU,
        (address >> 24U) & 0xffU
    );
}

void CopyBotReportPledgeName(CPledge* pledge, std::array<char16_t, 24>& output) {
    if (pledge == nullptr || pledge->GetPledgeName() == nullptr) {
        output[0] = u'\0';
        return;
    }
    std::u16string_view(pledge->GetPledgeName()).copy(output.data(), output.size() - 1U);
    output.back() = u'\0';
}


const void* DoubleBitsAsPointer(double value) noexcept {
    std::uint64_t bits = 0;
    static_assert(sizeof(bits) == sizeof(value));
    std::memcpy(&bits, &value, sizeof(bits));
    return reinterpret_cast<const void*>(static_cast<std::uintptr_t>(bits));
}


#if !defined(_WIN32)
void CopyHostWideToTargetUserName(const wchar_t* source, char16_t* destination, std::size_t maximumCodeUnits) noexcept {
    std::size_t output = 0;
    for (std::size_t input = 0; output < maximumCodeUnits && source[input] != L'\0'; ++input) {
        const std::uint32_t codePoint = static_cast<std::uint32_t>(source[input]);
        if (codePoint <= 0xffffU) {
            destination[output++] = static_cast<char16_t>(codePoint);
            continue;
        }
        if (codePoint <= 0x10ffffU) {
            const std::uint32_t surrogateValue = codePoint - 0x10000U;
            destination[output++] = static_cast<char16_t>(0xd800U + (surrogateValue >> 10U));
            if (output < maximumCodeUnits) {
                destination[output++] = static_cast<char16_t>(0xdc00U + (surrogateValue & 0x3ffU));
            }
            continue;
        }
        destination[output++] = u'\ufffd';
    }
    destination[output] = u'\0';
}


#endif

