CUserReleaseVerifier::CUserReleaseVerifier(User* const user, const wchar_t* const guardString) :
    CCreatureReleaseVerifier(static_cast<CCreature*>(user)), m_pUser(user), m_guardStr(guardString) {
    // Current L2Server 0x00b1bd2c.
    L2_GUARD_FUNCTION();
    L2_ADD_REF(m_pUser, ObjectRefType::VerifierRetain);
    AddTimer(20000, 0);
    L2_RELEASE(this, ObjectRefType::CreateDelete);
}

void CUserReleaseVerifier::TimerExpired(int) {
    // Current L2Server 0x00b1bdcc.
    L2_GUARD_FUNCTION();
    const std::uint32_t accountId = m_pUser->GetAccountID();
    const std::uint32_t databaseId = m_pUser->GetDBID();
    const std::uint32_t serverId = m_pUser->GetServerId();
    const std::int32_t initialRefCount = m_pUser->RefCount();
    std::array<char16_t, 28> who{};
    static_cast<void>(FormatUtf16To(who.data(), who.size(), u"%ls", m_pUser->GetName()));

    // Log.Add(
    //     LOG_ERROR,
    //     L"[NO_ERROR] TID[%d] File[%s] Line[%d], AccountId [%d], "
    //     L"Who[%s]. DBID[%d], ServerID[%d], Ref count[%d], "
    //     L"LastSkillId=[%d]",
    //     CThreadManager::GetThreadID(),
    //     L"User.cpp",
    //     0x11ff,
    //     runtime::Int32FromBits(accountId),
    //     who.data(),
    //     runtime::Int32FromBits(databaseId),
    //     runtime::Int32FromBits(serverId),
    //     initialRefCount,
    //     m_pUser->m_nLastSkillId)
    // L2_LOG_ERROR(Log,
    //     L"[NO_ERROR] TID[%d] File[%s] Line[%d], AccountId [%d], "
    //     L"Who[%s]. DBID[%d], ServerID[%d], Ref count[%d], "
    //     L"LastSkillId=[%d]",
    //     CThreadManager::GetThreadID(),
    //     L"User.cpp",
    //     0x11ff,
    //     runtime::Int32FromBits(accountId),
    //     who.data(),
    //     runtime::Int32FromBits(databaseId),
    //     runtime::Int32FromBits(serverId),
    //     initialRefCount,
    //     m_pUser->m_nLastSkillId)
    L2_LOG_DEBUG(
        Log,
        "[user lifetime] Checking release of character %u, object %u: "
        "%d references before releasing the verifier reference; last skill %d.",
        static_cast<unsigned int>(databaseId), static_cast<unsigned int>(serverId), initialRefCount, m_pUser->m_nLastSkillId
    );

    const std::int32_t remaining = L2_RELEASE(m_pUser, ObjectRefType::VerifierRetain);
    if (remaining < 1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] User Release Success!. AccountId [%d], "
        //     L"Who[%s], DBID[%d], ServerID[%d]",
        //     L"User.cpp",
        //     0x121c,
        //     runtime::Int32FromBits(accountId),
        //     who.data(),
        //     runtime::Int32FromBits(databaseId),
        //     runtime::Int32FromBits(serverId))
        // L2_LOG_ERROR(Log,
        //     L"[%s][%d] User Release Success!. AccountId [%d], "
        //     L"Who[%s], DBID[%d], ServerID[%d]",
        //     L"User.cpp",
        //     0x121c,
        //     runtime::Int32FromBits(accountId),
        //     who.data(),
        //     runtime::Int32FromBits(databaseId),
        //     runtime::Int32FromBits(serverId))
        L2_LOG_DEBUG(
            Log,
            "[user lifetime] Released verifier reference for character %u, "
            "object %u; remaining references %d.",
            static_cast<unsigned int>(databaseId), static_cast<unsigned int>(serverId), remaining
        );
        return;
    }

    std::int32_t expectedRefCount = initialRefCount - 1;
    for (;;) {
        const std::int32_t cachedReferences =
            m_pUser->m_RefHelpers.m_RefData[static_cast<std::size_t>(ObjectRefType::Cached)].m_nRefCount.load(
                std::memory_order_relaxed
            );
        if (cachedReferences < 1) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] ORT - User Release failed. AccountId [%d], "
            //     L"Who[%s], DBID[%d], ServerID[%d], refcount[%d] "
            //     L"Caller [%s]",
            //     L"User.cpp",
            //     0x1211,
            //     runtime::Int32FromBits(accountId),
            //     who.data(),
            //     runtime::Int32FromBits(databaseId),
            //     runtime::Int32FromBits(serverId),
            //     expectedRefCount,
            //     m_guardStr)
            L2_LOG_ERROR(
                Log,
                u"[user lifetime] Cannot release '%s' (account %d, DB ID %d, object %d): "
                u"%d references remain and no cached reference is available; verifier caller '%s'.",
                who.data(), runtime::Int32FromBits(accountId), runtime::Int32FromBits(databaseId),
                runtime::Int32FromBits(serverId), expectedRefCount, m_guardStr
            );
            g_ServerContext.NotReleasedUser.fetch_add(1, std::memory_order_seq_cst);
            return;
        }

        --expectedRefCount;
        if (L2_RELEASE(m_pUser, ObjectRefType::Cached) == 0) {
            return;
        }
    }
}

std::int32_t User::Release(
    const char* const callerFile, const int callerLine, const ObjectRefType type, const bool releaseFromTimer
) {
    // Current L2Server 0x00b04154, User.cpp:0x20b.
    static_cast<void>(releaseFromTimer);

    const std::size_t typeIndex = static_cast<std::size_t>(type);
    RefHelperStruct& helper = m_RefHelpers.m_RefData[typeIndex];
    const std::int32_t subtypeRemaining = helper.m_nRefCount.fetch_sub(1, std::memory_order_seq_cst) - 1;
    if (subtypeRemaining < 0) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d]  sub-type[%s] sub-reference count[%d] "
        //     L"is below zero!",
        //     callerFile,
        //     callerLine,
        //     ObjectRefTypeName(type),
        //     subtypeRemaining)
        L2_LOG_ERROR(
            Log, u"[user lifetime] Reference subtype '%s' fell below zero (%d) after release from '%S'.",
            ObjectRefTypeName(type), subtypeRemaining, callerFile
        );
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%d]-[%s]  last_add[%S][%d] last_release[%S][%d]",
        //     subtypeRemaining,
        //     ObjectRefTypeName(type),
        //     helper.m_pAddCaller,
        //     helper.m_nAddLine,
        //     helper.m_pReleaseCaller,
        //     helper.m_nReleaseLine)
        L2_LOG_ERROR(
            Log, u"[user lifetime] Reference subtype '%s' was last added by '%S' and last released by '%S'.",
            ObjectRefTypeName(type), helper.m_pAddCaller, helper.m_pReleaseCaller
        );
        helper.m_pReleaseCaller = callerFile;
        helper.m_nReleaseLine = callerLine;
        runtime::process::ReportCallStack(2, false);
        ReportOrt("User.cpp", 0x20b);
    } else {
        helper.m_nReleaseLine = callerLine;
        helper.m_pReleaseCaller = callerFile;
    }

    const std::int32_t remaining = runtime::raw_atomic::AddI32(&m_nRefCount, -1);
    if (remaining == 0) {
        if (!IsInTimer()) {
            void* const allocation = this;
            this->~User();
            runtime::process::FreeMemoryObject(allocation);
        } else {
            runtime::process::ReportDeletingInTimer("User", callerFile, callerLine);
            ReportOrt("User.cpp", 0x20b);
        }
        runtime::process::DecrementMemoryClassReference(L2_MEMORY_CLASS_ID(User));
    } else if (remaining < 0) {
        runtime::process::ReportInvalidReference(remaining, "User", MemoryObjectID(), callerFile, callerLine);
        ReportOrt("User.cpp", 0x20b);
        runtime::process::ReportCallStack(2, true);
    }
    return remaining;
}

User::~User() {
    // Current L2Server 0x00b68d14. The language owns the reverse-order
    // destruction of every typed embedded member after this explicit body.
    L2_GUARD_FUNCTION();

    if (!g_bUserGarbageCollector) {
        ReleaseSocket();
    } else if (m_pSocket != NullUserSocket::GetNullUserSocket()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[Garbage]Usersocket is not released. dbid[%d] name[%s]",
        //     static_cast<int>(GetServerId()),
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[Garbage]Usersocket is not released. dbid[%d] name[%s]",
        //     static_cast<int>(GetServerId()),
        //     GetName())
        L2_LOG_ERROR(
            Log, u"[Garbage]Usersocket is not released. dbid[%d] name[%s]", static_cast<int>(GetServerId()), GetName()
        );
    }

    if (m_pFishingController != nullptr) {
        L2_RELEASE(m_pFishingController, ObjectRefType::CreateDelete);
    }

    g_ServerContext.User.fetch_sub(1, std::memory_order_seq_cst);

    if (!g_bUserGarbageCollector) {
        if (m_pAgent != nullptr) {
            L2_RELEASE(m_pAgent, ObjectRefType::CreateDelete);
            m_pAgent = nullptr;
        }
    } else if (m_pAgent != nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[Garbage] Agent is not released! dbid[%d] name[%s]",
        //     static_cast<int>(GetServerId()),
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[Garbage] Agent is not released! dbid[%d] name[%s]",
        //     static_cast<int>(GetServerId()),
        //     GetName())
        L2_LOG_ERROR(Log, u"[Garbage] Agent is not released! dbid[%d] name[%s]", static_cast<int>(GetServerId()), GetName());
    }

    if (m_pBuilderCmdHistory != nullptr) {
        L2_RELEASE(m_pBuilderCmdHistory, ObjectRefType::CreateDelete);
        m_pBuilderCmdHistory = nullptr;
    }

    delete m_pRidingInfo;
    m_pRidingInfo = nullptr;

    delete m_pAgathionActivationInfo;
    m_pAgathionActivationInfo = nullptr;

    ClearInZoneRestriction();

    if (m_pVitality != nullptr) {
        L2_RELEASE(m_pVitality, ObjectRefType::CreateDelete);
    }
    if (m_pPostInfo != nullptr) {
        L2_RELEASE(m_pPostInfo, ObjectRefType::CreateDelete);
    }
    if (m_pWOlympiadUser != nullptr) {
        L2_RELEASE(m_pWOlympiadUser, ObjectRefType::CreateDelete);
    }
}

// Current L2Server.exe 0x00b04598.
void User::OnCreate() {
    L2_GUARD_FUNCTION();
    g_ServerContext.User.fetch_add(1, std::memory_order_seq_cst);
    CCreature::OnCreate();

    for (int threadIndex = 0; threadIndex < CThreadManager::GetThreadCount(); ++threadIndex) {
        L2_ADD_REF(this, ObjectRefType::ThreadLocalMap);
    }
    IncreaseTLRef();

    if (!CThreadManager::IsMainThread() && !CThreadManager::IsListenThread()) {
        m_pFishingController = new CFishingController();
        m_pFishingController->SetActor(this);
        return;
    }

    SetController(nullptr);
}

void User::Delete() {
    // Current L2Server 0x00b34ae8.
    L2_GUARD_FUNCTION();
    const std::int32_t deleteCount = runtime::raw_atomic::IncrementI32(&m_nUserDeleteCount);
    if (deleteCount < 2) {
        m_bDeleting = true;
        if (!g_bUserGarbageCollector) {
            const wchar_t* caller = runtime::process::CurrentGuardCaller();
            if (caller == nullptr) {
                caller = L"callStackError";
            }
            static_cast<void>(new CUserReleaseVerifier(this, caller));
        } else {
            g_UserGC.Insert(this);
        }

        m_bConnected = false;
        CCreature::Delete();
        g_ptlUserMap->Remove(m_data->index, this);
        g_npcserver.Send("cddd", 0x30, runtime::Int32FromBits(GetServerId()), 0, 0);
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] User is deleted. User[%s], SID[%d]",
        //     L"User.cpp",
        //     0x1264,
        //     GetName(),
        //     runtime::Int32FromBits(GetServerId()))
        // L2_LOG_ERROR(Log,
        //     L"[user lifetime] Deleting character '%s', object %d.",
        //     GetName(),
        //     runtime::Int32FromBits(GetServerId()))
        L2_LOG_ERROR(
            Log, u"[user lifetime] Deleting character '%s', object %d.", GetName(), runtime::Int32FromBits(GetServerId())
        );
        L2_RELEASE(this, ObjectRefType::CreateDelete);
        return;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"[%s][%d] invalid User::Delete",
    //     L"User.cpp",
    //     0x122e)
    // L2_LOG_ERROR(Log,
    //     L"[user lifetime] Duplicate delete request rejected for character '%s', object %u.",
    //     GetName(),
    //     static_cast<unsigned int>(GetServerId()))
    L2_LOG_ERROR(
        Log, u"[user lifetime] Duplicate delete request rejected for character '%s', object %u.", GetName(),
        static_cast<unsigned int>(GetServerId())
    );
    runtime::process::ReportCallStack(2, false);
}

void User::TimerExpired(int id) {
    // Current L2Server.exe 0x00b6f0f8.
    L2_GUARD_FUNCTION();
    CCreature::TimerExpired(id);
    if (m_bDeleting || m_Deleted != 0) {
        return;
    }

    L2_DECLARE_AUTO_TIMER(timer, JOB_USER_TIMEREXPIRED);
    if (m_bLeft) {
        return;
    }
    if (m_pAgent != nullptr && !m_pAgent->TimeCheck()) {
        return;
    }

    if (!IsPremiumUser() && ((GetClass() >= 139 && GetClass() < 147) || GetClass() == 190 || GetClass() == 191)) {
        GetSocket()->ForceClose(SCR_ILLEGAL_BEHAVIOR);
        // Log.Add(
        //     LOG_ERROR,
        //     L"User Disconnected... userdbid[%d] username[%s] "
        //     L"classid[%d]",
        //     static_cast<int>(GetDBID()),
        //     GetName(),
        //     static_cast<int>(GetClassId()))
        // L2_LOG_ERROR(Log,
        // L"[session] User disconnected: DB ID %d, name '%s', class %d.",
        //     static_cast<int>(GetDBID()),
        //     GetName(),
        //     static_cast<int>(GetClassId()))
        L2_LOG_ERROR(
            Log, u"[session] User disconnected: DB ID %d, name '%s', class %d.", static_cast<int>(GetDBID()), GetName(),
            static_cast<int>(GetClassId())
        );
    }

    UpdateQuestState();
    if (m_bNeedSaveQuest != 0 && !m_bWaitForSavingQuest) {
        runtime::raw_atomic::ExchangeI32(&m_bNeedSaveQuest, 0);
        db.SaveQuestInfo(this);
    }

    const std::int32_t now = runtime::crt::Time32Now();
    if (m_tNextBindTime <= now) {
        m_tNextBindTime = runtime::AddInt32Wrapping(m_tNextBindTime, 86400);
        SendCompletedDailyQuestListClear();
    }

    m_BotChecker.OnTimerExpired();
    if (m_bKeepExp && m_dwKeepExpTick != 0 && runtime::GetTickCount() - m_dwKeepExpTick > 1199999U) {
        m_bKeepExp = false;
        m_dwKeepExpTick = 0;
        SendETCBuffStatusInfo();
    }

    if (runtime::Int32FromBits(m_nLastItemManipulateTick) > 0 && m_nItemManipulation != 1) {
        const std::uint32_t currentTick = runtime::GetTickCount();
        if (currentTick - m_nLastItemManipulateTick > 4999U) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"item manipulation lasted too long, may be error. "
            //     L"user[%s] time[%d] manipulation type[%d] ItemID[%d] "
            //     L"Count[%d]",
            //     GetName(),
            //     currentTick - m_nLastItemManipulateTick,
            //     static_cast<int>(m_nItemManipulation),
            //     m_nItemManipulationID,
            //     m_nItemManipulationCount)
            // L2_LOG_ERROR(Log,
            //         L"[items] Manipulation for user '%s' has run for %d ms: type %d, "
            //         L"item %d, count %d.",
            //     GetName(),
            //     currentTick - m_nLastItemManipulateTick,
            //     static_cast<int>(m_nItemManipulation),
            //     m_nItemManipulationID,
            //     m_nItemManipulationCount)
            L2_LOG_ERROR(
                Log,
                u"[items] Manipulation for user '%s' has run for %d ms: type %d, "
                u"item %d, count %d.",
                GetName(), currentTick - m_nLastItemManipulateTick, static_cast<int>(m_nItemManipulation),
                m_nItemManipulationID, m_nItemManipulationCount
            );
            LeaveItemManipulation();
        }
    }

    CheckRidingOnTimer();
    if (m_nPreviewTimeStamp > 0 && runtime::AddInt32Wrapping(m_nPreviewTimeStamp, 10) < runtime::crt::Time32Now()) {
        m_nPreviewTimeStamp = 0;
        SendSystemMessage(SystemMessageId::EQUIPMENT_TRY_ON_ENDED);
        ParamChanged(PCB_USER);
        GetSocket()->Send("cd", 0xf6, -1);
    }

    if (m_FootEffect != FOOT_EFFECT_NONE) {
        m_FootEffectEndTick = runtime::AddInt32Wrapping(m_FootEffectEndTick, -1);
        if (m_FootEffectEndTick == 0) {
            SetFootEffect(FOOT_EFFECT_NONE, 0);
        }
    }

    ReducePunishTime();
    ProcessUnderWaterEffect();

    if (m_bIsObserving) {
        if (!CIOObject::IsInTime(m_nObservingStartTime, m_nObservingPeriod)) {
            SendSystemMessage(SystemMessageId::OBSERVATION_TIME_EXPIRED);
            ObserverEnd();
        } else if (!CIOObject::IsInTime(
                       m_nObservingStartTime,
                       runtime::SubtractInt32Wrapping(m_nObservingPeriod, m_nNextObservingAnnounceTime)
                   )) {
            GetSocket()->SendSystemMessage_d(
                SystemMessageId::OBSERVATION_MINUTES_REMAINING, m_nNextObservingAnnounceTime / 60
            );
            if (m_nNextObservingAnnounceTime == 600) {
                m_nNextObservingAnnounceTime = 300;
            } else if (m_nNextObservingAnnounceTime == 300) {
                m_nNextObservingAnnounceTime = 60;
            } else {
                if (m_nNextObservingAnnounceTime != 60) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"abnormal observing announce time [%d]",
                    //     m_nNextObservingAnnounceTime)
                    L2_LOG_ERROR(
                        Log, u"[observer] Next announcement time %d is invalid; schedule reset requested.",
                        m_nNextObservingAnnounceTime
                    );
                }
                m_nNextObservingAnnounceTime = 0;
            }
        }
    }

    CheckCompassRegionOnTimerExpired();
    if (m_AreaMod.m_bWasInBattleField != m_AreaMod.m_bIsInBattleField) {
        if (!m_AreaMod.m_bIsInBattleField && !m_AreaMod.m_bWasInPvPZone && !m_AreaMod.m_bIsInPeaceField &&
            !g_bIsNonPKServer) {
            if (GetGuilty() != 1) {
                SetGuilty(1);
                runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
            }
            CIOObject::SetTimeStamp(&m_data->m_nPKTimeStamp);
        }
        runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
    }
    ProcessVioletBoy();

    {
        L2_GUARD(m_UnEquipQueueLock);
        if (!m_UnEquipItemQueue.empty()) {
            const UnEquipItemQueue queued = m_UnEquipItemQueue.front();
            if (queued.UnEquipItemServerID == 0) {
                if (static_cast<std::uint32_t>(queued.UnEquipSlotType) < static_cast<std::uint32_t>(ST_MAX)) {
                    UnequipItem(queued.UnEquipSlotType, queued.bDelete);
                }
            } else {
                CItem* const item = ItemSmartIdManager()->GetObjectW(queued.UnEquipItemServerID);
                if (item == nullptr) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d] ServerID[%d] pItem is NULL",
                    //     L"User.cpp",
                    //     0xb7b,
                    //     queued.UnEquipItemServerID)
                    L2_LOG_ERROR(
                        Log, u"[inventory] Cannot unequip queued item %d: the item object is missing.",
                        queued.UnEquipItemServerID
                    );
                } else {
                    const SlotType slot = UnequipItem(item, queued.bDelete);
                    if (slot == ST_NONE) {
                        // Log.Add(
                        //     LOG_ERROR,
                        //     L"[NO_ERROR][%s][%d] TimerExpired Insert Queue "
                        //     L"ItemDBID[%d], UserDBID[%d]",
                        //     "User.cpp",
                        //     0xb5e,
                        //     static_cast<int>(item->GetDBID()),
                        //     static_cast<int>(GetDBID()))
                        // Noise: UnequipItem requeued this item while another
                        // item operation or the agathion is busy.
                        // L2_LOG_ERROR(Log,
                        //     L"[NO_ERROR][%s][%d] TimerExpired Insert Queue "
                        //     L"ItemDBID[%d], UserDBID[%d]",
                        //     "User.cpp",
                        //     0xb5e,
                        //     static_cast<int>(item->GetDBID()),
                        //     static_cast<int>(GetDBID()))
                    } else if (queued.bDelete) {
                        if (item->IsDuration()) {
                            GetSocket()->Send(
                                "chccd", 0x62, SystemMessageId::ITEM_DISAPPEARED_MANA_DEPLETED, 1, 3, item->m_nClassId
                            );
                        }
                        if (item->m_const->m_period > 0) {
                            OnPeriodicItemDestroyed(static_cast<int>(item->GetDBID()), false);
                        }
                        {
                            L2_WRITE_GUARD(m_inv);
                            m_inv.Pop(item->m_data->index, false);
                            m_inv.SetInventoryChanged(item, IUT_DELETE);
                        }
                        item->Delete();
                        SendItemList(true, true, nullptr);
                    }
                }
            }
            if (!m_UnEquipItemQueue.empty()) {
                m_UnEquipItemQueue.pop();
            }
        }
    }

    bool savedCharacter = false;
    if (m_bConnected && m_data->m_bIsActive) {
        if (m_nCommitTick < 200) {
            m_nCommitTick = runtime::AddInt32Wrapping(m_nCommitTick, 1);
        } else {
            m_nCommitTick = 0;
            savedCharacter = true;
            if (m_lSaveCharacter != 1) {
                db.SendSaveCharacterInfo(this, false, true);
            }
            SaveInfectedSkills();
            CheckSocailityFaint();
        }

        if (m_nCommitTick2 < 1000) {
            m_nCommitTick2 = runtime::AddInt32Wrapping(m_nCommitTick2, 1);
        } else {
            m_nCommitTick2 = 0;
            db.SendSaveItemInfo(this);
            db.RequestLogCharInfo(*this);
            LogNPBuffStatus();
        }

        if (m_lSaveSkillReuseDelay != 0 || savedCharacter) {
            TrySaveSkillUsedTime(ReuseDelaySaveReason::SR_NORMAL);
        }
    }

    bool vitalityChanged = false;
    if (m_nTickCount % 5 == 0 && m_nChangeSubjobFlag != 1) {
        vitalityChanged = m_pVitality->OnTick(this);
        if (m_pVitality->CheckSendEffectInfo()) {
            SendVitalityEffectInfo(nullptr);
        }
        CheckAndDeleteReturnValue();
    }

    if (m_bParamChanged.load(std::memory_order_seq_cst) != 0) {
        if (m_nParamChanged == 0) {
            m_nParamChanged = PCB_CHAR_MARK;
        }
        m_bParamChanged.exchange(0, std::memory_order_seq_cst);
    }

    if (m_bParamHPCPMPChanged) {
        const std::uint32_t changed = runtime::raw_atomic::ExchangeU32(&m_nParamHPCPMPChanged, 0);
        CParty* const party = GetParty();
        if (party != nullptr) {
            party->UpdateWindowPacket(this, 3, 0, 0, changed);
        }
        m_bParamHPCPMPChanged = false;
    }

    const std::int32_t relationChanged = runtime::raw_atomic::ExchangeI32(&m_nRelationChanged, 0);
    if (relationChanged != 0) {
        if (relationChanged > 1) {
            GatherRelationChanged();
        }
        SendRelationChanged(nullptr);

        FOR_ALL_SUMMON_PET_IN_SUMMON_LIST(this, summon, {
            summon->m_data->m_NeedUpdatePacketBitSet.SetBit(0x62);
            summon->SendMyInfo();
        });
    }

    std::int64_t changedParameters = 0;
    if (IsActive()) {
        changedParameters = runtime::raw_atomic::ExchangeI64(&m_nParamChanged, 0);
        m_nParamChangedStat = static_cast<std::uint64_t>(changedParameters);
    }

    if (m_bValidateExChanged) {
        const std::int32_t changed = runtime::raw_atomic::ExchangeI32(&m_nValidateExChanged, 0);
        m_bValidateExChanged = false;
        ValidateExParameters(changed);
    }
    if (m_bValidateChanged && !m_lockValidate.IsEntered()) {
        const std::int32_t changed = runtime::raw_atomic::ExchangeI32(&m_nValidateChanged, 0);
        m_bValidateChanged = false;
        ValidateParameters(changed, false);
    }

    const std::uint64_t changedBits = static_cast<std::uint64_t>(changedParameters);
    if ((changedBits & PCB_NICKNAME) != 0) {
        SendNicknameChanged();
    }
    if ((changedBits & PCB_PLEDGE) != 0) {
        SendPledgeStatusChanged();
    }
    if (relationChanged != 0 || vitalityChanged || (changedBits & PCB_USER) != 0) {
        SendUserInfo(nullptr, &m_NeedUpdatePacketBitsStat);
    }
    if ((changedBits & PCB_CHAR) != 0 || changedParameters > PCB_CHAR) {
        BroadcastCharInfoUpdate(((changedBits >> PCT_TRANSFORM) & 1U) != 0);
    }

    if (m_bSpelledInfoChanged) {
        const std::uint32_t changed = runtime::raw_atomic::ExchangeU32(&m_NeedUpdatePacketBits, 0);
        if ((changed & 4U) != 0) {
            SendSpelledInfoChanged();
        } else if ((changed & 2U) != 0) {
            SendExSpelledInfoChanged();
        }
        m_bSpelledInfoChanged = false;
        if (IsAlreadyHaveMentor() && m_Mentee.CanBeBuffed()) {
            runtime::raw_atomic::ExchangeI32(&m_Mentee.m_nInfectedSkillByMentor, 0);
        }
    }

    TimerExpiredOnPartyMatching();
    if (m_bIsNewInWorld) {
        m_bIsNewInWorld = false;
    }

    if (GetSocket()->m_nWarnFlag == 1 && m_nTickCount % 90 == 0) {
        SendSystemMessage(SystemMessageId::ACCOUNT_REPORTED_FOR_UNPAID_PC_CAFE_FEES_CONTACT_SUPPORT);
    }
    GetSocket()->CheckLoginTime();

    if (g_bUsePledgeBonus && m_nTickCount % 15 == 0) {
        CPledge* const pledge = GetPledge();
        if (pledge != nullptr) {
            const std::int32_t currentTime = runtime::crt::Time32Now();
            std::tm* const localTime = runtime::crt::LocalTime32(currentTime);
            if (localTime->tm_hour == 6 && localTime->tm_min == 30) {
                if (CanResetTimeStamp(PledgeBonus::ACCESS_MISSION_COMPLETE, currentTime)) {
                    tPledgeBonusTimeStamp[PledgeBonus::ACCESS_MISSION_COMPLETE] = currentTime;
                }
                if (pledge->m_PledgeBonus.CheckSaveTime(
                        runtime::crt::Time32Now(), pledge->m_PledgeBonus.m_PledgeBonus[0].m_nLastSaveTime
                    ) != PledgeBonus::TODAY) {
                    pledge->SetPledgeMissionCheck(nullptr, 0);
                }
            }

            std::int32_t& missionTimestamp = tPledgeBonusTimeStamp[PledgeBonus::ACCESS_MISSION_COMPLETE];
            if (missionTimestamp > 0 && (localTime->tm_hour != 6 || localTime->tm_min < 30) &&
                runtime::SubtractInt32Wrapping(currentTime, missionTimestamp) / 60 > 29) {
                missionTimestamp = runtime::Int32FromBits(0U - static_cast<std::uint32_t>(currentTime));
                pledge->ProcessBonusPoint(this, 0, 1, static_cast<int>(pledge->GetPledgeLevel()), currentTime);
                pledge->SetPledgeMissionCheck(this, currentTime);
            }
        }
    }

    if (m_nTickCount % 450 == 1) {
        RequestAccountStamp(0, true, false);
        if (GetSocket()->m_VipAttendnaceCheck == 0) {
            GetSocket()->CheckAttendanceTime(false);
        }
    }
    if (m_nTickCount % 8 == 0) {
        CheckPCCafeEvent();
    }

    if (m_DuelUserInfo.IsInDuel() && m_DuelUserInfo.IsInPartyDuel()) {
        int reason = 0;
        if (CheckDuelCancelCondition(reason, m_nTickCount % 5 == 0)) {
            CDuelManager::inst().CancelDuel(this, reason);
        }
    }

    if (GetEquipDurationItemCount() > 0 && m_nTickCount % 15 == 0) {
        DecreaseEquippedItemDurationOnTimerExpired();
    }
    if (m_nTickCount % 15 == 0) {
        CheckPeriodicItemOnTick();
        CheckPeriodicShapeShiftedItemOnTick();
        CheckPeriodicHennaOnTick();
        CheckPremiumHennaConditionOnTick();
    }

    if (m_SoulCount > 0 && !CIOObject::IsInShortTime(m_SoulStartTime, 600000)) {
        {
            L2_GUARD(*m_lock);
            m_SoulCount = 0;
        }
        SendETCBuffStatusInfo();
    }

    GetPVPPointByTimerInBattleField();
    KillPVPPointChecker.CheckGivableAndSendChange(this);
    if (m_nBotReportPoint != 0 && m_nTickCount % 5400 == 1000) {
        db.RequestDecayBotReport(this);
    }
    if (m_nTickCount % 5 == 0) {
        CheckPledgeMasterOnline();
    }
    if (m_nTickCount == 900) {
        SetAvoidAgroFalse();
    }
    if (m_nTickCount % 5 == 0) {
        AuraSkillBySkill();
        _SynergyAuraByAbnormalSlot();
    }

    CheckHasFlag();
    if (m_nTickCount % 15 == 0) {
        CheckXMasSantaEvent();
    }
    CheckYearCatchEvent();
    TimerExpiredAgathion();

    if (m_nTickCount % 15 == 0) {
        m_pPostInfo->ProcessList();
    }
    if (m_nTickCount % 15 == 0 && runtime::Int32FromBits(m_nTimeToDie) > 0) {
        CheckDieTickOnTimerExpired();
    }
    if (m_nTickCount % 15 == 0 && m_bNeedUpdateSummon != 0) {
        SummonAllPending();
    }
    if (m_nTickCount % 5400 == 1000) {
        m_nCreateInstantZoneCount = 0;
        CheckDormantUser(false);
    }

    if (m_CommissionDelay == 1) {
        m_nCommissionTickCount = runtime::AddInt32Wrapping(m_nCommissionTickCount, 1);
    }
    if (m_nCommissionTickCount > 2) {
        runtime::raw_atomic::ExchangeI32(&m_CommissionRelease, 1);
        runtime::raw_atomic::ExchangeI32(&m_CommissionDelay, 0);
    }
    if (m_CommissionDelay == 1 && m_CommissionRelease == 1) {
        runtime::raw_atomic::ExchangeI32(&m_CommissionRelease, 0);
    }

    if (m_BeautyDelay == 1) {
        m_nBeautyTickCount = runtime::AddInt32Wrapping(m_nBeautyTickCount, 1);
    }
    if (m_nBeautyTickCount > 2) {
        runtime::raw_atomic::ExchangeI32(&m_BeautyRelease, 1);
        runtime::raw_atomic::ExchangeI32(&m_BeautyDelay, 0);
    }
    if (m_BeautyDelay == 1 && m_BeautyRelease == 1) {
        runtime::raw_atomic::ExchangeI32(&m_BeautyRelease, 0);
    }

    if (m_nTickCount % 90 == 0) {
        CheckInitVoteSystem();
        CheckVoteSystemTime();
        CalcVoteSystemTime();
        CalExpBonus();
    }
    if (m_nTickCount % 3 == 0) {
        m_inv.UpdateRuneItem();
        SendBrAgathionEnergyInfo();
        m_UpDownGame.OnTimer(*this);
    }

    if (m_nTickCount % 900 == 0 && m_nGiftDayIn7Days > 0) {
        const _SYSTEMTIME localTime = runtime::crt::LocalSystemTimeNow<_SYSTEMTIME>();
        if (static_cast<std::uint32_t>(localTime.wDay) == static_cast<std::uint32_t>(m_nGiftDayIn7Days)) {
            CelebrateBirthday(0, false);
        }
    }

    CheckMentorMenteeTimer();
    ProcessFlyMove();
    if (m_nTickCount % 8 == 0) {
        g_PledgeGameSystem.CheckUser(this);
    }
    if (m_nTickCount % 90 == 0) {
        m_nSpeedHackSuspectCount = 0;
    }

    if (g_bUseOneDayReward && m_nTickCount % 900 == 0 &&
        runtime::SubtractInt32Wrapping(runtime::crt::Time32Now(), m_CheckTimeDailyMission) > 900) {
        CheckOneDayReward(true);
    }

    if (m_nTickCount % 900 == 0 && ExDropItemSystem::inst().IsNeedInit(m_tmExDropItemGetTime)) {
        L2_GUARD(*m_lock);
        ResetDropCount();
    }

    if (m_PledgeSearchDelay == 1) {
        m_nPledgeJoinSearchTickCount = runtime::AddInt32Wrapping(m_nPledgeJoinSearchTickCount, 1);
    }
    if (m_PledgeIODelay == 1) {
        m_nPledgeJoinIOTickCount = runtime::AddInt32Wrapping(m_nPledgeJoinIOTickCount, 1);
    }
    if (m_WaitListDelay == 1) {
        m_nWaitListTickCount = runtime::AddInt32Wrapping(m_nWaitListTickCount, 1);
    }
    if (m_DraftSearchDelay == 1) {
        m_nDraftSearchTickCount = runtime::AddInt32Wrapping(m_nDraftSearchTickCount, 1);
    }
    if (m_nPledgeJoinSearchTickCount > 1) {
        runtime::raw_atomic::ExchangeI32(&m_PledgeSearchDelay, 0);
    }
    if (m_nPledgeJoinIOTickCount > 1) {
        runtime::raw_atomic::ExchangeI32(&m_PledgeIODelay, 0);
    }
    if (m_nWaitListTickCount > 1) {
        runtime::raw_atomic::ExchangeI32(&m_WaitListDelay, 0);
    }
    if (m_nDraftSearchTickCount > 1) {
        runtime::raw_atomic::ExchangeI32(&m_DraftSearchDelay, 0);
    }

    if (m_nTickCount % 90 == 0 && GetPledge() != nullptr) {
        CPledge* const pledge = GetPledge();
        const std::int32_t notifyTime = CPledgeJoinSystem::Inst()->GetNotifyTable(static_cast<int>(pledge->GetDbId()));
        if ((m_nPledgeJoinTimeStamp == 0 && m_data->GetAccountLastLogoutTime() < notifyTime) ||
            (m_nPledgeJoinTimeStamp != 0 && m_nPledgeJoinTimeStamp < notifyTime)) {
            GetSocket()->Send("c", 0xfe);
        }
        m_nPledgeJoinTimeStamp = notifyTime;
    }

    if (KalieEvent::Inst().m_bEventStarted) {
        CEvent* const event = CEventManager::inst().GetEvent(GAME_EVENT::ET_KALIE);
        if (event == nullptr) {
            return;
        }
        CEvent_Kalie* const kalie = static_cast<CEvent_Kalie*>(event);
        if (m_nTickCount % 9 == 0 && kalie->m_nRewardMinLevel <= m_data->m_nLevel &&
            kalie->m_nRewardMinChangedClass < GetClassGroupNoByClassType(m_data->m_nClass)) {
            bool gaveEveryReward = false;
            if (g_bFreeKalieEvent || m_nKalieBuff != 0) {
                if (KalieEvent::Inst().ChangeRewardValueToZero() != 0) {
                    KalieTimerExpired();
                    KalieEvent::Inst().EveryRewardValueOn();
                }
                if ((g_bFreeKalieEvent || m_nKalieBuff != 0) && KalieEvent::Inst().m_bEveryReward &&
                    m_bKalieRewardForEveryone) {
                    runtime::raw_atomic::AddI32(&m_nKalieToken, KalieEvent::Inst().m_nRewardTokenCnt);
                    db.RequestUpdateKalieEventForUser(*this, m_nKalieToken);
                    KalieEvent::Inst().SendRewardItemForEveryUser(*this);
                    const int notifyTokenCount = KalieEvent::Inst().m_nRewardTokenCnt;
                    GetSocket()->SendSystemMessage_d(SystemMessageId::LUCKY_COINS_OBTAINED, notifyTokenCount);
                    m_bKalieRewardForEveryone = false;
                    gaveEveryReward = true;
                }
            }
            if (!gaveEveryReward && !KalieEvent::Inst().m_bEveryReward && !m_bKalieRewardForEveryone) {
                m_bKalieRewardForEveryone = true;
            }
        }
    }

    if (BalthusEvent::inst().IsStartedEvent()) {
        CEvent* const event = CEventManager::inst().GetEvent(GAME_EVENT::ET_BALTHUS);
        if (event != nullptr) {
            CEvent_Balthus* const balthus = static_cast<CEvent_Balthus*>(event);
            if (balthus->GetRewardMinLevel() <= m_data->m_nLevel &&
                balthus->GetRewardMinChangedClass() < GetClassGroupNoByClassType(m_data->m_nClass)) {
                const bool canProcess = m_bIsNCGuardBotDetected || m_SkillDurationMod.m_bBalthusBuff;
                bool distributedToken = false;
                if (!m_bIsNCGuardBotDetected && m_SkillDurationMod.m_bBalthusBuff &&
                    BalthusEvent::inst().EndRewardGivingForUserTimerExpired() != 0) {
                    CSPointer<User> self(this, ObjectRefType::FunctionChain);
                    BalthusEvent::inst().GiveRewardToLotteryWinner(std::move(self));
                }
                if (canProcess && m_SkillDurationMod.m_bBalthusBuff && BalthusEvent::inst().IsTokenDistributing() != 0 &&
                    m_bBalthusTokenReady) {
                    CSPointer<User> self(this, ObjectRefType::FunctionChain);
                    runtime::raw_atomic::AddI32(&m_nBalthusTokenCount, BalthusEvent::inst().GetTokenCount());
                    db.RequestUpdateBalthusEventUserInfo(self);
                    CSPointer<User> logUser(self);
                    const int logTokenCount = BalthusEvent::inst().GetTokenCount();
                    BalthusEvent::inst().WriteTokenLog(std::move(logUser), logTokenCount, GAME_EVENT::BALTHUS_JACKPOT);
                    CSPointer<User> eventInfoUser(self);
                    BalthusEvent::inst().SendEventInfo(std::move(eventInfoUser), GAME_EVENT::BALTHUS_NO_CHANGE);
                    const int notifyTokenCount = BalthusEvent::inst().GetTokenCount();
                    GetSocket()->SendSystemMessage_d(SystemMessageId::LUCKY_COINS_OBTAINED, notifyTokenCount);
                    m_bBalthusTokenReady = false;
                    distributedToken = true;
                }
                if (!distributedToken && BalthusEvent::inst().IsTokenDistributing() == 0 && !m_bBalthusTokenReady) {
                    m_bBalthusTokenReady = true;
                }
            }
        }
    }

    CEvent* const invitationBase = CEventManager::inst().GetEvent(GAME_EVENT::ET_INVITATION);
    if (invitationBase != nullptr) {
        CEvent_InvitationEvent* const invitation = static_cast<CEvent_InvitationEvent*>(invitationBase);
        if (m_nTickCount % invitation->GetTick() == 0) {
            UpdateInkEnergy(invitation->GetTickInkEnergy(), false);
        }
    }

    if (m_nTickCount % 9 == 0) {
        if (m_data->m_TrainingState == 1) {
            const std::int32_t currentTime = runtime::crt::Time32Now();
            const std::int32_t endTime = m_TrainingEndTime;
            if (currentTime < endTime) {
                if (!m_AreaMod.m_bIsInTrainingZone) {
                    EndTraining(TrainingZone::BY_OUTSIDE, runtime::crt::Time32Now());
                }
            } else {
                EndTraining(TrainingZone::BY_TIMER, endTime);
            }
        } else if (m_AreaMod.m_bIsInTrainingZone) {
            const int z = runtime::Win64CvttDoubleToInt32(GetPos().z);
            const int y = runtime::Win64CvttDoubleToInt32(GetPos().y);
            const int x = runtime::Win64CvttDoubleToInt32(GetPos().x);
            // Log.Add(
            //     LOG_ERROR,
            //     L"[TrainingCamp] Invalid State[%d] charID[%d] "
            //     L"[%d,%d,%d]",
            //     m_data->m_TrainingState,
            //     static_cast<int>(GetDBID()),
            //     x,
            //     y,
            //     z)
            L2_LOG_ERROR(
                Log,
                u"[training camp] Character %d is inside the training zone with state %d at (%d, %d, %d); returning it to "
                u"the village.",
                static_cast<int>(GetDBID()), m_data->m_TrainingState, x, y, z
            );
            Restart(RESTART_VILLAGE, 0);
        }
    }

    if (m_nTickCount % 9 != 0 && !CAreaDB::inst().IsFishingZone(GetPos(), 0) && HasAbnormalStatusSlot(ABNS_FISHING_BLESS)) {
        {
            L2_GUARD(m_InfectedSkillsSect);
            _DeleteAbnormalStatus(ABNS_FISHING_BLESS, this, nullptr, true, SPET_REPLACE, false);
        }
    }

    CheckManipulateQueue();
    UpdateFriendsInfo();
    if (g_CaptchaSetting.enable && m_nTickCount % 15 == 0) {
        CheckCaptchaConfirmExpired();
    }
    if (m_nTickCount % 1350 == 0) {
        RelayClient::Inst()->SendUserInfo(this);
    }
    if (!m_bIsSendFactionInfoCompleted && m_bIsSendUserInfoCompleted && m_bIsDBFactionInfoLoaded) {
        SendFactionInfoList(0);
        m_bIsSendFactionInfoCompleted = true;
    }

    MergeMonsterBook();
    SendMonsterBook();
    SendMonsterBookNoti();
    ValidateAP();
    if (m_nTickCount % 90 == 0) {
        UpdateMonsterBookToDB();
    }
    if (m_nTickCount % 2 == 0) {
        g_FieldCycleSystem.OnUserTimerExpired(this);
    }
    UserStatusLog();
    PledgeMissionIntervalCheck();
    CheckPeaceZoneTimeOnTimerExpired();
}

void User::OnActivate() {
    // Current L2Server.exe 0x00b60518.
    L2_GUARD_FUNCTION();
    CCreature::OnActivate();
    CCursedWeaponMgr::inst().OnEnterWorld(this);
    if (!IsValidCursedWeapon()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Error, m_nCursedWeaponClassId is %d but Have "
        //     L"CursedWeapon [%s]!!",
        //     L"User.cpp",
        //     0x5ef0,
        //     m_nCursedWeaponClassId,
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[cursed weapon] Character '%s' has cursed-weapon state, but item class %d is recorded.",
        //     GetName(),
        //     m_nCursedWeaponClassId)
        L2_LOG_ERROR(
            Log, u"[cursed weapon] Character '%s' has cursed-weapon state, but item class %d is recorded.", GetName(),
            m_nCursedWeaponClassId
        );
    }
}

bool User::IsValidCursedWeapon() {
    // Current L2Server.exe 0x00b363c8.
    L2_GUARD_FUNCTION();
    bool result = true;
    if (m_nCursedWeaponClassId != 0) {
        return result;
    }

    for (CSharedItemData* data = m_inv.GetFirst(); data != nullptr; data = data->Next()) {
        CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(data->index);
        if (!item) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d]ERROR, Cannot Find item object. item "
            //     L"classid[%d][%s]",
            //     L"User.cpp",
            //     0x2061,
            //     data->m_nClassID,
            //     GetName())
            // L2_LOG_ERROR(Log,
            //     L"[cursed weapon] Cannot inspect item class %d for '%s': the item object is missing.",
            //     data->m_nClassID,
            //     GetName())
            L2_LOG_ERROR(
                Log, u"[cursed weapon] Cannot inspect item class %d for '%s': the item object is missing.", data->m_nClassID,
                GetName()
            );
            continue;
        }

        const int itemClassId = data->m_nClassID;
        if (itemClassId != 0x1ffe && itemClassId != 0x21f1) {
            continue;
        }

        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d]delete curesed item object. item classid[%d]",
        //     L"User.cpp",
        //     0x2067,
        //     itemClassId)
        L2_LOG_ERROR(Log, u"[cursed weapon] Removing unexpected cursed-weapon item class %d from inventory.", itemClassId);
        db.RequestDestroyItem(item.get(), 1, this, 0);
        SetKarma(0);
        result = false;
    }
    return result;
}

CUserCloser::CUserCloser(const std::uint32_t userServerId) : m_UserSID(userServerId) {}

// Current L2Server.exe 0x00b285c8.
void CUserCloser::TimerExpired(int) {
    CCreature* const creature = g_CreatureSmartIdManager.GetObjectW(m_UserSID);
    if (creature != nullptr && creature->IsPC()) {
        User* const user = creature->CastUser();
        CUserSocket* const socket = user->GetSocket();
        if (socket != nullptr) {
            socket->ForceClose(SCR_ILLEGAL_BEHAVIOR);
        }
    }

    L2_RELEASE(this, ObjectRefType::CreateDelete);
}

// Current L2Server.exe 0x00b0bfb0.
void User::SetCloseLater() {
    L2_GUARD_FUNCTION();
    CUserCloser* const closer = new CUserCloser(GetServerId());
    closer->AddTimer(static_cast<std::int64_t>(std::rand() % 10000 + 5000), 0);
}

