    m_eIgnoreGradePenalty = CRT_NONE;
    m_MatchingPoint = {};
    m_ReturnSkillPosMap.clear();
    m_ReturnTimeSkillMap.clear();
    m_nCaptchaConfirmTransactionId = 0;
    m_tCaptchaConfirmStartTime = 0;
    m_CaptchaConfirmTimes = 0;
    m_nCaptchaConfirmSec = 0;
    m_tCaptchaDelayStartTime = 0;
