    m_data->m_nHairShapeEx = hairShapeEx;
    m_data->m_nHairColorEx = hairColorEx;

    m_data->m_Pos = FVector{static_cast<double>(x), static_cast<double>(y), static_cast<double>(z)};
    m_data->SetHP(hp);
    m_data->SetMP(mp);
    m_data->SetCP(static_cast<double>(cp));
    m_data->m_NeedUpdatePacketBitSet.SetInt64Value_IfModifed(m_data->m_nSP, sp, 0x0e);
    if (m_data->m_nExp != experience) {
        m_data->m_NeedUpdatePacketBitSet.SetInt64Value_IfModifed(m_data->m_nExp, experience, 0x06);
        m_data->m_NeedUpdatePacketBitSet.SetBit(0x07);
    }
    if (m_data->m_nLevel != level) {
        m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(m_data->m_nLevel, level, 0x05);
        m_data->m_NeedUpdatePacketBitSet.SetBit(0x07);
    }
    m_data->SetAP(abilityPoint, true);
    if (m_data->m_nSubJobId == 0) {
        m_data->m_MainClassLevel = level;
    }

    m_data->m_nKarma = karma;
    m_data->m_nPKCount = pkCount;
    m_data->m_nDuelCount = static_cast<std::int32_t>(duelCount);
    m_data->m_nPKPardonCount = static_cast<std::int32_t>(pkPardonCount);
    m_data->m_nSulffrageCount = static_cast<std::int16_t>(GetSulffrageCountByLevel(m_data->m_nLevel));

    m_nJobGroup = jobGroup;
    if (jobGroup < 0 || jobGroup > 1) {
        const int loadedClassType = static_cast<int>(m_data->m_nClass);
        if (loadedClassType < 0 || loadedClassType > 0xbf) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"user class invalid. %d [user : %s]",
            //     loadedClassType,
            //     GetName())
            // L2_LOG_ERROR(Log,
            //         L"[character load] Class %d is invalid for user '%s'. Load validation failed.",
            //     loadedClassType,
            //     GetName())
            L2_LOG_ERROR(
                Log, u"[character load] Class %d is invalid for user '%s'; load validation failed.", loadedClassType,
                GetName()
            );
        } else {
            m_nJobGroup = loadedClassType == 0x90 ? 1 : static_cast<int>(CT_to_FMT[loadedClassType]);
            db.RequestSaveUserJobGroup(m_data->m_nWorldId, static_cast<int>(GetDBID()), m_nJobGroup);
        }
    }

    m_nBaseClass = CPCParamDB::GetBasicClassByRaceAndFTM(m_data->m_Race, m_nJobGroup == 0, m_data->m_Sex == ST_MALE);
