void User::ReportOrt(const char* const callerFile, const int) {
    // Current L2Server 0x00b0438c. The guard literal names a third
    // nWorkType lane, but the vtable ABI has only these two explicit args.
    // the current body hard-codes work type 1.
    L2_GUARD_FUNCTION();

    static thread_local int totalCall = 0;
    int sequence = 1;
    ++totalCall;
    if (callerFile == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[ORT Report][tid:%d][tick:%d][%d] begin "
        //     "---------------------------",
        //     threadId,
        //     totalCall,
        //     sequence)
        L2_LOG_ERROR(Log, "[user lifetime] Reference report %d started; first record %d.", totalCall, sequence);
    } else {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ORT Report][tid:%d][tick:%d][%d] begin called from "
        //     L"file[%S], line[%d] -------------",
        //     threadId,
        //     totalCall,
        //     sequence,
        //     callerFile,
        //     callerLine)
        L2_LOG_ERROR(
            Log, u"[user lifetime] Reference report %d started from '%S'; first record %d.", totalCall, callerFile, sequence
        );
    }

    for (std::size_t index = 0; index < RefHelpers::kCount; ++index) {
        const RefHelperStruct& helper = m_RefHelpers.m_RefData[index];
        if (helper.m_pAddCaller == nullptr || helper.m_pReleaseCaller == nullptr) {
            continue;
        }
        const std::int32_t referenceCount = helper.m_nRefCount.load(std::memory_order_relaxed);
        if (referenceCount == 0) {
            continue;
        }

        ++sequence;
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ORT Report][tid:%d][tick:%d][%d] "
        //     L"[RefCount:%d]-[%s]  last_add[%S][%d] "
        //     L"last_release[%S][%d]",
        //     threadId,
        //     totalCall,
        //     sequence,
        //     referenceCount,
        //     ObjectRefTypeName(
        //         static_cast<ObjectRefType>(index)),
        //     helper.m_pAddCaller,
        //     helper.m_nAddLine,
        //     helper.m_pReleaseCaller,
        //     helper.m_nReleaseLine)
        L2_LOG_ERROR(
            Log,
            u"[user lifetime] Reference report %d record %d: subtype '%s' has %d references; "
            u"last add '%S', last release '%S'.",
            totalCall, sequence, ObjectRefTypeName(static_cast<ObjectRefType>(index)), referenceCount, helper.m_pAddCaller,
            helper.m_pReleaseCaller
        );
    }

    // Log.Add(
    //     LOG_ERROR,
    //     "[ORT Report][tid:%d][tick:%d][%d] end "
    //     "-----------------------------",
    //     threadId,
    //     totalCall,
    //     sequence + 1)
    L2_LOG_ERROR(Log, "[user lifetime] Reference report %d completed after record %d.", totalCall, sequence + 1);
}

