bool User::SetAbilitySkillList(const int skillId, const int skillLevel) {
    // Current L2Server 0x00b4a37c.
    L2_GUARD_FUNCTION();
    L2_GUARD(m_AcquiredAbilitySkillsLock);

    const auto potential = CPotentialSkillDB::Inst().m_mapPotentailSkillAcquireInfos.find(skillId);
    if (potential == CPotentialSkillDB::Inst().m_mapPotentailSkillAcquireInfos.end() || potential->second == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] hacking? user[%s] class[%d] "
        //     L"skill_id[%d] skill_level[%d]",
        //     L"User.cpp",
        //     0x74ea,
        //     GetName(),
        //     static_cast<int>(m_data->m_nClass),
        //     skillId,
        //     skillLevel)
        // L2_LOG_ERROR(Log,
        //     L"[ability skill] Rejected unregistered potential skill %d level %d for '%s', class %d.",
        //     skillId,
        //     skillLevel,
        //     GetName(),
        //     static_cast<int>(m_data->m_nClass))
        L2_LOG_ERROR(
            Log, u"[ability skill] Rejected unregistered potential skill %d level %d for '%s', class %d.", skillId,
            skillLevel, GetName(), static_cast<int>(m_data->m_nClass)
        );
        runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
        return false;
    }

    if (g_SkillDB.GetSkillInfo(CSkillKey(skillId, skillLevel, 0), this) == nullptr) {
        return false;
    }

    const auto inserted = m_AcquiredAbilitySkills.emplace(skillId, AcquiredPotentialSkillInfo(skillId, skillLevel));
    if (!inserted.second) {
        AcquiredPotentialSkillInfo& current = inserted.first->second;
        // The current image compares against the stored skill ID, not its
        // stored level. Preserve that observable oddity literally.
        if (skillLevel <= current.m_nId) {
            return false;
        }
        if (g_SkillDB.GetSkillInfo(CSkillKey(current.m_nId, current.m_nLevel, 0), this) == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] Skill ID[%d] level[%d] doesn't exist",
            //     L"User.cpp",
            //     0x7504,
            //     current.m_nId,
            //     current.m_nLevel)
            L2_LOG_ERROR(
                Log, u"[ability skill] Stored skill %d level %d is missing from the skill database.", current.m_nId,
                current.m_nLevel
            );
            return false;
        }
        current.m_nLevel = skillLevel;
    }
    return true;
}

void User::SendAbilitySkillList(const int type) {
    // Current L2Server 0x00b3a258.
    L2_GUARD_FUNCTION();
    std::optional<CPacketHelperEx<20480>> packetStorage;
    {
        L2_GUARD(m_AcquiredAbilitySkillsLock);

        CPacketHelperEx<20480>& packet = packetStorage.emplace();
        for (const auto& acquiredSkill : m_AcquiredAbilitySkills) {
            const AcquiredPotentialSkillInfo& info = acquiredSkill.second;
            packet.Assemble("dd", info.m_nId, info.m_nLevel);
        }

        const std::int32_t totalAcquired = runtime::AddInt32Wrapping(
            runtime::AddInt32Wrapping(m_data->m_stPotentialCount.nCount1, m_data->m_stPotentialCount.nCount2),
            m_data->m_stPotentialCount.nCount3
        );
        GetSocket()->Send(
            "chdQdddb", 0xfe, 0x15f, type, CPotentialSkillDB::Inst().m_nResetSP, m_data->GetAP(), totalAcquired,
            runtime::Int32FromBits(static_cast<std::uint32_t>(m_AcquiredAbilitySkills.size())), packet.GetLength(),
            packet.GetPacket()
        );
    }
}

void User::AcquireExtraSkills() {
    // Current L2Server 0x00b3a470.
    L2_GUARD_FUNCTION();

    AcquirePledgeSkillsAfterReload(false);
    if (m_data->m_nNoblessType == 1 || m_data->m_nNoblessType == 2) {
        static_cast<void>(NoblessSystemUtil::SetNoblessSkillToUser(CSPointer<User>(this, ObjectRefType::FunctionChain)));
    }
    ValidateHeroSkills();
    ValidateHenna();
    if (m_data->m_nSubJobId != 0) {
        AcquireSubjobCertSkills();
    }
    OnRuneItemsChange();

    if (IsAlreadyHaveMentor()) {
        runtime::raw_atomic::ExchangeI32(&m_Mentee.m_nInfectedSkillByMentor, 0);
        m_Mentee.SubjobChange();
        AcquireMentorMenteeSkills(ESAT_MENTEE);
    } else if (IsHaveMentee()) {
        runtime::raw_atomic::IncrementI32(&m_Mentor.m_nSomethingChanged);
        m_Mentor.m_nInfectedSkillByMentee = 0;
        AcquireMentorMenteeSkills(ESAT_MENTOR);
    }

    m_nSetItemClassId = 0;
    ValidateSetItem(ST_MAX);
    ValidateNewSetItem();
    ValidateShapeShiftedSetItem();
}

void User::ValidateAbilitySkills() {
    // Current L2Server 0x00b5d2fc.
    L2_GUARD_FUNCTION();

    std::map<int, AcquiredPotentialSkillInfo> acquiredSkills;
    {
        L2_GUARD(m_AcquiredAbilitySkillsLock);
        acquiredSkills = m_AcquiredAbilitySkills;
    }

    {
        L2_GUARD(m_AcquiredSkillsSect);
        for (const auto& acquiredSkill : acquiredSkills) {
            const AcquiredPotentialSkillInfo& info = acquiredSkill.second;
            _AcquireSkill(info.m_nId, info.m_nLevel, 0, false, true);
        }
    }
}

bool User::Transform(const int transformId, const bool broadcast) {
    L2_GUARD_FUNCTION();

    if (transformId < 1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] No transform info. id[%d], gender[%d], "
        //     L"name[%s]",
        //     L"User.cpp",
        //     0x5c15,
        //     transformId,
        //     static_cast<int>(m_data->m_Sex),
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[transformation] Invalid transform ID %d for '%s', gender %d.",
        //     transformId,
        //     GetName(),
        //     static_cast<int>(m_data->m_Sex))
        L2_LOG_ERROR(
            Log, u"[transformation] Invalid transform ID %d for '%s', gender %d.", transformId, GetName(),
            static_cast<int>(m_data->m_Sex)
        );
        return false;
    }

    L2_GUARD(m_TransformLock);
    m_transform = g_TransformDB.Find(transformId, m_data->m_Sex);
    if (m_transform == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] No transform info. id[%d], gender[%d], "
        //     L"name[%s]",
        //     L"User.cpp",
        //     0x5c20,
        //     transformId,
        //     static_cast<int>(m_data->m_Sex),
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[transformation] No transform definition for ID %d and gender %d. Character '%s' was not transformed.",
        //     transformId,
        //     static_cast<int>(m_data->m_Sex),
        //     GetName())
        L2_LOG_ERROR(
            Log, u"[transformation] No transform definition for ID %d and gender %d; character '%s' was not transformed.",
            transformId, static_cast<int>(m_data->m_Sex), GetName()
        );
        return false;
    }

    int previousTransformId = 0;
    if (m_data->m_transformID > 0 && m_transform->IsCursed()) {
        previousTransformId = m_data->m_transformID;
        DispelBySlot(ABNS_TRANSFORM, nullptr, -1, nullptr, SPET_CURSED, false);
    }
    if (m_data->m_transformID != transformId) {
        m_data->m_transformID = transformId;
        m_data->m_NeedUpdatePacketBitSet.SetBit(0x51);
    }

    if (!_OnTransform(broadcast)) {
        m_data->m_transformID = 0;
        m_data->m_NeedUpdatePacketBitSet.SetBit(0x51);
        m_transform = nullptr;
        SendSystemMessage(SystemMessageId::CANNOT_TRANSFORM_NOT_ENOUGH_SPACE);
        return false;
    }

    if (m_transform != nullptr) {
        m_data->m_bCanMove = m_transform->m_bCanMove;
    }
    if (m_transform->IsModeChange()) {
        Singleton<TalkChannelCache>::inst().ResetCache(GetServerId());
    }
    if (previousTransformId > 0) {
        CLogFormatter formatter;
        formatter.WriteLog2_1(0x1a2, this, nullptr, previousTransformId, 3, 0, 0, 0, 0, 0);
    }
    if (broadcast) {
        const FVector position = GetPos();
#if defined(_WIN32)
        const wchar_t* const accountName = reinterpret_cast<const wchar_t*>(m_sAccountName.data());
#else
        std::array<wchar_t, 16> accountNameBuffer{};
        const wchar_t* const accountName = CopyUtf16ToWide(m_sAccountName.data(), m_sAccountName.size(), accountNameBuffer);
#endif
        // Log.AddT(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
        //     L"%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,%s,%s,,,,",
        //     0x1a1,
        //     GetDBID(),
        //     GetAccountID(),
        //     runtime::Win64CvttDoubleToInt32(position.x),
        //     runtime::Win64CvttDoubleToInt32(position.y),
        //     runtime::Win64CvttDoubleToInt32(position.z),
        //     m_data->m_Race,
        //     m_data->m_Sex,
        //     m_data->m_nClass,
        //     m_data->m_nLevel,
        //     transformId,
        //     GetName(),
        //     accountName)
        Log.AddT(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
            u"%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,%s,%s,,,,",
            0x1a1, GetDBID(), GetAccountID(), runtime::Win64CvttDoubleToInt32(position.x),
            runtime::Win64CvttDoubleToInt32(position.y), runtime::Win64CvttDoubleToInt32(position.z), m_data->m_Race,
            m_data->m_Sex, m_data->m_nClass, m_data->m_nLevel, transformId, GetName(), accountName
        );
    }
    ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_TRANSFORM});
    return true;
}

bool User::CancelTransform(const int targetTransformId, const bool force, const SkillPumpEndType pumpEndType) {
    // Current L2Server 0x00b3e7c0.
    L2_GUARD_FUNCTION();

    L2_GUARD(m_TransformLock);
    CTransform* const transform = IsTransformed(TransformType::Max);
    if (transform == nullptr || (!force && transform->IsPureState())) {
        return false;
    }

    m_data->m_bCanMove = true;
    if (targetTransformId != 0 && targetTransformId != m_data->m_transformID) {
        return false;
    }

    const int collisionRadius =
        static_cast<int>(g_PCParamDB.GetCollisionRadius(m_data->m_Sex, m_nBaseClass, m_data->m_Race));
    const int collisionHeight =
        static_cast<int>(g_PCParamDB.GetCollisionHeight(m_data->m_Sex, m_nBaseClass, m_data->m_Race));
    if (!transform->SetCollision(this, collisionRadius, collisionHeight, true)) {
        return false;
    }

    m_data->m_transformID = 0;
    transform->OnCancelTransform(this);
    _OnCancelTransform();

    int reason = -1;
    switch (pumpEndType) {
        case SPET_TIMEOUT:
            reason = 4;
            break;
        case SPET_DISPEL:
            reason = 0;
            break;
        case SPET_DIE:
            reason = 1;
            break;
        case SPET_CURSED:
            reason = 3;
            break;
        case SPET_REPLACE:
            reason = 5;
            break;
        case SPET_ETC:
            reason = 2;
            break;
        case SPET_SELF_DISPEL:
            reason = 6;
            break;
        default:
            break;
    }

    CLogFormatter formatter{};
    formatter.WriteLog2_1(0x1a2, this, nullptr, targetTransformId, reason, 0, 0, 0, 0, 0);
    if (reason == -1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"CancelTransform() targetTransformID:[%d] "
        //     L"isCursedUser:[%d] pumpEndType:[%d] reason:[%d] "
        //     L"Name[%s]",
        //     targetTransformId,
        //     force ? 1 : 0,
        //     static_cast<int>(pumpEndType),
        //     reason,
        //     GetName())
        // L2_LOG_ERROR(Log,
        // L"[transformation] Cancel request: target %d, cursed flag %d, pump "
        // L"end type %d, reason %d, user '%s'.",
        //     targetTransformId,
        //     force ? 1 : 0,
        //     static_cast<int>(pumpEndType),
        //     reason,
        //     GetName())
        L2_LOG_ERROR(
            Log,
            u"[transformation] Cancel request: target %d, cursed flag %d, pump "
            u"end type %d, reason %d, user '%s'.",
            targetTransformId, force ? 1 : 0, static_cast<int>(pumpEndType), reason, GetName()
        );
    }
    ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_TRANSFORM});
    return true;
}

bool User::_OnTransform(const bool broadcast) {
    L2_GUARD_FUNCTION();

    DoNothing();
    const bool transformed = [&] {
        L2_GUARD(*m_lock);
        if (!m_transform->SetTransformData(this)) {
            return false;
        }
        if (!IsTargetable()) {
            SetTargetable(true, true);
        }
        PumpStartTransformSkill();
        return true;
    }();
    if (!transformed) {
        return false;
    }

    StopStore(false, true);
    GetController()->Stand(0);
    if (broadcast) {
        m_nParamChanged |= PCB_TRANSFORM;
    }
    ValidateHenna();
    SendItemList(false, false, nullptr);
    ValidateParameters(VB_SKILLLIST, false);
    ValidateChanged(VB_MAX);
    SendBasicActionList();

    if (m_transform->m_SpawnHeight > 0 && m_data->index != -1) {
        FVector position = GetPos();
        position.z = static_cast<double>(runtime::Win64CvttDoubleToInt32(position.z) + m_transform->m_SpawnHeight);
        CWorld::Inst().MoveTo(this, position, false);
    }
    CheckAbnormalVisualEffect();
    return true;
}

void User::_OnCancelTransform() {
    L2_GUARD_FUNCTION();

    StopMove();
    DoNothing();
    {
        L2_GUARD(*m_lock);
        SetOriginalBaseStat();
    }
    ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_TRANSFORM});
    PumpEndTransformSkill();
    ValidateHenna();
    SendItemList(false, false, nullptr);
    SendBasicActionList();
    ValidateChanged(VB_MAX);
}

void User::SendBasicActionList() {
    L2_GUARD_FUNCTION();

    if (m_data->GetWorldId() != g_nWorldId) {
        RaidAllowAction::Inst().SendActionList(this);
        return;
    }

    if (IsTransformed(TransformType::Max) != nullptr) {
        m_transform->SendActionList(this);
        return;
    }

    if (!IsOlympiadPlaying() && !m_PledgeGameUser.IsPlaying() && !m_PledgeGameUser.IsWaiting()) {
        g_UserBasicAction.SendList(this);
        return;
    }

    Singleton<WOlympiadDefaultSetting>::inst().SendActionList(this);
}

bool User::SendUserSubJobInfo(const SubJob::SubJobPacketType packetType) {
    // Current L2Server 0x00b063f0.
    L2_GUARD_FUNCTION();

    if (GetSocket() == nullptr) {
        return false;
    }

    int subJobCount = 1;
    if (m_data->m_nSubJob1Class > 0) {
        ++subJobCount;
    }
    if (m_data->m_nSubJob2Class > 0) {
        ++subJobCount;
    }
    if (m_data->m_nSubJob3Class > 0) {
        ++subJobCount;
    }

    std::array<char, 0x5000> packet;
    int packetLength = ::Assemble(
        packet.data(), 0x5000, "dddddc", static_cast<int>(m_data->m_Race), subJobCount, 0, m_data->m_nSubJob0Class,
        m_data->m_SubJobLevel[0], 0
    );

    if (m_data->m_nSubJob1Class > 0) {
        packetLength += ::Assemble(
            packet.data() + packetLength, 0x5000 - packetLength, "dddc", 1, m_data->m_nSubJob1Class,
            m_data->m_SubJobLevel[1], (m_data->m_DualClassID != 1) + 1
        );
    }
    if (m_data->m_nSubJob2Class > 0) {
        packetLength += ::Assemble(
            packet.data() + packetLength, 0x5000 - packetLength, "dddc", 2, m_data->m_nSubJob2Class,
            m_data->m_SubJobLevel[2], (m_data->m_DualClassID != 2) + 1
        );
    }
    if (m_data->m_nSubJob3Class > 0) {
        packetLength += ::Assemble(
            packet.data() + packetLength, 0x5000 - packetLength, "dddc", 3, m_data->m_nSubJob3Class,
            m_data->m_SubJobLevel[3], (m_data->m_DualClassID != 3) + 1
        );
    }

    GetSocket()->Send(
        "chcdb", 0xfe, 0xea, static_cast<int>(packetType), static_cast<int>(m_data->m_nClass), packetLength, packet.data()
    );
    return true;
}

void User::AcquireHennaSkill(const int hennaId) {
    L2_GUARD_FUNCTION();
    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr || !henna->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
        return;
    }

    for (const CSkillKey& skillKey : henna->m_HennaSkillList) {
        const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(skillKey, nullptr);
        if (skillInfo != nullptr) {
            AcquireSkill(skillInfo->m_nSkillId, skillInfo->m_nLevel, skillInfo->m_nSubLevel, false, true);
        }
    }
}

void User::DeleteAcquireHennaSkill(const int hennaId) {
    L2_GUARD_FUNCTION();
    if (hennaId == m_data->m_HennaId_1 || hennaId == m_data->m_HennaId_2 || hennaId == m_data->m_HennaId_3) {
        return;
    }

    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr || !henna->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
        return;
    }
    for (const CSkillKey& skillKey : henna->m_HennaSkillList) {
        const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(skillKey, nullptr);
        if (skillInfo != nullptr) {
            DeleteAcquireSkill(skillInfo->m_nSkillId);
        }
    }
}

void User::AcquireUnEquipHennaSkill(const int hennaId) {
    L2_GUARD_FUNCTION();
    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr || !henna->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
        return;
    }
    for (const CSkillKey& skillKey : henna->m_HennaUnequipSkillList) {
        const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(skillKey, nullptr);
        if (skillInfo != nullptr) {
            skillInfo->ActivateSkill(this, this, 0.0, nullptr, CSkillInfo::EAT_SUCCESS, false);
        }
    }
}

void User::ValidateHenna() {
    L2_GUARD_FUNCTION();

    m_SkillMod.InitializeHennaBonus();
    if (IsTransformed(TransformType::PureStat) == nullptr) {
        CStats accumulatedBonus;
        const int classId = static_cast<int>(m_data->m_nClass);
        const int normalHennaIds[] = {
            m_data->m_HennaId_1,
            m_data->m_HennaId_2,
            m_data->m_HennaId_3,
        };
        for (const int hennaId : normalHennaIds) {
            if (hennaId <= 0) {
                continue;
            }
            CHenna* const henna = g_HennaDB.Find(hennaId);
            if (henna != nullptr && henna->CanUse(classId, nullptr)) {
                accumulatedBonus += henna->m_HennaBonus;
                AcquireHennaSkill(hennaId);
            }
        }

        if (m_HennaId_premium > 0) {
            CHenna* const premium = g_HennaDB.Find(m_HennaId_premium);
            if (premium == nullptr || !premium->CanUse(classId, nullptr)) {
                AcquireUnEquipHennaSkill(m_HennaId_premium);
                DeleteAcquireHennaSkill(m_HennaId_premium);
            } else {
                accumulatedBonus += premium->m_HennaBonus;
                AcquireHennaSkill(m_HennaId_premium);
            }
        }

        for (std::size_t index = 0; index < std::size(accumulatedBonus.m_N); ++index) {
            const int original = m_data->m_OriginalStat.m_N[index];
            const int cappedBonus = accumulatedBonus.m_N[index] < 0x24 ? accumulatedBonus.m_N[index] : 0x24;
            const int resultingStat = original + cappedBonus > 1 ? original + cappedBonus : 1;
            m_SkillMod.m_HennaBonus.m_N[index] = resultingStat - original;
        }
    }
    SendUserHennaInfo(nullptr);
}

