WorldChatManager& WorldChatManager::Inst() {
    L2_GUARD_FUNCTION();
    if (m_WorldChatManager == nullptr) {
        m_WorldChatManager = new WorldChatManager;
    }
    return *m_WorldChatManager;
}

void WorldChatManager::ReserveSendChat(WorldChatData& data) {
    L2_GUARD_FUNCTION();
    L2_GUARD(m_lock);
    m_WorldChatQueue.push(data);
}

void WorldChatManager::ProcessSendChat() {
    L2_GUARD_FUNCTION();
    L2_GUARD(m_lock);
    if (m_WorldChatQueue.empty()) {
        return;
    }

    const WorldChatData data = m_WorldChatQueue.front();
    CSPointer<User> user = g_UserMap.FindObject(data.m_nUserID);
    if (!user) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Invalid user[sid:%d]",
        //     L"User.cpp",
        //     0x898a,
        //     data.m_nUserID)
        L2_LOG_ERROR(
            Log, u"[world chat] Cannot deliver queued message: user object %d is no longer available.", data.m_nUserID
        );
        m_WorldChatQueue.pop();
        return;
    }

    user->BroadcastToAllowedUser("cddSdS", 0x4a, data.m_nUserID, 0x19, data.m_sName, -1, data.m_Msg);

    std::wstring hostName;
    for (const char16_t* cursor = data.m_sName; *cursor != u'\0'; ++cursor) {
        hostName.push_back(static_cast<wchar_t>(*cursor));
    }
    // Log.Add(
    //     LOG_NORMAL,
    //     L"[WorldChat] Success Send Msg userid[%d] username[%s]",
    //     data.m_nUserID,
    //     hostName.c_str())
    L2_LOG_INFO(Log, u"[world chat] Delivered queued message for user %d ('%s').", data.m_nUserID, hostName.c_str());
    RelayClient::Inst()->SendWorldChatPacket(user.get(), data.m_Msg);
    m_WorldChatQueue.pop();
}

