void User::SendDB(const char* format, ...) const {
    L2_GUARD_FUNCTION();
    if (m_pSocket != nullptr && m_pSocket->GetRaidStatus() == URS_ON_RAID) {
        SystemMail::sendCriticalCallstack(mailServer);
        return;
    }

    const int worldId = CThreadManager::GetThreadID() < 16 ? m_data->m_nWorldId : g_nWorldId;
    runtime::process::SetCurrentWorldId(worldId);
    CDB::CWorldSetter worldSetter;

    va_list arguments;
    va_start(arguments, format);
    if (runtime::process::CurrentWorldId() < 1) {
        SystemMail::sendNotSetThreadLocalWorldID(mailServer);
    } else {
        db.m_pDBSockets[::LegacyCrtRand() & 1]->SendV(format, arguments);
    }
    va_end(arguments);
}

void User::SendDB(RQ_PROTOCOL protocol, RQ_EX_PROTOCOL extendedProtocol, network::IPacket& packet) const {
    L2_GUARD_FUNCTION();
    if (m_pSocket != nullptr && m_pSocket->GetRaidStatus() == URS_ON_RAID) {
        SystemMail::sendCriticalCallstack(mailServer);
        return;
    }

    const int worldId = CThreadManager::GetThreadID() < 16 ? m_data->m_nWorldId : g_nWorldId;
    runtime::process::SetCurrentWorldId(worldId);
    CDB::CWorldSetter worldSetter;
    if (runtime::process::CurrentWorldId() < 1) {
        SystemMail::sendNotSetThreadLocalWorldID(mailServer);
    } else {
        db.m_pDBSockets[::LegacyCrtRand() & 1]->Send(protocol, extendedProtocol, packet);
    }
}

