std::int64_t User::ExpInc(const std::int64_t experience, const bool applyBonus) {
    // Current L2Server 0x00b5eb44.
    L2_GUARD_FUNCTION();
    const std::int64_t result = CCreature::ExpInc(experience, false);
    if (!m_bEinhasadeTransformed) {
        if (!applyBonus && m_data->m_nKarma < 0 && experience > 0) {
            static_cast<void>(CCursedWeaponMgr::inst());
            if (m_nCursedWeaponClassId < 1) {
                const double vitalityBonus = GetVitalityExpBonus();
                const double karmaIncrease = g_PCParamDB.GetKarmaIncreaseAmount(m_data->m_nLevel);
                const int karmaDelta = runtime::Win64CvttDoubleToInt32(
                    (static_cast<double>(experience) / karmaIncrease) / (vitalityBonus * 120.0)
                );
                ChangeKarmaByDelta(karmaDelta, false);
                if (karmaDelta != 0) {
                    GetSocket()->SendSystemMessage_d(SystemMessageId::REPUTATION_CHANGED, m_data->m_nKarma);
                }
                SendETCBuffStatusInfo();
                SendStatusUpdate(VCP_CRIMINAL_RATE, 0, 0);
            }
        }
        m_UserStatData.AddUserStat2(UserStat::US_EXP, experience);
    }
    return result;
}

void User::UpdateTotalPeaceZoneTime() {
    // Current L2Server 0x00b17c9c.
    const std::int32_t started = runtime::raw_atomic::ExchangeI32(&m_nStartPeaceZoneTime, 0);
    if (started > 0) {
        m_nTotalPeaceZoneTime = runtime::AddInt32Wrapping(
            m_nTotalPeaceZoneTime, runtime::SubtractInt32Wrapping(runtime::crt::Time32Now(), started)
        );
    }
}

void User::CheckPeaceZoneTimeOnTimerExpired() {
    // Current L2Server 0x00b17cd0 has no guard frame.
    if (!AreaBasedRule::UpdateTimeChangePeaceZone(this)) {
        return;
    }
    if (m_AreaMod.m_bIsInPeaceField) {
        runtime::raw_atomic::ExchangeI32(&m_nStartPeaceZoneTime, runtime::crt::Time32Now());
    } else {
        UpdateTotalPeaceZoneTime();
    }
}

