void User::SetGuilty(char guilty) {
    L2_GUARD_FUNCTION();
    if (!g_bIsNonPKServer || guilty < 1) {
        m_data->m_NeedUpdatePacketBitSet.SetCharValue_IfModifed(m_data->m_cIsGuilty, guilty, 38);
        CacheMasterInfoToAll();
        return;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"[%S][%d] set guilty [%d] is called in non pk server",
    //     "User.cpp",
    //     0x13b7,
    //     static_cast<int>(guilty))
    L2_LOG_ERROR(Log, u"[PvP] Ignored guilty-state change to %d because this is a non-PK server.", static_cast<int>(guilty));
}

bool User::IsGuilty() { return m_data->m_cIsGuilty > 0; }

void User::SetKarma(int karma) {
    // Current L2Server 0x00b087c4, original owner User.cpp.
    L2_GUARD_FUNCTION();
    const int previousKarma = m_data->m_nKarma;
    if (karma < 0 && IsGuilty()) {
        m_data->m_nPKTimeStamp = 0;
        SetGuilty(0);
        runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
        m_bIsSkillViolet = false;
    }

    if (karma < -100000000) {
        karma = -100000000;
    }
    m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(m_data->m_nKarma, karma, 0x45);
    UnequipItemWhenBeChao(previousKarma);
    CacheMasterInfoToAll();
}

int User::CalcCriminalRate() {
    if (m_data->m_nKarma > 500) {
        SetKarma(500);
    }
    return m_bEinhasadeTransformed ? -999999 : m_data->m_nKarma;
}

