bool User::ValidateBaseHP() {
    L2_GUARD_FUNCTION();
    const double charismaBonus = std::sqrt(g_PCParamDB.GetParamBonus(PC_CHA_BONUS, m_data->m_Stat.m_N[7]));
    if (m_data->m_Race == ::RT_NONE) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] Race type (RT_NONE) error.",
        //     "User.cpp",
        //     0x5fe9)
        L2_LOG_ERROR(Log, "[stats] Cannot validate base HP: character race is RT_NONE.");
        return false;
    }

    const double constitutionBonus = ConBonusF();
    const double originalHP = m_data->m_dOrgHP;
    const double maximumHPPer = m_SkillMod.m_Mods[CCreatureSkillMod::MaxHP].m_Per;
    const double maximumHPDiff = m_SkillMod.m_Mods[CCreatureSkillMod::MaxHP].m_Diff;
    const double armorBonus = EquipedArmorsHpBonus();
    double maximumHP = armorBonus + constitutionBonus * charismaBonus * originalHP * maximumHPPer + maximumHPDiff;

    if (IsRidingOnGround()) {
        const double ridingMaximumHP = m_pRidingInfo->MaxHP();
        if (!FloatChecker::CheckValidation(ridingMaximumHP)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"FloatERR [%s] strider max hp is inval fp "
            //     L"input:%.5f(%p) fpclass:%04x",
            //     GetName(),
            //     ridingMaximumHP,
            //     DoubleBitsAsPointer(ridingMaximumHP),
            //     FloatChecker::FPClass(ridingMaximumHP))
            // L2_LOG_ERROR(Log,
            // L"[stats] Strider maximum HP is non-finite for '%s': %.5f (%p), "
            // L"FP class 0x%04x.",
            //     GetName(),
            //     ridingMaximumHP,
            //     DoubleBitsAsPointer(ridingMaximumHP),
            //     FloatChecker::FPClass(ridingMaximumHP))
            L2_LOG_ERROR(
                Log,
                u"[stats] Strider maximum HP is non-finite for '%s': %.5f (%p), "
                u"FP class 0x%04x.",
                GetName(), ridingMaximumHP, DoubleBitsAsPointer(ridingMaximumHP), FloatChecker::FPClass(ridingMaximumHP)
            );
            return false;
        }
        maximumHP += ridingMaximumHP;
    }

    if (!FloatChecker::CheckValidation(maximumHP)) {
        const int fpClass = FloatChecker::FPClass(maximumHP);
        const double oldMaximumHP = m_data->m_dBaseHP;
        const char16_t* const name = GetName();
        // Log.Add(
        //     LOG_ERROR,
        //     L"FloatERR [%s]1 inval fp input:%.5f(%p) "
        //     L"fpclass:%04x old:%.5f(%p)",
        //     name,
        //     maximumHP,
        //     DoubleBitsAsPointer(maximumHP),
        //     fpClass,
        //     oldMaximumHP,
        //     DoubleBitsAsPointer(oldMaximumHP))
        // L2_LOG_ERROR(Log,
        //     L"[stats] Maximum HP calculation is non-finite for '%s': new "
        //     L"%.5f (%p), FP class 0x%04x, old %.5f (%p).",
        //     name,
        //     maximumHP,
        //     DoubleBitsAsPointer(maximumHP),
        //     fpClass,
        //     oldMaximumHP,
        //     DoubleBitsAsPointer(oldMaximumHP))
        L2_LOG_ERROR(
            Log,
            u"[stats] Maximum HP calculation is non-finite for '%s': new "
            u"%.5f (%p), FP class 0x%04x, old %.5f (%p).",
            name, maximumHP, DoubleBitsAsPointer(maximumHP), fpClass, oldMaximumHP, DoubleBitsAsPointer(oldMaximumHP)
        );

        const double diagnosticDiff = m_SkillMod.m_Mods[CCreatureSkillMod::MaxHP].m_Diff;
        const double diagnosticPer = m_SkillMod.m_Mods[CCreatureSkillMod::MaxHP].m_Per;
        const double diagnosticOriginalHP = m_data->m_dOrgHP;
        const double diagnosticArmorFirst = EquipedArmorsHpBonus();
        const double diagnosticArmorSecond = EquipedArmorsHpBonus();
        const double diagnosticConFirst = ConBonusF();
        const double diagnosticConSecond = ConBonusF();
        const char16_t* const diagnosticName = GetName();
        // Log.Add(
        //     LOG_ERROR,
        //     L"FloatERR [%s]2 inval fp org:%.5f(%p) con:%d "
        //     L"c_bonus:%.5f(%p) m_per:%.5f(%p) "
        //     L"m_dif:%.5f(%p) arm:%.5f(%p)",
        //     diagnosticName,
        //     diagnosticOriginalHP,
        //     DoubleBitsAsPointer(diagnosticOriginalHP),
        //     m_data->m_Stat.m_N[2],
        //     diagnosticConSecond,
        //     DoubleBitsAsPointer(diagnosticConFirst),
        //     diagnosticPer,
        //     DoubleBitsAsPointer(diagnosticPer),
        //     diagnosticDiff,
        //     DoubleBitsAsPointer(diagnosticDiff),
        //     diagnosticArmorSecond,
        //     DoubleBitsAsPointer(diagnosticArmorFirst))
        // L2_LOG_ERROR(Log,
        //     L"[stats] Maximum HP inputs are non-finite for '%s': original "
        //     L"%.5f (%p), CON %d, bonus %.5f (%p), multiplier %.5f (%p), "
        //     L"difference %.5f (%p), armor %.5f (%p).",
        //     diagnosticName,
        //     diagnosticOriginalHP,
        //     DoubleBitsAsPointer(diagnosticOriginalHP),
        //     m_data->m_Stat.m_N[2],
        //     diagnosticConSecond,
        //     DoubleBitsAsPointer(diagnosticConFirst),
        //     diagnosticPer,
        //     DoubleBitsAsPointer(diagnosticPer),
        //     diagnosticDiff,
        //     DoubleBitsAsPointer(diagnosticDiff),
        //     diagnosticArmorSecond,
        //     DoubleBitsAsPointer(diagnosticArmorFirst))
        L2_LOG_ERROR(
            Log,
            u"[stats] Maximum HP inputs are non-finite for '%s': original "
            u"%.5f (%p), CON %d, bonus %.5f (%p), multiplier %.5f (%p), "
            u"difference %.5f (%p), armor %.5f (%p).",
            diagnosticName, diagnosticOriginalHP, DoubleBitsAsPointer(diagnosticOriginalHP), m_data->m_Stat.m_N[2],
            diagnosticConSecond, DoubleBitsAsPointer(diagnosticConFirst), diagnosticPer, DoubleBitsAsPointer(diagnosticPer),
            diagnosticDiff, DoubleBitsAsPointer(diagnosticDiff), diagnosticArmorSecond,
            DoubleBitsAsPointer(diagnosticArmorFirst)
        );
        return false;
    }

    const double publishedMaximumHP = 1.0 <= maximumHP ? maximumHP : 1.0;
    if (m_pPolymorphNPC != nullptr || maximumHP <= 150000.0) {
        m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dBaseHP, publishedMaximumHP, 8);
    } else {
        CTransform* const transform = IsCombatTransformed();
        const bool limitless =
            (transform != nullptr && m_transform->IsPureState()) || (m_ItemMod.m_bHpLimitBreak && maximumHP < 2147483647.0);
        if (limitless) {
            m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dBaseHP, publishedMaximumHP, 8);
            m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dBaseHP, publishedMaximumHP, 8);
        } else {
            m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dBaseHP, 150000.0, 8);
        }
    }
    return true;
}

bool User::ValidateBaseMP() {
    L2_GUARD_FUNCTION();
    const double charismaBonus = std::sqrt(g_PCParamDB.GetParamBonus(PC_CHA_BONUS, m_data->m_Stat.m_N[7]));
    const double mentalBonus = MenBonusF();
    const double originalMP = m_data->m_dOrgMP;
    const double maximumMPPer = m_SkillMod.m_Mods[CCreatureSkillMod::MaxMP].m_Per;
    const double maximumMPDiff = m_SkillMod.m_Mods[CCreatureSkillMod::MaxMP].m_Diff;
    const double armorBonus = static_cast<double>(EquipedArmorsMpBonus());
    double maximumMP = armorBonus + mentalBonus * charismaBonus * originalMP * maximumMPPer + maximumMPDiff;
    if (IsRidingOnGround()) {
        maximumMP += m_pRidingInfo->MaxMP();
    }

    m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dBaseMP, 1.0 <= maximumMP ? maximumMP : 1.0, 9);
    return true;
}

bool User::ValidateAttackSpeed() {
    L2_GUARD_FUNCTION();
    CCreature::ValidateAttackSpeed();

    double attackSpeed = m_data->m_dParam[VALIDATE::PATTACKSPEED];
    if (IsRidingWyvern()) {
        attackSpeed = static_cast<double>(m_data->m_nBaseParam[VALIDATE::PATTACKSPEED]);
    }
    if (IsRidingOnGround() && m_pRidingInfo->IsHungry()) {
        attackSpeed *= 0.5;
    }

    double clamped = 1500.0;
    if (attackSpeed <= clamped) {
        clamped = attackSpeed;
    }
    if (!(0.0 <= clamped)) {
        clamped = 0.0;
    }
    m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dParam[VALIDATE::PATTACKSPEED], clamped, 0x3b);
    return true;
}

bool User::ValidateSpeed() {
    L2_GUARD_FUNCTION();
    double speed = (static_cast<double>(m_data->m_nOrgParam[VALIDATE::SPEED]) * m_dGMSpeed *
                           m_SkillMod.m_Mods[CCreatureSkillMod::Speed].m_Per * m_AreaMod.m_dSpeedModByArea +
                       m_SkillMod.m_Mods[CCreatureSkillMod::Speed].m_Diff) *
        m_dSpeedModByWeight;

    if (IsCameraMode()) {
        m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dParam[VALIDATE::SPEED], 400.0, 0x3b);
        return false;
    }

    if (IsRidingOnGround()) {
        if (m_pRidingInfo->IsHungry()) {
            speed *= 0.5;
        }
        if (runtime::AddInt32Wrapping(m_data->m_nLevel, 10) <= m_pRidingInfo->Level()) {
            speed *= 0.5;
        }
    }

    m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dParam[VALIDATE::SPEED], speed, 0x3b);
    ValidateGradePenalty(VALIDATE::SPEED);

    double publishedSpeed = m_data->m_dParam[VALIDATE::SPEED];
    if (static_cast<std::int32_t>(m_data->m_moveType) == CMT_FLY) {
        if (publishedSpeed < 1.0) {
            publishedSpeed = 1.0;
        } else if (350.0 < publishedSpeed) {
            publishedSpeed = 350.0;
        }
    } else {
        if (!(1.0 <= publishedSpeed)) {
            publishedSpeed = 1.0;
        } else if (300.0 < publishedSpeed) {
            publishedSpeed = 300.0;
        }
    }
    m_data->m_NeedUpdatePacketBitSet.SetDoubleValue_IfModifed(m_data->m_dParam[VALIDATE::SPEED], publishedSpeed, 0x3b);
    return true;
}

double User::ValidateBaseHPAndGetLimitlessValue() {
    L2_GUARD_FUNCTION();
    const double charismaBonus = std::sqrt(g_PCParamDB.GetParamBonus(PC_CHA_BONUS, m_data->m_Stat.m_N[7]));
    const double constitutionBonus = ConBonusF();
    const double originalHP = m_data->m_dOrgHP;
    const double maximumHPPer = m_SkillMod.m_Mods[CCreatureSkillMod::MaxHP].m_Per;
    const double maximumHPDiff = m_SkillMod.m_Mods[CCreatureSkillMod::MaxHP].m_Diff;
    const double armorBonus = EquipedArmorsHpBonus();
    const double maximumHP = armorBonus + constitutionBonus * charismaBonus * originalHP * maximumHPPer + maximumHPDiff;
    ValidateBaseHP();
    return 1.0 <= maximumHP ? maximumHP : 1.0;
}

