bool User::ValidateOrgPAttack() {
    L2_GUARD_FUNCTION();
    const double armorValue = EquipedArmorsValidate(VALIDATE::PATTACK);
    const double weaponValue = EquipedWeaponValidate(VALIDATE::PATTACK);
    CSharedCreatureData* const data = m_data;
    data->m_nOrgParam[VALIDATE::PATTACK] = runtime::Win64CvttDoubleToInt32(armorValue + weaponValue);
    if (data->m_nOrgParam[VALIDATE::PATTACK] == 0 ||
        data->m_nOrgParam[VALIDATE::PATTACK] < data->m_nBaseParam[VALIDATE::PATTACK]) {
        data->m_nOrgParam[VALIDATE::PATTACK] = data->m_nBaseParam[VALIDATE::PATTACK];
    }
    if (IsRidingOnGround()) {
        data->m_nOrgParam[VALIDATE::PATTACK] =
            runtime::Win64CvttDoubleToInt32(m_pRidingInfo->Record(data->m_nLevel).mdPAttackOnRide);
    }
    CTransform* const transform = IsCombatTransformed();
    if (transform != nullptr && transform->IsPureState()) {
        data->m_nOrgParam[VALIDATE::PATTACK] = data->m_nBaseParam[VALIDATE::PATTACK];
    }
    ValidatePAttack();
    return true;
}

