bool User::ValidateOrgSpeed() {
    L2_GUARD_FUNCTION();
    // Current 00b1b1d0 publishes the selected base speed to both
    // m_nOrgParam[SPEED] (+0x331c) and m_nMoveTypeSpeed (+0x3330).
    // Equipment modifiers are applied only to m_nOrgParam[SPEED].
    const int moveType = static_cast<int>(m_data->m_MoveMode);
    const int environment = static_cast<int>(m_data->m_Environment);

    if (IsRiding()) {
        const PetDataSheet::Record& record = m_pRidingInfo->Record();
        const std::int32_t ridingSpeed = record.mSpeedOnRide[moveType][environment];
        m_data->m_nOrgParam[VALIDATE::SPEED] = ridingSpeed;
        m_data->m_nMoveTypeSpeed = ridingSpeed;
        ValidateSpeed();
        return true;
    }

    CTransform* const transform = IsTransformedExceptModeChange();
    if (transform != nullptr) {
        const double transformedSpeed = m_transform->m_commonData->orgSpeed[moveType][environment];
        m_data->m_nOrgParam[VALIDATE::SPEED] = runtime::Win64CvttDoubleToInt32(transformedSpeed);
        m_data->m_nMoveTypeSpeed =
            runtime::Win64CvttDoubleToInt32(m_transform->m_commonData->orgSpeed[moveType][environment]);
        ValidateSpeed();
        return true;
    }

    if (m_pPolymorphNPC == nullptr) {
        m_data->m_nOrgParam[VALIDATE::SPEED] = runtime::Win64CvttDoubleToInt32(g_PCParamDB.GetOrgSpeed(
            m_data->m_Sex, m_data->m_nClass, m_data->m_MoveMode, m_data->m_Environment, m_data->m_Race
        ));
        m_data->m_nMoveTypeSpeed = runtime::Win64CvttDoubleToInt32(g_PCParamDB.GetOrgSpeed(
            m_data->m_Sex, m_data->m_nClass, m_data->m_MoveMode, m_data->m_Environment, m_data->m_Race
        ));
    } else {
        m_data->m_nOrgParam[VALIDATE::SPEED] = m_pPolymorphNPC->m_pClassConst->m_SpeedByME[moveType][environment];
        m_data->m_nMoveTypeSpeed = m_pPolymorphNPC->m_pClassConst->m_SpeedByME[moveType][environment];
    }

    const std::int32_t armorValue = runtime::Win64CvttDoubleToInt32(EquipedArmorsValidate(VALIDATE::SPEED));
    CSharedCreatureData* const data = m_data;
    const std::int32_t weaponValue = runtime::Win64CvttDoubleToInt32(EquipedWeaponValidate(VALIDATE::SPEED));
    data->m_nOrgParam[VALIDATE::SPEED] = runtime::AddInt32Wrapping(
        data->m_nOrgParam[VALIDATE::SPEED], runtime::AddInt32Wrapping(weaponValue, armorValue)
    );
    ValidateSpeed();
    return true;
}

const char16_t* User::GetName() const {
    L2_GUARD_FUNCTION();
    return m_data->m_nWorldId == g_nWorldId ? m_data->Name() : m_sRaidName;
}

const char16_t* User::GetName2(User* const viewer) {
    L2_GUARD_FUNCTION();
    if (!m_PledgeGameUser.IsPlayer() && !m_PledgeGameUser.IsObserver()) {
        return GetName();
    }

    User* aliasViewer = viewer;
    if (aliasViewer == nullptr || (!aliasViewer->m_PledgeGameUser.IsPlayer() && !m_PledgeGameUser.IsObserver())) {
        aliasViewer = nullptr;
    }
    return m_PledgeGameUser.GetAliasName(aliasViewer);
}

CUserSocket* User::GetSocket() const { return m_pSocket; }

void User::SendDeleteObject(CObject* object, bool flag) {
    // Current L2Server.exe 0x00b42430.
    L2_GUARD_FUNCTION();
    if (object == nullptr) {
        return;
    }

    const std::uint32_t objectId = object->Id();
    if (m_spTarget.Sid() == objectId) {
        ChangeTarget(nullptr, CTR_DEFAULT);
        PushSerializedMessage(new CSerializedLostTargetMessage(this, object));
    }
    if (m_spActionTarget.Sid() == objectId) {
        GetController()->TargetOutOfSight(static_cast<int>(objectId));
        DoNothing();
    }

    const bool broadcastToTarget = object->IsNPC() && object->CastNPC()->m_bDespawnByScript;
    FOR_ALL_SUMMON_PET_IN_SUMMON_LIST(this, summon, {
        if (summon->m_spTarget.Sid() == objectId) {
            summon->ChangeTarget(nullptr, CTR_DEFAULT);
            summon->PushSerializedMessage(new CSerializedLostTargetMessage(summon, object));
        }
        if (summon->m_spActionTarget.Sid() == objectId) {
            summon->GetController()->TargetOutOfSight(static_cast<int>(objectId));
            g_npcserver.Send("cdd", 0x37, static_cast<int>(summon->Id()), 2);
        }

        CSummon* const deletedSummon = object->CastSummon();
        if (deletedSummon != nullptr && summon == deletedSummon && !flag) {
            return;
        }
    });

    GetSocket()->Send("cdc", 8, static_cast<int>(objectId), broadcastToTarget);
}

void User::SendETCBuffStatusInfo() {
    // Current L2Server 0x00b1cd98.
    L2_GUARD_FUNCTION();

    // std::uint8_t flags = m_bBlockAll ? 1U : 0U
    std::uint8_t flags =
        m_bBlockAll ? static_cast<unsigned>(PacketType::ESU_PROHIBITCHAT) : static_cast<unsigned>(PacketType::ESU_NONE);
    bool dangerZone = false;
    CAreaDB& areaDb = CAreaDB::inst();
    for (const AreaTypeEnum type : {AREAT_DAMAGE, AREAT_POISON, AREAT_SWAMP}) {
        CArea* const area = areaDb.FindAllArea(GetPos(), type);
        if (area != nullptr && area->IsOn(0) && area->m_bShowDangerZone) {
            dangerZone = true;
            break;
        }
    }

    int deathPenaltyLevel = GetAcquiredSkillLevel(0x38eb);
    if (deathPenaltyLevel == -1) {
        deathPenaltyLevel = 0;
    }
    if (dangerZone) {
        // flags |= 2U.
        flags |= static_cast<unsigned>(PacketType::ESU_DANGERZONE);
    }
    if (m_bKeepExp) {
        // flags |= 4U.
        flags |= static_cast<unsigned>(PacketType::ESU_KEEPEXP);
    }

    GetSocket()->Send(
        "ccdccccc", 0xf9, static_cast<int>(static_cast<std::uint8_t>(m_nEnergyCount)), m_nCurrentWeight,
        static_cast<int>(static_cast<std::uint8_t>(GetWeaponGradePenalty())),
        static_cast<int>(static_cast<std::uint8_t>(GetArmorGradePenalty())),
        static_cast<int>(static_cast<std::uint8_t>(deathPenaltyLevel)),
        static_cast<int>(static_cast<std::uint8_t>(m_SoulCount)), static_cast<int>(flags)
    );
}

CTrade* User::GetTrade() {
    CSPointer<CTrade> trade = g_TradeManager.GetTradeSP(m_nTrade);
    return trade.get();
}

void User::InitTrade() {
    L2_GUARD_FUNCTION();

    if (m_nTrade != 0) {
        g_TradeManager.DeleteTrade(m_nTrade);
        m_nTrade = 0;
    }

    if (GetItemManipulation() == 1) {
        LeaveItemManipulation();
    }
}

bool User::TradeStart(bool synchronize) {
    L2_GUARD_FUNCTION();

    CTrade* const trade = [&] {
        L2_GUARD(*m_lock);
        return GetTrade();
    }();
    if (trade == nullptr) {
        GetSocket()->Send("cd", 0x1c, 0);
        if (GetItemManipulation() == 1) {
            LeaveItemManipulation();
        }
        return false;
    }

    if (!synchronize) {
        trade->Canceled(this, false);
        return false;
    }

    CIOObject::SetTimeStamp(&m_nTradeModeTimeStamp);
    return trade->Request();
}

bool User::TradeItemAdd(const unsigned char* packet) {
    L2_GUARD_FUNCTION();

    if (m_data->m_StopMode == STP_STORE) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_OR_DESTROY_ITEMS_DURING_PRIVATE_STORE_OR_TRADE);
        return false;
    }

    CTrade* const trade = GetTrade();
    return trade != nullptr && trade->m_bIsStart && trade->RequestAddItems(packet, this);
}

void User::TradeCancel(bool notify) {
    L2_GUARD_FUNCTION();

    m_nTradeTimeStamp = 0;
    CTrade* const trade = GetTrade();
    if (trade != nullptr) {
        trade->Canceled(this, notify);
    }
}

void User::TradeDone() {
    L2_GUARD_FUNCTION();

    m_nTradeTimeStamp = 0;
    CTrade* const trade = GetTrade();
    if (trade != nullptr && !trade->PressDone(this)) {
        TradeCancel(false);
    }
}

void User::TradeEnd() {
    L2_GUARD_FUNCTION();

    m_nTradeTimeStamp = 0;
    CTrade* const trade = GetTrade();
    if (trade != nullptr) {
        trade->Done();
    }
}

bool User::IsNowTrade() {
    L2_GUARD_FUNCTION();

    CTrade* const trade = GetTrade();
    if (trade == nullptr || (trade->CheckTradeTimeout() && trade->Canceled(this, false))) {
        return false;
    }
    return trade->m_bIsStart;
}

bool User::SendAlchemySkillList() {
    // Current L2Server 0x00b4d1d8, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (m_lWaitItemJob == 1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"cannot send alchemy skill list while using warehouse")
        // Previous diagnostic inferred warehouse state from the wrong field:
        // L2_LOG_ERROR(Log, L"[alchemy] Skill list cannot be sent while a warehouse is open, request rejected.")
        L2_LOG_ERROR(Log, "[alchemy] Skill list request rejected: an item operation is pending.");
        return false;
    }

    protocol::S_AlchemySkillList response{};
    for (int type = 0; type < 2; ++type) {
        L2_GUARD(m_AlchemySkillsLock[type]);
        for (const auto& entry : m_AlchemySkills[type]) {
            const AcquiredAlchemySkillInfo& skill = entry.second;
            protocol::AlchemySkillServerInfo info{};
            info.nSkillId = skill.pSkillInfo->m_nSkillId;
            info.nLev = skill.pSkillInfo->m_nLevel;
            info.type = static_cast<char>(type);
            info.dRemainTime = skill.bMaster ? GetRemainReuseDelaySec(info.nSkillId, info.nLev, 0) : 0.0;
            response.skillInfoList.push_back(info);
        }
    }

    GetSocket()->Send(S_EX, S_EX_ALCHEMY_SKILL_LIST, response);
    return false;
}

bool User::CheckAlchemyJob() {
    // Current L2Server 0x00b338c4, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (m_data->m_nPrivateStoreType > 0) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_DURING_TRADE_STORE_OR_WORKSHOP);
        return false;
    }
    if (m_data->m_bIsInCombatMode) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_DURING_COMBAT);
        return false;
    }
    if (!IsItemUsable(0)) {
        if (!IsAlive() && m_data->m_bIsAlive == 0) {
            SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_WHILE_DEAD);
        }
        if (IsNowTrade()) {
            SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_DURING_TRADE_STORE_OR_WORKSHOP);
        }
        if (!m_SkillMod.m_bCanAct) {
            SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_WHILE_IMMOBILE);
        }
        return false;
    }
    if (IsFrozen(true)) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_WHILE_IMMOBILE);
        return false;
    }
    if (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing == true) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_WHILE_IMMOBILE);
        return false;
    }
    if (m_data->m_StopMode != STP_STAND) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ALCHEMY_WHILE_IMMOBILE);
        return false;
    }
    return m_lWaitVariation != 1;
}

namespace {

bool CalculateCurrentRollyBonus(
    const std::int64_t bonusBase, const std::int64_t fourthItemAmount, double& rewardMultiplier, double& bonusProbability
) {
    // Current L2Server 0x00b1a150. The only current caller supplies the
    // 10,000,000 constant stored at current .rdata 0x011f9e48.
    constexpr std::int64_t kMultiplierDivisor = 10000000;
    if (bonusBase <= 0 || fourthItemAmount <= 0) {
        return false;
    }
    const std::int64_t product = runtime::MultiplyInt64Wrapping(fourthItemAmount, bonusBase);
    if (product < 0) {
        return false;
    }
    rewardMultiplier = std::min(2.0, static_cast<double>(product / kMultiplierDivisor));
    bonusProbability = std::min(0.49, static_cast<double>(fourthItemAmount) / 1000.0);
    return true;
}

} // namespace

bool User::TryRollyCube(std::list<protocol::ItemServerInfo>& itemInfoList) {
    // Current L2Server 0x00b50784, original owner User.cpp.
    L2_GUARD_FUNCTION();

    const auto sendBusyResult = [this]() {
        protocol::S_AlchemyTryMixCube response{};
        // response.nSuccessInfo = 6.
        response.nSuccessInfo = AlchemyConst::ARRT_FAIL_INVALID_ACTION;
        GetSocket()->Send(S_EX, S_EX_TRY_MIX_CUBE, response);
        if (m_lWaitItemJob == 1) {
            SendSystemMessage(SystemMessageId::EXPERIMENT_FAILED_RETRY);
        }
        return false;
    };
    if (!CheckAlchemyJob()) {
        return sendBusyResult();
    }
    if (runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 1) == 1) {
        return sendBusyResult();
    }

    const auto sendFailure = [this](const char result) {
        runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
        protocol::S_AlchemyTryMixCube response{};
        response.nSuccessInfo = result;
        GetSocket()->Send(S_EX, S_EX_TRY_MIX_CUBE, response);
        SendSystemMessage(SystemMessageId::EXPERIMENT_FAILED_RETRY);
        return false;
    };

    if (m_nAlchemyRollyLev == 0 || m_nAlchemyRollySkillId == 0) {
        if (IsBuilder() && g_L2ServerType == L2ServerType::DEV) {
            SendSystemMessage(SystemMessageId::CREATE_ITEM_SKILL_MISSING_OR_LEVEL_TOO_LOW);
        }
        // return sendFailure(4)
        return sendFailure(AlchemyConst::ARRT_FAIL_SKILL_INVALID);
    }

    std::array<ItemManip, 100> requests{};
    int requestCount = 0;
    std::int64_t totalDefaultPrice = 0;
    for (const protocol::ItemServerInfo& itemInfo : itemInfoList) {
        CItem* const item = ItemSmartIdManager()->GetObjectW(static_cast<std::uint32_t>(itemInfo.nItemServerId));
        if (item == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[ALCHEMY]TryRollyCube() invalid item")
            L2_LOG_ERROR(
                Log, u"[alchemy] Rolly-cube request for character %u references missing item server ID %d.", GetDBID(),
                itemInfo.nItemServerId
            );
            // return sendFailure(3)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_INVALID);
        }

        const int sharedItemClassId = item->m_data->m_nClassID;
        if (CItemRestrict::Inst().CheckItemRestrict(sharedItemClassId)) {
            // Current 0x00b50a08 leaves m_lWaitItemJob set and emits no
            // response on this item-restrict rejection path.
            return false;
        }
        if (!item->IsAccessary() && !item->IsArmor() && !item->IsWeapon() && !item->IsAsset() && !item->IsEtcItem()) {
            SendSystemMessage(SystemMessageId::ITEM_IS_NOT_COMBINATION_MATERIAL);
            // return sendFailure(3)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_INVALID);
        }
        if (item->m_const->m_nDefaultPrice == 0) {
            SendSystemMessage(SystemMessageId::ITEM_IS_NOT_COMBINATION_MATERIAL);
            // return sendFailure(3)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_INVALID);
        }
        if (g_AlchemyDB.IsRollyReward(item->GetClassId()) || item->m_data->GetLocked() != 0) {
            SendSystemMessage(SystemMessageId::ITEM_IS_NOT_COMBINATION_MATERIAL);
            // return sendFailure(3)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_INVALID);
        }
        if (item->m_data->m_nCount == 0 || item->m_data->m_nCount < itemInfo.nAmount ||
            g_AlchemyDB.m_nRollyAmountCriterion < itemInfo.nAmount) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[ALCHEMY]TryRollyCube() item amount has problem")
            L2_LOG_ERROR(
                Log,
                u"[alchemy] Rolly-cube item %u has amount %I64d, but character %u requested %I64d; configured per-item "
                u"limit is %I64d.",
                item->GetDBID(), item->m_data->m_nCount, GetDBID(), itemInfo.nAmount, g_AlchemyDB.m_nRollyAmountCriterion
            );
            // return sendFailure(2)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_AMOUNT);
        }
        if ((item->m_itemOption.itemOptionKey.variationOption1 > 0 &&
                item->m_itemOption.itemOptionKey.variationOption2 > 0) ||
            item->m_data->m_nDamaged > 0) {
            SendSystemMessage(SystemMessageId::CANNOT_COMBINE_ENCHANTED_OR_AUGMENTED_ITEMS);
            // return sendFailure(3)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_INVALID);
        }

        requests[requestCount].mCount = runtime::NegateInt64Wrapping(itemInfo.nAmount);
        requests[requestCount].mClassId = item->GetClassId();
        ++requestCount;
        totalDefaultPrice = runtime::AddInt64Wrapping(
            totalDefaultPrice, runtime::MultiplyInt64Wrapping(item->m_const->m_nDefaultPrice, itemInfo.nAmount)
        );
        if (totalDefaultPrice < 1) {
            // return sendFailure(2)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_AMOUNT);
        }
    }

    std::int64_t baseItemDefaultPrice = g_AlchemyDB.m_nRollyBaseItemDP;
    std::int64_t rewardAmount = 0;
    if (Alchemy_LollyCube::CalcRewardItemCountByPushItem(
            &requestCount, &baseItemDefaultPrice, &totalDefaultPrice, &rewardAmount
        ) == 0) {
        // return sendFailure(2)
        return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_AMOUNT);
    }

    auto* const atomicResult = new AtomicAlchemyResult(
        Id(),
        // 0,
        AlchemyConst::AT_ROLLY, m_nAlchemyRollySkillId
    );
    // char baseRewardType = 0.
    char baseRewardType = AlchemyConst::ALRRT_NORMAL_SUCCESS;
    int effectSkillId = 0;
    // char successInfo = 0.
    char successInfo = AlchemyConst::ARRT_SUCCESS_NORMAL;
    if (requestCount == 4) {
        double rewardMultiplier = 0.0;
        double bonusProbability = 0.0;
        const std::int64_t fourthItemAmount = runtime::NegateInt64Wrapping(requests[3].mCount);
        if (!CalculateCurrentRollyBonus(10000000, fourthItemAmount, rewardMultiplier, bonusProbability)) {
            // This is the current overflow-only leak path: the freshly
            // allocated job is not destroyed before the ordinary result-2
            // response. Valid configured amounts cannot reach it.
            // return sendFailure(2)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_AMOUNT);
        }
        if (rewardMultiplier != 0.0 && ::genrand64_real1() * 1.0 + 0.0 < bonusProbability) {
            rewardAmount = runtime::Win64CvttDoubleToInt64(
                static_cast<double>(rewardAmount) * rewardMultiplier + static_cast<double>(rewardAmount)
            );
            // baseRewardType = 1.
            baseRewardType = AlchemyConst::ALRRT_MULTI_SUCCESS;
        }

        AlchemyResultStructures::AlchemyOutputBase* const outputBase =
            g_AlchemyDB.GetCorrectRollyOutput(requests[3].mClassId, m_nAlchemyRollyLev);
        if (outputBase == nullptr || outputBase->m_Type != AlchemyResultStructures::AOT_ROLLY) {
            if (outputBase != nullptr) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[ALCHEMY]TryRollyCube has problem, recipe is not rolly type")
                L2_LOG_ERROR(
                    Log, u"[alchemy] Rolly-cube output for character %u has recipe type %d instead of %d.", GetDBID(),
                    static_cast<int>(outputBase->m_Type), static_cast<int>(AlchemyResultStructures::AOT_ROLLY)
                );
            }
            atomicResult->Destroy();
            // return sendFailure(3)
            return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_INVALID);
        }

        auto* const output = static_cast<AlchemyResultStructures::AlchemyRollyOutput*>(outputBase);
        if (::genrand64_real1() * 100.0 + 0.0 < output->m_dProb) {
            requests[4].mCount = output->m_Item.nAmount;
            requests[4].mClassId = output->m_Item.nItemClassId;
            requestCount = 5;
            effectSkillId = g_AlchemyDB.m_pAlchemyRollyRecipe->m_nSuccessEffectId;
            // successInfo = 1.
            successInfo = AlchemyConst::ARRT_SUCCESS_RANDOM;
            atomicResult->AddRollyRewardInfo(
                // 2,
                AlchemyConst::ALRRT_RANDOM_SUCCESS, output->m_Item.nItemClassId, output->m_Item.nAmount
            );
        }
    }

    atomicResult->AddRollyRewardInfo(baseRewardType, g_AlchemyDB.m_nRollyBaseItemID, rewardAmount);
    atomicResult->m_nEffectSkillId = effectSkillId;
    atomicResult->m_nSuccessInfo = successInfo;
    if (rewardAmount > 0) {
        requests[requestCount].mCount = rewardAmount;
        requests[requestCount].mClassId = g_AlchemyDB.m_nRollyBaseItemID;
        ++requestCount;
    }

    if (!ManipuateAlchemyItems(requests.data(), requestCount, atomicResult)) {
        atomicResult->Destroy();
        // return sendFailure(2)
        return sendFailure(AlchemyConst::ARRT_FAIL_ITEM_AMOUNT);
    }

    CLogFormatter formatter;
    formatter.WriteLog1(
        0x233d, this, nullptr, nullptr, nullptr, nullptr, m_nAlchemyRollyLev, effectSkillId != 0, requests[4].mClassId,
        requests[4].mCount, requests[5].mClassId, requests[5].mCount, 0
    );

    const int logZ = runtime::Win64CvttDoubleToInt32(GetPos().z);
    const int logY = runtime::Win64CvttDoubleToInt32(GetPos().y);
    const int logX = runtime::Win64CvttDoubleToInt32(GetPos().x);
    const std::u16string userName = std::u16string(GetName());
    const std::uint32_t accountId = GetAccountID();
    const std::uint32_t userDbId = GetDBID();
    formatter.WriteLog(
        0x233f, userDbId, accountId, 0, 0, logX, logY, logZ, nullptr, nullptr, nullptr, requests[0].mClassId,
        requests[0].mCount, requests[1].mClassId, requests[1].mCount, requests[2].mClassId, requests[2].mCount,
        requests[3].mClassId, requests[3].mCount, 0, 0, userName.c_str(), m_sAccountName.data(), nullptr, nullptr, 0
    );
    PledgeMissionCheckAndAddCount(PledgeMission::PMGT_ITEM_DISASSEMBLE, 0, 1);
    return false;
}

bool User::TryAlchemyConversion(
    const int skillId, const int skillLevel, std::list<protocol::ItemInfo>& materialList, int tryCount
) {
    // Current L2Server 0x00b510b8, original owner User.cpp.
    L2_GUARD_FUNCTION();

    const auto sendResponse = [this](const char result) {
        protocol::S_AlchemyConversion response{};
        response.nSuccessInfo = result;
        GetSocket()->Send(S_EX, S_EX_REQUEST_ALCHEMY_CONVERSION, response);
    };
    const auto sendBusyResult = [this, &sendResponse]() {
        // sendResponse(4)
        sendResponse(AlchemyConst::ACT_FAIL_INVALID_ACTION);
        if (m_lWaitItemJob == 1) {
            SendSystemMessage(SystemMessageId::EXPERIMENT_FAILED_RETRY);
        }
        return false;
    };

    if (!CheckAlchemyJob() || tryCount < 1) {
        return sendBusyResult();
    }
    if (runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 1) == 1) {
        return sendBusyResult();
    }

    const auto sendFailure = [this, &sendResponse](const char result) {
        // Current 0x00b5176b publishes the response while the wait flag
        // is still set, then releases that flag.
        sendResponse(result);
        runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
        return false;
    };

    if (materialList.empty()) {
        // Current 0x00b51197 sends result 4 but leaves the
        // item-job wait flag set on this path.
        // sendResponse(4)
        sendResponse(AlchemyConst::ACT_FAIL_INVALID_ACTION);
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ALCHEMY]TryAlchemyConversion lMaterial is empty")
        L2_LOG_ERROR(
            Log, u"[alchemy] Conversion request for character %u and skill %d has no materials.", GetDBID(), skillId
        );
        return false;
    }
    for (const protocol::ItemInfo& material : materialList) {
        if (CItemRestrict::Inst().CheckItemRestrict(material.nItemClassId)) {
            // Current 0x00b5124b emits neither a response nor a wait reset.
            return false;
        }
    }

    const CSkillInfo* skillInfo = nullptr;
    {
        L2_GUARD(m_AlchemySkillsLock[1]);
        const auto found = m_AlchemySkills[1].find(skillId);
        if (found == m_AlchemySkills[1].end()) {
            if (g_L2ServerType == L2ServerType::DEV && IsBuilder()) {
                std::array<char16_t, 100> message{};
                FormatUtf16To(message.data(), message.size(), u"dont have [%d] alchemy conversion skill!", skillId);
                GetSocket()->SendSystemMessage(u"SYS", message.data());
            }
        } else if (found->second.pSkillInfo == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[ALCHEMY]TryAlchemyConversion skillInfo is null")
            L2_LOG_ERROR(
                Log, u"[alchemy] Conversion skill %d for character %u has no skill definition.", skillId, GetDBID()
            );
        } else {
            if (found->second.bMaster && tryCount != 1) {
                tryCount = 1;
            }
            if (found->second.pSkillInfo->m_nLevel < skillLevel) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[ALCHEMY]TryAlchemyConversion fail, skill lv has problem!!")
                L2_LOG_ERROR(
                    Log, u"[alchemy] Character %u requested conversion skill %d at level %d, but owns level %d.", GetDBID(),
                    skillId, skillLevel, found->second.pSkillInfo->m_nLevel
                );
            } else {
                skillInfo = found->second.pSkillInfo;
            }
        }
    }
    if (skillInfo == nullptr) {
        // return sendFailure(3)
        return sendFailure(AlchemyConst::ACT_FAIL_SKILL);
    }

    const double remainReuseDelay = GetRemainReuseDelaySec(skillId, skillInfo->m_nLevel, 0);
    if (remainReuseDelay > 0.0) {
        SendRemainTime(
            runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(remainReuseDelay), 1), EST_SKILLID, skillId,
            skillInfo->m_nLevel, skillInfo->m_nSubLevel, runtime::Win64CvttDoubleToInt32(skillInfo->m_nReuseDelay)
        );
        // return sendFailure(3)
        return sendFailure(AlchemyConst::ACT_FAIL_SKILL);
    }

    std::int64_t effectiveTryCount = tryCount;
    for (const protocol::ItemInfo& material : materialList) {
        const std::int64_t ownedAmount = HasItem(static_cast<std::uint32_t>(material.nItemClassId));
        if (ownedAmount == 0) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[ALCHEMY]TryConversion, own item amount = 0")
            L2_LOG_ERROR(
                Log, u"[alchemy] Character %u owns none of material class %d required by conversion skill %d.", GetDBID(),
                material.nItemClassId, skillId
            );
            // return sendFailure(2)
            return sendFailure(AlchemyConst::ACT_FAIL_ITEM);
        }

        const std::int64_t requiredAmount = runtime::MultiplyInt64Wrapping(material.nAmount, effectiveTryCount);
        if (ownedAmount < requiredAmount) {
            const std::int64_t availableTryCount = runtime::Win64CvttDoubleToInt64(
                std::floor(static_cast<double>(ownedAmount) / static_cast<double>(material.nAmount))
            );
            if (availableTryCount < effectiveTryCount) {
                effectiveTryCount = availableTryCount;
            }
            if (effectiveTryCount < 1) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[ALCHEMY]TryConversion, amount boundary has problem")
                L2_LOG_ERROR(
                    Log,
                    u"[alchemy] Material class %d cannot satisfy one conversion attempt for character %u: owned %I64d, "
                    u"required per attempt %I64d.",
                    material.nItemClassId, GetDBID(), ownedAmount, material.nAmount
                );
                // return sendFailure(2)
                return sendFailure(AlchemyConst::ACT_FAIL_ITEM);
            }
        }

        CItem* const item = static_cast<CItem*>(g_ObjectDB.GetObjectW(material.nItemClassId, false));
        if (item == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[ALCHEMY]TryConversion() invalid item")
            L2_LOG_ERROR(
                Log, u"[alchemy] Conversion request for character %u references missing material object %d.", GetDBID(),
                material.nItemClassId
            );
            // return sendFailure(2)
            return sendFailure(AlchemyConst::ACT_FAIL_ITEM);
        }
        if (item->m_data->GetLocked() != 0) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[ALCHEMY]TryConversion() Locked item")
            L2_LOG_ERROR(
                Log, u"[alchemy] Conversion request for character %u uses locked material object %d.", GetDBID(),
                material.nItemClassId
            );
            // return sendFailure(2)
            return sendFailure(AlchemyConst::ACT_FAIL_ITEM);
        }
    }

    std::array<ItemManip, 100> requests{};
    int requestCount = 0;
    for (const protocol::ItemInfo& material : materialList) {
        requests[requestCount].mClassId = material.nItemClassId;
        requests[requestCount].mCount =
            runtime::NegateInt64Wrapping(runtime::MultiplyInt64Wrapping(material.nAmount, effectiveTryCount));
        ++requestCount;
    }

    AlchemyResultStructures::AlchemyOutputBase* const outputBase =
        g_AlchemyDB.GetCorrectConvOutput(skillId, skillLevel, materialList);
    if (outputBase == nullptr || outputBase->m_Type != AlchemyResultStructures::AOT_CONVERSION) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ALCHEMY]alchemy conversion fail, invalid recipe or invalid materials")
        L2_LOG_ERROR(
            Log, u"[alchemy] No conversion recipe matched skill %d level %d and the supplied materials for character %u.",
            skillId, skillLevel, GetDBID()
        );
        // return sendFailure(3)
        return sendFailure(AlchemyConst::ACT_FAIL_SKILL);
    }

    auto* const output = static_cast<AlchemyResultStructures::AlchemyConvOutput*>(outputBase);
    int successCount = 0;
    int failCount = 0;
    for (std::int64_t index = 0; index < effectiveTryCount; ++index) {
        if (output->m_dProb <= ::genrand64_real1() * 100.0 + 0.0) {
            ++failCount;
        } else {
            ++successCount;
        }
    }

    if (successCount > 0) {
        requests[requestCount].mClassId = output->m_successItem.nItemClassId;
        requests[requestCount].mCount = runtime::MultiplyInt64Wrapping(output->m_successItem.nAmount, successCount);
        ++requestCount;
    }
    if (failCount > 0) {
        requests[requestCount].mClassId = output->m_failItem.nItemClassId;
        requests[requestCount].mCount = runtime::MultiplyInt64Wrapping(output->m_failItem.nAmount, failCount);
        ++requestCount;
    }

    auto* const atomicResult = new AtomicAlchemyResult(
        Id(),
        // 1,
        AlchemyConst::AT_CONV, skillId
    );
    atomicResult->m_nEffectSkillId = successCount == 0 ? output->m_nFailEffect : output->m_nSuccessEffect;
    // atomicResult->m_nSuccessInfo = 0.
    atomicResult->m_nSuccessInfo = AlchemyConst::ACT_SUCCESS;
    atomicResult->SetConvRewardInfo(successCount, failCount);
    if (!ManipuateAlchemyItems(requests.data(), requestCount, atomicResult)) {
        atomicResult->Destroy();
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ALCHEMY]TryAlchemyConversion, ManipulateAlchemyItem has problem")
        L2_LOG_ERROR(
            Log, u"[alchemy] Item manipulation failed for character %u, conversion skill %d, and %d item entries.",
            GetDBID(), skillId, requestCount
        );
        // return sendFailure(2)
        return sendFailure(AlchemyConst::ACT_FAIL_ITEM);
    }

    CLogFormatter formatter;
    formatter.WriteLog1(
        0x233e, this, nullptr, nullptr, nullptr, nullptr, skillId, skillLevel, successCount, failCount, 0, 0, 0
    );
    return true;
}

bool User::CheckEnsoulJob() {
    // Current L2Server 0x00b33a9c, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (m_data->m_nPrivateStoreType > 0) {
        SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_DURING_PRIVATE_STORE_OR_WORKSHOP);
        return false;
    }
    if (m_data->m_bIsInCombatMode) {
        SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_DURING_COMBAT);
        return false;
    }
    if (!IsItemUsable(0)) {
        if (!IsAlive() && m_data->m_bIsAlive == 0) {
            SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_WHILE_DEAD);
        }
        if (IsNowTrade()) {
            SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_DURING_TRADE);
        }
        if (!m_SkillMod.m_bCanAct) {
            SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_WHILE_FROZEN);
        }
        return false;
    }
    if (IsFrozen(true)) {
        SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_WHILE_FROZEN);
        return false;
    }
    if (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing == true) {
        SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_WHILE_FISHING);
        return false;
    }
    if (m_data->m_StopMode != STP_STAND) {
        SendSystemMessage(SystemMessageId::CANNOT_APPLY_SOUL_CRYSTAL_WHILE_SITTING);
        return false;
    }
    if (m_lWaitVariation == 1) {
        SendSystemMessage(SystemMessageId::ANOTHER_OPERATION_IN_PROGRESS);
        return false;
    }
    return true;
}

bool User::OnEnsoulTry(const int targetItemSid, std::vector<EnsoulTryData>& ensoulTryData) {
    // Current L2Server 0x00b4d460, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (!CheckEnsoulJob()) {
        GetSocket()->Send("chc", 0xfe, 0x181, 0);
        if (m_lWaitItemJob == 1) {
            SendSystemMessage(SystemMessageId::PREVIOUS_REQUEST_NOT_COMPLETED);
        }
        return false;
    }
    if (runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 1) == 1) {
        GetSocket()->Send("chc", 0xfe, 0x181, 0);
        if (m_lWaitItemJob == 1) {
            SendSystemMessage(SystemMessageId::PREVIOUS_REQUEST_NOT_COMPLETED);
        }
        return false;
    }

    CItem* const targetItem = m_inv.GetByServerID(targetItemSid);
    if (targetItem != nullptr && !CItemRestrict::Inst().CheckItemRestrict(targetItem->GetClassId())) {
        if (targetItem->m_data->m_hLocked == 0) {
            std::array<ItemManip, 100> requests{};
            int requestCount = 0;
            std::map<int, int> ensoulInfo[3];
            std::array<int, 3> currentSlotIndex{-1,
                static_cast<int>(targetItem->m_mEnsoulInfo[EnsoulItem::EIST_NORMAL].size()),
                static_cast<int>(targetItem->m_mEnsoulInfo[EnsoulItem::EIST_BM].size())};

            bool valid = true;
            for (const EnsoulTryData& tryData : ensoulTryData) {
                const int slotType = static_cast<int>(tryData.m_slotType);
                const int slotIndex = tryData.m_nSlotIndex;
                valid = false;
                if (currentSlotIndex[slotType] <= slotIndex) {
                    if (slotIndex - currentSlotIndex[slotType] > 1) {
                        break;
                    }
                    currentSlotIndex[slotType] = slotIndex;
                }
                if (!targetItem->CheckEnsoulSlotIndex(tryData.m_slotType, slotIndex)) {
                    break;
                }

                CItem* const stoneItem = m_inv.GetByServerID(tryData.m_nStoneItemID);
                if (stoneItem == nullptr || CItemRestrict::Inst().CheckItemRestrict(stoneItem->GetClassId())) {
                    break;
                }

                const auto stonePosition = g_mEnsoulStoneData.find(static_cast<std::int64_t>(stoneItem->GetClassId()));
                if (stonePosition == g_mEnsoulStoneData.end() || stonePosition->second == nullptr) {
                    break;
                }
                EnsoulStoneData* const stoneData = stonePosition->second;
                if (!stoneData->CheckType(tryData.m_slotType) || !stoneData->CheckOption(tryData.m_nOptionID)) {
                    break;
                }

                const auto optionPosition = g_mEnsoulOptionData.find(tryData.m_nOptionID);
                if (optionPosition == g_mEnsoulOptionData.end() || optionPosition->second == nullptr) {
                    break;
                }

                const auto feePosition = g_EnsoulFeeData.find(targetItem->m_const->GetCrystalType());
                if (feePosition == g_EnsoulFeeData.end()) {
                    break;
                }
                EnsoulFeeData* const feeData = feePosition->second;

                bool replacing = false;
                const auto currentOption = targetItem->m_mEnsoulInfo[slotType].find(slotIndex);
                if (currentOption != targetItem->m_mEnsoulInfo[slotType].end() && currentOption->second != nullptr &&
                    currentOption->second->m_nId > 0) {
                    replacing = true;
                }

                EnsoulFeeData::FeeItemVector* fees = nullptr;
                if (tryData.m_slotType == EnsoulItem::EIST_NORMAL) {
                    fees = replacing ? &feeData->m_vReFeeNormal : &feeData->m_vFeeNormal;
                } else if (tryData.m_slotType == EnsoulItem::EIST_BM) {
                    fees = replacing ? &feeData->m_vReFeeBM : &feeData->m_vFeeBM;
                }

                int feeIndex = slotIndex - 1;
                if (fees != nullptr && fees->size() <= static_cast<std::size_t>(feeIndex)) {
                    feeIndex = -1;
                }
                if (feeIndex < 0) {
                    break;
                }
                EnsoulFeeItemData* const fee = runtime::CheckedVectorAt((*fees), static_cast<std::size_t>(feeIndex));
                if (fee == nullptr) {
                    break;
                }

                bool stoneFound = false;
                bool feeFound = false;
                for (int index = 0; index < requestCount; ++index) {
                    if (requests[index].mClassId == stoneData->m_nItemType) {
                        requests[index].mClassId = static_cast<int>(stoneData->m_nItemType);
                        requests[index].mCount = runtime::AddInt64Wrapping(requests[index].mCount, 1);
                        stoneFound = true;
                    } else if (requests[index].mClassId == fee->m_nFeeItemType) {
                        requests[index].mClassId = fee->m_nFeeItemType;
                        requests[index].mCount = runtime::AddInt64Wrapping(
                            requests[index].mCount, static_cast<std::int64_t>(fee->m_nFeeItemCount)
                        );
                        feeFound = true;
                    }
                }
                if (!stoneFound) {
                    requests[requestCount].mClassId = static_cast<int>(stoneData->m_nItemType);
                    requests[requestCount].mCount = 1;
                    ++requestCount;
                }
                if (!feeFound) {
                    requests[requestCount].mClassId = fee->m_nFeeItemType;
                    requests[requestCount].mCount = fee->m_nFeeItemCount;
                    ++requestCount;
                }

                ensoulInfo[slotType].emplace(slotIndex, tryData.m_nOptionID);
                PledgeMissionCheckAndAddCount(PledgeMission::PMGT_ITEM_ENSOUL_TRY, stoneItem->GetClassId(), 1);
                valid = true;
            }

            const bool optionValid = targetItem->CheckEnsoulOption(ensoulInfo);
            if (valid && optionValid) {
                const bool enoughItems = [&] {
                    L2_READ_GUARD(m_inv);
                    bool enoughItems = true;
                    for (int index = 0; index < requestCount; ++index) {
                        if (m_inv.GetItemAmount(requests[index].mClassId, 0, true) <
                            static_cast<int>(requests[index].mCount)) {
                            enoughItems = false;
                            break;
                        }
                        requests[index].mCount = runtime::NegateInt64Wrapping(requests[index].mCount);
                    }
                    return enoughItems;
                }();

                if (enoughItems) {
                    EtcManiEnsoul manipulation(targetItem->GetDBID(), GetDBID(), GetServerId(), ensoulInfo);
                    CPacketHelperEx<20480> packet;
                    manipulation.Assemble(packet);
                    if (ManipuateEnsoulItems(requests.data(), requestCount, packet, nullptr)) {
                        return true;
                    }
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[Ensoul]TryEnsoul, "
                    //     L"ManipulateEnsoulItems has problem")
                    L2_LOG_ERROR(
                        Log, u"[ensoul] Item manipulation failed while applying options to item %d for character %u.",
                        targetItemSid, GetDBID()
                    );
                }
            }
        } else {
            SendSystemMessage(SystemMessageId::ITEM_SEALED_UNSEAL_BEFORE_USE);
        }
    }

    runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
    return false;
}

bool User::OnEnsoulExtractionTry(
    const int targetItemSid, const EnsoulItem::EnsoulItemSlotType slotType, const int slotIndex
) {
    // Current L2Server 0x00b4dddc, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (!CheckEnsoulJob()) {
        GetSocket()->Send("chc", 0xfe, 0x1b5, 0);
        if (m_lWaitItemJob == 1) {
            SendSystemMessage(SystemMessageId::PREVIOUS_REQUEST_NOT_COMPLETED);
        }
        return false;
    }
    if (runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 1) == 1) {
        GetSocket()->Send("chc", 0xfe, 0x1b5, 0);
        if (m_lWaitItemJob == 1) {
            SendSystemMessage(SystemMessageId::PREVIOUS_REQUEST_NOT_COMPLETED);
        }
        return false;
    }

    CItem* const targetItem = m_inv.GetByServerID(targetItemSid);
    if (targetItem != nullptr) {
        const int slotTypeIndex = static_cast<int>(slotType);
        const auto optionPosition = targetItem->m_mEnsoulInfo[slotTypeIndex].find(slotIndex);
        if (optionPosition != targetItem->m_mEnsoulInfo[slotTypeIndex].end() && optionPosition->second != nullptr &&
            optionPosition->second->CanExtraction()) {
            const int extractionStoneClassId = optionPosition->second->GetExtractionStoneClassId();
            const auto feePosition = g_EnsoulFeeData.find(targetItem->m_const->GetCrystalType());
            if (feePosition != g_EnsoulFeeData.end() && feePosition->second != nullptr) {
                EnsoulFeeData::FeeItemVector* fees = nullptr;
                if (slotType == EnsoulItem::EIST_NORMAL) {
                    fees = &feePosition->second->m_vExtractionNormal;
                } else if (slotType == EnsoulItem::EIST_BM) {
                    fees = &feePosition->second->m_vExtractionBM;
                }

                std::array<ItemManip, 100> requests{};
                requests[0].mClassId = extractionStoneClassId;
                requests[0].mCount = 1;
                int requestCount = 1;
                for (EnsoulFeeItemData* const fee : *fees) {
                    requests[requestCount].mClassId = fee->m_nFeeItemType;
                    requests[requestCount].mCount = fee->m_nFeeItemCount;
                    ++requestCount;
                }

                const bool enoughItems = [&] {
                    L2_READ_GUARD(m_inv);
                    bool enoughItems = true;
                    for (int index = 1; index < requestCount; ++index) {
                        if (m_inv.GetItemAmount(requests[index].mClassId, 0, true) <
                            static_cast<int>(requests[index].mCount)) {
                            enoughItems = false;
                            break;
                        }
                        requests[index].mCount = runtime::NegateInt64Wrapping(requests[index].mCount);
                    }
                    return enoughItems;
                }();

                if (enoughItems) {
                    std::map<int, int> ensoulInfo[3];
                    ensoulInfo[slotTypeIndex].emplace(slotIndex, 0);
                    EtcManiEnsoul manipulation(targetItem->GetDBID(), GetDBID(), GetServerId(), ensoulInfo, true);
                    CPacketHelperEx<20480> packet;
                    manipulation.Assemble(packet);
                    if (ManipuateEnsoulItems(requests.data(), requestCount, packet, nullptr)) {
                        return true;
                    }
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[Ensoul]TryEnsoul Extraction, "
                    //     L"ManipulateEnsoulItems has problem")
                    L2_LOG_ERROR(
                        Log, u"[ensoul] Item manipulation failed while extracting slot %d:%d from item %d for character %u.",
                        slotTypeIndex, slotIndex, targetItemSid, GetDBID()
                    );
                }
            }
        }
    }

    GetSocket()->Send("chc", 0xfe, 0x1b5, 0);
    runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
    return false;
}

bool User::CanUseItem(int itemClassId) {
    // Current 0x00b30aa8. The final gate at 0x00b30bcc reads shared
    // +0x3198 (fake death), not +0x3468 (combat mode).
    L2_GUARD_FUNCTION();

    if (IsFrozen(true)) {
        SendSystemMessage(SystemMessageId::CANNOT_ACT_WHILE_FROZEN);
        return false;
    }
    if (IsNowTrade()) {
        SendSystemMessage(SystemMessageId::CANNOT_PICK_UP_OR_USE_ITEMS_WHILE_TRADING);
        return false;
    }
    if (!IsItemUsable(itemClassId)) {
        return false;
    }
    if (!IsAlive()) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ITEMS_WHILE_DEAD);
        return false;
    }
    if (m_data->m_nPrivateStoreType > 0) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_ITEMS_DURING_PRIVATE_STORE_OR_WORKSHOP);
        return false;
    }
    if (m_data->m_bIsFakeDeath) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_WHILE_FEIGNING_DEATH);
        return false;
    }
    return true;
}

bool User::CanUseItem(CItem* item) {
    L2_GUARD_FUNCTION();

    if (item == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"item is null at file[%s], line[%d]",
        //     L"User.cpp",
        //     0x4225)
        L2_LOG_ERROR(Log, u"[inventory] Item pointer is null; use request rejected.");
        return false;
    }
    if (item->IsQuestItem()) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_QUEST_ITEM);
        return false;
    }
    if (!item->IsItem()) {
        return false;
    }
    if (CSharedItemData::IsStackable(item->m_data->m_ItemConsumeType) && item->m_data->m_nCount < 1) {
        // Log.Add(
        //     LOG_ERROR,
        //     "item[%d] is stackable, but item count is less than 1",
        //     item->m_data->m_nClassID)
        L2_LOG_ERROR(
            Log, "[inventory] Stackable item class %d has count below one; entry rejected.", item->m_data->m_nClassID
        );
        return false;
    }
    if (item->m_const->m_period > 0 && GetPeriodLeft(item->GetDBID()) < 1) {
        return false;
    }
    return CanUseItem(item->GetClassId());
}

bool User::OnExAutoSoulShotPacket(int itemClassId, bool activate, int uiSlot, int activeState) {
    // Current L2Server 0x00b38c1c.
    L2_GUARD_FUNCTION();

    if (g_bUseAutoSoulShotUI) {
        CItem* const item = m_inv.GetFirstItemByClassID(itemClassId, false, false);
        if (item != nullptr && item->IsItem() && IsAutoSoulShotAction(item->m_const->m_enumDefaultAction) &&
            static_cast<unsigned int>(uiSlot) < 4U && static_cast<unsigned int>(activeState) < 4U) {
            if (!activate) {
                GetSocket()->Send("chccd", 0x62, SystemMessageId::ITEM_AUTO_USE_DISABLED, 1, 3, itemClassId);
                TurnOffAutoSoulshot(itemClassId, activeState, uiSlot, false);
            } else if (CanUseItem(item)) {
                if (UseItem(*item, 0, false, 0)) {
                    GetSocket()->Send("chccd", 0x62, SystemMessageId::ITEM_AUTO_USE_ENABLED, 1, 3, itemClassId);
                    TurnOnAutoSoulshot(itemClassId, activeState, uiSlot);
                } else {
                    m_AutoSoulShotUi[uiSlot].m_ItemClassID = 0;
                    GetSocket()->Send(
                        "chddd", 0xfe, 0x0c, m_AutoSoulShotUi[uiSlot].m_ItemClassID,
                        m_AutoSoulShotUi[uiSlot].m_IsActiveState, uiSlot
                    );

                    if ((!m_pWOlympiadUser->IsPlayer() || item->m_const->m_bCanOlympiadUse) &&
                        (!m_PledgeGameUser.IsPlayer() || !item->m_const->m_bCanNotPledgeGameUse)) {
                        const ItemDefaultActionEnum action = item->m_const->m_enumDefaultAction;
                        if ((action == ITEM_ACTION_SUMMON_SOULSHOT || action == ITEM_ACTION_SUMMON_SPIRITSHOT) &&
                            !HaveSummon() && !HavePet()) {
                            GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_ENABLE_AUTO_USE_WITHOUT_PET_OR_SERVITOR);
                        } else {
                            GetSocket()->Send(
                                "chccd", 0x62, SystemMessageId::CANNOT_ENABLE_AUTO_USE_REQUIRED_ITEM_MISSING, 1, 3,
                                itemClassId
                            );
                        }
                    }
                }
            }
        }
    }
    return false;
}

bool User::OnExAutoSoulShotPacket(int itemClassId, bool activate) {
    // Current L2Server 0x00b38f4c.
    L2_GUARD_FUNCTION();

    if (!g_bUseAutoSoulShotUI) {
        CItem* const item = m_inv.GetFirstItemByClassID(itemClassId, false, false);
        if (item != nullptr && item->IsItem() && IsAutoSoulShotAction(item->m_const->m_enumDefaultAction)) {
            if (!activate) {
                GetSocket()->Send("chddd", 0xfe, 0x0c, itemClassId, 0, -1);
                GetSocket()->Send("chccd", 0x62, SystemMessageId::ITEM_AUTO_USE_DISABLED, 1, 3, itemClassId);
                TurnOffAutoSoulshot(itemClassId, 0, 4, true);
            } else if (CanUseItem(item)) {
                if (UseItem(*item, 0, false, 0)) {
                    GetSocket()->Send("chddd", 0xfe, 0x0c, itemClassId, 1, -1);
                    GetSocket()->Send("chccd", 0x62, SystemMessageId::ITEM_AUTO_USE_ENABLED, 1, 3, itemClassId);
                    TurnOnAutoSoulshot(itemClassId, 1, -1);
                } else {
                    GetSocket()->Send("chddd", 0xfe, 0x0c, itemClassId, 0, -1);
                    if ((!m_pWOlympiadUser->IsPlayer() || item->m_const->m_bCanOlympiadUse) &&
                        (!m_PledgeGameUser.IsPlayer() || !item->m_const->m_bCanNotPledgeGameUse)) {
                        const ItemDefaultActionEnum action = item->m_const->m_enumDefaultAction;
                        if ((action == ITEM_ACTION_SUMMON_SOULSHOT || action == ITEM_ACTION_SUMMON_SPIRITSHOT) &&
                            !HaveSummon() && !HavePet()) {
                            GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_ENABLE_AUTO_USE_WITHOUT_PET_OR_SERVITOR);
                        } else {
                            GetSocket()->Send(
                                "chccd", 0x62, SystemMessageId::CANNOT_ENABLE_AUTO_USE_REQUIRED_ITEM_MISSING, 1, 3,
                                itemClassId
                            );
                        }
                    }
                }
            }
        }
    }
    return false;
}

bool User::OnUseItemPacket(std::uint32_t itemServerId, int force) {
    // Current L2Server 0x00b37eb8, original owner User.cpp.
    L2_GUARD_FUNCTION();

    if (m_bItemDebugReady) {
        CUserSocket::ItemDebug(this, static_cast<int>(itemServerId));
        m_bItemDebugReady = false;
        return false;
    }

    SetAvoidAgroFalse();
    CItem* const item = m_inv.GetByServerID(static_cast<int>(itemServerId));
    if (item == nullptr || !CanUseItem(item)) {
        return false;
    }

    const int itemClassId = item->m_data->m_nClassID;
    if (CItemRestrict::Inst().CheckItemRestrict(itemClassId)) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[NO_ERROR] OnUseItempacket. item restrict on. ClassID[%d]",
        //     itemClassId)
        // L2_LOG_ERROR(Log,
        //     L"[NO_ERROR] OnUseItempacket. item restrict on. ClassID[%d]",
        //     itemClassId)
        L2_LOG_DEBUG(
            Log, "[items] Use rejected for character %u: item class %d is restricted.", static_cast<unsigned int>(GetDBID()),
            itemClassId
        );
        return false;
    }

    const auto pending = [this](PendingUseItemType type) { return GetPendingUseETCItem(type) != nullptr; };
    const EtcItemType itemType = static_cast<EtcItemType>(item->m_const->m_EtcitemType);

    switch (itemType) {
        case EIT_ENCHT_WP:
        case EIT_ENCHT_AM:
        case EIT_BLESS_ENCHT_WP:
        case EIT_BLESS_ENCHT_AM:
        case EIT_CRYSTAL_ENCHANT_AM:
        case EIT_CRYSTAL_ENCHANT_WP:
        case EIT_ANCIENT_CRYSTAL_ENCHANT_AM:
        case EIT_ANCIENT_CRYSTAL_ENCHANT_WP:
        case EIT_MULTI_ENCHT_WP:
        case EIT_MULTI_ENCHT_AM:
        case EIT_ENCHT_AG:
        case EIT_BLESS_ENCHT_AG:
        case EIT_ANCIENT_CRYSTAL_ENCHANT_AG:
        case EIT_MULTI_ENCHT_AG:
            if (m_data->m_nWorldId != g_nWorldId) {
                SendSystemMessage(SystemMessageId::FUNCTION_UNAVAILABLE_AFTER_DIMENSIONAL_TRANSFER);
            } else if (m_data->m_StopMode == STP_STORE || m_data->m_nPrivateStoreType != 0) {
                SendSystemMessage(SystemMessageId::CANNOT_ENCHANT_DURING_PRIVATE_STORE_OR_WORKSHOP);
            } else if (pending(PUIT_ATTRIBUTE_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ANOTHER_ENCHANT_IN_PROGRESS);
            } else if (pending(PUIT_ATTRIBUTE_CHANGE)) {
                SendSystemMessage(SystemMessageId::ATTRIBUTE_CHANGE_IN_PROGRESS);
            } else if (pending(PUIT_ONE) || pending(PUIT_TWO)) {
                SendSystemMessage(SystemMessageId::PREVIOUS_OPERATION_STILL_IN_PROGRESS);
            } else if (pending(PUIT_HLOCKED)) {
                SendSystemMessage(SystemMessageId::SEAL_OR_UNSEAL_IN_PROGRESS);
            } else if (pending(PUIT_SHAPE_SHIFTING)) {
                SendSystemMessage(SystemMessageId::ITEM_APPEARANCE_MODIFICATION_OR_RESTORATION_IN_PROGRESS);
            // Original-behavior bug (0xb38b81..0xb38bda): once selected, the scroll
            // silently rejects every further click until the client cancels it.
            // An invisible/closed client window can therefore require relogging.
            // Original:
            // } else if (!IsNowTrade() && CheckAndSetPendingUseETCItem(item, PUIT_ENCHANT) && !m_bConvertingItem) {
            //     SetPendingUseETCItem(nullptr, PUIT_INC_ENCHANT_PROP)
            //     InitAllEnchantBonusOptions()
            //     GetSocket()->Send("cd", 0x7c, itemClassId)
            } else if (!IsNowTrade() && !m_bConvertingItem && m_lWaitVariation != 1) {
                // Do not clear any transaction flag or switch an already selected
                // scroll. A retry only reopens the same idle enchant session.
                const bool selected = CheckAndSetPendingUseETCItem(item, PUIT_ENCHANT);
                if (selected) {
                    SetPendingUseETCItem(nullptr, PUIT_INC_ENCHANT_PROP);
                    InitAllEnchantBonusOptions();
                }
                if (selected || GetPendingUseETCItem(PUIT_ENCHANT) == item) {
                    GetSocket()->Send("cd", 0x7c, itemClassId);
                }
            }
            return false;

        case EIT_ENCHT_ATTR:
        case EIT_ENCHT_ATTR_CURSED: {
            if (m_data->m_StopMode == STP_STORE || m_data->m_nPrivateStoreType != 0) {
                SendSystemMessage(SystemMessageId::CANNOT_ENCHANT_DURING_PRIVATE_STORE_OR_WORKSHOP);
                return false;
            }
            if (pending(PUIT_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ANOTHER_ENCHANT_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_ATTRIBUTE_CHANGE)) {
                SendSystemMessage(SystemMessageId::ATTRIBUTE_CHANGE_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_SHAPE_SHIFTING)) {
                SendSystemMessage(SystemMessageId::ITEM_APPEARANCE_MODIFICATION_OR_RESTORATION_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_HLOCKED)) {
                SendSystemMessage(SystemMessageId::SEAL_OR_UNSEAL_IN_PROGRESS);
                return false;
            }
            if (IsNowTrade() || !CheckAndSetPendingUseETCItem(item, PUIT_ATTRIBUTE_ENCHANT)) {
                return false;
            }

            int attributeTypes[ATTRT_MAX]{};
            int attributeLevel = 0;
            for (const CSkillInfo* const skill : item->m_ItemSkillList) {
                if (skill == nullptr) {
                    continue;
                }
                for (int type = ATTRT_FIRE; type < ATTRT_MAX; ++type) {
                    attributeTypes[type] =
                        const_cast<CSkillInfo*>(skill)->GetEnchantAttributeType(static_cast<AttributeTypeEnum>(type));
                }
                attributeLevel = skill->m_nAttrEnchantLevel;
            }

            CPacketHelperEx<20480> eligibleItems;
            int eligibleCount = 0;
            {
                L2_READ_GUARD(m_inv);
                for (CSharedItemData* data = m_inv.GetFirst(); data != nullptr; data = data->Next()) {
                    CSPointer<CItem> candidate = CItemFactory::Inst().FindObjectSP(data->index);
                    if (!candidate || !candidate->m_const->m_bCanAttrEnchant) {
                        continue;
                    }
                    if (itemType == EIT_ENCHT_ATTR_CURSED && candidate->m_const->m_nAttribution != -1) {
                        continue;
                    }
                    eligibleItems.Assemble("d", candidate->m_data->m_nId);
                    ++eligibleCount;
                }
            }

            GetSocket()->Send(
                "chdQddddddddb", 0xfe, 99, itemClassId, item->m_data->m_nCount, attributeTypes[ATTRT_FIRE],
                attributeTypes[ATTRT_WATER], attributeTypes[ATTRT_WIND], attributeTypes[ATTRT_EARTH],
                attributeTypes[ATTRT_HOLY], attributeTypes[ATTRT_UNHOLY], attributeLevel, eligibleCount,
                eligibleItems.GetLength(), eligibleItems.GetPacket()
            );
            return false;
        }

        case EIT_CHANGE_ATTR:
            if (m_data->m_StopMode == STP_STORE || m_data->m_nPrivateStoreType != 0) {
                SendSystemMessage(SystemMessageId::CANNOT_CHANGE_ATTRIBUTE_DURING_PRIVATE_STORE_OR_WORKSHOP);
            } else if (pending(PUIT_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ENCHANT_OR_ATTRIBUTE_ENCHANT_IN_PROGRESS);
            } else if (pending(PUIT_HLOCKED)) {
                SendSystemMessage(SystemMessageId::SEAL_OR_UNSEAL_IN_PROGRESS);
            } else if (pending(PUIT_ATTRIBUTE_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ATTRIBUTE_CHANGE_IN_PROGRESS);
            } else if (pending(PUIT_ONE) || pending(PUIT_TWO)) {
                SendSystemMessage(SystemMessageId::PREVIOUS_OPERATION_STILL_IN_PROGRESS);
            } else if (pending(PUIT_SHAPE_SHIFTING)) {
                SendSystemMessage(SystemMessageId::ITEM_APPEARANCE_MODIFICATION_OR_RESTORATION_IN_PROGRESS);
            } else if (!IsNowTrade() && CheckAndSetPendingUseETCItem(item, PUIT_ATTRIBUTE_CHANGE) && !m_bConvertingItem) {
                g_ItemAttrChangeDB.ItemAssemble(this, item->m_const->m_nGroupId);
            }
            return false;

        case EIT_SHAPE_SHIFTING_WP:
        case EIT_BLESS_SHAPE_SHIFTING_WP:
        case EIT_SHAPE_SHIFTING_WP_FIXED:
        case EIT_SHAPE_SHIFTING_AM:
        case EIT_BLESS_SHAPE_SHIFTING_AM:
        case EIT_SHAPE_SHIFTING_AM_FIXED:
        case EIT_SHAPE_SHIFTING_HAIRACC:
        case EIT_BLESS_SHAPE_SHIFTING_HAIRACC:
        case EIT_SHAPE_SHIFTING_HAIRACC_FIXED:
        case EIT_RESTORE_SHAPE_SHIFTING_WP:
        case EIT_RESTORE_SHAPE_SHIFTING_AM:
        case EIT_RESTORE_SHAPE_SHIFTING_HAIRACC:
        case EIT_RESTORE_SHAPE_SHIFTING_ALLITEM:
        case EIT_SHAPE_SHIFTING_ALLITEM_FIXED: {
            if (m_data->m_bIsInCombatMode) {
                return false;
            }
            if (m_data->m_StopMode == STP_STORE || m_data->m_nPrivateStoreType != 0) {
                SendSystemMessage(SystemMessageId::SYSTEM_UNAVAILABLE_DURING_TRADE_STORE_OR_WORKSHOP_SETUP);
                return false;
            }
            if (pending(PUIT_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ENCHANT_OR_ATTRIBUTE_ENCHANT_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_HLOCKED)) {
                SendSystemMessage(SystemMessageId::SEAL_OR_UNSEAL_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_ATTRIBUTE_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ENCHANT_OR_ATTRIBUTE_ENCHANT_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_ONE) || pending(PUIT_TWO)) {
                SendSystemMessage(SystemMessageId::PREVIOUS_OPERATION_STILL_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_ATTRIBUTE_CHANGE)) {
                SendSystemMessage(SystemMessageId::ATTRIBUTE_CHANGE_IN_PROGRESS);
                return false;
            }
            if (pending(PUIT_SHAPE_SHIFTING)) {
                SendSystemMessage(SystemMessageId::ITEM_APPEARANCE_MODIFICATION_OR_RESTORATION_IN_PROGRESS);
                return false;
            }
            if (IsNowTrade()) {
                SendSystemMessage(SystemMessageId::SYSTEM_UNAVAILABLE_DURING_TRADE_STORE_OR_WORKSHOP_SETUP);
                return false;
            }
            if (!CheckAndSetPendingUseETCItem(item, PUIT_SHAPE_SHIFTING) || m_bConvertingItem) {
                return false;
            }

            int targetType = 0;
            switch (itemType) {
                case EIT_SHAPE_SHIFTING_WP:
                case EIT_BLESS_SHAPE_SHIFTING_WP:
                case EIT_SHAPE_SHIFTING_WP_FIXED:
                case EIT_RESTORE_SHAPE_SHIFTING_WP:
                    targetType = 1;
                    break;
                case EIT_SHAPE_SHIFTING_AM:
                case EIT_BLESS_SHAPE_SHIFTING_AM:
                case EIT_SHAPE_SHIFTING_AM_FIXED:
                case EIT_RESTORE_SHAPE_SHIFTING_AM:
                    targetType = 2;
                    break;
                case EIT_SHAPE_SHIFTING_HAIRACC:
                case EIT_BLESS_SHAPE_SHIFTING_HAIRACC:
                case EIT_SHAPE_SHIFTING_HAIRACC_FIXED:
                case EIT_RESTORE_SHAPE_SHIFTING_HAIRACC:
                    targetType = 3;
                    break;
                case EIT_RESTORE_SHAPE_SHIFTING_ALLITEM:
                case EIT_SHAPE_SHIFTING_ALLITEM_FIXED:
                    targetType = 4;
                    break;
                default:
                    break;
            }

            int detailType = 0;
            switch (itemType) {
                case EIT_SHAPE_SHIFTING_WP:
                case EIT_SHAPE_SHIFTING_AM:
                case EIT_SHAPE_SHIFTING_HAIRACC:
                    detailType = 1;
                    break;
                case EIT_BLESS_SHAPE_SHIFTING_WP:
                case EIT_BLESS_SHAPE_SHIFTING_AM:
                case EIT_BLESS_SHAPE_SHIFTING_HAIRACC:
                    detailType = 2;
                    break;
                case EIT_SHAPE_SHIFTING_WP_FIXED:
                case EIT_SHAPE_SHIFTING_AM_FIXED:
                case EIT_SHAPE_SHIFTING_HAIRACC_FIXED:
                case EIT_SHAPE_SHIFTING_ALLITEM_FIXED:
                    detailType = 3;
                    break;
                case EIT_RESTORE_SHAPE_SHIFTING_WP:
                case EIT_RESTORE_SHAPE_SHIFTING_AM:
                case EIT_RESTORE_SHAPE_SHIFTING_HAIRACC:
                case EIT_RESTORE_SHAPE_SHIFTING_ALLITEM:
                    detailType = 4;
                    break;
                default:
                    break;
            }
            GetSocket()->Send("chddd", 0xfe, 0x129, targetType, detailType, itemClassId);
            return false;
        }

        case EIT_LOCK_ITEM:
        case EIT_UNLOCK_ITEM:
            if (m_data->m_StopMode == STP_STORE || m_data->m_nPrivateStoreType != 0) {
                SendSystemMessage(SystemMessageId::SYSTEM_UNAVAILABLE_DURING_TRADE_STORE_OR_WORKSHOP_SETUP);
            } else if (pending(PUIT_ENCHANT) || pending(PUIT_ATTRIBUTE_ENCHANT)) {
                SendSystemMessage(SystemMessageId::ENCHANT_OR_ATTRIBUTE_ENCHANT_IN_PROGRESS);
            } else if (pending(PUIT_ONE) || pending(PUIT_TWO)) {
                SendSystemMessage(SystemMessageId::PREVIOUS_OPERATION_STILL_IN_PROGRESS);
            } else if (pending(PUIT_ATTRIBUTE_CHANGE)) {
                SendSystemMessage(SystemMessageId::ATTRIBUTE_CHANGE_IN_PROGRESS);
            } else if (pending(PUIT_SHAPE_SHIFTING)) {
                SendSystemMessage(SystemMessageId::ITEM_APPEARANCE_MODIFICATION_OR_RESTORATION_IN_PROGRESS);
            } else if (IsNowTrade()) {
                SendSystemMessage(SystemMessageId::SYSTEM_UNAVAILABLE_DURING_TRADE_STORE_OR_WORKSHOP_SETUP);
            } else if (CheckAndSetPendingUseETCItem(item, PUIT_HLOCKED) && !m_bConvertingItem) {
                protocol::S_EX_CHOOSE_LOCKED_ITEM packet{};
                packet.nScrollItemClassID = itemClassId;
                GetSocket()->Send(S_EX, S_EX_CHOOSE_LOCKED_ITEM, packet);
            }
            return false;

        default:
            UseItem(*item, force, false, 0);
            return false;
    }
}

bool User::OnDropItemPacket(
    const std::uint32_t itemServerId, const std::int64_t amount, const int x, const int y, const int z
) {
    // Current L2Server 0x00b30d28, original owner User.cpp.
    L2_GUARD_FUNCTION();

    if (GetSocket()->m_bEconomicRestriction) {
        SendSystemMessage(SystemMessageId::ACCOUNT_CANNOT_DROP_ITEMS);
        return false;
    }

    CItem* const item = m_inv.GetByServerID(static_cast<int>(itemServerId));
    if (item == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d]What a wonderful world(1). item server id[%d], amount[%d], user[%s]",
        //     L"User.cpp",
        //     0x52be,
        //     static_cast<int>(itemServerId),
        //     static_cast<int>(amount),
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[item drop] Character '%s' requested missing item object %d with amount %d.",
        //     GetName(),
        //     static_cast<int>(itemServerId),
        //     static_cast<int>(amount))
        L2_LOG_ERROR(
            Log, u"[item drop] Character '%s' requested missing item object %d with amount %d.", GetName(),
            static_cast<int>(itemServerId), static_cast<int>(amount)
        );
        return false;
    }
    if (CItemRestrict::Inst().CheckItemRestrict(item->m_data->m_nClassID)) {
        return false;
    }
    if (IsFrozen(true)) {
        SendSystemMessage(SystemMessageId::CANNOT_ACT_WHILE_FROZEN);
        return false;
    }
    if (m_data->m_StopMode == STP_STORE) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_OR_DESTROY_ITEMS_DURING_PRIVATE_STORE_OR_WORKSHOP);
        return false;
    }
    if (m_data->m_nPrivateStoreType != 0) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_DESTROY_OR_TRADE_ITEMS_DURING_PRIVATE_STORE_OR_WORKSHOP);
        return false;
    }
    if (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing) {
        SendSystemMessage(SystemMessageId::CANNOT_EQUIP_UNEQUIP_DESTROY_OR_DROP_ITEMS_WHILE_FISHING);
        return false;
    }
    if (m_DuelUserInfo.IsInPartyDuel() || IsAirShipDriver()) {
        return false;
    }

    bool validAmount = false;
    const std::uint64_t unsignedAmount = static_cast<std::uint64_t>(amount);
    if (item->m_data->m_ItemConsumeType == ICT_ASSET) {
        validAmount = unsignedAmount - 1U < 999999999999ULL;
    } else if (unsignedAmount - 1U < 1000000ULL) {
        std::array<char, 32> amountText{};
        std::snprintf(amountText.data(), 0x0b, "%lld", static_cast<long long>(amount));
        validAmount = std::strlen(amountText.data()) < 9U;
    }
    if (!validAmount) {
        SendSystemMessage(SystemMessageId::INPUT_QUANTITY_LIMIT_EXCEEDED);
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] invalid amount (DropItem : %I64d of %d by %s)",
        //     L"User.cpp",
        //     0x52f5,
        //     amount,
        //     item->m_data->m_nClassID,
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[item drop] Character '%s' requested invalid amount %I64d of item class %d.",
        //     GetName(),
        //     amount,
        //     item->m_data->m_nClassID)
        L2_LOG_ERROR(
            Log, u"[item drop] Character '%s' requested invalid amount %I64d of item class %d.", GetName(), amount,
            item->m_data->m_nClassID
        );
        return false;
    }

    if (!IsAlive() || m_data->m_bGMInvisible) {
        return false;
    }
    if (item->IsQuestItem()) {
        SendSystemMessage(SystemMessageId::CANNOT_DISCARD_QUEST_ITEM);
        return false;
    }
    if (item->m_itemOption.itemOptionKey.variationOption1 > 0 && item->m_itemOption.itemOptionKey.variationOption2 > 0) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_AUGMENTED_ITEM);
        return false;
    }
    if (item->IsDuration()) {
        SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_DROPPED);
        return false;
    }
    if (static_cast<int>(m_data->m_moveType) == CMT_FLY || GetPendingUseETCItem(PUIT_ENCHANT) != nullptr) {
        return false;
    }
    if (GetPendingUseETCItem(PUIT_HLOCKED) != nullptr) {
        SendSystemMessage(SystemMessageId::SEAL_OR_UNSEAL_IN_PROGRESS);
        return false;
    }

    const std::uint32_t previousDropTick = m_dwDropItemTick;
    m_dwDropItemTick = runtime::GetTickCount();
    if (m_dwDropItemTick < previousDropTick + 1000U) {
        SendSystemMessage(SystemMessageId::WAIT_BEFORE_DROPPING_ANOTHER_ITEM);
        return false;
    }
    if (item->m_data->GetLocked() != 0) {
        SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_DROPPED);
        return false;
    }

    if (!item->IsDrop()) {
        if (!item->IsEtcItem()) {
            SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_DROPPED);
            return false;
        }
        CEtcItem* const etcItem = item->CastEtcItem();
        SendSystemMessage(
            etcItem->m_bPetCollarTradable ? SystemMessageId::ITEM_CANNOT_BE_DROPPED
                                          : SystemMessageId::CANNOT_DROP_SUMMONING_ITEM_WHILE_PET_SUMMONED
        );
        return false;
    }

    if (m_nPetItemCount >= 1 && item->IsPetCollarItem()) {
        SendSystemMessage(SystemMessageId::CANNOT_SELL_OR_DROP_PET_SUMMONING_ITEM_PET_INVENTORY_NOT_EMPTY);
        return false;
    }
    if (IsNowTrade()) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_OR_DESTROY_ITEMS_DURING_PRIVATE_STORE_OR_TRADE);
        return false;
    }
    if (!IsItemUsable(0)) {
        return false;
    }
    if (item->IsEtcItem() && item->m_const->m_EtcitemType == EIT_CASTLE_GUARD) {
        DropCastleGuard(item, 1);
        return false;
    }
    if (item->IsPeriodicShapeShiftedItem(this)) {
        SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_DROPPED);
        return false;
    }

    FVector position{static_cast<double>(x), static_cast<double>(y), static_cast<double>(z)};
    const FVector currentPosition = GetPos();
    const double xDistance = position.x - currentPosition.x;
    const double yDistance = position.y - currentPosition.y;
    if (xDistance * xDistance + yDistance * yDistance > 62500.0) {
        SendSystemMessage(SystemMessageId::DROP_LOCATION_TOO_FAR);
        return false;
    }

    CGeoData* const geo = CWorld::Inst().GetGeo();
    CGeoZone* const zone = geo->GetZone(
        ((runtime::Win64CvttDoubleToInt32(position.x) + 0x50000) >> 15) + 10,
        ((runtime::Win64CvttDoubleToInt32(position.y) + 0x40000) >> 15) + 10
    );
    if (zone != nullptr && zone->IsInNoDropItemArea(position)) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_ITEMS_HERE);
        return false;
    }

    DropItem(item, amount, position, false);
    return false;
}

bool User::RequestTrade(User* user) {
    L2_GUARD_FUNCTION();

    {
        GuardHelper tradeGuard1(L"request trade 1", CThreadManager::GetThreadID());
        if (user == this) {
            SendSystemMessage(SystemMessageId::INCORRECT_TARGET);
            return false;
        }
    }

    {
        GuardHelper tradeGuard2(L"request trade 2", CThreadManager::GetThreadID());
        if (m_bBlockAll) {
            SendSystemMessage(SystemMessageId::CANNOT_TRADE_WHILE_BLOCKING_ALL);
            return false;
        }
        if (IsInBlockList(*user)) {
            GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_BLOCKED_BY_YOU, user->GetName());
            return false;
        }
    }

    {
        GuardHelper tradeGuard3(L"request trade 3", CThreadManager::GetThreadID());
        if (user->m_data->m_StopMode == STP_STORE || m_data->m_StopMode == STP_STORE) {
            return false;
        }
    }

    {
        GuardHelper tradeGuard4(L"request trade 4", CThreadManager::GetThreadID());
        if (IsNowTrade()) {
            SendSystemMessage(SystemMessageId::ALREADY_TRADING);
            return false;
        }
        if (user->IsNowTrade()) {
            GetSocket()->SendSystemMessage_S(
                SystemMessageId::OTHER_CHARACTER_ALREADY_TRADING, user->CastUser()->GetName2(this)
            );
            GetSocket()->Send("cd", 0x1c, 0);
            return false;
        }
        if (m_data->m_TrainingState == 1) {
            SendSystemMessage(SystemMessageId::CANNOT_TAKE_OTHER_ACTIONS_WHILE_IN_TRAINING_CAMP);
            return false;
        }
        if (user->m_data->m_TrainingState == 1) {
            SendSystemMessage(SystemMessageId::CANNOT_SEND_REQUEST_TO_CHARACTER_IN_TRAINING_CAMP);
            return false;
        }
    }

    {
        GuardHelper tradeGuard5(L"request trade 5", CThreadManager::GetThreadID());
        User* firstLock = user;
        User* secondLock = this;
        if (user->GetIndex() < GetIndex()) {
            firstLock = this;
            secondLock = user;
        }
        std::optional<GuardHelper> phaseGuard;
        const bool registered = [&] {
            L2_GUARD(*firstLock->m_lock);
            L2_GUARD(*secondLock->m_lock);

            {
                phaseGuard.emplace(L"request trade 5-1", CThreadManager::GetThreadID());
                if (GetTrade() != nullptr) {
                    SendSystemMessage(SystemMessageId::ALREADY_TRADING);
                    return false;
                }
                phaseGuard.reset();
            }

            {
                phaseGuard.emplace(L"request trade 5-2", CThreadManager::GetThreadID());
                if (user->GetTrade() != nullptr) {
                    GetSocket()->SendSystemMessage_S(
                        SystemMessageId::OTHER_CHARACTER_ALREADY_TRADING, user->CastUser()->GetName2(this)
                    );
                    GetSocket()->Send("cd", 0x1c, 0);
                    return false;
                }
                phaseGuard.reset();
            }

            {
                phaseGuard.emplace(L"request trade 5-3", CThreadManager::GetThreadID());
                const L2ServerLong userManipulation = user->EnterItemManipulation(1);
                const L2ServerLong selfManipulation = EnterItemManipulation(1);
                if (userManipulation == 2 || selfManipulation == 2) {
                    SendSystemMessage(SystemMessageId::CANNOT_TRADE_WHILE_USING_ITEM);
                    GetSocket()->Send("cd", 0x1c, 0);
                    return false;
                }

                const int tradeId = g_TradeManager.CreateTrade(this, user);
                m_nTrade = tradeId;
                user->m_nTrade = tradeId;
                phaseGuard.reset();
            }
            return true;
        }();
        if (!registered) {
            return false;
        }
    }

    {
        GuardHelper tradeGuard6(L"request trade 6", CThreadManager::GetThreadID());
        user->GetSocket()->Send("cd", 0x70, static_cast<int>(Id()));
        GetSocket()->SendSystemMessage_S(SystemMessageId::TRADE_REQUEST_SENT, user->CastUser()->GetName2(this));
        return true;
    }
}

bool User::OnTradeRequestPacket(int targetServerId) {
    L2_GUARD_FUNCTION();

    if (GetSocket()->m_bEconomicRestriction) {
        SendSystemMessage(SystemMessageId::ACCOUNT_CANNOT_TRADE_ITEMS);
        return false;
    }
    if (IsAirShipDriver()) {
        SendSystemMessage(SystemMessageId::CANNOT_ACT_WHILE_STEERING);
        return false;
    }
    CParty* const party = GetParty();
    if (party != nullptr && party->IsLootingTypeModifyInProgress()) {
        SendSystemMessage(SystemMessageId::CANNOT_MAKE_ONE_TO_ONE_REQUEST_DURING_PARTY_LOOT_CHANGE);
        return false;
    }

    const CSPointer<User> targetPointer = g_UserMap.FindObject(targetServerId);
    User* const target = targetPointer.get();
    if (target == nullptr || !target->IsPC()) {
        SendSystemMessage(SystemMessageId::INVALID_TARGET);
        return false;
    }
    CParty* const targetParty = target->GetParty();
    if (targetParty != nullptr && targetParty->IsLootingTypeModifyInProgress()) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_CHANGING_PARTY_LOOT, target->GetName());
        return false;
    }
    if (target->GetSocket()->m_bEconomicRestriction) {
        SendSystemMessage(SystemMessageId::CANNOT_TRADE_ITEMS_WITH_TARGET_USER);
        return false;
    }
    if (m_data->m_StopMode == STP_STORE) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_DESTROY_OR_TRADE_ITEMS_DURING_PRIVATE_STORE_OR_WORKSHOP);
        return false;
    }
    if (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing) {
        SendSystemMessage(SystemMessageId::CANNOT_PERFORM_OTHER_ACTIONS_WHILE_FISHING);
        return false;
    }
    if (m_DuelUserInfo.IsInPartyDuel()) {
        return false;
    }
    if (target->m_data->m_StopMode == STP_STORE) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_DESTROY_OR_TRADE_ITEMS_DURING_PRIVATE_STORE_OR_WORKSHOP);
        return false;
    }
    if (GetTrade() != nullptr) {
        SendSystemMessage(SystemMessageId::ALREADY_TRADING);
        return false;
    }
    if (target->GetTrade() != nullptr) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::OTHER_CHARACTER_ALREADY_TRADING, target->GetName());
        return false;
    }
    if (!target->m_bTradeEnabled) {
        return false;
    }
    if (m_data->m_nPrivateStoreType != 0) {
        SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        return false;
    }
    if (target->m_data->m_nPrivateStoreType != 0) {
        SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        target->SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        return false;
    }
    if (target->m_bBlockAll) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::TARGET_BLOCKS_ALL, target->GetName());
        return false;
    }
    if (target->IsInBlockList(*this)) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_BLOCKED_YOU, target->GetName());
        return false;
    }
    if (!IsItemUsable(0)) {
        return false;
    }

    const auto hasPendingTradeItem = [](User* candidate) {
        return candidate->GetPendingUseETCItem(PUIT_ENCHANT) != nullptr ||
            candidate->GetPendingUseETCItem(PUIT_ATTRIBUTE_ENCHANT) != nullptr ||
            candidate->GetPendingUseETCItem(PUIT_SHAPE_SHIFTING) != nullptr ||
            candidate->GetPendingUseETCItem(PUIT_CRYSTAL) != nullptr ||
            candidate->GetPendingUseETCItem(PUIT_ONE) != nullptr || candidate->GetPendingUseETCItem(PUIT_TWO) != nullptr ||
            candidate->GetPendingUseETCItem(PUIT_HLOCKED) != nullptr;
    };
    if (hasPendingTradeItem(this)) {
        SendSystemMessage(SystemMessageId::CANNOT_TRADE_IN_CURRENT_STATE);
        return false;
    }
    if (hasPendingTradeItem(target)) {
        SendSystemMessage(SystemMessageId::CANNOT_TRADE_ITEMS_WITH_TARGET_USER);
        return false;
    }

    const FVector source = GetPos();
    const FVector destination = target->GetPos();
    if (!CWorld::Inst().GetGeo()->CanSee(source, destination, static_cast<int>(GetInZoneID()), true)) {
        SendSystemMessage(SystemMessageId::TARGET_NOT_VISIBLE);
        return false;
    }
    if (target->CastUser()->m_bAskCoupleAction) {
        GetSocket()->SendSystemMessage(SystemMessageId::WAITING_FOR_ANOTHER_OPERATION_REPLY);
        return false;
    }
    RequestTrade(target->CastUser());
    return false;
}

bool User::OnTradeStartPacket(int synchronize) {
    L2_GUARD_FUNCTION();

    if (m_data->m_StopMode == STP_STORE) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_OR_DESTROY_ITEMS_DURING_PRIVATE_STORE_OR_TRADE);
    } else if (m_data->m_nPrivateStoreType != 0) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_DESTROY_OR_TRADE_ITEMS_DURING_PRIVATE_STORE_OR_WORKSHOP);
    } else if (m_data->m_TrainingState == 1) {
        SendSystemMessage(SystemMessageId::MOVE_BEFORE_PASSAGE_CLOSES);
    } else {
        TradeStart(synchronize == 1);
    }
    return false;
}

bool User::OnTradeDonePacket(std::uint32_t result) {
    L2_GUARD_FUNCTION();

    if (m_data->m_StopMode == STP_STORE) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_OR_DESTROY_ITEMS_DURING_PRIVATE_STORE_OR_TRADE);
    } else if (result == 0) {
        TradeCancel(false);
    } else if (CIOObject::IsInShortTime(m_nTradeTimeStamp, 1000)) {
        LogAbnormalAction(AUA_TOO_FAST_TRADE, false, 0, 0, 0, 0);
    } else {
        CIOObject::SetShortTimeStamp(&m_nTradeTimeStamp, 0);
        TradeDone();
    }
    return false;
}

bool User::OnGetItemPacket(const int itemServerId, const std::int64_t) {
    // Current L2Server.exe 0x00b63620, original owner User.cpp.
    L2_GUARD_FUNCTION();

    if (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing == true) {
        SendSystemMessage(SystemMessageId::CANNOT_PERFORM_OTHER_ACTIONS_WHILE_FISHING);
        return false;
    }
    if (m_DuelUserInfo.IsInPartyDuel()) {
        return false;
    }
    if (IsNowTrade()) {
        SendSystemMessage(SystemMessageId::CANNOT_DROP_OR_DESTROY_ITEMS_DURING_PRIVATE_STORE_OR_TRADE);
        return false;
    }
    if (!IsItemUsable(0)) {
        return false;
    }

    CItem* const object = g_ItemSmartIdManager.GetObjectW(static_cast<std::uint32_t>(itemServerId));
    CItem* const item = object != nullptr && object->IsItem() ? object->CastItem() : nullptr;
    if (item == nullptr) {
        wchar_t* const safeName = SafeString(Utf16ToWide(GetName()).data(), 0x18);
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] User[%s] trying get invalid item",
        //     L"User.cpp",
        //     0x57b7,
        //     safeName)
        L2_LOG_ERROR(Log, u"[item pickup] Character '%s' attempted to pick up an invalid item object.", safeName);
        LogAbnormalAction(AUA_TRY_ITEM_NOT_ITEM, true, 0, 0, 0, 0);
        return true;
    }
    return GetItem(item, false);
}

void User::Set(CUserSocket* socket) {
    L2_GUARD_FUNCTION();
    m_pSocket = socket;
    L2_ADD_REF(socket, ObjectRefType::Anonymous);
}

void User::ReleaseSocket() {
    // Current L2Server 0x00b154d4.
    L2_GUARD_FUNCTION();
    if (GetSocket() == nullptr) {
        const char16_t* const name = GetName();
        const std::uint32_t databaseId = GetDBID();
        // Log.Add(
        //     LOG_ERROR,
        //     L"UserSocket is NULL, dbid[%d] name[%s]",
        //     databaseId,
        //     name)
        // L2_LOG_ERROR(Log,
        //     L"[session] User socket is null for DB ID %d, name '%s'.",
        //     databaseId,
        //     name)
        L2_LOG_ERROR(Log, u"[session] User socket is null for DB ID %d, name '%s'.", databaseId, name);
        runtime::process::ReportCallStack(2, false);
        return;
    }

    CUserSocket* const socket = m_pSocket;
    if (g_bUserGarbageCollector) {
        m_pSocket = NullUserSocket::GetNullUserSocket();
        L2_RELEASE(socket, ObjectRefType::Anonymous);
    } else {
        L2_RELEASE(socket, ObjectRefType::Anonymous);
    }
}

