bool User::ShowMultiSell(const int npcIndex, const int listId) {
    // Current L2Server 0x00b60bb0.
    L2_GUARD_FUNCTION();

    CMultiSellList* const list = g_MultiSellDB.find(listId);
    if (list == nullptr) {
        return false;
    }

    CNPC* npc = nullptr;
    if (!list->IsWithoutNPC()) {
        CSPointer<CCreature> creature = CCreatureFactory::Inst().FindObjectSP(npcIndex);
        if (!creature || !creature->IsNPC()) {
            return false;
        }

        npc = creature->CastNPC();
        if (npc == nullptr || !IsTalkableDistance(npc)) {
            return false;
        }

        TalkChannelCache::inst().mChannels[1].Cache(Id(), npc->Id(), 0);
    }

    list->SendList(this, npc, false);
    return false;
}

