bool User::DecreaseEnergyCount(int count) {
    L2_GUARD_FUNCTION();
    const bool enoughEnergy = [&] {
        L2_GUARD(*m_lock);

        const std::int32_t energyCount = m_nEnergyCount;
        const bool enoughEnergy = count <= energyCount;
        if (enoughEnergy) {
            m_nEnergyCount = runtime::SubtractInt32Wrapping(energyCount, count);
        }

        return enoughEnergy;
    }();
    return enoughEnergy;
}

void User::AccumulateExpForItem(std::int64_t experience) {
    // Current L2Server 0x00b4fb44.
    L2_GUARD_FUNCTION();

    if (m_bEinhasadeTransformed || !m_SkillMod.m_bGetItemByExp || experience < 1) {
        return;
    }

    InventoryParams parameters;
    const std::int64_t unit = m_SkillMod.m_nGetItemByExpUnit;
    const std::int64_t amount = std::min(experience, unit);

    const std::int64_t accumulated = [&] {
        L2_GUARD(*m_lock);
        const std::int64_t accumulated = runtime::AddInt64Wrapping(amount, m_nAccumulatedExpForItem);
        m_nAccumulatedExpForItem = accumulated < unit ? accumulated : 0;
        return accumulated;
    }();

    if (accumulated >= unit) {
        parameters.nItemClassID = m_SkillMod.m_nGetItemByExpItemType;
        parameters.nCount = m_SkillMod.m_nGetItemByExpItemAmount;
        AddItemToInventory(parameters);
    }

    if (amount == 10000000 || m_nAccumulatedExpForItem < m_nAccumulatedExpForItemBefore ||
        m_nAccumulatedExpForItem - m_nAccumulatedExpForItemBefore >= 10000000) {
        CLogFormatter formatter;
        formatter.WriteLog2_1(
            0x1f97, this, nullptr, amount, m_nAccumulatedExpForItem, parameters.nItemClassID, parameters.nCount, unit, 0, 0
        );
        m_nAccumulatedExpForItemBefore = m_nAccumulatedExpForItem;
    }
}

bool User::IsMyParty(CCreature* creature) {
    L2_GUARD_FUNCTION();
    if (creature->IsSummonOrPet()) {
        creature = creature->CastSummon()->GetMaster();
    }

    if (creature == nullptr) {
        return false;
    }
    if (creature == this) {
        return true;
    }

    const std::uint32_t partyId = m_data->m_nPartyId;
    return partyId != 0 && partyId == creature->m_data->m_nPartyId;
}

bool User::IsPartyMaster() {
    L2_GUARD_FUNCTION();
    CParty* party = GetParty();
    return party != nullptr && party->m_data->m_OnlineMaster.id == m_nId;
}

void User::ProcessMyParty(const bool sendPacket) {
    // Current L2Server 0x00b28db8.
    L2_GUARD_FUNCTION();

    CParty* const party = GetParty();
    if (!party) {
        CSPointer<User> self(this, ObjectRefType::FunctionChain);
        CPartyMatchingRequest::inst().OnLeaveWorld(std::move(self));
        return;
    }

    if (IsPartyMaster()) {
        if (party->GetMemberCount() < 3) {
            party->Dismiss(sendPacket, false);
            return;
        }

        User* const candidate = party->GetMasterCandidate();
        if (!candidate) {
            return;
        }
        party->HandOverMaster(candidate);
    } else if (party->GetMemberCount() < 3) {
        party->Dismiss(sendPacket, false);
        return;
    }

    party->Withdraw(this, sendPacket);
}

void User::ProcessMyMPCC(const bool) {
    // Current L2Server 0x00b2e154. The source parameter is intentionally
    // unused by the current body.
    L2_GUARD_FUNCTION();
    if (GetMPCC() != nullptr) {
        CSPointer<User> self(this, ObjectRefType::FunctionChain);
        CPartyMatchingRequest::inst().OnLeaveWorld(std::move(self));
    }
}

bool User::SendUserHPInfo(const int reason, const int objectId, const bool deferPartyUpdate) {
    // Current L2Server 0x00b28f00.
    L2_GUARD_FUNCTION();

    if (GetSocket() == nullptr) {
        return false;
    }

    if (!FloatChecker::CheckValidation(m_data->m_dHP) || !FloatChecker::CheckValidation(m_data->m_dCP)) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[PLog] HP(%.5f(%p)/%.5f(%p)) "
        //     L"CP(%.5f(%p)/%.5f(%p))",
        //     m_data->m_dHP,
        //     DoubleBitsAsPointer(m_data->m_dHP),
        //     m_data->m_dBaseHP,
        //     DoubleBitsAsPointer(m_data->m_dBaseHP),
        //     m_data->m_dCP,
        //     DoubleBitsAsPointer(m_data->m_dCP),
        //     m_data->m_dBaseCP,
        //     DoubleBitsAsPointer(m_data->m_dBaseCP))
        // Log.Add(
        //     LOG_ERROR,
        //     "[character state] HP/CP validation failed during HP-info preparation for character runtime ID %u. Observed HP
        //     %.17g (bits %p), base HP %.17g (bits %p), CP %.17g (bits %p), base CP %.17g (bits %p). Requesting optional
        //     packet history and continuing HP-info processing.", m_nId, m_data->m_dHP, DoubleBitsAsPointer(m_data->m_dHP),
        //     m_data->m_dBaseHP, DoubleBitsAsPointer(m_data->m_dBaseHP),
        //     m_data->m_dCP, DoubleBitsAsPointer(m_data->m_dCP),
        //     m_data->m_dBaseCP, DoubleBitsAsPointer(m_data->m_dBaseCP))
        L2_LOG_ERROR(
            Log,
            "[character state] HP/CP validation failed during HP-info preparation for character runtime ID %u. Observed HP "
            "%.17g (bits %p), base HP %.17g (bits %p), CP %.17g (bits %p), base CP %.17g (bits %p); requesting optional "
            "packet history and continuing HP-info processing.",
            m_nId, m_data->m_dHP, DoubleBitsAsPointer(m_data->m_dHP), m_data->m_dBaseHP,
            DoubleBitsAsPointer(m_data->m_dBaseHP), m_data->m_dCP, DoubleBitsAsPointer(m_data->m_dCP), m_data->m_dBaseCP,
            DoubleBitsAsPointer(m_data->m_dBaseCP)
        );
        GetSocket()->ReportPacketLog(false);
    }

    const int packetReason = static_cast<int>(static_cast<std::int8_t>(reason));
    const int hp = runtime::Win64CvttDoubleToInt32(m_data->m_dHP);
    const int maximumHp = runtime::Win64CvttDoubleToInt32(m_data->m_dBaseHP);
    const int cp = runtime::Win64CvttDoubleToInt32(m_data->m_dCP);
    const int maximumCp = runtime::Win64CvttDoubleToInt32(m_data->m_dBaseCP);
    const auto sendPacket = [this, objectId, packetReason, hp, maximumHp, cp, maximumCp](CUserSocket* destination) {
        destination->Send(
            "cddcccdcdcdcd", 0x18, runtime::Int32FromBits(m_nId), objectId, packetReason, 4, 9, hp, 10, maximumHp, 0x21,
            cp, 0x22, maximumCp
        );
    };
    sendPacket(GetSocket());

    if (reason == 6) {
        CCreature* const target = g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(objectId));
        if (target != nullptr && target->IsPC()) {
            User* const targetUser = target->CastUser();
            sendPacket(targetUser->GetSocket());
        }
    }

    if (CParty* const party = GetParty()) {
        if (deferPartyUpdate) {
            m_bParamHPCPMPChanged = true;
            m_nParamHPCPMPChanged |= 1U;
        } else {
            party->UpdateWindowPacket(this, 1, reason, objectId, 0);
        }
    }

    if (m_EventMatchUser.m_byEventMatchTeamId != 0) {
        CSPointer<CEventMatch> eventMatch = m_EventMatchUser.GetEventMatch();
        if (eventMatch) {
            eventMatch->UpdateUserStatus(this, 1);
        }
    }

    if (m_pWOlympiadUser != nullptr && m_pWOlympiadUser->IsPlayer()) {
        if (WOlympiadMatch* const field = m_pWOlympiadUser->GetField()) {
            field->UpdateUserStatus(GetServerId(), 1);
        }
    }

    if (m_PledgeGameUser.IsPlayer()) {
        if (CPledgeGameField* const field = m_PledgeGameUser.GetField()) {
            field->RegisterMessage(6, static_cast<std::int32_t>(GetServerId()), 1, false);
        }
    }

    if (m_DuelUserInfo.IsInFightStatus()) {
        CDuelManager::inst().UpdateDuelPlayerStatus(this);
    }
    return true;
}

bool User::SendUserMPInfo(const int reason, const int objectId, const bool deferPartyUpdate) {
    // Current L2Server 0x00b29548.
    L2_GUARD_FUNCTION();

    if (GetSocket() == nullptr) {
        return false;
    }

    GetSocket()->Send(
        "cddcccdcd", 0x18, runtime::Int32FromBits(m_nId), objectId, static_cast<int>(static_cast<std::int8_t>(reason)), 2,
        0x0b, runtime::Win64CvttDoubleToInt32(m_data->m_dMP), 0x0c, runtime::Win64CvttDoubleToInt32(m_data->m_dBaseMP)
    );

    if (CParty* const party = GetParty()) {
        if (deferPartyUpdate) {
            m_bParamHPCPMPChanged = true;
            m_nParamHPCPMPChanged |= 2U;
        } else {
            party->UpdateWindowPacket(this, 2, reason, objectId, 0);
        }
    }

    if (m_EventMatchUser.m_byEventMatchTeamId != 0) {
        CSPointer<CEventMatch> eventMatch = m_EventMatchUser.GetEventMatch();
        if (eventMatch) {
            eventMatch->UpdateUserStatus(this, 2);
        }
    }

    if (m_DuelUserInfo.IsInFightStatus()) {
        CDuelManager::inst().UpdateDuelPlayerStatus(this);
    }
    return true;
}

