void User::SetParty(CParty* const party, User* const partyMaster) {
    // Current L2Server 0x00b297a0.
    L2_GUARD_FUNCTION();

    if (!party) {
        if (CParty* const currentParty = GetParty()) {
            currentParty->OnLeaveParty(*this);
        }

        const std::uint8_t teamId = m_EventMatchUser.m_byEventMatchTeamId;
        if (static_cast<std::int8_t>(teamId) > 0) {
            CSPointer<CEventMatch> eventMatch = m_EventMatchUser.GetEventMatch();
            if (eventMatch) {
                eventMatch->LeaveUser(this, partyMaster, teamId);
            }
        }

        SetPrivateID(0);
        m_nPartySid = 0;
        m_data->m_nPartyId = 0;
        m_data->m_nPartyIndex = -1;
        m_data->m_bPartyMaster = false;
    } else {
        m_nPartySid = party->m_nId;
        m_data->m_nPartyId = static_cast<std::uint32_t>(party->m_data->m_nId);
        m_data->m_nPartyIndex = party->m_data->index;
        m_data->m_bPartyMaster = party->m_data->m_OnlineMaster.id == m_nId;
        party->OnJoinParty(*this);
    }

    m_nParamChanged |= std::int64_t{PCB_PLEDGE | PCB_USER};
    runtime::raw_atomic::ExchangeI32(&m_nRelationChanged, 2);
}

