bool User::CreateMPCCWithItem(User* const targetUser) {
    // Current L2Server 0x00b3d24c, original owner User.cpp.
    L2_GUARD_FUNCTION();

    CItem* const item = GetPendingUseETCItem(PUIT_MPCC_CREATE);
    SetPendingUseETCItem(nullptr, PUIT_MPCC_CREATE);
    if (item == nullptr) {
        return true;
    }

    if (CanUseItem(item) && UseItem(*item, 0, true, 0) && targetUser != nullptr) {
        auto* const job = new AtomicCreateMPCC(Id(), targetUser->Id());
        if (DeleteItemInInventory(item->m_data->m_nClassID, 1, job, false, false)) {
            return true;
        }

        GetSocket()->Send(
            "chccdcQ", 0x62, SystemMessageId::NAMED_ITEM_QUANTITY_REQUIRED, 2, 3, item->m_data->m_nClassID, 6,
            std::int64_t{1}
        );
        job->Destroy();
        return true;
    }

    GetSocket()->SendSystemMessage_d(SystemMessageId::NAMED_ACTION_CONDITIONS_NOT_MET, item->m_data->m_nClassID);
    return true;
}

bool User::IsPartyJoinable() {
    // Current L2Server.exe 0x00b5ed30.
    L2_GUARD_FUNCTION();

    CCursedWeaponMgr::inst();
    if (m_nCursedWeaponClassId > 0) {
        return false;
    }
    if (CPVPMatchSystem::inst().IsCrataeCubeUser(*this)) {
        SendSystemMessage(SystemMessageId::CANNOT_FORM_PARTY_IN_THIS_AREA);
        return false;
    }
    if (m_data->m_PVPMatchType == PVPMatchType::CLEFT) {
        SendSystemMessage(SystemMessageId::CANNOT_FORM_PARTY_IN_THIS_AREA);
        return false;
    }
    if (CUndergroundColosseum::IsPartyPVPPlayer(*this)) {
        return false;
    }
    if (m_pWOlympiadUser->IsPlaying()) {
        GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_SEND_PARTY_OR_FRIEND_INVITATION_DURING_OLYMPIAD);
        return false;
    }
    if (m_PledgeGameUser.IsPlayer()) {
        GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_INVITE_FRIEND_OR_PARTY_DURING_CEREMONY_OF_CHAOS);
        return false;
    }
    if (m_data->m_TrainingState == 1) {
        SendSystemMessage(SystemMessageId::CANNOT_TAKE_OTHER_ACTIONS_WHILE_IN_TRAINING_CAMP);
        return false;
    }
    return true;
}

bool User::AskJoinMPCC(User* const user, const MPCCCreateType createType) {
    // Current L2Server 0x00b5f32c, original owner User.cpp.
    L2_GUARD_FUNCTION();

    if (createType == MCT_ITEM && CMultiPartyCommandChannelRegistry::IsChannelOwner(GetParty())) {
        return false;
    }
    if (user == nullptr) {
        SendSystemMessage(SystemMessageId::INVALID_PARTY_INVITATION_TARGET);
        return false;
    }
    if (user->m_bBlockAll) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::TARGET_BLOCKS_ALL, user->GetName());
        return false;
    }
    if (user->IsInBlockList(*this)) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_BLOCKED_YOU, user->GetName());
        return false;
    }
    if (m_data->m_TrainingState == 1) {
        SendSystemMessage(SystemMessageId::CANNOT_TAKE_OTHER_ACTIONS_WHILE_IN_TRAINING_CAMP);
        return false;
    }
    if (user->m_data->m_TrainingState == 1) {
        SendSystemMessage(SystemMessageId::CANNOT_SEND_REQUEST_TO_CHARACTER_IN_TRAINING_CAMP);
        return false;
    }
    if (user->m_data->m_cIsGuilty != 0 || m_nCursedWeaponClassId > 0 || user->m_nCursedWeaponClassId > 0) {
        return false;
    }

    CParty* const invitedParty = user->GetParty();
    CParty* const requesterParty = GetParty();
    if (invitedParty == nullptr || invitedParty == requesterParty) {
        SendSystemMessage(SystemMessageId::INVALID_PARTY_INVITATION_TARGET);
        return false;
    }
    User* const invitedMaster = invitedParty->GetMaster();
    if (invitedMaster == nullptr) {
        SendSystemMessage(SystemMessageId::INVALID_PARTY_INVITATION_TARGET);
        return false;
    }

    CMultiPartyCommandChannel* const channel = GetMPCC();
    if (channel != nullptr && !channel->IsMaster(GetServerId())) {
        SendSystemMessage(SystemMessageId::NO_AUTHORITY_TO_INVITE_TO_COMMAND_CHANNEL);
        return false;
    }

    if (requesterParty == nullptr || !IsPartyMaster()) {
        SendSystemMessage(SystemMessageId::NO_AUTHORITY_TO_INVITE_TO_COMMAND_CHANNEL);
        return false;
    }
    if (!CMultiPartyCommandChannelRegistry::IsChannelOwner(requesterParty)) {
        if (!CMultiPartyCommandChannelRegistry::IsAvailable()) {
            SendSystemMessage(SystemMessageId::CANNOT_CREATE_MORE_COMMAND_CHANNELS);
            return false;
        }
        if (createType == MCT_NORMAL_SKILL) {
            CSPointer<User> requester(this, ObjectRefType::FunctionChain);
            if (!CMultiPartyCommandChannelManager::CanOpen(std::move(requester))) {
                SendSystemMessage(SystemMessageId::NO_AUTHORITY_TO_INVITE_TO_COMMAND_CHANNEL);
                return false;
            }
        }
    }

    if (CMultiPartyCommandChannelRegistry::IsChannelMember(invitedParty)) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::TARGET_PARTY_ALREADY_IN_COMMAND_CHANNEL, invitedMaster->GetName());
        return false;
    }
    if (CReplyChecker::IsUserWaitingReply(this)) {
        SendSystemMessage(SystemMessageId::WAITING_FOR_ANOTHER_OPERATION_REPLY);
        return false;
    }
    if (!CReplyChecker::AttachReplyChecker(9, this, invitedMaster, 0x3c)) {
        GetSocket()->Send(
            "chccS", 0x62, SystemMessageId::INVITED_CHARACTER_BUSY, 1, 0x0c, invitedMaster->CastUser()->GetName2(this)
        );
        return false;
    }

    invitedMaster->GetSocket()->Send("chSd", 0xfe, 0x1a, GetName(), static_cast<int>(createType));
    return true;
}

