// User::IncreaseSoulCount@0x00b0517c.
bool User::IncreaseSoulCount(int count, const int emitterId) {
    L2_GUARD_FUNCTION();
    const bool increased = [&] {
        L2_GUARD(*m_lock);

        const int maximum = m_SkillMod.m_SoulMaxCount;
        if (m_SoulCount >= maximum) {
            return false;
        }

        if (maximum < runtime::AddInt32Wrapping(m_SoulCount, count)) {
            count = runtime::SubtractInt32Wrapping(maximum, m_SoulCount);
        }
        m_SoulStartTime = runtime::GetTickCount();
        m_SoulCount = runtime::AddInt32Wrapping(m_SoulCount, count);
        return true;
    }();
    if (!increased) {
        SendSystemMessage(static_cast<unsigned int>(SystemMessageId::SOUL_COUNT_CANNOT_INCREASE));
        return false;
    }

    GetSocket()->Send(
        "chccccc", 0x62, SystemMessageId::SOUL_COUNT_INCREASED_WITH_TOTAL, 2, 0x14,
        static_cast<int>(static_cast<std::int8_t>(count)), 0x14, static_cast<int>(static_cast<std::int8_t>(m_SoulCount))
    );
    SendETCBuffStatusInfo();
    if (emitterId != 0) {
        BroadcastEmitterSpawn(emitterId, GetServerId(), 0);
    }
    return true;
}

bool User::DecreaseSoulCount(int count) {
    L2_GUARD_FUNCTION();
    const bool insufficient = [&] {
        L2_GUARD(*m_lock);

        const bool insufficient = m_SoulCount < count;
        if (insufficient) {
            SendSystemMessage(static_cast<unsigned int>(SystemMessageId::NOT_ENOUGH_SOULS));
        } else {
            m_SoulCount = runtime::SubtractInt32Wrapping(m_SoulCount, count);
        }

        return insufficient;
    }();
    if (!insufficient) {
        SendETCBuffStatusInfo();
    }
    return !insufficient;
}

