bool User::OnSwapAgathionSlotItemsPacket(protocol::C_EX_SWAP_AGATHION_SLOT_ITEMS_INFO& packet) {
    L2_GUARD_FUNCTION();

    if (packet.SrcSlotBitType == packet.DestSlotBitType) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::OnSwapAgathionSlotItemsPacket failed. "
        //     "SrcSlotBitType(%I64d) == sReqPacket.DestSlotBitType(%I64d)",
        //     "User.cpp",
        //     0x84a0,
        //     packet.SrcSlotBitType,
        //     packet.DestSlotBitType)
        L2_LOG_ERROR(
            Log, "[Agathion] Cannot swap slots: source bit type %I64d equals destination bit type %I64d.",
            packet.SrcSlotBitType, packet.DestSlotBitType
        );
        return false;
    }

    const auto isAgathionSlotBit = [](std::int64_t slotBit) {
        return slotBit == 0x0000001000000000LL || slotBit == 0x0000002000000000LL || slotBit == 0x0000004000000000LL ||
            slotBit == 0x0000008000000000LL || slotBit == 0x0000010000000000LL;
    };
    if (!isAgathionSlotBit(packet.SrcSlotBitType) || !isAgathionSlotBit(packet.DestSlotBitType)) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::OnSwapAgathionSlotItemsPacket failed. "
        //     "Invalid SlotBitType - Src(%I64d)/Dest(%I64d)",
        //     "User.cpp",
        //     0x84b3,
        //     packet.SrcSlotBitType,
        //     packet.DestSlotBitType)
        L2_LOG_ERROR(
            Log, "[Agathion] Cannot swap slots: source bit type %I64d or destination bit type %I64d is invalid.",
            packet.SrcSlotBitType, packet.DestSlotBitType
        );
        return false;
    }

    SlotType sourceSlot = ST_NONE;
    SlotType destinationSlot = ST_NONE;
    for (int slot = 0; slot < ST_MAX; ++slot) {
        if ((ST2SBT[slot] & packet.SrcSlotBitType) != 0) {
            sourceSlot = static_cast<SlotType>(slot);
        }
        if ((ST2SBT[slot] & packet.DestSlotBitType) != 0) {
            destinationSlot = static_cast<SlotType>(slot);
        }
    }

    if (sourceSlot == ST_NONE || destinationSlot == ST_NONE) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::OnSwapAgathionSlotItemsPacket failed. "
        //     "Invalid SlotType - Src(%d)/Dest(%d)",
        //     "User.cpp",
        //     0x84cc,
        //     static_cast<int>(sourceSlot),
        //     static_cast<int>(destinationSlot))
        L2_LOG_ERROR(
            Log, "[Agathion] Cannot swap slots: resolved source slot %d or destination slot %d is invalid.",
            static_cast<int>(sourceSlot), static_cast<int>(destinationSlot)
        );
        return false;
    }

    CItem* const sourceItem = m_inv.GetByServerID(packet.SrcItemID);
    if (sourceItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::OnSwapAgathionSlotItemsPacket failed. "
        //     "SrcItem is nullptr",
        //     "User.cpp",
        //     0x84d5)
        L2_LOG_ERROR(Log, "[Agathion] Cannot swap slots: source item %d is missing.", packet.SrcItemID);
        return false;
    }

    CItem* const destinationItem = m_inv.GetByServerID(packet.DestItemID);
    if (destinationItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::OnSwapAgathionSlotItemsPacket failed. "
        //     "DestItem is nullptr",
        //     "User.cpp",
        //     0x84dc)
        L2_LOG_ERROR(Log, "[Agathion] Cannot swap slots: destination item %d is missing.", packet.DestItemID);
        return false;
    }

    if (!SwapAgathionSlotItems(sourceItem, sourceSlot, destinationItem, destinationSlot)) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::SwapAgathionSlotItems() failed",
        //     "User.cpp",
        //     0x84e3)
        L2_LOG_ERROR(
            Log, "[Agathion] Slot swap failed for source item %d and destination item %d.", packet.SrcItemID,
            packet.DestItemID
        );
    }

    // The current executable clears AL on every exit, including success.
    return false;
}

void User::_OnSwapAgathionSlotItems(CItem* firstItem, SlotType firstSlot, CItem* secondItem, SlotType secondSlot) {
    L2_GUARD_FUNCTION();
    if (firstItem != nullptr && secondItem != nullptr) {
        _OnUnequipItemProcess(firstItem, firstSlot);
        _OnUnequipItemProcess(secondItem, secondSlot);
        _OnEquipItem(firstItem, secondSlot);
        _OnEquipItem(secondItem, firstSlot);
    }
}

bool User::AgathionSwapItemForBuilder(int sourceSlot, int destinationSlot) {
    L2_GUARD_FUNCTION();

    CItem* const sourceItem = m_inv.GetByIndex(m_data->m_nSlotIndex[sourceSlot]);
    if (sourceItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::AgathionSwapItemForBuilder failed. "
        //     "SrcItem is nullptr",
        //     "User.cpp",
        //     0x86f1)
        L2_LOG_ERROR(Log, "[Agathion] Builder swap cannot find an item in source slot %d.", sourceSlot);
        return false;
    }

    CItem* const destinationItem = m_inv.GetByIndex(m_data->m_nSlotIndex[destinationSlot]);
    if (destinationItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] User::AgathionSwapItemForBuilder failed. "
        //     "DestItem is nullptr",
        //     "User.cpp",
        //     0x86f8)
        L2_LOG_ERROR(Log, "[Agathion] Builder swap cannot find an item in destination slot %d.", destinationSlot);
        return false;
    }

    protocol::C_EX_SWAP_AGATHION_SLOT_ITEMS_INFO packet;
    packet.SrcSlotBitType = ST2SBT[sourceSlot];
    packet.SrcItemID = sourceItem->m_data->m_nId;
    packet.DestSlotBitType = ST2SBT[destinationSlot];
    packet.DestItemID = destinationItem->m_data->m_nId;
    return OnSwapAgathionSlotItemsPacket(packet);
}

