bool User::IsBuilder() {
    L2_GUARD_FUNCTION();
    return static_cast<std::uint32_t>(m_data->m_nBuilder) - 1U < 9U;
}

bool User::UpdateBuilder(const int builderLevel) {
    // Current L2Server 0x00b5eef4.
    L2_GUARD_FUNCTION();
    int previousBuilderLevel = 0;
    {
        L2_GUARD(*m_lock);
        previousBuilderLevel = m_data->m_nBuilder;
        m_data->SetBuilder(builderLevel);
    }

    if (builderLevel < 0) {
        L2_GUARD(*m_lock);
        if (m_pBuilderCmdHistory != nullptr) {
            m_pBuilderCmdHistory->ClearList();
        }
    }

    if (previousBuilderLevel == 0) {
        if (builderLevel < 1) {
            return true;
        }
        L2_GUARD(*m_lock);
        if (m_pBuilderCmdHistory == nullptr) {
            m_pBuilderCmdHistory = new BuilderCmdHistory(this);
        }
    } else {
        if (previousBuilderLevel < 1 || builderLevel != 0 || m_pBuilderCmdHistory == nullptr) {
            return true;
        }
        L2_GUARD(*m_lock);
        L2_RELEASE(m_pBuilderCmdHistory, ObjectRefType::CreateDelete);
        m_pBuilderCmdHistory = nullptr;
    }
    return true;
}

void User::LogAbnormalAction(AbnormalUserAction action, bool forceClose, int value1, int value2, int value3, int value4) {
    L2_GUARD_FUNCTION();
    CLogFormatter formatter;
    formatter.WriteLog2(
        0x6a8, this, nullptr, static_cast<int>(action), forceClose ? 1 : 0, value1, value2, value3, value4, 0
    );
    if (!forceClose) {
        return;
    }

    CUserSocket* const socket = GetSocket();
    if (!socket) {
        return;
    }
    if (action != AUA_NOT_EXIST_ITEM_IN_USERDB) {
        CBotBlockManager::inst().AddAsBotUser(socket->GetAccountID());
    }
    socket->ForceClose(SCR_ILLEGAL_BEHAVIOR);
}

bool User::CanDoAction_china() {
    L2_GUARD_FUNCTION();
    if (GetSocket() == nullptr) {
        return false;
    }
    return GetSocket()->CanDoAction_china();
}

void User::CheckRelaxType() {
    L2_GUARD_FUNCTION();
    if (g_nPlayTimeLimit < 1) {
        return;
    }

    const bool spendPlaytime = !m_AreaMod.m_bIsInPeaceField;
    if (!spendPlaytime || m_AreaMod.m_bIsInBattleField || m_bIsObserving) {
        if (!m_bStopTime) {
            m_bStopTime = true;
            GetSocket()->SetSitTimeStart();
        }
        return;
    }

    if (m_bStopTime) {
        GetSocket()->SetEndSitTimeStart();
        m_bStopTime = false;
    }
}

