void User::SetInkEnergy(int value) {
    L2_GUARD_FUNCTION();
    L2_GUARD(*m_lock);

    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_INVITATION);
    if (baseEvent == nullptr) {
        return;
    }

    const auto* const event = static_cast<CEvent_InvitationEvent*>(baseEvent);
    if (value < 0) {
        value = 0;
    }
    if (event->GetMaxInkEnergy() <= value) {
        value = event->GetMaxInkEnergy();
    }
    m_data->m_nInkEnergy = value;
    SendInkEnergyInvitationEventPacket(m_data->m_nInkEnergy);
}

void User::UpdateInkEnergy(int value, const bool setDirectly) {
    // Current L2Server 0x00b6de5c.
    L2_GUARD_FUNCTION();
    L2_GUARD(*m_lock);

    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_INVITATION);
    if (baseEvent == nullptr) {
        return;
    }

    if (!setDirectly) {
        value = runtime::AddInt32Wrapping(value, m_data->m_nInkEnergy);
    }
    value = std::max(value, 0);
    value = std::min(value, static_cast<CEvent_InvitationEvent*>(baseEvent)->GetMaxInkEnergy());
    if (m_data->m_nInkEnergy == value) {
        return;
    }

    db.RequestSetEventScore(baseEvent->GetEventType(), 1, GetDBID(), value);
}

