const unsigned char* User::SetSSQInfo(const unsigned char* packet) {
    L2_GUARD_FUNCTION();

    std::int32_t roundNumber;
    std::int32_t part;
    std::int32_t position;
    std::int32_t sealSelection;
    std::int64_t point;
    std::int64_t twilightItemCount[3];
    std::int64_t dawnItemCount[3];
    std::int32_t ticketBuyCount;

    const unsigned char* const remainder = ::Disassemble(
        packet, "ddddQQQQQQQd", &roundNumber, &part, &position, &sealSelection, &point, &twilightItemCount[0],
        &twilightItemCount[1], &twilightItemCount[2], &dawnItemCount[0], &dawnItemCount[1], &dawnItemCount[2],
        &ticketBuyCount
    );

    m_data->m_nSSQRoundNumber = roundNumber;
    m_data->m_nSSQPart = part;
    m_data->m_nSSQPosition = position;
    m_data->m_nSealSelectionNo = sealSelection;
    m_data->m_nSSQPoint = point;
    m_data->m_nTwilightItemCount[0] = twilightItemCount[0];
    m_data->m_nTwilightItemCount[1] = twilightItemCount[1];
    m_data->m_nTwilightItemCount[2] = twilightItemCount[2];
    m_data->m_nDawnItemCount[0] = dawnItemCount[0];
    m_data->m_nDawnItemCount[1] = dawnItemCount[1];
    m_data->m_nDawnItemCount[2] = dawnItemCount[2];
    m_data->m_nTicketBuyCount = ticketBuyCount;
    return remainder;
}

void User::SetPetitionSeq(wchar_t* petitionSequence) {
    L2_GUARD_FUNCTION();
#if defined(_WIN32)
    static_assert(sizeof(wchar_t) == sizeof(char16_t));
    const auto* source = reinterpret_cast<const char16_t*>(petitionSequence);
    std::size_t index = 0;
    while (index < 0x1ff && source[index] != u'\0') {
        m_PetitionSeq[index] = source[index];
        ++index;
    }
    m_PetitionSeq[index] = u'\0';
#else
    CopyHostWideToTargetUserName(petitionSequence, m_PetitionSeq, 0x1ff);
#endif
    m_CanPetitionVote = true;
}

void User::SendPetitionVote(int* petitionIds, int petitionCount, wchar_t* message, int messageLength) {
    // Current L2Server 0x00b0bbb0.
    L2_GUARD_FUNCTION();

    char16_t* const petitionSequence = m_PetitionSeq;
    if (!m_CanPetitionVote || petitionSequence == nullptr) {
        return;
    }

    m_CanPetitionVote = false;
    std::array<char, 0x5000> packet{};
    int packetLength = 0;

    const int sequenceLength = static_cast<int>(std::char_traits<char16_t>::length(petitionSequence));
    int assembled = ::Assemble(
        packet.data(), static_cast<int>(packet.size()), "hbc", sequenceLength, sequenceLength * 2, petitionSequence,
        petitionCount
    );
    if (assembled > 0) {
        packetLength = assembled;
    }

    for (int index = 0; index < petitionCount; ++index) {
        assembled = ::Assemble(
            packet.data() + packetLength, static_cast<int>(packet.size()) - packetLength, "c", petitionIds[index]
        );
        if (assembled > 0) {
            packetLength += assembled;
        }
    }

    const void* targetMessage = message;
#if !defined(_WIN32)
    std::array<char16_t, 512> targetMessageStorage{};
    for (int index = 0; index < messageLength; ++index) {
        targetMessageStorage[static_cast<std::size_t>(index)] = static_cast<char16_t>(message[index]);
    }
    targetMessage = targetMessageStorage.data();
#else
    static_assert(sizeof(wchar_t) == sizeof(char16_t));
#endif
    assembled = ::Assemble(
        packet.data() + packetLength, static_cast<int>(packet.size()) - packetLength, "hb", messageLength, messageLength * 2,
        targetMessage
    );
    if (assembled > 0) {
        packetLength += assembled;
    }

    petitionCli.RequestFeedback(packetLength, packet.data());
    std::fill_n(petitionSequence, 512, u'\0');
    SendSystemMessage(SystemMessageId::FEEDBACK_SUBMISSION_THANKS);
}

