bool User::CheckAbilityCond() {
    L2_GUARD_FUNCTION();

    if (m_pWOlympiadUser->IsPlaying() || m_PledgeGameUser.IsPlaying() || m_PledgeGameUser.IsWaiting()) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_OR_RESET_ABILITY_POINTS_DURING_OLYMPIAD_OR_CHAOS);
        return false;
    }

    if (m_nAbilityClass == m_data->m_nSubJobId) {
        return true;
    }

    runtime::raw_atomic::ExchangeI32(&m_nAbilityClass, -1);
    if (CUserSocket* socket = GetSocket()) {
        socket->Send("ch", 0xfe, 0x167);
    }
    return false;
}

bool User::OnRequestResetAbilitySkillPacket(const unsigned char*) {
    // Current L2Server 0x00b238b4, original owner User.cpp.
    L2_GUARD_FUNCTION();

    {
        L2_GUARD(m_AcquiredAbilitySkillsLock);
        if (m_AcquiredAbilitySkills.empty()) {
            return false;
        }
    }

    if (CPotentialSkillDB::Inst().m_nResetSP != 0) {
        L2_GUARD(*m_lock);
        if (m_data->m_nSP < CPotentialSkillDB::Inst().m_nResetSP) {
            return false;
        }
        SPInc(runtime::NegateInt64Wrapping(CPotentialSkillDB::Inst().m_nResetSP));
    }

    db.RequestResetAbilitySkillToDB(*this, CPotentialSkillDB::Inst().m_nResetSP);
    return true;
}

bool User::OnRequestAbilitySkillPacket(const unsigned char* const packet) {
    // Current L2Server 0x00b2cb44, original owner User.cpp.
    L2_GUARD_FUNCTION();

    CPacketHelperEx<20480> request;
    int totalAcquired = 0;
    int requestedAbilityPoints = 0;
    const unsigned char* cursor = ::Disassemble(packet, "d", &requestedAbilityPoints);
    request.Assemble("d", requestedAbilityPoints);
    if (m_data->GetAP() < requestedAbilityPoints) {
        return false;
    }

    for (int type = 1; type < 4; ++type) {
        int skillCount = 0;
        cursor = ::Disassemble(cursor, "d", &skillCount);
        request.Assemble("d", skillCount);

        int acquiredForType = 0;
        for (int index = 0; index < skillCount; ++index) {
            int skillId = 0;
            int skillLevel = 0;
            cursor = ::Disassemble(cursor, "dd", &skillId, &skillLevel);
            request.Assemble("dd", skillId, skillLevel);
            if (!IsLearnableAbilitySkill(skillId, skillLevel, type, acquiredForType)) {
                return false;
            }
            acquiredForType = runtime::AddInt32Wrapping(acquiredForType, skillLevel);
            totalAcquired = runtime::AddInt32Wrapping(totalAcquired, skillLevel);
        }
    }

    if (totalAcquired <= m_data->GetAP()) {
        db.SendAcquiredAbilitySkill(*this, request);
        return true;
    }
    return false;
}

bool User::EventByLuckyStat(bool premium) {
    L2_GUARD_FUNCTION();

    if (g_bLuckyTest) {
        return true;
    }

    const double levelBonus = g_PCParamDB.GetParamBonus(PC_LEVEL_BONUS, m_data->m_nLevel);
    const double luckBonus = g_PCParamDB.GetParamBonus(PC_LUC_BONUS, m_data->m_Stat.m_N[6]);

    double probability = 0.0;
    int maximumProbability = 0;
    if (premium) {
        probability = std::pow(levelBonus, 1.5) * luckBonus * luckBonus * luckBonus * 1.8;
        maximumProbability = 20;
    } else {
        probability = std::pow(luckBonus, 2.5) * std::pow(levelBonus, 1.5) * 1.2;
        maximumProbability = 15;
    }

    const int chance = std::min(runtime::Win64CvttDoubleToInt32(probability), maximumProbability);
    return ::genrand64_real1() * 100.0 + 0.0 <= static_cast<double>(chance);
}

void User::LogNPBuffStatus() {
    // Current L2Server 0x00b23d20.
    L2_GUARD_FUNCTION();
    L2_GUARD(m_InfectedSkillsSect);
    const std::int32_t now = runtime::crt::Time32Now();
    for (const InfectedSkillType& infected : m_InfectedSkills) {
        CSkillInfo* const skill = infected.pSkillInfo;
        if (skill == nullptr || skill->m_nAbnormalType != -2) {
            continue;
        }
        CLogFormatter formatter;
        formatter.WriteLog2_1(
            0x1b9, this, this, skill->m_nSkillId,
            static_cast<std::int64_t>(
                (static_cast<std::uint32_t>(skill->m_nSubLevel) << 16) | static_cast<std::uint16_t>(skill->m_nLevel)
            ),
            infected.nDuration + infected.nStartTime - now, 0, 0, 0, 0
        );
    }
}

bool User::ItemBonusByLuckyStat(std::int64_t experience) {
    L2_GUARD_FUNCTION();

    if (g_bLuckyTest) {
        return true;
    }
    if (experience <= 0) {
        return false;
    }

    const std::int64_t standardExperience = g_PCParamDB.GetStandardExpByLevel(m_data->m_nLevel);
    const double luckBonus = g_PCParamDB.GetParamBonus(PC_LUC_BONUS, m_data->m_Stat.m_N[6]);
    const double calculatedProbability =
        (static_cast<double>(experience) / static_cast<double>(standardExperience)) * luckBonus * luckBonus * 3.17;
    const double probability = 1.5 > calculatedProbability ? calculatedProbability : 1.5;
    return ::genrand64_real1() * 100.0 + 0.0 <= probability;
}

bool User::SetInteractRejectType(int type, int value) {
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(m_InteractRejectTypesLock);
    }
    if (static_cast<std::uint32_t>(type) < m_InteractRejectTypes.size()) {
        m_InteractRejectTypes[static_cast<std::size_t>(type)] = value;
    }
    return false;
}

bool User::AllowInteractWith(User* const user, const ClientINI::InteractType type) {
    // Current L2Server.exe 0x00b33c84.
    L2_GUARD_FUNCTION();

    if (user == nullptr || static_cast<std::uint32_t>(type) >= static_cast<std::uint32_t>(ClientINI::IT_MAX)) {
        return false;
    }

    int relation = 0;
    CSPointer<CFriends> friends = GetFriends();
    if (friends && friends->HasFriend(user->GetDBID())) {
        // relation = 4.
        relation = ClientINI::IRB_FRIEND;
    }

    CPledge* const pledge = GetPledge();
    CPledge* const targetPledge = user->GetPledge();
    if (pledge != nullptr && targetPledge != nullptr) {
        const std::uint32_t targetPledgeId = targetPledge->GetDbId();
        if (pledge->GetDbId() == targetPledgeId) {
            // relation |= 2.
            relation |= ClientINI::IRB_PLEDGE;
        }
    }
    if (relation == 0) {
        // relation = 1.
        relation = ClientINI::IRB_PUBLIC;
    }

    {
        L2_GUARD(m_InteractRejectTypesLock);
    }
    return (m_InteractRejectTypes[static_cast<std::size_t>(type)] & relation) == 0;
}

bool User::SetSnoop(int snoopGmId) {
    L2_GUARD_FUNCTION();

    if (snoopGmId < 1 || m_nSnoopGmId < 1) {
        if (snoopGmId == 0) {
            CCreature* const snoopGm = g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(m_nSnoopGmId));
            if (snoopGm != nullptr && snoopGm->IsPC()) {
                snoopGm->CastUser()->SetSnoopClient(0);
            }
            m_nSnoopGmId = 0;
        } else {
            CCreature* const snoopGm = g_CreatureSmartIdManager.GetObjectW(static_cast<std::uint32_t>(snoopGmId));
            if (snoopGm == nullptr || !snoopGm->IsPC()) {
                return false;
            }
            snoopGm->CastUser()->SetSnoopClient(static_cast<int>(m_nId));
            m_nSnoopGmId = snoopGmId;
        }
        return true;
    }
    return false;
}

