double User::GetAdjustedRaidPoint(int point) {
    L2_GUARD_FUNCTION();
    double adjustedPoint =
        static_cast<double>(point) + (m_SkillDurationMod.m_dRaidPointBonus / 100.0) * static_cast<double>(point);
    if (IsMPCCMaster()) {
        adjustedPoint *= 2.0;
    }
    return adjustedPoint;
}

void User::AddRaidPointBonus(double bonus) {
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(*m_lock);

        const double adjustedBonus = bonus + m_SkillDurationMod.m_dRaidPointBonus;
        if (adjustedBonus >= 0.0) {
            m_SkillDurationMod.m_dRaidPointBonus = adjustedBonus <= 300.0 ? adjustedBonus : 300.0;
        } else {
            m_SkillDurationMod.m_dRaidPointBonus = 0.0;

            // The target passes a double to a %d slot. Win64's variadic ABI
            // so exposes the low 32 bits of that stack slot.
            std::uint64_t adjustedBonusBits = 0;
            std::memcpy(&adjustedBonusBits, &adjustedBonus, sizeof(adjustedBonusBits));
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] raid Bonus Percent Out of Bounds - "
            //     L"RaidBonusPercent : %d",
            //     L"User.cpp",
            //     0x3efa,
            //     runtime::Int32FromBits(
            //         static_cast<std::uint32_t>(adjustedBonusBits)))
            L2_LOG_ERROR(
                Log, u"[raid points] Calculated bonus was below zero; clamped to zero (raw diagnostic %d).",
                runtime::Int32FromBits(static_cast<std::uint32_t>(adjustedBonusBits))
            );
        }
    }
}

int User::GetPrivateStoreType() { return m_data->m_nPrivateStoreType; }

void User::SendPrivateStoreMessage(CUserSocket* socket, PrivateStoreMessageType messageType) {
    // Current L2Server.exe 0x00b41dcc. The CHANGE_MESSAGE/open-recipe
    // branch does not test the message for emptiness. That is
    // an observable current-machine asymmetry kept below.
    L2_GUARD_FUNCTION();

    const int storeType = m_data->m_nPrivateStoreType;
    const FVector position = GetPos();
    // The LU4 client shows a store's sign only when it gets the title, so
    // while one is connected an empty title is sent as well.
    const auto hasText = [](const char16_t* text) {
        return text != nullptr && (text[0] != u'\0' || runtime::client_protocol::HasLu4Clients());
    };
    const auto sendDirect = [this, socket](int opcode, const char16_t* text, bool extended) {
        if (socket == nullptr) {
            return;
        }
        if (extended) {
            socket->Send("chdS", 0xfe, 0x81, static_cast<int>(m_nId), text);
        } else {
            socket->Send("cdS", opcode, static_cast<int>(m_nId), text);
        }
    };
    const auto broadcast = [this, &position](int opcode, const char16_t* text, bool extended, bool exceptSelf) {
        if (extended) {
            if (exceptSelf) {
                g_ptlUserMap->BroadcastToNeighborExceptSelf(
                    this, 0x80000, position, "chdS", 0xfe, 0x81, static_cast<int>(m_nId), text
                );
            } else {
                g_ptlUserMap->BroadcastToNeighbor(
                    *this, 0x80000, position, "chdS", 0xfe, 0x81, static_cast<int>(m_nId), text
                );
            }
            return;
        }
        if (exceptSelf) {
            g_ptlUserMap->BroadcastToNeighborExceptSelf(
                this, 0x80000, position, "cdS", opcode, static_cast<int>(m_nId), text
            );
        } else {
            g_ptlUserMap->BroadcastToNeighbor(*this, 0x80000, position, "cdS", opcode, static_cast<int>(m_nId), text);
        }
    };

    const char16_t* text = nullptr;
    int opcode = 0;
    bool extended = false;
    switch (storeType) {
        case PST_OPEN:
        case PST_MANAGE:
            text = m_wszPrivateStoreMsg;
            opcode = 0xa2;
            break;
        case PST_BUY_OPEN:
        case PST_BUY_MANAGE:
            text = m_wszPrivateStoreBuyMsg;
            opcode = 0xbf;
            break;
        case PST_RECIPE_SHOP_OPEN:
        case PST_RECIPE_SHOP_MANAGE:
            text = m_wszRecipeStoreMsg;
            opcode = 0xe1;
            break;
        case PST_WHOLESALE_OPEN:
        case PST_WHOLESALE_MANAGE:
            text = m_wszPrivateStoreWholeMsg;
            extended = true;
            break;
        default:
            return;
    }

    switch (messageType) {
        case PSMT_NO_BROADCAST:
            if (storeType != PST_OPEN && storeType != PST_BUY_OPEN && storeType != PST_RECIPE_SHOP_OPEN &&
                storeType != PST_WHOLESALE_OPEN) {
                return;
            }
            if (hasText(text)) {
                sendDirect(opcode, text, extended);
            }
            return;

        case PSMT_BROADCAST_EXCEPT_ME:
            if (storeType != PST_OPEN && storeType != PST_BUY_OPEN && storeType != PST_RECIPE_SHOP_OPEN &&
                storeType != PST_WHOLESALE_OPEN) {
                return;
            }
            if (hasText(text)) {
                broadcast(opcode, text, extended, true);
            }
            return;

        case PSMT_CHANGE_MESSAGE:
            if (storeType == PST_OPEN || storeType == PST_BUY_OPEN || storeType == PST_WHOLESALE_OPEN) {
                if (hasText(text)) {
                    broadcast(opcode, text, extended, false);
                }
                return;
            }
            if (storeType == PST_RECIPE_SHOP_OPEN) {
                broadcast(opcode, text, false, false);
                return;
            }
            if (storeType == PST_MANAGE || storeType == PST_BUY_MANAGE || storeType == PST_RECIPE_SHOP_MANAGE ||
                storeType == PST_WHOLESALE_MANAGE) {
                if (hasText(text)) {
                    sendDirect(opcode, text, extended);
                }
            }
            return;
    }
}

void User::AccmulateCharInfoStat(bool reset, int value) {
    // Current L2Server.exe 0x00b33654.
    L2_GUARD_FUNCTION();
    if (!g_bServerToUserPacketStatMonitor) {
        return;
    }

    if (reset) {
        m_NeedUpdatePacketBitsStat.SetAllBits();
        m_nParamChangedStat |= std::uint64_t{PCB_CHAR_INSIGHT};
    }

    const int byteCount = static_cast<int>(m_NeedUpdatePacketBitsStat.GetByteCount());
    for (int byteIndex = 0; byteIndex < byteCount; ++byteIndex) {
        if (byteIndex >= static_cast<int>(m_bNeedUpdatePacketBitsStat.size()) ||
            !m_bNeedUpdatePacketBitsStat[static_cast<std::size_t>(byteIndex)]) {
            continue;
        }
        const int firstBit = byteIndex * 8;
        for (int bit = firstBit; bit < 103; ++bit) {
            if (m_NeedUpdatePacketBitsStat.IsSet(static_cast<std::uint32_t>(bit))) {
                CPacketStat<103, 103>::Inst().Accumulate(bit, value);
            }
        }
    }
    m_NeedUpdatePacketBitsStat.Clear();

    std::uint64_t mask = UINT64_C(1);
    for (int bit = 0; bit < PCT_MAX; ++bit, mask <<= 1) {
        if ((m_nParamChangedStat & mask) != 0) {
            CPacketStat<48, 48>::Inst().Accumulate(bit, value);
        }
    }
    m_nParamChangedStat = 0;
}

