bool User::SetPrivateStoreList(const unsigned char* packet) {
    // Current L2Server 0x00b5a6b8.
    L2_GUARD_FUNCTION();
    int saleType = 0;
    int itemCount = 0;
    const unsigned char* const itemsPacket = ::Disassemble(packet, "dd", &saleType, &itemCount);
    if (saleType != 0 && saleType != 1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Invalid Sale Type[%d] user[%s]",
        //     L"User.cpp",
        //     0x26f2,
        //     saleType,
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[private store] Character '%s' requested invalid sale type %d.",
        //     GetName(),
        //     saleType)
        L2_LOG_ERROR(Log, u"[private store] Character '%s' requested invalid sale type %d.", GetName(), saleType);
        return false;
    }

    const bool wholesale = saleType == 1;
    if (itemCount < 1 || itemCount > GetPrivateStoreLimit()) {
        SendSystemMessage(SystemMessageId::INVALID_STORE_OR_WORKSHOP_ITEM_QUANTITY);
        SendPrivateStoreManageList(wholesale, GetSocket());
        return false;
    }

    std::vector<PrivateStoreItemData> relayItems;
    std::wstring classLog;
    // Retained manual ownership: current EXE acquires at 0x00b5a832.
    // Restricted-item branch 0x00b5a938 -> 0x00b5aa81 cleans up and
    // jumps at 0x00b5ab24 to 0x00b5b288, returning without unlock.
    // A scope guard would change this shipping behavior.
    m_inv.WriteLock(L"User.cpp", 0x26ff);
    const unsigned char* cursor = itemsPacket;
    std::int64_t priceSum = 0;
    bool valid = true;
    for (int index = 0; index < itemCount; ++index) {
        int serverId = 0;
        std::int64_t count = 0;
        std::int64_t price = 0;
        cursor = ::Disassemble(cursor, "dQQ", &serverId, &count, &price);
        // The packet lane is a CItem SmartID, not a shared-item index.
        // Current 0x00b5a8d8..0x00b5a8e3 calls the item SmartID manager's
        // GetObjectW directly with this decoded value.
        CItem* const item = ItemSmartIdManager()->GetObjectW(static_cast<std::uint32_t>(serverId));
        if (item && CItemRestrict::Inst().CheckItemRestrict(item->m_data->m_nClassID)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] Item Restrict on ClassID[%d]",
            //     L"User.cpp",
            //     0x2716,
            //     item->m_data->m_nClassID)
            L2_LOG_ERROR(
                Log, u"[private store] Restricted item class %d cannot be added to the sell list.", item->m_data->m_nClassID
            );
            // The current branch returns without releasing the inventory
            // write lock.
            return false;
        }
        if (!IsValidPrivateStoreItem(count, price, item)) {
            valid = false;
            break;
        }
        priceSum += count * price;
        if (priceSum < 1 || priceSum > INT64_C(999999999999)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"invalid amount at file[%s], line[%d], "
            //     L"nCount[%I64d]/nPrice[%I64d]/nPriceSum[%I64d]",
            //     L"User.cpp",
            //     0x2727,
            //     count,
            //     price,
            //     priceSum)
            L2_LOG_ERROR(
                Log, u"[private store] Sell-list total is invalid: count %I64d, price %I64d, accumulated total %I64d.",
                count, price, priceSum
            );
            SendSystemMessage(SystemMessageId::CANNOT_PROCEED_SALE_AMOUNT_EXCEEDS_ADENA_LIMIT);
            valid = false;
        }
        AppendPrivateStoreClassLog(classLog, item->m_data->m_nClassID);
    }

    if (!valid) {
        m_inv.WriteUnlock();
        SendPrivateStoreManageList(wholesale, GetSocket());
        return false;
    }
    if (m_bWaitCrystal) {
        m_inv.WriteUnlock();
        SendPrivateStoreManageList(wholesale, GetSocket());
        return false;
    }

    PrivateStoreMap& store = GetPrivateStoreMap(wholesale);
    DeletePrivateStoreEntries(store);
    cursor = itemsPacket;
    for (int index = 0; index < itemCount; ++index) {
        int serverId = 0;
        std::int64_t requestedCount = 0;
        std::int64_t price = 0;
        cursor = ::Disassemble(cursor, "dQQ", &serverId, &requestedCount, &price);
        // Current 0x00b5ad73..0x00b5ad7e repeats the same SmartID lookup
        // while materializing the accepted store entries.
        CItem* const item = ItemSmartIdManager()->GetObjectW(static_cast<std::uint32_t>(serverId));
        if (!IsValidPrivateStoreItem(requestedCount, price, item)) {
            continue;
        }

        const std::int64_t count = std::min(requestedCount, item->m_data->m_nCount);
        CPrivateStoreData* const data = new CPrivateStoreData(
            serverId, index, item->m_data->m_bBlessed, item->m_data->GetEnchanted(), item->m_data->m_nDamaged,
            static_cast<int>(item->GetDBID()), count, item->m_data->m_nClassID, price,
            item->m_itemOption.intensiveItemClassID, item->m_itemOption.itemOptionKey.variationOption1,
            item->m_itemOption.itemOptionKey.variationOption2, item->GetTotalAttribute(),
            item->m_data->GetShapeShiftedClassId()
        );
        data->SetEnsoulOption(item->m_mEnsoulInfo);
        store[static_cast<int>(item->Id())] = data;
        relayItems.emplace_back(item->m_data->m_nClassID, count, price, item->m_data->m_nDBID);
    }

    CPrivateStoreMarket::inst().InsertItems(static_cast<int>(Id()), wholesale, store);
    m_inv.WriteUnlock();
    // GetController()->PrivateStore(wholesale ? 7 : 1)
    GetController()->PrivateStore(wholesale ? PSA_WHOLE_SELL : PSA_SELL);
    RelayClient::Inst()->SendPrivateStoreOpen(this, relayItems);

    if (!classLog.empty()) {
        classLog.pop_back();
    }
    const std::uint32_t tick = runtime::GetTickCount();
    CLogFormatter formatter;
    formatter.WriteLog1(
        0x347, this, nullptr, WideToUtf16(classLog.empty() ? nullptr : classLog.data()), nullptr, nullptr, 1, saleType,
        static_cast<std::int64_t>(tick), 0, 0, 0, 0
    );
    for (const auto& entry : store) {
        CPrivateStoreData* const data = entry.second;
        char16_t shapeAndVariation[256]{};
        char16_t attribute[256]{};
        char16_t ensoul[256]{};
        data->MakeShapeShiftAndVariationLogInfo(shapeAndVariation);
        data->m_BaseAttribute.GetLogString(attribute);
        data->MakeEnsoulLogInfo(ensoul);
        formatter.WriteLog4(
            0x232e, this, nullptr, ensoul, attribute, shapeAndVariation, data->nClassId, data->nEnchanted, data->nCount,
            data->nPrice, 1, saleType, static_cast<std::int64_t>(tick), 0, 0, 0, data->nItemDBID
        );
    }
    return true;
}

void User::SetPrivateStoreBuyList(const unsigned char* packet) {
    // Current L2Server 0x00b54184.
    L2_GUARD_FUNCTION();
    int itemCount = 0;
    const unsigned char* const itemsPacket = ::Disassemble(packet, "d", &itemCount);
    if (itemCount < 1 || itemCount > GetPrivateStoreBuyLimit()) {
        SendSystemMessage(SystemMessageId::INVALID_STORE_OR_WORKSHOP_ITEM_QUANTITY);
        SendPrivateStoreBuyManageList(GetSocket());
        return;
    }

    // Retained manual ownership: current EXE acquires at 0x00b54278.
    // Restricted-item branch 0x00b5440d -> 0x00b54677 cleans up and
    // jumps at 0x00b5470a to 0x00b55217, skipping unlock 0x00b54eda.
    // A scope guard would change this shipping behavior.
    m_inv.WriteLock(L"User.cpp", 0x2bd7);
    bool valid = true;
    int addedNormalItems = 0;
    int addedArtifactItems = 0;
    int resultingWeight = m_inv.GetCarryingWeight();
    std::int64_t priceSum = 0;
    const unsigned char* cursor = itemsPacket;
    for (int index = 0; index < itemCount; ++index) {
        int classId = 0;
        std::int16_t enchanted = 0;
        std::int16_t damaged = 0;
        std::int64_t count = 0;
        std::int64_t price = 0;
        int variation1 = 0;
        int variation2 = 0;
        BaseAttribute attribute;
        int shapeShiftClassId = 0;
        std::map<int, EnsoulOptionData*> ensoulOptions[3];
        cursor = ::Disassemble(cursor, "dhhQQ", &classId, &enchanted, &damaged, &count, &price);
        cursor = CItem::DisassembleVariation(cursor, variation1, variation2);
        cursor = CItem::DisassembleAttribute(cursor, attribute);
        cursor = CItem::DisassembleShapeShift(cursor, shapeShiftClassId);
        cursor = CItem::DisassembleEnsoul(cursor, ensoulOptions);

        if (CItemRestrict::Inst().CheckItemRestrict(classId)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR]SetPrivateStoreBuyList item restrict on. "
            //     L"classid[%d]",
            //     classId)
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR]SetPrivateStoreBuyList item restrict on. "
            //     L"classid[%d]",
            //     classId)
            L2_LOG_DEBUG(
                Log,
                "[private store] Buy list rejected for character %u: "
                "item class %d is restricted.",
                static_cast<unsigned int>(GetDBID()), classId
            );
            // The current restricted-item branch leaves the write lock held.
            return;
        }
        if (count < 1) {
            SendSystemMessage(SystemMessageId::INVALID_STORE_OR_WORKSHOP_ITEM_QUANTITY);
            // Log.Add(
            //     LOG_ERROR,
            //     L"SetPrivateStoreBuyList request error. "
            //     L"invalid count[%I64d]",
            //     count)
            L2_LOG_ERROR(Log, u"[private store] Buy-list count %I64d is invalid; request rejected.", count);
            valid = false;
            break;
        }
        if (classId == 0x39) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] private store, try hack?",
            //     L"User.cpp",
            //     0x2c13)
            L2_LOG_ERROR(Log, u"[private store] Buy list requested adena as an item; request rejected.");
            valid = false;
            break;
        }
        if (enchanted < 0) {
            SendSystemMessage(SystemMessageId::INVALID_ITEM_ENCHANT_VALUE);
            // Log.Add(
            //     LOG_ERROR,
            //     L"SetPrivateStoreBuyList request error. "
            //     L"invalid enchanted[%d]",
            //     static_cast<int>(enchanted))
            L2_LOG_ERROR(
                Log, u"[private store] Buy-list enchant value %d is invalid; request rejected.", static_cast<int>(enchanted)
            );
            valid = false;
            break;
        }
        if (damaged < 0) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"SetPrivateStoreBuyList request error. "
            //     L"invalid damaged[%d]",
            //     static_cast<int>(damaged))
            L2_LOG_ERROR(
                Log, u"[private store] Buy-list damage value %d is invalid; request rejected.", static_cast<int>(damaged)
            );
            valid = false;
            break;
        }
        if (price < 1) {
            SendSystemMessage(SystemMessageId::INVALID_ITEM_PRICE);
            // Log.Add(
            //     LOG_ERROR,
            //     L"SetPrivateStoreBuyList request error. "
            //     L"invalid price[%I64d]",
            //     price)
            L2_LOG_ERROR(Log, u"[private store] Buy-list price %I64d is invalid; request rejected.", price);
            valid = false;
            break;
        }
        if (shapeShiftClassId < 0) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"SetPrivateStoreBuyList request error. "
            //     L"invalid ShapeShiftingClassId[%d]",
            //     shapeShiftClassId)
            L2_LOG_ERROR(
                Log,
                u"[private store] Buy-list appearance class %d is invalid; "
                u"request rejected.",
                shapeShiftClassId
            );
            valid = false;
            break;
        }

        CItem* const item = m_inv.GetFirstItemByAttribute(classId, attribute);
        if (item == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"g_ObjectDB.GetObject Failed. class id [%d]",
            //     classId)
            L2_LOG_ERROR(
                Log,
                u"[private store] Item class %d is absent from inventory; "
                u"buy-list request rejected.",
                classId
            );
            SendSystemMessage(SystemMessageId::INVALID_STORE_OR_WORKSHOP_ITEM_QUANTITY);
            valid = false;
        } else {
            if (item->IsArtifact()) {
                addedArtifactItems = runtime::AddInt32Wrapping(addedArtifactItems, 1);
            } else {
                addedNormalItems = runtime::AddInt32Wrapping(addedNormalItems, 1);
            }
            resultingWeight = runtime::AddInt32Wrapping(
                resultingWeight,
                runtime::MultiplyInt32Wrapping(
                    item->m_const->m_nWeight, runtime::Int32FromBits(static_cast<std::uint32_t>(count))
                )
            );
        }
        priceSum = runtime::AddInt64Wrapping(priceSum, runtime::MultiplyInt64Wrapping(count, price));
        if (!valid) {
            break;
        }
    }

    const bool artifactCapacityOkay =
        addedArtifactItems + m_data->m_nCurrentArtifactInventoryNum <= GetArtifactInventoryLimit();
    if (m_inv.GetTotalCount() + addedNormalItems > GetInventoryLimit()) {
        SendSystemMessage(SystemMessageId::CANNOT_EXCEED_INVENTORY_WEIGHT_OR_QUANTITY_LIMIT);
        SendSystemMessage(
            artifactCapacityOkay ? SystemMessageId::NOT_ENOUGH_INVENTORY_SPACE
                                 : SystemMessageId::NOT_ENOUGH_NORMAL_AND_ARTIFACT_INVENTORY_SPACE
        );
        valid = false;
    } else if (!artifactCapacityOkay) {
        SendSystemMessage(SystemMessageId::CANNOT_EXCEED_INVENTORY_WEIGHT_OR_QUANTITY_LIMIT);
        SendSystemMessage(SystemMessageId::NOT_ENOUGH_ARTIFACT_INVENTORY_SPACE);
        valid = false;
    }
    if (runtime::Win64CvttDoubleToInt32(GetWeightLimit(69000.0)) < resultingWeight) {
        SendSystemMessage(SystemMessageId::CANNOT_EXCEED_INVENTORY_WEIGHT_OR_QUANTITY_LIMIT);
        valid = false;
    }
    if (valid && (priceSum < 1 || priceSum > INT64_C(999999999999))) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] invalid amount",
        //     L"User.cpp",
        //     0x2c7b)
        L2_LOG_ERROR(Log, u"[private store] Buy-list total %I64d is outside the supported adena range.", priceSum);
        SendSystemMessage(SystemMessageId::CANNOT_PROCEED_ADENA_LIMIT_EXCEEDED);
        valid = false;
    }
    const std::int64_t adena = m_inv.GetAdenaAmount();
    if (valid && (priceSum < 1 || priceSum > INT64_C(999999999999) || priceSum > adena)) {
        SendSystemMessage(SystemMessageId::CANNOT_OPEN_BUY_STORE_TOTAL_EXCEEDS_FUNDS);
        valid = false;
    }

    std::vector<PrivateStoreItemData> relayItems;
    std::wstring classLog;
    if (valid) {
        DeletePrivateStoreEntries(m_PrivateStoreBuyMap);
        cursor = itemsPacket;
        int internalId = 0;
        for (int index = 0; index < itemCount; ++index) {
            int classId = 0;
            std::int16_t enchanted = 0;
            std::int16_t damaged = 0;
            std::int64_t count = 0;
            std::int64_t price = 0;
            int variation1 = 0;
            int variation2 = 0;
            BaseAttribute attribute;
            int shapeShiftClassId = 0;
            std::map<int, EnsoulOptionData*> ensoulOptions[3];
            cursor = ::Disassemble(cursor, "dhhQQ", &classId, &enchanted, &damaged, &count, &price);
            cursor = CItem::DisassembleVariation(cursor, variation1, variation2);
            cursor = CItem::DisassembleAttribute(cursor, attribute);
            cursor = CItem::DisassembleShapeShift(cursor, shapeShiftClassId);
            cursor = CItem::DisassembleEnsoul(cursor, ensoulOptions);

            if (count < 1) {
                SendSystemMessage(SystemMessageId::INVALID_STORE_OR_WORKSHOP_ITEM_QUANTITY);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]SetPrivateStoreBuyList request error. "
                //     L"invalid count[%I64d], ",
                //     "User.cpp",
                //     0x2cad,
                //     count)
                L2_LOG_ERROR(Log, u"[private store] Buy-list count %I64d is invalid; entry skipped.", count);
                continue;
            }
            if (price < 1) {
                SendSystemMessage(SystemMessageId::INVALID_ITEM_PRICE);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]SetPrivateStoreBuyList request error. "
                //     L"invalid price[%I64d], ",
                //     "User.cpp",
                //     0x2cb4,
                //     price)
                L2_LOG_ERROR(Log, u"[private store] Buy-list price %I64d is invalid; entry skipped.", price);
                continue;
            }
            if (enchanted < 0) {
                SendSystemMessage(SystemMessageId::INVALID_ITEM_ENCHANT_VALUE);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]SetPrivateStoreBuyList request error. "
                //     L"invalid enchant[%d], ",
                //     "User.cpp",
                //     0x2cbb,
                //     static_cast<int>(enchanted))
                L2_LOG_ERROR(
                    Log, u"[private store] Buy-list enchant value %d is invalid; entry skipped.", static_cast<int>(enchanted)
                );
                continue;
            }
            if (damaged < 0) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]SetPrivateStoreBuyList request error. "
                //     L"invalid damaged[%d], ",
                //     "User.cpp",
                //     0x2cc1,
                //     static_cast<int>(damaged))
                L2_LOG_ERROR(
                    Log, u"[private store] Buy-list damage value %d is invalid; entry skipped.", static_cast<int>(damaged)
                );
                continue;
            }
            CItem* const item = m_inv.GetFirstItemByAttribute(classId, attribute);
            if (item == nullptr) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] g_ObjectDB.GetObject Failed. class id [%d]",
                //     L"User.cpp",
                //     0x2cc8,
                //     classId)
                L2_LOG_ERROR(
                    Log, u"[private store] Buy-list item class %d is absent from inventory; entry skipped.", classId
                );
                continue;
            }
            if (shapeShiftClassId < 0) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]SetPrivateStoreBuyList request error. "
                //     L"invalid ShapeShiftingClassId[%d], ",
                //     "User.cpp",
                //     0x2cd0,
                //     shapeShiftClassId)
                L2_LOG_ERROR(
                    Log, u"[private store] Buy-list appearance class %d is invalid; entry skipped.", shapeShiftClassId
                );
                continue;
            }

            bool conflictingPrice = false;
            for (const auto& entry : m_PrivateStoreBuyMap) {
                const CPrivateStoreData* const existing = entry.second;
                if (existing != nullptr && existing->nClassId == classId && existing->nEnchanted == enchanted &&
                    existing->nDamaged == damaged && existing->nVariation1 == variation1 &&
                    existing->nVariation2 == variation2 && existing->m_BaseAttribute == attribute &&
                    existing->nShapeShiftingClassId == shapeShiftClassId &&
                    CItem::CompareOptionData(existing->mEnsoulOptionMap, ensoulOptions) && existing->nPrice != price) {
                    SendSystemMessage(SystemMessageId::SAME_SALE_ITEM_HAS_DIFFERENT_PRICE);
                    conflictingPrice = true;
                    break;
                }
            }
            if (conflictingPrice) {
                continue;
            }

            relayItems.emplace_back(classId, count, price, 0);
            ++internalId;
            if (!item->m_data->IsStackable()) {
                count = 1;
            }
            CPrivateStoreData* const data = new CPrivateStoreData(
                static_cast<int>(item->Id()), internalId, static_cast<int>(enchanted), static_cast<int>(damaged), count,
                classId, price, item->m_itemOption.intensiveItemClassID, variation1, variation2, attribute, shapeShiftClassId
            );
            data->SetEnsoulOption(ensoulOptions);
            m_PrivateStoreBuyMap[internalId] = data;
            AppendPrivateStoreClassLog(classLog, classId);
        }
    }

    m_inv.WriteUnlock();
    if (!valid) {
        SendPrivateStoreBuyManageList(GetSocket());
        return;
    }

    // GetController()->PrivateStore(2)
    GetController()->PrivateStore(PSA_BUY);
    if (!classLog.empty()) {
        classLog.pop_back();
    }
    const std::uint32_t tick = runtime::GetTickCount();
    CLogFormatter formatter;
    formatter.WriteLog1(
        0x347, this, nullptr, WideToUtf16(classLog.empty() ? nullptr : classLog.data()), nullptr, nullptr, 0, 0,
        static_cast<std::int64_t>(tick), 0, 0, 0, 0
    );
    for (const auto& entry : m_PrivateStoreBuyMap) {
        CPrivateStoreData* const data = entry.second;
        char16_t shapeAndVariation[256]{};
        char16_t attribute[256]{};
        char16_t ensoul[256]{};
        data->MakeShapeShiftAndVariationLogInfo(shapeAndVariation);
        data->m_BaseAttribute.GetLogString(attribute);
        data->MakeEnsoulLogInfo(ensoul);
        formatter.WriteLog4(
            0x232e, this, nullptr, ensoul, attribute, shapeAndVariation, data->nClassId, data->nEnchanted, data->nCount,
            data->nPrice, 0, 0, static_cast<std::int64_t>(tick), 0, 0, 0, data->nItemDBID
        );
    }
    RelayClient::Inst()->SendPrivateStoreBuyOpenPacket(this, relayItems);
}

void User::PrivateStoreBuy(const unsigned char* packet, User* buyer) {
    // Current L2Server 0x00b52bd0.
    L2_GUARD_FUNCTION();
    int itemCount = 0;
    const unsigned char* cursor = ::Disassemble(packet, "d", &itemCount);
    std::array<PSStoreBuyData, 15> purchases{};
    if (buyer == nullptr || itemCount < 1 || itemCount > GetPrivateStoreBuyLimit()) {
        if (buyer != nullptr) {
            buyer->SendSystemMessage(SystemMessageId::INVALID_PURCHASE_ITEM_QUANTITY);
        }
        return;
    }
    if (IsShopManaging()) {
        buyer->SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        return;
    }

    PrivateStoreMap* store = nullptr;
    const int storeType = GetPrivateStoreType();
    if (storeType == PST_OPEN) {
        store = &m_PrivateStoreMap;
    } else if (storeType == PST_WHOLESALE_OPEN) {
        store = &m_PrivateStoreWholeMap;
    } else {
        buyer->SendSystemMessage(SystemMessageId::PRIVATE_STORE_ALREADY_CLOSED);
        return;
    }
    if (store->empty()) {
        buyer->SendSystemMessage(SystemMessageId::ITEM_OUT_OF_STOCK);
        return;
    }

    const bool commitReserved = [&] {
        L2_GUARD(m_PrivateStoreLock);
        if (m_bWaitPrivateStoreCommit) {
            buyer->SendSystemMessage(SystemMessageId::ANOTHER_USER_BUYING_TRY_AGAIN_LATER);
            return false;
        }
        m_bWaitPrivateStoreCommit = true;
        return true;
    }();
    if (!commitReserved) {
        return;
    }

    // Keep construction under both inventory locks and destruction after shop closure.
    std::optional<std::set<std::uint32_t>> seenDatabaseIdsStorage;
    std::optional<ItemAmountDataStruct> addableItemsStorage;
    std::optional<CPacketHelperEx<20480>> commitPacketStorage;
    {
        L2_WRITE_GUARD(m_inv);
        L2_WRITE_GUARD(buyer->m_inv);
        bool valid = true;
        auto& seenDatabaseIds = seenDatabaseIdsStorage.emplace();
        std::int64_t totalPrice = 0;
        for (int index = 0; index < itemCount; ++index) {
            int serverId = 0;
            std::int64_t count = 0;
            std::int64_t price = 0;
            cursor = ::Disassemble(cursor, "dQQ", &serverId, &count, &price);
            if (serverId < 1) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuy request error. "
                //     L"nItemServerId[%d], ",
                //     "User.cpp",
                //     0x29c1,
                //     serverId)
                L2_LOG_ERROR(Log, u"[private store] Purchase requested invalid store item ID %d.", serverId);
                valid = false;
                break;
            }
            if (count < 1) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuy request error. "
                //     L"nItemCount[%I64d], ",
                //     "User.cpp",
                //     0x29c8,
                //     count)
                L2_LOG_ERROR(Log, u"[private store] Purchase requested invalid item count %I64d.", count);
                valid = false;
                break;
            }
            if (price < 1) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuy request error. "
                //     L"nItemPrice[%I64d], ",
                //     "User.cpp",
                //     0x29cf,
                //     price)
                L2_LOG_ERROR(Log, u"[private store] Purchase requested invalid item price %I64d.", price);
                valid = false;
                break;
            }

            const auto found = store->find(serverId);
            if (found == store->end() || found->second == nullptr) {
                valid = false;
                break;
            }
            CPrivateStoreData* const storeData = found->second;
            CItem* const item = m_inv.GetByServerID(storeData->nItemServerId);
            if (item == nullptr) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] m_inv.GetByServerID Failed[%dd]",
                //     L"User.cpp",
                //     0x29e0,
                //     storeData->nItemServerId)
                L2_LOG_ERROR(
                    Log, u"[private store] Seller inventory item %d is missing; purchase rejected.", storeData->nItemServerId
                );
                valid = false;
                break;
            }
            if (item->m_itemOption.itemOptionKey.variationOption1 > 0 &&
                item->m_itemOption.itemOptionKey.variationOption2 > 0) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] This is Variation Item -_- [%dd]",
                //     L"User.cpp",
                //     0x29ea,
                //     storeData->nItemServerId)
                L2_LOG_ERROR(
                    Log, u"[private store] Augmented item %d cannot be sold through this store.", storeData->nItemServerId
                );
                valid = false;
                break;
            }
            if (item->IsDuration()) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] This is Duration Item -_- [%dd]",
                //     L"User.cpp",
                //     0x29f3,
                //     storeData->nItemServerId)
                L2_LOG_ERROR(
                    Log, u"[private store] Timed item %d cannot be sold through this store.", storeData->nItemServerId
                );
                valid = false;
                break;
            }
            if (item->IsEtcItem() && !item->CastEtcItem()->m_bPetCollarTradable) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] This is Etc Item - pet summoned, "
                //     L"already -_- [%dd]",
                //     L"User.cpp",
                //     0x29fc,
                //     storeData->nItemServerId)
                L2_LOG_ERROR(
                    Log, u"[private store] Pet-related item %d cannot be sold while its pet state forbids trading.",
                    storeData->nItemServerId
                );
                valid = false;
                break;
            }
            if (count > storeData->nCount || count > item->m_data->m_nCount) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuy request error. "
                //     L"nItemCount[%I64d], ",
                //     "User.cpp",
                //     0x2a0a,
                //     count)
                L2_LOG_ERROR(Log, u"[private store] Purchase count %I64d exceeds the listed or available amount.", count);
                valid = false;
                break;
            }
            if (price != storeData->nPrice) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuy request error. "
                //     L"nItemPrice[%I64d], ",
                //     "User.cpp",
                //     0x2a11,
                //     price)
                L2_LOG_ERROR(Log, u"[private store] Purchase price %I64d does not match the seller's listing.", price);
                valid = false;
                break;
            }

            if (seenDatabaseIds.find(item->GetDBID()) != seenDatabaseIds.end()) {
                valid = false;
                break;
            }
            PSStoreBuyData& purchase = purchases[static_cast<std::size_t>(index)];
            purchase.m_ServerId = serverId;
            purchase.m_Count = count;
            purchase.m_Price = price;
            purchase.m_ClassId = storeData->nClassId;
            purchase.m_DBId = static_cast<int>(item->GetDBID());
            seenDatabaseIds.insert(item->GetDBID());
            totalPrice = runtime::AddInt64Wrapping(totalPrice, runtime::MultiplyInt64Wrapping(count, price));
            const std::int64_t resultingAdena = runtime::AddInt64Wrapping(m_inv.GetAdenaAmount(), totalPrice);
            if (resultingAdena < 1 || resultingAdena > INT64_C(999999999999)) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuy request error. "
                //     L"nItemPrice[%I64d], ",
                //     "User.cpp",
                //     0x2a2a,
                //     price)
                L2_LOG_ERROR(
                    Log, u"[private store] Purchase price %I64d would move seller adena outside the supported range.", price
                );
                valid = false;
                break;
            }
        }

        auto& addableItems = addableItemsStorage.emplace();
        if (valid) {
            totalPrice = 0;
            for (int index = 0; index < itemCount; ++index) {
                const PSStoreBuyData& purchase = purchases[static_cast<std::size_t>(index)];
                addableItems.Push(purchase.m_ClassId, purchase.m_Count);
                totalPrice = runtime::AddInt64Wrapping(
                    totalPrice, runtime::MultiplyInt64Wrapping(purchase.m_Count, purchase.m_Price)
                );
            }
            if (totalPrice < 1 || totalPrice > INT64_C(999999999999) ||
                !buyer->m_inv.CheckAddableMulti(addableItems, false)) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                valid = false;
            } else if (buyer->m_inv.GetAdenaAmount() < totalPrice) {
                buyer->SendSystemMessage(SystemMessageId::NOT_ENOUGH_ADENA);
                valid = false;
            }
        }

        auto& commitPacket = commitPacketStorage.emplace();
        if (valid) {
            for (int index = 0; index < itemCount; ++index) {
                const PSStoreBuyData& purchase = purchases[static_cast<std::size_t>(index)];
                CItem* const sellerItem = m_inv.GetByServerID(static_cast<int>(purchase.m_ServerId));
                if (sellerItem == nullptr) {
                    buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d] m_inv.GetByServerID Failed[%d]",
                    //     L"User.cpp",
                    //     0x2a58,
                    //     static_cast<int>(purchase.m_ServerId))
                    L2_LOG_ERROR(
                        Log, u"[private store] Seller inventory item %d disappeared before commit.",
                        static_cast<int>(purchase.m_ServerId)
                    );
                    valid = false;
                    break;
                }
                if (sellerItem->m_itemOption.itemOptionKey.variationOption1 > 0 &&
                    sellerItem->m_itemOption.itemOptionKey.variationOption2 > 0) {
                    buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d] This is variation item [%d]",
                    //     L"User.cpp",
                    //     0x2a62,
                    //     static_cast<int>(purchase.m_ServerId))
                    L2_LOG_ERROR(
                        Log, u"[private store] Augmented item %d became ineligible before commit.",
                        static_cast<int>(purchase.m_ServerId)
                    );
                    valid = false;
                    break;
                }
                if (sellerItem->IsDuration()) {
                    buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"[%s][%d] This is duration item [%d]",
                    //     L"User.cpp",
                    //     0x2a6b,
                    //     static_cast<int>(purchase.m_ServerId))
                    L2_LOG_ERROR(
                        Log, u"[private store] Timed item %d became ineligible before commit.",
                        static_cast<int>(purchase.m_ServerId)
                    );
                    valid = false;
                    break;
                }

                int sellerOperation = 3;
                int buyerOperation = 4;
                int buyerDatabaseId = 0;
                int buyerServerId = 0;
                std::int64_t transferCount = purchase.m_Count;
                CItem* buyerItem = nullptr;
                if (sellerItem->m_data->IsStackable()) {
                    buyerItem = buyer->m_inv.GetFirstItemByClassID(sellerItem->m_data->m_nClassID, false, false);
                    const std::int64_t sellerCount = sellerItem->m_data->m_nCount;
                    if (buyerItem == nullptr) {
                        if (sellerCount <= purchase.m_Count) {
                            if (sellerCount == 0) {
                                // Log.Add(
                                //     LOG_ERROR,
                                //     L"[%S][%d]error, [%I64d][%I64d]",
                                //     "User.cpp",
                                //     0x2aa6,
                                //     purchase.m_Count,
                                //     std::int64_t{0})
                                L2_LOG_ERROR(
                                    Log,
                                    u"[private store] Seller stack is empty while purchase count is %I64d; entry skipped.",
                                    purchase.m_Count
                                );
                                continue;
                            }
                            transferCount = sellerCount;
                            sellerOperation = 3;
                            buyerOperation = 4;
                        } else {
                            sellerOperation = 1;
                            buyerOperation = 2;
                        }
                    } else {
                        buyerOperation = 1;
                        if (purchase.m_Count < sellerCount) {
                            sellerOperation = 1;
                        } else if (sellerCount != 0) {
                            sellerOperation = 3;
                            transferCount = sellerCount;
                        } else {
                            // Log.Add(
                            //     LOG_ERROR,
                            //     L"[%S][%d]error, [%I64d][%I64d]",
                            //     "User.cpp",
                            //     0x2a8e,
                            //     purchase.m_Count,
                            //     std::int64_t{0})
                            L2_LOG_ERROR(
                                Log,
                                u"[private store] Seller stack is empty while purchase count is %I64d; commit rejected.",
                                purchase.m_Count
                            );
                            valid = false;
                            break;
                        }
                    }
                }

                int sellerDatabaseId = 0;
                if (buyerItem == nullptr) {
                    sellerDatabaseId = static_cast<int>(sellerItem->GetDBID());
                } else {
                    sellerDatabaseId = static_cast<int>(sellerItem->GetDBID());
                    buyerDatabaseId = static_cast<int>(buyerItem->GetDBID());
                    buyerServerId = static_cast<int>(buyerItem->Id());
                }

                if (commitPacket.Assemble(
                        "ddddddQQ", sellerOperation, sellerDatabaseId, static_cast<int>(purchase.m_ServerId), buyerOperation,
                        buyerDatabaseId, buyerServerId, transferCount, purchase.m_Price
                    ) < 1) {
                    valid = false;
                    break;
                }
            }
        }

        if ((storeType == PST_WHOLESALE_OPEN || storeType == PST_WHOLESALE_MANAGE)) {
            PrivateStoreMap remainingWholesale = *store;
            for (int index = 0; index < itemCount; ++index) {
                const PSStoreBuyData& purchase = purchases[static_cast<std::size_t>(index)];
                const auto found = remainingWholesale.find(static_cast<int>(purchase.m_ServerId));
                if (found != remainingWholesale.end() && found->second != nullptr &&
                    found->second->nCount <= purchase.m_Count) {
                    remainingWholesale.erase(found);
                }
            }
            if (!remainingWholesale.empty()) {
                buyer->SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                valid = false;
            }
        }

        if (valid && commitPacket.GetAssembledCount() > 0) {
            valid = db.SendPrivateStoreCommit(
                this, buyer, totalPrice, commitPacket.GetAssembledCount(), commitPacket.GetLength(), commitPacket.GetPacket()
            );
            if (valid) {
                for (int index = 0; index < itemCount; ++index) {
                    const PSStoreBuyData& purchase = purchases[static_cast<std::size_t>(index)];
                    const auto found = store->find(static_cast<int>(purchase.m_ServerId));
                    if (found == store->end() || found->second == nullptr) {
                        continue;
                    }
                    CPrivateStoreData* const data = found->second;
                    data->nCount -= purchase.m_Count;
                    if (data->nCount < 1) {
                        store->erase(found);
                        delete data;
                    }
                }
            }
        }

        if (!valid) {
            {
                L2_GUARD(m_PrivateStoreLock);
                m_bWaitPrivateStoreCommit = false;
            }
        } else {
            RelayClient::Inst()->SendPrivateStoreBuyPacket(this, buyer, *store, purchases.data(), itemCount);
        }
    }
    if (store->empty()) {
        QuitPrivateStore(false);
    }
}

void User::PrivateStoreBuyBuy(const unsigned char* packet, User* seller) {
    // Current L2Server 0x00b55b74.
    L2_GUARD_FUNCTION();
    int itemCount = 0;
    const unsigned char* cursor = ::Disassemble(packet, "d", &itemCount);
    std::array<CPrivateStoreData, 15> purchases{};
    if (itemCount < 1 || itemCount > GetPrivateStoreBuyLimit()) {
        seller->SendSystemMessage(SystemMessageId::INVALID_PURCHASE_ITEM_QUANTITY);
        return;
    }
    if (GetPrivateStoreType() == PST_BUY_MANAGE) {
        seller->SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        return;
    }
    if (GetPrivateStoreType() != PST_BUY_OPEN) {
        seller->SendSystemMessage(SystemMessageId::PRIVATE_STORE_ALREADY_CLOSED);
        return;
    }
    if (m_PrivateStoreBuyMap.empty()) {
        seller->SendSystemMessage(SystemMessageId::ITEM_OUT_OF_STOCK);
        return;
    }

    std::optional<std::set<std::uint32_t>> matchedDatabaseIdsStorage;
    const bool storeClosed = [&] {
        L2_WRITE_GUARD(m_inv);
        L2_WRITE_GUARD(seller->m_inv);
        if (CheckPrivateStoreInventory()) {
            return true;
        }

        bool valid = true;
        std::int64_t sellerResultingPrice = 0;
        for (int index = 0; index < itemCount; ++index) {
            int orderNumber = 0;
            int classId = 0;
            std::int16_t enchanted = 0;
            std::int16_t damaged = 0;
            std::int64_t count = 0;
            std::int64_t price = 0;
            int variation1 = 0;
            int variation2 = 0;
            int shapeShiftClassId = 0;
            std::map<int, EnsoulOptionData*> ensoulOptions[3];
            cursor = ::Disassemble(cursor, "ddhhQQ", &orderNumber, &classId, &enchanted, &damaged, &count, &price);
            cursor = CItem::DisassembleVariation(cursor, variation1, variation2);
            cursor = CItem::DisassembleShapeShift(cursor, shapeShiftClassId);
            cursor = CItem::DisassembleEnsoul(cursor, ensoulOptions);

            if (orderNumber < 0) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nOrderNo[%d]",
                //     orderNumber)
                L2_LOG_ERROR(Log, u"[private store] Purchase order number %d is invalid; request rejected.", orderNumber);
                valid = false;
                break;
            }
            if (count < 1) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nCount[%I64d]",
                //     count)
                L2_LOG_ERROR(Log, u"[private store] Purchase count %I64d is invalid; request rejected.", count);
                valid = false;
                break;
            }
            if (price < 1) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nPrice[%I64d]",
                //     price)
                L2_LOG_ERROR(Log, u"[private store] Purchase price %I64d is invalid; request rejected.", price);
                valid = false;
                break;
            }
            if (shapeShiftClassId < 0) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. "
                //     L"nShapeShiftingClass[%d]",
                //     shapeShiftClassId)
                L2_LOG_ERROR(
                    Log, u"[private store] Purchase appearance class %d is invalid; request rejected.", shapeShiftClassId
                );
                valid = false;
                break;
            }

            const auto found = m_PrivateStoreBuyMap.find(orderNumber);
            if (found == m_PrivateStoreBuyMap.end() || found->second == nullptr) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nOrderNo[%d]",
                //     orderNumber)
                L2_LOG_ERROR(
                    Log, u"[private store] Stored order number %d does not match the request; purchase rejected.",
                    orderNumber
                );
                valid = false;
                break;
            }
            CPrivateStoreData& stored = *found->second;
            if (stored.nClassId != classId) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nClassId[%d]",
                //     classId)
                L2_LOG_ERROR(
                    Log, u"[private store] Stored item class %d does not match the request; purchase rejected.", classId
                );
                valid = false;
                break;
            }
            if (stored.nPrice != price) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nPrice[%I64d]",
                //     price)
                L2_LOG_ERROR(
                    Log, u"[private store] Stored price %I64d does not match the request; purchase rejected.", price
                );
                valid = false;
                break;
            }
            if (stored.nVariation1 != variation1) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nVariation1[%d]",
                //     variation1)
                L2_LOG_ERROR(
                    Log, u"[private store] Variation option 1 value %d does not match; purchase rejected.", variation1
                );
                valid = false;
                break;
            }
            if (stored.nVariation2 != variation2) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nVariation2[%d]",
                //     variation2)
                L2_LOG_ERROR(
                    Log, u"[private store] Variation option 2 value %d does not match; purchase rejected.", variation2
                );
                valid = false;
                break;
            }
            if (stored.nEnchanted != enchanted) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. shEnchanted[%d]",
                //     static_cast<int>(enchanted))
                L2_LOG_ERROR(
                    Log, u"[private store] Enchant value %d does not match; purchase rejected.", static_cast<int>(enchanted)
                );
                valid = false;
                break;
            }
            if (stored.nCount < count) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nCount[%I64d]",
                //     count)
                L2_LOG_ERROR(Log, u"[private store] Stored count %I64d is insufficient; purchase rejected.", count);
                valid = false;
                break;
            }
            if (stored.nDamaged != damaged) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. nDamaged[%d]",
                //     static_cast<int>(damaged))
                L2_LOG_ERROR(
                    Log, u"[private store] Damage value %d does not match; purchase rejected.", static_cast<int>(damaged)
                );
                valid = false;
                break;
            }
            if (stored.nShapeShiftingClassId != shapeShiftClassId) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. "
                //     L"nShapeShiftingClass[%d]",
                //     shapeShiftClassId)
                L2_LOG_ERROR(
                    Log, u"[private store] Stored appearance class %d does not match; purchase rejected.", shapeShiftClassId
                );
                valid = false;
                break;
            }
            if (!CItem::CompareOptionData(stored.mEnsoulOptionMap, ensoulOptions)) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"PrivateStoreBuyBuy request error. "
                //     L"ensoulOption Different")
                L2_LOG_ERROR(
                    Log,
                    u"[private store] Ensoul options do not match the stored item; "
                    u"purchase rejected."
                );
                valid = false;
                break;
            }

            CPrivateStoreData& purchase = purchases[static_cast<std::size_t>(index)];
            purchase.nOrderNo = orderNumber;
            purchase.nClassId = classId;
            purchase.nEnchanted = enchanted;
            purchase.nCount = count;
            purchase.nPrice = price;
            purchase.nDamaged = damaged;
            purchase.nVariation1 = variation1;
            purchase.nVariation2 = variation2;
            purchase.m_BaseAttribute = stored.m_BaseAttribute;
            purchase.nShapeShiftingClassId = shapeShiftClassId;
            purchase.SetEnsoulOption(stored.mEnsoulOptionMap);

            const std::int64_t linePrice = runtime::MultiplyInt64Wrapping(count, price);
            sellerResultingPrice = runtime::AddInt64Wrapping(sellerResultingPrice, linePrice);
            const std::int64_t sellerAdena = seller->m_inv.GetAdenaAmount();
            const std::int64_t resultingLineAdena = runtime::AddInt64Wrapping(sellerAdena, linePrice);
            const std::int64_t resultingTotalAdena = runtime::AddInt64Wrapping(sellerAdena, sellerResultingPrice);
            if (resultingLineAdena < 1 || resultingLineAdena > INT64_C(999999999999) || resultingTotalAdena < 1 ||
                resultingTotalAdena > INT64_C(999999999999)) {
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuyBuy request error. "
                //     L"nItemPrice[%I64d], ",
                //     "User.cpp",
                //     0x2fab,
                //     price)
                L2_LOG_ERROR(
                    Log, u"[private store] Seller would exceed the adena limit at item price %I64d; purchase rejected.",
                    price
                );
                valid = false;
                break;
            }
        }

        auto& matchedDatabaseIds = matchedDatabaseIdsStorage.emplace();
        if (valid) {
            CItemFactory& itemFactory = CItemFactory::Inst();
            int itemIndex = seller->m_inv.GetFirstIndex();
            int depth = 0;
            while (itemIndex != -1 && valid) {
                CSPointer<CItem> itemReference = itemFactory.FindObjectSP(itemIndex);
                CItem* const item = itemReference ? itemReference->CastItem() : nullptr;
                if (item != nullptr) {
                    for (int index = 0; index < itemCount; ++index) {
                        CPrivateStoreData& purchase = purchases[static_cast<std::size_t>(index)];
                        if (!MatchesPrivateStoreBuyRecord(*item, purchase) || !item->IsTradable(this, false) ||
                            purchase.nItemServerId != 0 || item->m_data->m_nCount < purchase.nCount) {
                            continue;
                        }

                        if (matchedDatabaseIds.find(item->GetDBID()) != matchedDatabaseIds.end()) {
                            valid = false;
                            break;
                        }
                        purchase.nItemServerId = static_cast<int>(item->Id());
                        purchase.nItemDBID = static_cast<int>(item->GetDBID());
                        matchedDatabaseIds.insert(item->GetDBID());
                        break;
                    }
                }

                itemIndex = itemFactory.GetNextIndex(itemIndex);
                ++depth;
                if (depth > 0x192) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     "depth > %d at file[%s], line[%d]",
                    //     0x192,
                    //     "User.cpp",
                    //     0x2ff3)
                    L2_LOG_ERROR(
                        Log, "[private store] Purchase traversal exceeded %d inventory entries; request stopped.", 0x192
                    );
                    break;
                }
            }
        }

        if (valid) {
            for (int index = 0; index < itemCount; ++index) {
                const CPrivateStoreData& purchase = purchases[static_cast<std::size_t>(index)];
                if (purchase.nItemServerId != 0) {
                    continue;
                }
                seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%S][%d]PrivateStoreBuyBuy request error. "
                //     L"nItemCount[%I64d], ",
                //     "User.cpp",
                //     0x3005,
                //     std::int64_t{0})
                L2_LOG_ERROR(
                    Log, u"[private store] No seller inventory item matched a requested purchase entry; purchase rejected."
                );
                valid = false;
                break;
            }
        }

        {
            ItemAmountDataStruct addableItems;
            std::int64_t totalPrice = 0;
            if (valid) {
                if (itemCount < 1) {
                    seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                    valid = false;
                } else {
                    for (int index = 0; index < itemCount; ++index) {
                        const CPrivateStoreData& purchase = purchases[static_cast<std::size_t>(index)];
                        addableItems.Push(purchase.nClassId, purchase.nCount);
                        totalPrice = runtime::AddInt64Wrapping(
                            totalPrice, runtime::MultiplyInt64Wrapping(purchase.nCount, purchase.nPrice)
                        );
                    }
                    if (totalPrice < 1 || totalPrice > INT64_C(999999999999) ||
                        !m_inv.CheckAddableMulti(addableItems, false)) {
                        seller->SendSystemMessage(SystemMessageId::SALE_FAILED);
                        valid = false;
                    } else if (m_inv.GetAdenaAmount() < totalPrice) {
                        seller->SendSystemMessage(SystemMessageId::NOT_ENOUGH_ADENA);
                        valid = false;
                    }
                }
            }

            std::array<char, 0x5000> commitPacket{};
            int commitPacketLength = 0;
            int assembledItemCount = 0;
            if (valid) {
                for (int index = 0; index < itemCount; ++index) {
                    const CPrivateStoreData& purchase = purchases[static_cast<std::size_t>(index)];
                    CItem* const sellerItem = seller->m_inv.GetByServerID(purchase.nItemServerId);
                    if (sellerItem == nullptr) {
                        SendSystemMessage(SystemMessageId::PURCHASE_FAILED);
                        // Log.Add(
                        //     LOG_ERROR,
                        //     L"m_inv.GetByServerID Failed[%d]",
                        //     purchase.nItemServerId)
                        L2_LOG_ERROR(
                            Log, u"[private store] Inventory item SID %d was not found; purchase rejected.",
                            purchase.nItemServerId
                        );
                        valid = false;
                        break;
                    }

                    int sellerOperation = 3;
                    int buyerOperation = 4;
                    int buyerDatabaseId = 0;
                    int buyerServerId = 0;
                    CItem* buyerItem = nullptr;
                    std::int64_t transferCount = purchase.nCount;
                    if (sellerItem->m_data->IsStackable()) {
                        buyerItem = m_inv.GetFirstItemByClassID(sellerItem->m_data->m_nClassID, false, false);
                        const std::int64_t sellerCount = sellerItem->m_data->m_nCount;
                        if (buyerItem == nullptr) {
                            if (sellerCount <= purchase.nCount) {
                                if (sellerCount == 0) {
                                    // Log.Add(
                                    //     LOG_ERROR,
                                    //     L"[%S][%d]error, [%I64d][%I64d]",
                                    //     "User.cpp",
                                    //     0x306e,
                                    //     purchase.nCount,
                                    //     std::int64_t{0})
                                    L2_LOG_ERROR(
                                        Log,
                                        u"[private store] Seller stack is empty while requested count is %I64d; entry "
                                        u"skipped.",
                                        purchase.nCount
                                    );
                                    continue;
                                }
                                transferCount = sellerCount;
                                sellerOperation = 3;
                                buyerOperation = 4;
                            } else {
                                sellerOperation = 1;
                                buyerOperation = 2;
                            }
                        } else {
                            buyerOperation = 1;
                            if (purchase.nCount < sellerCount) {
                                sellerOperation = 1;
                            } else if (sellerCount != 0) {
                                sellerOperation = 3;
                                transferCount = sellerCount;
                            } else {
                                // Log.Add(
                                //     LOG_ERROR,
                                //     L"[%S][%d]error, [%I64d][%I64d]",
                                //     "User.cpp",
                                //     0x3056,
                                //     purchase.nCount,
                                //     std::int64_t{0})
                                L2_LOG_ERROR(
                                    Log,
                                    u"[private store] Seller stack is empty while requested count is %I64d; purchase "
                                    u"rejected.",
                                    purchase.nCount
                                );
                                valid = false;
                                break;
                            }
                        }
                    }

                    int sellerDatabaseId;
                    if (buyerItem == nullptr) {
                        sellerDatabaseId = static_cast<int>(sellerItem->GetDBID());
                    } else {
                        sellerDatabaseId = static_cast<int>(sellerItem->GetDBID());
                        buyerDatabaseId = static_cast<int>(buyerItem->GetDBID());
                        buyerServerId = static_cast<int>(buyerItem->Id());
                    }

                    const int assembled = ::Assemble(
                        commitPacket.data() + commitPacketLength, static_cast<int>(commitPacket.size()) - commitPacketLength,
                        "ddddddQQ", sellerOperation, sellerDatabaseId, purchase.nItemServerId, buyerOperation,
                        buyerDatabaseId, buyerServerId, transferCount, purchase.nPrice
                    );
                    if (assembled < 1) {
                        valid = false;
                        break;
                    }
                    commitPacketLength += assembled;
                    ++assembledItemCount;
                }
            }

            if (valid && assembledItemCount > 0 &&
                db.SendPrivateStoreCommit(
                    seller, this, totalPrice, assembledItemCount, commitPacketLength, commitPacket.data()
                )) {
                for (int index = 0; index < itemCount; ++index) {
                    const CPrivateStoreData& purchase = purchases[static_cast<std::size_t>(index)];
                    const auto found = m_PrivateStoreBuyMap.find(purchase.nOrderNo);
                    if (found == m_PrivateStoreBuyMap.end() || found->second == nullptr) {
                        continue;
                    }
                    CPrivateStoreData* const data = found->second;
                    data->nCount -= purchase.nCount;
                    if (data->nCount < 1) {
                        m_PrivateStoreBuyMap.erase(found);
                        delete data;
                    }
                }
                RelayClient::Inst()->SendPrivateStoreBuyBuyPacket(this, seller, purchases.data(), itemCount);
            }
        }

        return false;
    }();
    if (storeClosed) {
        seller->SendSystemMessage(SystemMessageId::PRIVATE_STORE_ALREADY_CLOSED);
        QuitPrivateStore(false);
        return;
    }
    if (m_PrivateStoreBuyMap.empty()) {
        QuitPrivateStore(false);
    }
}

bool User::OnPrivateStoreBuyBuyListSend(const std::uint8_t* packet) {
    // Current L2Server 0x00b584c4.
    L2_GUARD_FUNCTION();
    if (IsNowTrade()) {
        return false;
    }
    if (GetTrade() != nullptr) {
        TradeCancel(false);
    }
    if (!IsItemUsable(0)) {
        return false;
    }

    int shopServerId = 0;
    const unsigned char* const cursor = ::Disassemble(packet, "d", &shopServerId);
    CSPointer<User> shop = g_UserMap.FindObject(shopServerId);
    if (!shop || !shop->IsAlive()) {
        return false;
    }
    if (!IsTalkableDistance(shop.get())) {
        return false;
    }
    if (GetDBID() == shop->GetDBID()) {
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        // Log.Add(
        //     LOG_ERROR,
        //     L"try hack? user dbid[%d], shop dbid[%d], "
        //     L"disconnect both",
        //     GetDBID(),
        //     shop->GetDBID())
        L2_LOG_ERROR(
            Log,
            u"[private store] Buyer DB ID %d equals shop DB ID %d; both "
            u"connections are closed as an invalid self-purchase.",
            GetDBID(), shop->GetDBID()
        );
        shop->GetSocket()->ForceClose(SCR_ILLEGAL_BEHAVIOR);
        return true;
    }
    if (shop->GetPrivateStoreType() == PST_BUY_OPEN) {
        shop->PrivateStoreBuyBuy(cursor, this);
    }
    return false;
}

void User::QuitPrivateStore(const bool force) {
    // Current L2Server 0x00b1d988.
    L2_GUARD_FUNCTION();
    const int previousStoreType = m_data->m_nPrivateStoreType;
    if (previousStoreType != PST_NONE) {
        runtime::raw_atomic::DecrementI32(&g_nStoreUserCount);

        if (m_dwPrivateStoreTick != 0) {
            const std::int64_t adenaAmount = [&] {
                L2_READ_GUARD(m_inv);
                return m_inv.GetAdenaAmount();
            }();

            const FVector position = GetPos();
            CUserSocket* const socket = GetSocket();
            const std::uint32_t elapsedSeconds = (runtime::GetTickCount() - m_dwPrivateStoreTick) / 1000U;
            std::array<wchar_t, 16> accountNameStorage{};
            const wchar_t* const accountName = PrivateStoreAccountName(m_sAccountName, accountNameStorage);
            // Log.AddT(
            //     LOG_BOTH,
            //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
            //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
            //     L"%s,%s,,,",
            //     std::int64_t{0x346},
            //     static_cast<std::int64_t>(GetDBID()),
            //     static_cast<std::int64_t>(GetAccountID()),
            //     static_cast<std::int64_t>(
            //         runtime::Win64CvttDoubleToInt32(position.x)),
            //     static_cast<std::int64_t>(
            //         runtime::Win64CvttDoubleToInt32(position.y)),
            //     static_cast<std::int64_t>(
            //         runtime::Win64CvttDoubleToInt32(position.z)),
            //     static_cast<std::int64_t>(m_data->m_nClass),
            //     static_cast<std::int64_t>(m_data->m_Race),
            //     static_cast<std::int64_t>(m_data->m_Sex),
            //     static_cast<std::int64_t>(m_data->m_nLevel),
            //     static_cast<std::int64_t>(elapsedSeconds),
            //     static_cast<std::int64_t>(
            //         socket != nullptr ? socket->m_nPayKind : 0),
            //     adenaAmount,
            //     GetName(),
            //     accountName)
            Log.AddT(
                LOG_BOTH,
                u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
                u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
                u"%s,%s,,,",
                std::int64_t{0x346}, static_cast<std::int64_t>(GetDBID()), static_cast<std::int64_t>(GetAccountID()),
                static_cast<std::int64_t>(runtime::Win64CvttDoubleToInt32(position.x)),
                static_cast<std::int64_t>(runtime::Win64CvttDoubleToInt32(position.y)),
                static_cast<std::int64_t>(runtime::Win64CvttDoubleToInt32(position.z)),
                static_cast<std::int64_t>(m_data->m_nClass), static_cast<std::int64_t>(m_data->m_Race),
                static_cast<std::int64_t>(m_data->m_Sex), static_cast<std::int64_t>(m_data->m_nLevel),
                static_cast<std::int64_t>(elapsedSeconds),
                static_cast<std::int64_t>(socket != nullptr ? socket->m_nPayKind : 0), adenaAmount, GetName(), accountName
            );
            ResetPrivateStoreTick();
        }

        const bool wholesale = previousStoreType == PST_WHOLESALE_OPEN || previousStoreType == PST_WHOLESALE_MANAGE;
        PrivateStoreMap& store = wholesale ? m_PrivateStoreWholeMap : m_PrivateStoreMap;
        CPrivateStoreMarket::inst().RemoveItems(static_cast<int>(m_nId), wholesale, store);
    }

    if (previousStoreType == PST_MANAGE || previousStoreType == PST_BUY_OPEN || previousStoreType == PST_WHOLESALE_MANAGE) {
        RelayClient::Inst()->SendPrivateStoreClose(this);
    }

    if (!force) {
        if (m_data->m_StopMode == STP_STORE) {
            m_data->m_StopMode = STP_SIT;
        }
        m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(m_data->m_nPrivateStoreType, PST_NONE, 0x1a);
        BroadcastWaitType(0);
        ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_PRIVATESTORE});
    }
}

void User::CancelPrivateStore(int privateStoreType) {
    // Current L2Server 0x00b2f9a0.
    L2_GUARD_FUNCTION();
    if (!IsShopManaging()) {
        return;
    }
    if (GetTrade() != nullptr) {
        TradeCancel(false);
    }
    if (!IsItemUsable(0)) {
        QuitPrivateStore(false);
    }
    if (privateStoreType == 0) {
        privateStoreType = m_data->m_nPrivateStoreType;
    }

    if (privateStoreType == PST_MANAGE && !m_PrivateStoreMap.empty()) {
        // GetController()->PrivateStore(1)
        GetController()->PrivateStore(PSA_SELL);
        return;
    }
    if (privateStoreType == PST_BUY_MANAGE && !m_PrivateStoreBuyMap.empty()) {
        // GetController()->PrivateStore(2)
        GetController()->PrivateStore(PSA_BUY);
        return;
    }
    if (privateStoreType == PST_WHOLESALE_MANAGE && !m_PrivateStoreWholeMap.empty()) {
        // GetController()->PrivateStore(7)
        GetController()->PrivateStore(PSA_WHOLE_SELL);
        return;
    }

    if (m_data->m_nPrivateStoreType != PST_NONE) {
        runtime::raw_atomic::DecrementI32(&g_nStoreUserCount);
        if (m_dwPrivateStoreTick != 0) {
            const std::int64_t adenaAmount = [&] {
                L2_READ_GUARD(m_inv);
                return m_inv.GetAdenaAmount();
            }();

            const FVector position = GetPos();
            CUserSocket* const socket = GetSocket();
            const std::uint32_t elapsedSeconds = (runtime::GetTickCount() - m_dwPrivateStoreTick) / 1000U;
            std::array<wchar_t, 16> accountNameStorage{};
            // Log.AddT(
            //     LOG_BOTH,
            //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
            //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
            //     L"%s,%s,,,",
            //     std::int64_t{0x346},
            //     static_cast<std::int64_t>(GetDBID()),
            //     static_cast<std::int64_t>(GetAccountID()),
            //     static_cast<std::int64_t>(
            //         runtime::Win64CvttDoubleToInt32(position.x)),
            //     static_cast<std::int64_t>(
            //         runtime::Win64CvttDoubleToInt32(position.y)),
            //     static_cast<std::int64_t>(
            //         runtime::Win64CvttDoubleToInt32(position.z)),
            //     static_cast<std::int64_t>(m_data->m_nClass),
            //     static_cast<std::int64_t>(m_data->m_Race),
            //     static_cast<std::int64_t>(m_data->m_Sex),
            //     static_cast<std::int64_t>(m_data->m_nLevel),
            //     static_cast<std::int64_t>(elapsedSeconds),
            //     static_cast<std::int64_t>(
            //         socket != nullptr ? socket->m_nPayKind : 0),
            //     adenaAmount,
            //     GetName(),
            //     PrivateStoreAccountName(
            //         m_sAccountName,
            //         accountNameStorage))
            Log.AddT(
                LOG_BOTH,
                u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,"
                u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
                u"%s,%s,,,",
                std::int64_t{0x346}, static_cast<std::int64_t>(GetDBID()), static_cast<std::int64_t>(GetAccountID()),
                static_cast<std::int64_t>(runtime::Win64CvttDoubleToInt32(position.x)),
                static_cast<std::int64_t>(runtime::Win64CvttDoubleToInt32(position.y)),
                static_cast<std::int64_t>(runtime::Win64CvttDoubleToInt32(position.z)),
                static_cast<std::int64_t>(m_data->m_nClass), static_cast<std::int64_t>(m_data->m_Race),
                static_cast<std::int64_t>(m_data->m_Sex), static_cast<std::int64_t>(m_data->m_nLevel),
                static_cast<std::int64_t>(elapsedSeconds),
                static_cast<std::int64_t>(socket != nullptr ? socket->m_nPayKind : 0), adenaAmount, GetName(),
                PrivateStoreAccountName(m_sAccountName, accountNameStorage)
            );
            ResetPrivateStoreTick();
        }
    }

    m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(m_data->m_nPrivateStoreType, PST_NONE, 0x1a);
    BroadcastWaitType(0);
    ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_PRIVATESTORE});
}

bool User::_GetPrivateStoreManagerList(PrivateStoreMap& store, CPacketHelperEx<20480>& packet, int& itemCount) {
    // Current L2Server 0x00b5244c. The caller owns the inventory write
    // lock. Missing live items are removed from the selected store map.
    L2_GUARD_FUNCTION();
    itemCount = 0;
    int depth = 0;

    for (auto position = store.begin(); position != store.end();) {
        CPrivateStoreData* const data = position->second;
        CItem* const item = m_inv.GetByServerID(data->nItemServerId);
        if (item == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"item does not exist in inventory 1 "
            //     L"[%s][%d][%d][%d][%d]",
            //     GetName(),
            //     data->nItemDBID,
            //     data->nClassId,
            //     data->nCount,
            //     data->nPrice)
            // L2_LOG_ERROR(Log,
            //     L"[private store] Inventory item is missing for '%s': DB ID "
            //     L"%d, class %d, count %d, price %d. Entry skipped.",
            //     GetName(),
            //     data->nItemDBID,
            //     data->nClassId,
            //     data->nCount,
            //     data->nPrice)
            L2_LOG_ERROR(
                Log,
                u"[private store] Inventory item is missing for '%s': DB ID "
                u"%d, class %d, count %d, price %d; entry skipped.",
                GetName(), data->nItemDBID, data->nClassId, data->nCount, data->nPrice
            );
            position = store.erase(position);
            continue;
        }

        const std::int64_t liveAmount = item->m_data->m_nCount;
        if (liveAmount < data->nCount) {
            data->nCount = liveAmount;
        }
        const std::int64_t amount = data->nCount;
        if (!item->IsTradable(this, false) || GetTrade() != nullptr) {
            ++position;
            continue;
        }

        BaseAttribute attribute = item->GetTotalAttribute();
        CItemAssemblerPrivateStore assembler(*item, *data, amount, attribute);
        int assembled = assembler.AssembleItemInfo(packet);
        assembled += packet.Assemble("QQ", data->nPrice, CMarketPriceList::Instance().GetMarketPrice(item));
        if (assembled < 1) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"Assembe Error at file[%s], line[%d], "
            //     L"assemble result = [%d], total length = [%d]",
            //     L"User.cpp",
            //     0x26a3,
            //     assembled,
            //     packet.GetLength())
            L2_LOG_ERROR(
                Log, u"[private store] Packet assembly failed: result %d, length %d.", assembled, packet.GetLength()
            );
        } else {
            ++itemCount;
        }

        ++depth;
        if (depth > 0xca) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"depth > %d  at file[%s], line[%d]",
            //     0xca,
            //     L"User.cpp",
            //     0x26aa)
            L2_LOG_ERROR(Log, u"[private store] Packet depth exceeded %d entries; list truncated.", 0xca);
            return false;
        }
        ++position;
    }
    return true;
}

int User::SendPrivateStoreManageList(const bool wholesale, CUserSocket* socket) {
    // Current L2Server 0x00b5a084. The explicit socket argument is present
    // in the source ABI but the current body sends through this User's socket.
    L2_GUARD_FUNCTION();
    (void)socket;

    CPackageItemPacketManager packageItems;
    CPacketHelperEx<20480> storePacket;
    PrivateStoreMap& store = wholesale ? m_PrivateStoreWholeMap : m_PrivateStoreMap;

    int packageDepth = 0;
    int storeItemCount = 0;
    int packageCount;
    std::int64_t adena;
    {
        L2_WRITE_GUARD(m_inv);
        for (CSharedItemData* itemData = m_inv.GetFirst(); itemData != nullptr;) {
            CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(itemData->index);
            if (!item) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] FindObject Failed",
                //     L"User.cpp",
                //     0x25fa)
                L2_LOG_ERROR(
                    Log,
                    u"[private store] Inventory item object is missing while building the sell-management list; entry "
                    u"skipped."
                );
                itemData = itemData->Next();
                continue;
            }

            std::int64_t available = item->m_data->m_nCount;
            const auto stored = store.find(static_cast<int>(item->Id()));
            if (stored != store.end()) {
                CPrivateStoreData* const data = stored->second;
                available -= data->nCount;
                const int enchanted = item->m_data->GetEnchanted();
                if (data->nEnchanted != enchanted) {
                    data->nEnchanted = enchanted;
                }
            }

            if (available > 0 && item->IsTradable(this, false) && GetTrade() == nullptr) {
                packageItems.CheckLimitPackageItemPacketDataSize();
                CItemAssemblerAmount assembler(*item.get(), available);
                int assembled = packageItems.PackageAssembleItem(&assembler);
                assembled += packageItems.PackageAssemble("Q", CMarketPriceList::Instance().GetMarketPrice(item.get()));
                if (assembled < 1) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"Assemble Error at file[%s], line[%d], "
                    //     L"assemble result = [%d], total length = [%d]",
                    //     L"User.cpp",
                    //     0x2625,
                    //     assembled,
                    //     packageItems.GetTotalPackageItemLength())
                    L2_LOG_ERROR(
                        Log, u"[private store] Package-item assembly failed: result %d, length %d.", assembled,
                        packageItems.GetTotalPackageItemLength()
                    );
                } else {
                    packageItems.SetAssembleItemLengthPerItem(assembled);
                    packageItems.IncreasePackageItemCount();
                    ++packageDepth;
                    if (packageDepth > 0x192) {
                        // Log.Add(
                        //     LOG_ERROR,
                        //     L"depth>%d at file[%s], line[%d]",
                        //     0x192,
                        //     L"User.cpp",
                        //     0x2634)
                        L2_LOG_ERROR(Log, u"[private store] Package-item depth exceeded %d entries; list truncated.", 0x192);
                        break;
                    }
                }
            }
            itemData = itemData->Next();
        }

        packageCount = packageItems.GetTotalPackageItemCount();
        _GetPrivateStoreManagerList(store, storePacket, storeItemCount);
        adena = m_inv.GetAdenaAmount();
    }

    CUserSocket* const destination = GetSocket();
    destination->Send(
        "ccddQdbd", S_PRIVATE_STORE_MANAGE_LIST, 1, static_cast<int>(Id()), static_cast<int>(wholesale), adena,
        storeItemCount, storePacket.GetLength(), storePacket.GetPacket(), packageCount
    );
    packageItems.SendPacket_PackageItemData(destination, S_PRIVATE_STORE_MANAGE_LIST, PackageItemPacket::PIPT_ITEM_INFO);

    CCreatureController* const controller = GetController();
    CCreatureController::__async_arg_PrivateStore argument(wholesale ? 8 : 3);
    controller->Serializer.AddExecutable(
        controller, [](CCreatureController* owner, CExecutionArgumentPad* pad) { owner->__async_PrivateStore(pad); },
        &argument, L"PrivateStore"
    );
    return storeItemCount + packageCount;
}

int User::SendPrivateStoreBuyManageList(CUserSocket* socket) {
    // Current L2Server 0x00b53a28. As in the sell-list body, the explicit
    // socket argument is unused by the current image.
    L2_GUARD_FUNCTION();
    (void)socket;

    int depth = 0;
    int buyItemCount = 0;
    CPackageItemPacketManager packageItems;
    CPacketHelperEx<20480> buyPacket;

    IsNowTrade();
    int packageCount;
    std::int64_t adena;
    {
        L2_WRITE_GUARD(m_inv);
        for (CSharedItemData* itemData = m_inv.GetFirst(); itemData != nullptr;) {
            CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(itemData->index);
            if (!item) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] FindObject Failed",
                //     L"User.cpp",
                //     0x2b3a)
                L2_LOG_ERROR(
                    Log,
                    u"[private store] Inventory item object is missing while building the buy-management list; entry "
                    u"skipped."
                );
                itemData = itemData->Next();
                continue;
            }

            if (item->IsTradable(this, true) && GetTrade() == nullptr) {
                packageItems.CheckLimitPackageItemPacketDataSize();
                CItemAssembler assembler(*this, *item.get(), false);
                int assembled = packageItems.PackageAssembleItem(&assembler);
                assembled += packageItems.PackageAssemble("Q", CMarketPriceList::Instance().GetMarketPrice(item));
                if (assembled < 1) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"Assembe Error at file[%s], line[%d], "
                    //     L"assemble result = [%d], total length = [%d]",
                    //     L"User.cpp",
                    //     0x2b56,
                    //     assembled,
                    //     packageItems.GetTotalPackageItemLength())
                    L2_LOG_ERROR(
                        Log, u"[private store] Package-item assembly failed: result %d, length %d.", assembled,
                        packageItems.GetTotalPackageItemLength()
                    );
                } else {
                    packageItems.SetAssembleItemLengthPerItem(assembled);
                    packageItems.IncreasePackageItemCount();
                    ++depth;
                    if (depth > 0x192) {
                        // Log.Add(
                        //     LOG_ERROR,
                        //     L"depth > %d  at file[%s], line[%d]",
                        //     0x192,
                        //     L"User.cpp",
                        //     0x2b66)
                        L2_LOG_ERROR(Log, u"[private store] Package-item depth exceeded %d entries; list truncated.", 0x192);
                        break;
                    }
                }
            }
            itemData = itemData->Next();
        }

        packageCount = packageItems.GetTotalPackageItemCount();
        for (const auto& entry : m_PrivateStoreBuyMap) {
            CPrivateStoreData* const data = entry.second;
            CItem* const item = ItemSmartIdManager()->GetObjectW(static_cast<std::uint32_t>(data->nItemServerId));
            if (!item) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] CItem::FindObjectSP Failed",
                //     L"User.cpp",
                //     0x2b76)
                L2_LOG_ERROR(Log, u"[private store] Listed buy item %d is missing; entry skipped.", data->nItemServerId);
                continue;
            }

            if (item->IsTradable(this, true) && GetTrade() == nullptr) {
                BaseAttribute attribute = item->GetTotalAttribute();
                CItemAssemblerPrivateStore assembler(*item, *data, data->nCount, attribute);
                int assembled = assembler.AssembleItemInfo(buyPacket);
                assembled += buyPacket.Assemble(
                    "dQQQ", data->nInternalId, data->nPrice, CMarketPriceList::Instance().GetMarketPrice(item), data->nCount
                );
                if (assembled < 1) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"Assembe Error at file[%s], line[%d], "
                    //     L"assemble result = [%d], total length = [%d]",
                    //     L"User.cpp",
                    //     0x2b9a,
                    //     assembled,
                    //     buyPacket.GetLength())
                    L2_LOG_ERROR(
                        Log, u"[private store] Buy-item packet assembly failed: result %d, length %d.", assembled,
                        buyPacket.GetLength()
                    );
                } else {
                    ++buyItemCount;
                }

                ++depth;
                if (depth > 0xca) {
                    // Log.Add(
                    //     LOG_ERROR,
                    //     L"depth > %d at file[%s], line[%d]",
                    //     0xca,
                    //     L"User.cpp",
                    //     0x2ba1)
                    L2_LOG_ERROR(Log, u"[private store] Buy-item packet depth exceeded %d entries; list truncated.", 0xca);
                    break;
                }
            }
        }

        adena = m_inv.GetAdenaAmount();
    }

    CUserSocket* const destination = GetSocket();
    destination->Send(
        "ccdQdbd", S_PRIVATE_STORE_BUY_MANAGE_LIST, 1, static_cast<int>(Id()), adena, buyItemCount, buyPacket.GetLength(),
        buyPacket.GetPacket(), packageCount
    );
    packageItems.SendPacket_PackageItemData(destination, S_PRIVATE_STORE_BUY_MANAGE_LIST, PackageItemPacket::PIPT_ITEM_INFO);

    CCreatureController* const controller = GetController();
    CCreatureController::__async_arg_PrivateStore argument(4);
    controller->Serializer.AddExecutable(
        controller, [](CCreatureController* owner, CExecutionArgumentPad* pad) { owner->__async_PrivateStore(pad); },
        &argument, L"PrivateStore"
    );
    return buyItemCount + packageCount;
}

bool User::CheckPrivateStoreInventory() {
    // Current L2Server 0x00b36c74.
    L2_GUARD_FUNCTION();
    int addedArtifactItems = 0;
    int addedNormalItems = 0;
    int addedWeight = 0;

    for (const auto& entry : m_PrivateStoreBuyMap) {
        CPrivateStoreData* const data = entry.second;
        if (data == nullptr) {
            continue;
        }
        CObject* const object = g_ObjectDB.GetObjectW(data->nClassId, false);
        if (object == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] CItem::GetObject Failed",
            //     L"User.cpp",
            //     0x2e60)
            L2_LOG_ERROR(
                Log, u"[private store] Item class %d is missing while checking buy-store inventory capacity; entry skipped.",
                data->nClassId
            );
            continue;
        }

        if (object->IsArtifact()) {
            addedArtifactItems = runtime::AddInt32Wrapping(addedArtifactItems, 1);
        } else {
            addedNormalItems = runtime::AddInt32Wrapping(addedNormalItems, 1);
        }

        const CItem* const item = static_cast<CItem*>(object);
        const int count = runtime::Int32FromBits(static_cast<std::uint32_t>(data->nCount));
        addedWeight =
            runtime::AddInt32Wrapping(addedWeight, runtime::MultiplyInt32Wrapping(item->m_const->m_nWeight, count));
    }

    const int inventoryCount = m_inv.GetTotalCount();
    const int normalLimit = GetInventoryLimit();
    const int artifactLimit = GetArtifactInventoryLimit();
    const bool artifactsFit =
        runtime::AddInt32Wrapping(m_data->m_nCurrentArtifactInventoryNum, addedArtifactItems) <= artifactLimit;

    bool failed = false;
    if (normalLimit < runtime::AddInt32Wrapping(inventoryCount, addedNormalItems)) {
        SendSystemMessage(SystemMessageId::CANNOT_EXCEED_INVENTORY_WEIGHT_OR_QUANTITY_LIMIT);
        SendSystemMessage(
            artifactsFit ? SystemMessageId::NOT_ENOUGH_INVENTORY_SPACE
                         : SystemMessageId::NOT_ENOUGH_NORMAL_AND_ARTIFACT_INVENTORY_SPACE
        );
        failed = true;
    } else if (!artifactsFit) {
        SendSystemMessage(SystemMessageId::CANNOT_EXCEED_INVENTORY_WEIGHT_OR_QUANTITY_LIMIT);
        SendSystemMessage(SystemMessageId::NOT_ENOUGH_ARTIFACT_INVENTORY_SPACE);
        failed = true;
    }

    const int weightLimit = runtime::Win64CvttDoubleToInt32(GetWeightLimit(69000.0));
    if (weightLimit < runtime::AddInt32Wrapping(m_inv.GetCarryingWeight(), addedWeight)) {
        SendSystemMessage(SystemMessageId::CANNOT_EXCEED_INVENTORY_WEIGHT_OR_QUANTITY_LIMIT);
        failed = true;
    }
    return failed;
}

bool User::GetPrivateStoreItems(CPacketHelperEx<20480>& packet, int& itemCount, const int itemClassId) {
    // Current L2Server.exe 0x00b52adc, original owner User.cpp.
    L2_GUARD_FUNCTION();
    const bool result = [&] {
        L2_READ_GUARD(m_inv);
        return _GetPrivateStoreItems(packet, itemCount, itemClassId);
    }();
    return result;
}

bool User::_GetPrivateStoreItems(CPacketHelperEx<20480>& packet, int& itemCount, int itemClassId) {
    // Current L2Server 0x00b4ff0c. The caller owns the inventory read lock.
    // this routine may prune store records whose live item disappeared.
    L2_GUARD_FUNCTION();
    itemCount = 0;
    if (GetTrade() != nullptr) {
        return false;
    }

    const int storeType = GetPrivateStoreType();
    PrivateStoreMap& store =
        storeType == PST_WHOLESALE_OPEN || storeType == PST_WHOLESALE_MANAGE ? m_PrivateStoreWholeMap : m_PrivateStoreMap;

    int depth = 0;
    for (auto position = store.begin(); position != store.end();) {
        CPrivateStoreData* const data = position->second;
        if (itemClassId != -1 && data->nClassId != itemClassId) {
            ++position;
            continue;
        }

        CItem* const item = m_inv.GetByServerID(data->nItemServerId);
        if (item == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"item does not exist in inventory 2 "
            //     L"[%s][%d][%d][%d][%d]",
            //     GetName(),
            //     data->nItemDBID,
            //     data->nClassId,
            //     runtime::Int32FromBits(
            //         static_cast<std::uint32_t>(data->nCount)),
            //     runtime::Int32FromBits(
            //         static_cast<std::uint32_t>(data->nPrice)))
            // L2_LOG_ERROR(Log,
            //     L"[private store] Inventory item is missing for '%s': DB ID "
            //     L"%d, class %d, count %d, price %d. Entry skipped.",
            //     GetName(),
            //     data->nItemDBID,
            //     data->nClassId,
            //     runtime::Int32FromBits(
            //         static_cast<std::uint32_t>(data->nCount)),
            //     runtime::Int32FromBits(
            //         static_cast<std::uint32_t>(data->nPrice)))
            L2_LOG_ERROR(
                Log,
                u"[private store] Inventory item is missing for '%s': DB ID "
                u"%d, class %d, count %d, price %d; entry skipped.",
                GetName(), data->nItemDBID, data->nClassId, runtime::Int32FromBits(static_cast<std::uint32_t>(data->nCount)),
                runtime::Int32FromBits(static_cast<std::uint32_t>(data->nPrice))
            );
            position = store.erase(position);
            continue;
        }

        if (item->IsTradable(this, false)) {
            if (AssemblePrivateStoreItem(*data, *item, packet)) {
                ++itemCount;
            }
            if (++depth > 0xca) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"depth > %d at file[%s], line[%d]",
                //     0xca,
                //     L"User.cpp",
                //     0x2951)
                L2_LOG_ERROR(Log, u"[private store] Sell-item packet depth exceeded %d entries; list truncated.", 0xca);
                break;
            }
        }
        ++position;
    }
    return true;
}

