void User::PrivateStoreListReq(int requesterServerId, int privateStoreType) {
    // Current L2Server 0x00b52804.
    L2_GUARD_FUNCTION();
    CPacketHelperEx<20480> packet;
    int itemCount = 0;

    CCreature* const requesterObject = g_CreatureSmartIdManager.GetObjectW(requesterServerId);
    User* const requester = requesterObject != nullptr && requesterObject->IsPC() ? requesterObject->CastUser() : nullptr;
    if (requester == nullptr) {
        return;
    }
    CUserSocket* const socket = requester->GetSocket();
    if (socket == nullptr) {
        return;
    }

    if (IsShopManaging()) {
        socket->SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        return;
    }
    if (GetPrivateStoreType() != privateStoreType) {
        socket->SendSystemMessage(SystemMessageId::PRIVATE_STORE_ALREADY_CLOSED);
        return;
    }
    if (socket->m_bEconomicRestriction) {
        socket->SendSystemMessage(SystemMessageId::ACCOUNT_CANNOT_USE_PRIVATE_STORES);
        return;
    }

    const bool assembled = [&] {
        L2_READ_GUARD(m_inv);
        const PrivateStoreMap& store =
            GetPrivateStoreType() == PST_WHOLESALE_OPEN || GetPrivateStoreType() == PST_WHOLESALE_MANAGE
            ? m_PrivateStoreWholeMap
            : m_PrivateStoreMap;
        if (store.empty()) {
            socket->SendSystemMessage(SystemMessageId::ITEM_OUT_OF_STOCK);
        }
        return _GetPrivateStoreItems(packet, itemCount, -1);
    }();
    if (!assembled) {
        return;
    }

    const int wholesale =
        GetPrivateStoreType() == PST_WHOLESALE_OPEN || GetPrivateStoreType() == PST_WHOLESALE_MANAGE ? 1 : 0;
    socket->Send(
        "cddQddb", 0xa1, static_cast<int>(Id()), wholesale, requester->m_inv.GetAdenaAmount(),
        requester->m_inv.GetInventoryCount(), itemCount, packet.GetLength(), packet.GetPacket()
    );
}

void User::PrivateStoreBuyListReq(int requesterServerId) {
    // Current L2Server 0x00b55234.
    L2_GUARD_FUNCTION();
    CPacketHelperEx<20480> packet;
    std::array<CPrivateStoreData, 20> snapshots{};
    std::size_t snapshotCount = 0;
    for (const auto& entry : m_PrivateStoreBuyMap) {
        if (entry.second == nullptr || snapshotCount == snapshots.size()) {
            break;
        }
        CPrivateStoreData& snapshot = snapshots[snapshotCount++];
        CPrivateStoreData& source = *entry.second;
        snapshot.nClassId = source.nClassId;
        snapshot.nEnchanted = source.nEnchanted;
        snapshot.nDamaged = source.nDamaged;
        snapshot.nVariation1 = source.nVariation1;
        snapshot.nVariation2 = source.nVariation2;
        snapshot.m_BaseAttribute = source.m_BaseAttribute;
        snapshot.nShapeShiftingClassId = source.nShapeShiftingClassId;
        snapshot.SetEnsoulOption(source.mEnsoulOptionMap);
    }

    CCreature* const requesterObject = g_CreatureSmartIdManager.GetObjectW(requesterServerId);
    User* const requester = requesterObject != nullptr && requesterObject->IsPC() ? requesterObject->CastUser() : nullptr;
    if (requester == nullptr) {
        return;
    }
    CUserSocket* const socket = requester->GetSocket();
    if (socket == nullptr) {
        return;
    }

    const int storeType = GetPrivateStoreType();
    if (storeType == PST_MANAGE || storeType == PST_BUY_MANAGE) {
        socket->SendSystemMessage(SystemMessageId::PREPARING_PRIVATE_STORE);
        return;
    }
    if (storeType != PST_BUY_OPEN) {
        socket->SendSystemMessage(SystemMessageId::NOT_CURRENTLY_BUYING);
        return;
    }
    if (socket->m_bEconomicRestriction) {
        socket->SendSystemMessage(SystemMessageId::ACCOUNT_CANNOT_USE_PRIVATE_STORES);
        return;
    }
    if (m_PrivateStoreBuyMap.empty()) {
        socket->SendSystemMessage(SystemMessageId::PURCHASE_COMPLETED);
        return;
    }

    static_cast<void>(IsNowTrade());
    int assembledCount;
    const std::int64_t adena = [&] {
        L2_READ_GUARD(m_inv);
        L2_READ_GUARD(requester->m_inv);

        CItemFactory& itemFactory = CItemFactory::Inst();
        int inventoryIndex = requester->m_inv.GetFirstIndex();
        int inventoryDepth = 0;
        while (inventoryIndex != -1) {
            CItem* const item = requester->m_inv.GetByIndex(inventoryIndex);
            if (item != nullptr) {
                for (std::size_t index = 0; index < snapshotCount; ++index) {
                    CPrivateStoreData& snapshot = snapshots[index];
                    if (snapshot.nIndex == 0 && MatchesPrivateStoreBuyRecord(*item, snapshot)) {
                        snapshot.nIndex = item->m_data->index;
                        break;
                    }
                }
            }
            inventoryIndex = itemFactory.GetNextIndex(inventoryIndex);
            if (++inventoryDepth > 0x192) {
                // Log.Add(
                //     LOG_ERROR,
                //     "depth > %d at file[%s], line[%d]",
                //     0x192,
                //     "User.cpp",
                //     0x2de1)
                L2_LOG_ERROR(
                    Log, "[private store] Buyer inventory traversal exceeded %d entries; operation stopped.", 0x192
                );
                break;
            }
        }

        assembledCount = 0;
        int depth = 0;
        std::size_t snapshotIndex = 0;
        for (const auto& entry : m_PrivateStoreBuyMap) {
            CPrivateStoreData* const data = entry.second;
            if (data == nullptr || snapshotIndex >= snapshotCount) {
                break;
            }
            const CPrivateStoreData& snapshot = snapshots[snapshotIndex++];
            bool liveItem = false;
            CItem* item = nullptr;
            if (snapshot.nIndex < 1) {
                CObject* const object = g_ObjectDB.GetObjectW(data->nClassId, false);
                item = object != nullptr ? object->CastItem() : nullptr;
            } else {
                item = requester->m_inv.GetByIndex(snapshot.nIndex);
                liveItem = item != nullptr;
            }
            if (item == nullptr || !item->IsTradable(this, false) || !item->IsTradable(requester, false) ||
                GetTrade() != nullptr) {
                continue;
            }

            CItemAssemblerPrivateStore assembler(*item, *data, liveItem ? item->m_data->m_nCount : 0, data->m_BaseAttribute);
            int result = assembler.AssembleItemInfo(packet);
            result += packet.Assemble(
                "dQQQ", data->nInternalId, data->nPrice, CMarketPriceList::Instance().GetMarketPrice(item), data->nCount
            );
            if (result < 1) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"Assembe Error at file[%s], line[%d], "
                //     L"assemble result = [%d], total length = [%d]",
                //     L"User.cpp",
                //     0x2e38,
                //     result,
                //     packet.GetLength())
                L2_LOG_ERROR(
                    Log, u"[private store] Buy-list packet assembly failed: result %d, length %d.", result,
                    packet.GetLength()
                );
            } else {
                ++assembledCount;
            }
            if (++depth > 0xca) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"depth > %d at file[%s], line[%d]",
                //     0xca,
                //     L"User.cpp",
                //     0x2e3f)
                L2_LOG_ERROR(Log, u"[private store] Buy-list packet depth exceeded %d entries; list truncated.", 0xca);
                break;
            }
        }

        return requester->m_inv.GetAdenaAmount();
    }();
    socket->Send(
        "cdQddb", 0xbe, static_cast<int>(Id()), adena, requester->m_inv.GetInventoryCount(), assembledCount,
        packet.GetLength(), packet.GetPacket()
    );
}

