void User::ProcessUnderWaterEffect() {
    // Current L2Server.exe 0x00b05820.
    L2_GUARD_FUNCTION();
    const bool wasUnderWater = m_AreaMod.m_bWasUnderWater;
    const bool isUnderWater = m_AreaMod.m_bIsUnderWater;

    if (wasUnderWater && !isUnderWater) {
        GetSocket()->Send("cdddd", 0x6b, GetServerId(), 2, 0, 0);
        return;
    }
    if (!wasUnderWater && !isUnderWater) {
        return;
    }

    if (wasUnderWater && isUnderWater && !m_bIsNewInWorld) {
        if (m_data->m_bIsAlive == 0 || CIOObject::IsInShortTime(m_nBreathLimit, 0)) {
            return;
        }

        const double damage = std::sqrt(m_data->m_dBaseHP) / ConBonusF() / 5.0;
        GotDamageByEnvironment(damage, true, static_cast<DamageTypeEnum>(3), true);
        GetSocket()->SendSystemMessage_d(
            SystemMessageId::RECEIVED_SUFFOCATION_DAMAGE, runtime::Win64CvttDoubleToInt32(damage)
        );
        return;
    }

    const int baseBreath = g_PCParamDB.GetIntValueByField(m_data->m_Sex, m_data->m_nClass, PC_BREATH_BONUS, m_data->m_Race);
    const int baseWithCon =
        runtime::MultiplyInt32Wrapping(runtime::MultiplyInt32Wrapping(baseBreath, m_data->m_Stat.m_N[2]), 2);
    int breathLimit = runtime::Win64CvttDoubleToInt32(
        ((static_cast<double>(baseWithCon) * m_SkillMod.m_Mods[CCreatureSkillMod::Breath].m_Per +
             m_SkillMod.m_Mods[CCreatureSkillMod::Breath].m_Diff * 100.0) *
            1000.0) /
        100.0
    );
    if (m_bIsNewInWorld) {
        breathLimit /= 10;
    }

    m_nBreathLimit = 0;
    CIOObject::SetShortTimeStamp(&m_nBreathLimit, static_cast<std::uint32_t>(breathLimit));
    GetSocket()->Send("cdddd", 0x6b, GetServerId(), 2, breathLimit, breathLimit);
}

void User::ProcessVioletBoy() {
    // Current L2Server.exe 0x00b05b84.
    L2_GUARD_FUNCTION();
    if (m_bIsSkillViolet) {
        return;
    }

    const int duration = m_bIsInitiativeViolet ? 120 : 60;
    const int remaining = runtime::AddInt32Wrapping(
        runtime::SubtractInt32Wrapping(m_data->m_nPKTimeStamp, runtime::crt::Time32Now()), duration
    );
    if (remaining < 1) {
        if (IsGuilty()) {
            SetGuilty(0);
            runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
            m_bIsInitiativeViolet = false;
        }
        return;
    }

    SendStatusUpdate(VCP_CRIMINAL_RATE, 0, 0);
    if (remaining < 21) {
        if (GetGuilty() == 2) {
            return;
        }
        SetGuilty(2);
    } else {
        if (m_bEinhasadeTransformed || GetGuilty() == 1) {
            return;
        }
        SetGuilty(1);
    }
    runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
}

void User::RequestPCCafeCouponUse(const char16_t* coupon) {
    // Current L2Server 0x00b6c18c.
    L2_GUARD_FUNCTION();
    CEvent_PCCafeCoupon* const event =
        static_cast<CEvent_PCCafeCoupon*>(CEventManager::inst().GetEvent(GAME_EVENT::ET_PCCAFE_COUPON_EVENT));
    if (event == nullptr || event->m_EventState != CEvent_PCCafeCoupon::IN_EVENT || !m_data->m_bPCCafeUser) {
        return;
    }

    int remainingMinutes = 0;
    if (!event->IsValidUser(GetDBID(), remainingMinutes)) {
        GetSocket()->SendSystemMessage_d(SystemMessageId::SERIAL_NUMBER_ENTRY_BLOCKED_FOR_MINUTES, remainingMinutes);
        return;
    }

    const CCouponKey key = event->Reversed(coupon);
    if (!event->Find(key)) {
        const int count = event->FailedInputCoupon(GetDBID());
        if (5 - count < 1) {
            SendSystemMessage(SystemMessageId::SERIAL_NUMBER_ENTRY_BLOCKED_AFTER_REPEATED_FAILURE);
        } else {
            GetSocket()->Send(
                "chccccc", 0x62, SystemMessageId::INVALID_SERIAL_NUMBER_WITH_FAILED_AND_REMAINING_ATTEMPTS, 2, 0x14,
                static_cast<int>(static_cast<std::int8_t>(count)), 0x14,
                static_cast<int>(static_cast<std::int8_t>(5 - count))
            );
        }
        return;
    }

    db.RequestPCCafeCouponCheck(
        this, static_cast<int>(key.Num(0)), static_cast<int>(key.Num(1)), static_cast<int>(key.Num(2)),
        static_cast<int>(key.Num(3))
    );
}

void User::RepliedPCCafeCouponResult(
    const char result, const int couponPart1, const int couponPart2, const int couponPart3, const int couponPart4
) {
    // Current L2Server 0x00b6c3c0.
    L2_GUARD_FUNCTION();

    int remainingMinutes = 0;
    CEvent_PCCafeCoupon* const event =
        static_cast<CEvent_PCCafeCoupon*>(CEventManager::inst().GetEvent(GAME_EVENT::ET_PCCAFE_COUPON_EVENT));
    if (!m_data->m_bPCCafeUser || event == nullptr || !event->IsValidUser(GetDBID(), remainingMinutes)) {
        return;
    }

    if (result == 1) {
        const int couponItemClassId = event->GetCouponItemId(m_data->m_nLevel);
        if (!m_inv.CheckAddable(couponItemClassId, 1, false)) {
            SendSystemMessage(SystemMessageId::INVENTORY_SLOTS_FULL);
            return;
        }

        ItemManip request(0, couponItemClassId, 1, 0, 0, 0, true);
        AtomicJob* const job = new CAtomicCouponUsed(
            m_data->m_nWorldId, static_cast<int>(Id()), GetDBID(), couponPart1, couponPart2, couponPart3, couponPart4,
            couponItemClassId, GetAccountID()
        );

        L2_GUARD(m_ManipulateQueueLock);
        CPacketHelperEx<20480> packet;
        etcMsg message = SaveEtcMsg(false, false, 0, 0, 0, std::u16string(), std::u16string(), 0);
        ManipulateQueue queue = SaveManipulateQueue(
            ManipulateType::MANI_PCCAFE_COUPON, 0, 1, &request, job, 0, packet, false, ItemGetReason::Etc, message
        );

        const ManiItemResultType manipulationResult = _SetManiItemJob(queue);
        if (manipulationResult == MRT_NOJOB) {
            if (!_HandleItemManipulation(queue)) {
                job->Destroy();
            }
        } else if (manipulationResult == MRT_JOBMAP) {
            job->Destroy();
            SendSystemMessage(SystemMessageId::PREVIOUS_REQUEST_NOT_COMPLETED);
        } else if (manipulationResult == MRT_JOBNOTMAP) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue Insert",
            //     L"User.cpp",
            //     0x31e0)
            // Noise: normal deferral behind a pending item operation. Not a failure.
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue Insert",
            //     L"User.cpp",
            //     0x31e0)
        } else {
            job->Destroy();
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue ERROR",
            //     L"User.cpp",
            //     0x31e6)
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue ERROR",
            //     L"User.cpp",
            //     0x31e6)
            L2_LOG_ERROR(
                Log,
                "[items] Operation %d, request %d, character %u: unexpected queue result %d; item operation not started.",
                static_cast<int>(queue.eType), queue.nId, static_cast<unsigned int>(GetDBID()),
                static_cast<int>(manipulationResult)
            );
        }
    } else if (result == 0) {
        SendSystemMessage(SystemMessageId::SERIAL_NUMBER_ALREADY_USED);
    } else if (result == 2) {
        SendSystemMessage(SystemMessageId::CANNOT_ENTER_SERIAL_NUMBER_COUPON_ALREADY_USED);
    }
}

