void User::VitalityConsume(CCreature* creature, int experience, double bonus) {
    L2_GUARD_FUNCTION();
    if ((m_data->m_nPKCount == 0 && m_data->m_nLevel < 10) || m_nChangeSubjobFlag == 1) {
        return;
    }

    double consumePoint = 0.0;
    bool directConsume = false;
    if (m_SkillDurationMod.m_RechargeVitalityPoint < 1) {
        CSPointer<User> self(this, ObjectRefType::FunctionChain);
        if (m_pVitality->IsSuspended(self)) {
            consumePoint = 0.0;
        } else {
            directConsume = true;
            consumePoint = static_cast<double>(m_pVitality->GetConsumePoint(
                creature, experience, bonus, m_data->m_nLevel, m_SkillDurationMod.m_VitalityBonusPer,
                m_SkillDurationMod.m_nVitalitySubPer, directConsume
            ));
        }
    } else {
        consumePoint = static_cast<double>(m_pVitality->GetConsumePoint(
            creature, experience, bonus, m_data->m_nLevel, m_SkillDurationMod.m_VitalityBonusPer,
            m_SkillDurationMod.m_nVitalitySubPer, directConsume
        ));
    }

    const int oldVitalPoint = m_pVitality->m_Data.vitalPoint;
    CSPointer<User> self(this, ObjectRefType::FunctionChain);
    if (consumePoint <= 0.0) {
        m_pVitality->Consume(self, static_cast<int>(consumePoint));
    } else {
        m_pVitality->Recharge(self, static_cast<int>(consumePoint), true);
    }

    if ((oldVitalPoint > 0) != (m_pVitality->m_Data.vitalPoint > 0)) {
        CLogFormatter formatter;
        formatter.WriteLog1(
            0x1f9d, this, nullptr, nullptr, nullptr, nullptr, m_pVitality->m_Data.vitalPoint > 0 ? 1 : 0,
            m_pVitality->m_Data.vitalPoint, m_data->m_nSubJobId, m_data->m_DualClassID, 0, 0, 0
        );
    }
}

