void User::SendVitalityEffectInfo(CUserSocket* socket) {
    L2_GUARD_FUNCTION();
    CUserSocket* destination = socket;
    if (destination == nullptr) {
        destination = GetSocket();
        if (destination == nullptr) {
            return;
        }
    }

    int expBonus = 0;
    int addedBonus = 0;
    const bool freeUser = CheckPremiumType(PremiumUserType::PUT_FREE_USER);
    if (freeUser) {
        CSPointer<User> user(this, ObjectRefType::FunctionChain);
        m_pVitality->GetExpBonusValue(user, expBonus, addedBonus);
    } else {
        CSPointer<User> user(this, ObjectRefType::FunctionChain);
        m_pVitality->GetPremiumExpBonusValue(user, expBonus, addedBonus);
    }

    const int maximum = freeUser ? m_pVitality->MAX_RESTORE_COUNT : m_pVitality->PREMIUM_MAX_RESTORE_COUNT;
    const int remainingValue = runtime::SubtractInt32Wrapping(maximum, m_pVitality->m_Data.restoreCount);
    const std::int16_t remaining =
        remainingValue < 0 ? 0 : runtime::Int16FromBits(static_cast<std::uint16_t>(remainingValue));
    const std::int16_t maximum16 = runtime::Int16FromBits(static_cast<std::uint16_t>(maximum));
    const std::int16_t addedBonus16 = runtime::Int16FromBits(static_cast<std::uint16_t>(addedBonus));

    destination->Send(
        "chddhhh", 0xfe, socket == nullptr ? 0x118 : 0x150, GetVitalPoint(), expBonus, static_cast<int>(addedBonus16),
        static_cast<int>(remaining), static_cast<int>(maximum16)
    );
}

