void User::ManipulatePVPPointWithItem(int point, int itemCount, int itemClassId, std::int64_t amount, int option) {
    // Current L2Server 0x00b0d3d8. The second integer is forwarded as the
    // point-operation value. The source parameter name is intentionally
    // kept even though current callers pass literal 3.
    L2_GUARD_FUNCTION();
    ItemManip manipulation(0, itemClassId, amount, option, 0, 0, true);
    const int result =
        HandlePointItemManipulation(runtime::SubtractInt32Wrapping(0, point), 5, itemCount, 1, &manipulation, nullptr, 0);
    if (result == 1) {
        SendSystemMessage_d(SystemMessageId::FAME_CONSUMED, point);
    } else if (result == -1) {
        SendSystemMessage(0x917);
    } else if (result == -2) {
        SendSystemMessage(SystemMessageId::INVENTORY_SLOTS_FULL);
    }
}

void User::ValidateCastleStateInfo() {
    // Current L2Server 0x00b0d9d4.
    L2_GUARD_FUNCTION();
    for (int residenceId = 1; residenceId <= 9; ++residenceId) {
        CResidence* const residence = g_ResidenceDB.GetResidence(residenceId);
        if (residence == nullptr || !residence->IsCastle()) {
            continue;
        }
        CResidenceData* const data = residence->m_data;
        const int publishedResidenceId = data != nullptr ? data->m_nResidenceID : 0;
        GetSocket()->Send("chdd", 0xfe, 0x12d, publishedResidenceId, data->m_ResidenceType);
    }
}

