int User::CheckDailyPCCafeBonus(int point) {
    // Current L2Server.exe 0x00b6bbe0.
    L2_GUARD_FUNCTION();
    int result = 0;
    if (!m_data->m_bPCCafeUser) {
        return result;
    }

    int successfulLevelCount = 0;
    const int oldCheckLevel = m_data->m_nBonusCheckLevel;
    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_PCCAFE_SETTING);
    if (baseEvent != nullptr) {
        successfulLevelCount = 1;
        auto* const event = static_cast<CEvent_PCCafe*>(baseEvent);
        const int nextCheckLevel = runtime::AddInt32Wrapping(oldCheckLevel, 1);
        const int bonusType =
            event->CheckPCCafeBonusItem(runtime::AddInt32Wrapping(m_data->m_nDailyPCCafePoint, point), nextCheckLevel);
        result = event->GetPCCafeLevelBonus(bonusType, nextCheckLevel);

        if (bonusType == CEvent_PCCafe::BT_ITEM) {
            const int itemClassId = event->GetPCCafeItemBonus(CEvent_PCCafe::BT_ITEM, nextCheckLevel);
            CObject* const object = g_ObjectDB.GetObjectW(itemClassId, false);
            if (object == nullptr || !object->IsItem()) {
                char16_t context[] = u"";
                GetSocket()->SendSystemMessage(context, u"Try to give Invalid Item");
                result = 0;
            } else {
                CItem* const item = static_cast<CItem*>(object);
                const int itemWeight = item->m_data->m_ItemConsumeType == ICT_ASSET ? 0 : item->m_const->m_nWeight;
                const bool inventoryFull = static_cast<float>(GetInventoryLimit()) * 0.9F <
                    static_cast<float>(runtime::AddInt32Wrapping(m_inv.GetTotalCount(), 1));
                const bool overweight = static_cast<float>(static_cast<std::int32_t>(GetWeightLimit(69000.0))) * 0.8F <
                    static_cast<float>(runtime::AddInt32Wrapping(m_inv.GetCarryingWeight(), itemWeight));
                if (inventoryFull || overweight) {
                    SendSystemMessage(SystemMessageId::PC_CAFE_LOGIN_REWARD_NOT_RECEIVED_INVENTORY_RESTRICTION);
                    successfulLevelCount = 0;
                    result = 0;
                } else {
                    std::optional<InventoryParams> parametersStorage;
                    {
                        L2_WRITE_GUARD(m_inv);
                        auto& parameters = parametersStorage.emplace();
                        parameters.nItemClassID = itemClassId;
                        parameters.nCount = 1;
                        AddItemToInventory(parameters);
                    }
                    result = 0;
                }
            }
        } else if (bonusType != CEvent_PCCafe::BT_POINT) {
            successfulLevelCount = 0;
            result = 0;
        }
    }

    m_data->m_nDailyPCCafePoint = runtime::AddInt32Wrapping(m_data->m_nDailyPCCafePoint, point);
    m_data->m_nBonusCheckLevel = runtime::AddInt32Wrapping(oldCheckLevel, successfulLevelCount);
    db.RequestSaveDailyPCCafePoint(this, point, m_data->m_nBonusCheckLevel);
    return result;
}

