void User::SendPCCafePointInfo(int point, int messageType, bool loaded, bool clear, int messageId) {
    L2_GUARD_FUNCTION();

    int delta = point - m_data->m_nPCCafePoint;
    if (loaded) {
        delta = 0;
    }

    if (clear) {
        GetSocket()->Send("chddcdcd", 0xfe, 0x32, 0, 0, 0, 0, 0, 0);
        return;
    }

    SetPoint(1, point);
    if (0 < delta) {
        PledgeMissionCheckAndAddCount(PledgeMission::PMGT_PCCAFE_POINT_GET, 0, delta);
    }

    char eventType = 0;
    int remainingHours = 0;
    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_PCCAFE_SETTING);
    if (baseEvent != nullptr) {
        auto* const event = static_cast<CEvent_PCCafe*>(baseEvent);
        eventType = static_cast<char>(event->GetPCCafeEventType());
        remainingHours = event->GetPCCafeEventRemainHour();
    }

    char result = 0;
    if (!loaded) {
        switch (messageType) {
            case 0:
                GetSocket()->SendSystemMessage_d(
                    0 < messageId ? static_cast<unsigned int>(messageId)
                                  : static_cast<unsigned int>(SystemMessageId::PC_POINTS_GAINED),
                    delta
                );
                break;
            case 1:
                GetSocket()->SendSystemMessage_d(
                    static_cast<unsigned int>(SystemMessageId::OBTAINED_DAILY_PC_CAFE_ATTENDANCE_POINTS), delta
                );
                break;
            case 2:
                GetSocket()->SendSystemMessage_d(
                    static_cast<unsigned int>(SystemMessageId::OBTAINED_DOUBLE_PC_POINTS), delta
                );
                result = 1;
                break;
            case 3:
                GetSocket()->SendSystemMessage_d(static_cast<unsigned int>(SystemMessageId::POINTS_CONSUMED), -delta);
                result = 2;
                break;
            default:
                SendSystemMessage(static_cast<unsigned int>(SystemMessageId::PURCHASE_FAILED));
                break;
        }
    }

    if (!m_data->m_bPCCafeUser && point == 0) {
        GetSocket()->Send("chddcdcd", 0xfe, 0x32, 0, 0, 0, 0, 0, 0);
        return;
    }

    GetSocket()->Send("chddcdcd", 0xfe, 0x32, point, delta, eventType, remainingHours, result, m_data->m_nDailyPCCafePoint);
}

void User::ActivateDormantEventBuff(int oldDormantType, int newDormantType) {
    // Current L2Server.exe 0x00b6e330.
    L2_GUARD_FUNCTION();
    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_DORMANT_BUFF_EVENT);
    if (baseEvent == nullptr || !baseEvent->InEventTime()) {
        return;
    }

    auto* const event = static_cast<CEvent_DormantBuffEvent*>(baseEvent);
    CSkillKey oldSkill;
    if (oldDormantType == 3) {
        oldSkill = event->GetDormantBuff();
    } else if (oldDormantType == 2) {
        oldSkill = event->GetNewbiewBuff();
    }

    if (oldSkill.m_nSkillId > 0 && oldSkill.m_nLevel != 0) {
        L2_GUARD(m_InfectedSkillsSect);
        std::vector<int> deleteIndices;
        int index = 0;
        for (const InfectedSkillType& infected : m_InfectedSkills) {
            if (infected.pSkillInfo->m_nSkillId == oldSkill.m_nSkillId &&
                infected.pSkillInfo->m_nLevel == oldSkill.m_nLevel) {
                deleteIndices.push_back(index);
            }
            ++index;
        }

        // The current target consumes the saved indices in
        // ascending order, even though each deletion shifts the vector.
        for (const int deleteIndex : deleteIndices) {
            const CSkillInfo* const skillInfo =
                runtime::CheckedVectorAt(m_InfectedSkills, static_cast<std::size_t>(deleteIndex)).pSkillInfo;
            _DeleteAbnormalStatus(deleteIndex, this, skillInfo, true, SPET_DISPEL, true);
        }
    }

    CSkillKey newSkill;
    if (newDormantType == 3) {
        newSkill = event->GetDormantBuff();
    } else if (newDormantType == 2) {
        newSkill = event->GetNewbiewBuff();
    }
    if (newSkill.m_nSkillId > 0 && newSkill.m_nLevel != 0) {
        const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(newSkill, nullptr);
        if (skillInfo != nullptr) {
            skillInfo->ActivateSkill(this, this, 0.0, nullptr, CSkillInfo::EAT_SUCCESS, false);
        }
    }
}

void User::CheckDormantUser(bool force) {
    // Current L2Server.exe 0x00b6ec30.
    L2_GUARD_FUNCTION();
    if (GetSocket() != nullptr && GetSocket() != NullUserSocket::GetNullUserSocket()) {
        // std::int16_t dormantType = 0
        std::int16_t dormantType = DormantConst::DT_NORMAL;
        if (GetSocket()->IsDormantUser()) {
            // dormantType = 3.
            dormantType = DormantConst::DT_DORMANT;
        } else if (GetSocket()->IsNewbieUser()) {
            // dormantType = 2.
            dormantType = DormantConst::DT_NEWBIE;
        }

        if (dormantType != m_data->m_nDormantType || force) {
            ActivateDormantEventBuff(m_data->m_nDormantType, dormantType);
            m_data->m_nDormantType = dormantType;
        }
        return;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"[CheckDormantUser] invalid socket")
    L2_LOG_ERROR(Log, u"[dormant user] Character %u has no usable client socket; dormant-state check skipped.", GetDBID());
}

void User::CheckPCCafeEvent() {
    // Current L2Server.exe 0x00b6ed90.
    L2_GUARD_FUNCTION();
    if (!CanUsePCCafePoint()) {
        if (m_data->m_bCanUsePCCafePoint) {
            SendSystemMessage(SystemMessageId::PC_POINT_SPENDING_PERIOD_ENDED);
            SendPCCafePointInfo(0, 0, false, true, 0);
        }
        m_data->m_bCanUsePCCafePoint = false;
        return;
    }

    m_data->m_bCanUsePCCafePoint = true;
    if (!CanGetPCCafePoint()) {
        if (m_bCanGetPCCafePoint) {
            LoadPCCafePoint(1);
            SendSystemMessage(SystemMessageId::PC_POINT_EARNING_PERIOD_ENDED);
        }
        m_bCanGetPCCafePoint = false;
        SendPCCafePointInfo(m_data->m_nPCCafePoint, 0, true, false, 0);
        return;
    }

    if (!m_data->m_bPCCafeUser) {
        if (CheckDayPassed()) {
            db.RequestSavePCCafeCount(this, 0, 3);
            return;
        }
        if (!CheckHomeCountAddable()) {
            AnnounceHomeMax();
            return;
        }
    }

    m_bCanGetPCCafePoint = true;
    const int useTime = GetPCCafeUseTime();
    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_PCCAFE_SETTING);
    if (baseEvent == nullptr) {
        return;
    }

    auto* const event = static_cast<CEvent_PCCafe*>(baseEvent);
    if (event->GetSettingTime() > runtime::SubtractInt32Wrapping(useTime, m_nLastAddPCCafePointTime)) {
        return;
    }

    int point = 0;
    int randomPointProbability = 0;
    if (m_data->m_bPCCafeUser) {
        point = event->m_PCCafe.m_nPoint;
        randomPointProbability = event->m_PCCafe.m_nRandomPointProb;
    } else {
        point = event->GetHomePCCafePoint();
        randomPointProbability = event->GetHomePCCafeRandomPoint();
    }

    DoJobWithPoint operation = DJWP_ADD;
    int bonusPoint = 0;
    const double random = ::genrand64_real1();
    if (100.0 - static_cast<double>(randomPointProbability) <= random * 100.0 + 0.0) {
        operation = DJWP_DOUBLEADD;
        bonusPoint = point;
    }

    ResetPCCafeUseTime(false);
    int totalPoint = runtime::AddInt32Wrapping(point, bonusPoint);
    if (!m_data->m_bPCCafeUser) {
        db.RequestSavePCCafeCount(this, runtime::AddInt32Wrapping(m_nHomePCCafeCount, 1), 3);
    }
    if (point >= 0) {
        totalPoint = runtime::AddInt32Wrapping(totalPoint, CheckDailyPCCafeBonus(point));
    }

    UpdatePoint(totalPoint, PT_PCCAFE_POINT, operation, 0);
    const int currentPoint = m_data->m_nPCCafePoint;
    CUserSocket* const socket = GetSocket();
    const std::u16string pcCafeCode = Utf16Text(reinterpret_cast<const char16_t*>(socket->GetPCCafeCodeW())).String();
    CLogFormatter formatter;
    formatter.WriteLog1(
        0x3cb, this, nullptr, nullptr, pcCafeCode.data(), nullptr, totalPoint,
        runtime::AddInt32Wrapping(totalPoint, currentPoint), 0, 0, 0, 0, 0
    );
}

int User::GetRealAddablePoint(int point, int pointType) {
    L2_GUARD_FUNCTION();

    int maximum = 0;
    if (pointType == 1) {
        maximum = 200000;
    } else if (pointType == 5 || pointType == 8) {
        maximum = 20000000;
    }

    const int addable = runtime::SubtractInt32Wrapping(maximum, GetPoint(pointType));
    return addable <= point ? addable : point;
}

bool User::UpdatePoint(int point, UserPointType pointType, DoJobWithPoint operation, int line) {
    L2_GUARD_FUNCTION();

    const int pointTypeValue = static_cast<int>(pointType);
    if (point >= 0) {
        if (pointType != PT_PCCAFE_POINT && pointType != PT_PVP_POINT && pointType != PT_RAID_POINT) {
            // The current body forwards unsupported point types unchanged.
        } else {
            if (pointType == PT_PVP_POINT && !CanGetPVPPoint()) {
                return false;
            }

            point = GetRealAddablePoint(point, pointTypeValue);
            if (point < 1) {
                if (pointType == PT_PCCAFE_POINT) {
                    SendSystemMessage(SystemMessageId::PC_POINT_ACCUMULATION_LIMIT_REACHED);
                    SendPCCafePointInfo(m_data->m_nPCCafePoint, 0, false, false, 0);
                } else if (pointType == PT_PVP_POINT) {
                    SendSystemMessage(SystemMessageId::FAME_LIMIT_REACHED);
                } else if (pointType == PT_RAID_POINT) {
                    SendSystemMessage(SystemMessageId::RAID_POINT_LIMIT_REACHED);
                }
                return true;
            }
        }
    }

    const int result =
        HandlePointItemManipulation(point, pointTypeValue, static_cast<int>(operation), 0, nullptr, nullptr, line);
    if (result == 1) {
        if (point < 0) {
            if (pointType == PT_PVP_POINT) {
                SendSystemMessage_d(SystemMessageId::FAME_CONSUMED, -point);
            } else if (pointType == PT_RAID_POINT) {
                SendSystemMessage_d(SystemMessageId::RAID_POINTS_CONSUMED, -point);
            }
        }
        return true;
    }

    if (result == -1) {
        if (pointType == PT_PVP_POINT) {
            SendSystemMessage(0x917);
        } else if (pointType == PT_RAID_POINT) {
            SendSystemMessage(SystemMessageId::NOT_ENOUGH_RAID_POINTS);
        } else {
            SendSystemMessage(SystemMessageId::NOT_ENOUGH_PC_POINTS);
        }
    } else if (result == -2) {
        SendSystemMessage(SystemMessageId::INVENTORY_SLOTS_FULL);
    }
    return false;
}

void User::SavePoint(int pointType, int currentPoint, int delta) {
    L2_GUARD_FUNCTION();
    int result = runtime::AddInt32Wrapping(currentPoint, delta);
    if ((pointType == 5 || pointType == 8) && result < 1 && delta < 0) {
        result = 0;
    }
    SetPoint(pointType, result);
    db.RequestSaveUserPoint(this, pointType, result, currentPoint);
}

void User::AddPoint(int pointType, int point, bool save) {
    L2_GUARD_FUNCTION();
    const int currentPoint = GetPoint(pointType);
    if (!save) {
        SetPoint(pointType, runtime::AddInt32Wrapping(point, currentPoint));
        return;
    }
    SavePoint(pointType, currentPoint, point);
}

void User::AddBonusCount(int count) {
    L2_GUARD_FUNCTION();
    if (count != 0) {
        runtime::raw_atomic::AddI32(&m_nBonusCount, count);
        m_data->m_NeedUpdatePacketBitSet.SetBit(0x21);
    }
    if (runtime::raw_atomic::LoadI32Relaxed(&m_nBonusCount) > 0xff) {
        SetBonusCount(0xff);
    }
    if (runtime::raw_atomic::LoadI32Relaxed(&m_nBonusCount) < 0) {
        SetBonusCount(0);
    }
}

void User::SetVoteSystem(
    int bonusTimeLimit, int playTime, int voteCount, int bonusCount, int playTimeCount, _SYSTEMTIME* lastInitTime
) {
    L2_GUARD_FUNCTION();

    SetVoteCount(voteCount);
    runtime::raw_atomic::ExchangeI32(&m_nBonusTimeLimit, bonusTimeLimit);
    SetBonusCount(bonusCount);
    runtime::raw_atomic::ExchangeI32(&m_nPlayTime, playTime);
    runtime::raw_atomic::ExchangeI32(&m_nPlayTimeCount, playTimeCount);
    std::memcpy(&m_tmLastInitTime, lastInitTime, sizeof(m_tmLastInitTime));
}

int User::CalInitialVoteSystem() {
    // Current L2Server 0x00b6d5c8.
    L2_GUARD_FUNCTION();
    if (Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_VOTE_SYSTEM) == nullptr) {
        return 0;
    }

    const _SYSTEMTIME current = runtime::crt::LocalSystemTimeNow<_SYSTEMTIME>();
    std::tm currentReset{};
    currentReset.tm_year = static_cast<int>(current.wYear) - 1900;
    currentReset.tm_mon = static_cast<int>(current.wMonth) - 1;
    currentReset.tm_mday =
        static_cast<int>(current.wDay) - ((current.wHour < 6 || (current.wHour == 6 && current.wMinute < 31)) ? 1 : 0);
    currentReset.tm_hour = 6;
    currentReset.tm_min = 30;
    currentReset.tm_sec = 0;

    std::tm previous{};
    previous.tm_year = static_cast<int>(m_tmLastInitTime.wYear) - 1900;
    previous.tm_mon = static_cast<int>(m_tmLastInitTime.wMonth) - 1;
    previous.tm_mday = m_tmLastInitTime.wDay;
    previous.tm_hour = m_tmLastInitTime.wHour;
    previous.tm_min = m_tmLastInitTime.wMinute;
    previous.tm_sec = m_tmLastInitTime.wSecond;

    const std::int32_t delta =
        runtime::SubtractInt32Wrapping(runtime::crt::Mktime32(&currentReset), runtime::crt::Mktime32(&previous));
    return delta > 0 ? static_cast<int>(std::floor(static_cast<double>(delta) / 86400.0)) : 0;
}

void User::InitVoteParam(const int elapsedDays) {
    // Current L2Server 0x00b6d79c.
    L2_GUARD_FUNCTION();
    CEvent_VoteSystem* const event =
        static_cast<CEvent_VoteSystem*>(Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_VOTE_SYSTEM));
    if (event == nullptr) {
        return;
    }

    const _SYSTEMTIME current = runtime::crt::LocalSystemTimeNow<_SYSTEMTIME>();
    SetVoteCount(20);
    runtime::raw_atomic::ExchangeI32(&m_nBonusTimeLimit, event->GetBonusTimeLimit());
    AddBonusCount(runtime::MultiplyInt32Wrapping(elapsedDays, -5));
    runtime::raw_atomic::ExchangeI32(&m_nPlayTime, 0);
    runtime::raw_atomic::ExchangeI32(&m_nPlayTimeCount, 0);
    std::memcpy(&m_tmLastInitTime, &current, sizeof(m_tmLastInitTime));
}

void User::CheckVoteSystemTime() {
    // Current L2Server 0x00b6d8c0.
    L2_GUARD_FUNCTION();
    CEvent_VoteSystem* const event =
        static_cast<CEvent_VoteSystem*>(Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_VOTE_SYSTEM));
    if (event == nullptr || event->GetVoteCount() == 0) {
        return;
    }

    std::int32_t elapsed = 0;
    if (runtime::raw_atomic::LoadI32Relaxed(&m_nVoteTimeStamp) >= 1) {
        elapsed = runtime::SubtractInt32Wrapping(
            runtime::crt::Time32Now(), runtime::raw_atomic::LoadI32Relaxed(&m_nVoteTimeStamp)
        );
    }
    const std::int32_t currentPlayTime =
        runtime::AddInt32Wrapping(runtime::raw_atomic::LoadI32Relaxed(&m_nPlayTime), elapsed);
    const std::int32_t voteCount = event->GetVoteCount();
    if (!(runtime::raw_atomic::LoadI32Relaxed(&m_nPlayTimeCount) < currentPlayTime / voteCount) ||
        !(runtime::MultiplyInt32Wrapping(voteCount, runtime::raw_atomic::LoadI32Relaxed(&m_nPlayTimeCount)) <
            currentPlayTime)) {
        return;
    }

    const std::int32_t playTimeCount = runtime::raw_atomic::AddI32(&m_nPlayTimeCount, 1);
    const char bonusTime = static_cast<char>(event->GetPlayTimeBaseValue() < playTimeCount ? 1 : 10);
    AddVoteCount(bonusTime);
    GetSocket()->Send("chccc", 0x62, SystemMessageId::RECOMMENDATIONS_GAINED, 1, 0x14, bonusTime);
    SendVoteSystemInfoPacket();
    runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);

    CLogFormatter formatter;
    formatter.WriteLog2(
        0x1f7e, this, nullptr, bonusTime, runtime::raw_atomic::LoadI32Relaxed(&m_nVoteCount), 0, 0, 0, 0, 0
    );
}

void User::CheckInitVoteSystem() {
    // Current L2Server 0x00b6daa4.
    L2_GUARD_FUNCTION();
    CEvent_VoteSystem* const event =
        static_cast<CEvent_VoteSystem*>(Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_VOTE_SYSTEM));
    if (event == nullptr) {
        return;
    }

    const _SYSTEMTIME current = runtime::crt::LocalSystemTimeNow<_SYSTEMTIME>();
    std::tm resetTime{};
    resetTime.tm_year = static_cast<int>(current.wYear) - 1900;
    resetTime.tm_mon = static_cast<int>(current.wMonth) - 1;
    resetTime.tm_mday = current.wDay;
    resetTime.tm_hour = 6;
    resetTime.tm_min = 30;
    resetTime.tm_sec = 0;

    _SYSTEMTIME previous{};
    std::memcpy(&previous, &m_tmLastInitTime, sizeof(previous));
    std::tm previousTime{};
    previousTime.tm_year = static_cast<int>(previous.wYear) - 1900;
    previousTime.tm_mon = static_cast<int>(previous.wMonth) - 1;
    previousTime.tm_mday = previous.wDay;
    previousTime.tm_hour = previous.wHour;
    previousTime.tm_min = previous.wMinute;
    previousTime.tm_sec = previous.wSecond;

    const std::int32_t resetTimestamp = runtime::crt::Mktime32(&resetTime);
    const std::int32_t previousTimestamp = runtime::crt::Mktime32(&previousTime);
    const std::int32_t now = runtime::crt::Time32Now();
    if (runtime::SubtractInt32Wrapping(now, resetTimestamp) < 0 ||
        runtime::SubtractInt32Wrapping(resetTimestamp, previousTimestamp) <= 0) {
        return;
    }

    SetVoteCount(20);
    runtime::raw_atomic::ExchangeI32(&m_nBonusTimeLimit, event->GetBonusTimeLimit());
    AddBonusCount(-5);
    runtime::raw_atomic::ExchangeI32(&m_nPlayTime, 0);
    runtime::raw_atomic::ExchangeI32(&m_nPlayTimeCount, 0);
    std::memcpy(&m_tmLastInitTime, &current, sizeof(m_tmLastInitTime));
    CIOObject::SetTimeStamp(&m_nVoteTimeStamp);
    SendVoteSystemInfoPacket();
    runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
}

