void User::UserStatusLog() {
    // Current L2Server 0x00b16118.
    L2_GUARD_FUNCTION();
    if (g_nUserStatusLogTime < 1) {
        return;
    }

    const int interval = runtime::Int32FromBits(static_cast<std::uint32_t>(g_nUserStatusLogTime) * 3U) / 2;
    if (m_nTickCount % interval != 0) {
        return;
    }

    int activity = 0;
    if (IsShopManaging() || IsShopOpen()) {
        activity = 1;
    } else if (m_pFishingController != nullptr &&
        (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing == true)) {
        activity = 2;
    }

    int competition = 1;
    if (IsNoSiegeRelation()) {
        if (IsInFortressSiege()) {
            competition = 2;
        } else if (IsInAgitWar(false)) {
            competition = 3;
        } else if (m_pWOlympiadUser->IsPlaying()) {
            competition = 4;
        } else if (m_PledgeGameUser.IsPlaying()) {
            competition = 5;
        } else {
            competition = 0;
        }
    }

    CLogFormatter formatter;
    formatter.WriteLog1(
        0x1fe4, this, nullptr, nullptr, nullptr, nullptr, activity, competition, m_bIsNCGuardBotDetected ? 1 : 0, 0, 0, 0, 0
    );
}

