CoupleActionErrorType User::CheckCoupleActionStartCondition(User* user) {
    L2_GUARD_FUNCTION();

    if (user->m_data->m_StopMode == STP_STORE || user->m_data->m_nPrivateStoreType != 0) {
        return CAET_IN_STORE_MODE;
    }
    if (user->m_pFishingController->m_FishingState != FISHINGS_NONE || user->m_pFishingController->m_bIsAutoFishing) {
        return CAET_FISHING;
    }
    if (user->m_data->m_bIsInCombatMode) {
        return CAET_IN_COMBAT_MODE;
    }
    if (user->m_bEinhasadeTransformed || user->m_data->m_nKarma < 0 || user->m_data->m_cIsGuilty > 0 ||
        user->m_bIsInitiativeViolet) {
        return CAET_CHAO_VIOLET;
    }
    if (user->m_nCoupleOption != 0) {
        return CAET_IN_COUPLE_ACTION;
    }
    if (user->m_pWOlympiadUser->IsPlaying()) {
        return CAET_OLYMPIAD_REGISTERED;
    }
    if (user->m_PledgeGameUser.IsPlaying()) {
        return CAET_IN_COMBAT_MODE;
    }
    if (user->IsInAgitWar(false)) {
        return CAET_IN_AGIT_WAR;
    }
    if (!user->IsNoSiegeRelation()) {
        return CAET_IN_CASTLE_WAR;
    }
    if (user->IsInVehicle() || user->IsInAirShip() || user->IsInShuttle() || user->IsRiding()) {
        return CAET_ON_VEHICLE;
    }
    if (user->IsTransformed(TransformType::Max) != nullptr) {
        return CAET_TRANSFORMED;
    }
    if (!user->IsAlive()) {
        return CAET_ALIVE;
    }
    if (!user->m_data->m_bIsActive) {
        return CAET_TELEPORT;
    }
    if (g_ActionTable[user->GetController()->GetCurrentActionType()][ACT_COUPLE] == 0) {
        return CAET_IN_CASTING;
    }
    if (user->m_data->m_bIsFakeDeath) {
        return CAET_FAKE_DEATH;
    }
    if (user->m_bFlyMoving) {
        return CAET_FLYMOVING;
    }
    CParty* const party = user->GetParty();
    if (party != nullptr && party->IsLootingTypeModifyInProgress()) {
        return CAET_IN_MODIFYING_PARTY_LOOTING;
    }
    return CAET_SUCCESS;
}

DuelStartErrorType User::CheckDuelStartCondition(bool partyDuel) {
    // Current L2Server 0x00b1f130.
    L2_GUARD_FUNCTION();

    if (m_data->m_StopMode == STP_STORE || m_data->m_nPrivateStoreType != 0) {
        return DSET_IN_STORE_MODE;
    }
    if (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing) {
        return DSET_FISHING;
    }
    if (m_data->GetHP() < m_data->m_dBaseHP * 0.5 || m_data->GetMP() < m_data->m_dBaseMP * 0.5) {
        return DSET_NOT_ENOUGH_HP_MP;
    }
    if (m_AreaMod.m_bIsInPvPZone || m_AreaMod.m_bIsInBattleField) {
        return DSET_IN_BATTLE_ZONE;
    }
    if (!partyDuel) {
        const DuelStartErrorType areaResult = AreaBasedRule::DuelStart(this);
        if (areaResult != DSET_SUCCESS) {
            return areaResult;
        }
    }

    const FVector position = GetPos();
    if (CAreaDB::inst().FindArea(static_cast<int>(GetInZoneID()), position, AREAT_NO_RESTART, true) != nullptr) {
        return DSET_IN_NO_RESTART_ZONE;
    }
    if (m_data->m_bIsInCombatMode) {
        return DSET_IN_COMBAT_MODE;
    }
    if (m_bEinhasadeTransformed || m_data->m_nKarma < 0 || m_data->m_cIsGuilty > 0 || m_bIsInitiativeViolet) {
        return DSET_CHAO_VIOLET;
    }
    if (IsInDuel()) {
        return DSET_IN_DUEL;
    }
    if (m_pWOlympiadUser->IsPlaying() || m_PledgeGameUser.IsPlaying() || m_PledgeGameUser.IsRegistered() ||
        g_PledgeGameSystem.IsRegisteredUser(this)) {
        return DSET_OLYMPIAD_REGISTERED;
    }
    if (IsInAgitWar(false)) {
        return DSET_IN_AGIT_WAR;
    }
    if (!IsNoSiegeRelation()) {
        return DSET_IN_CASTLE_WAR;
    }
    if (IsInVehicle() || IsInAirShip() || IsInShuttle() || IsRiding()) {
        return DSET_ON_VEHICLE;
    }
    if (IsTransformed(TransformType::Max) != nullptr) {
        return DSET_TRANSFORMED;
    }
    if (m_data->m_bIsFakeDeath) {
        return DSET_FAKE_DEATH;
    }
    if (!m_data->m_bIsActive) {
        return DSET_TELEPORT;
    }
    if (g_CaptchaSetting.enable && g_CaptchaSetting.reportCntSendCaptcha <= m_nBotReportPoint) {
        return DSET_ETC_ERROR;
    }
    return DSET_SUCCESS;
}

bool User::CheckDuelCancelCondition(int& reason, const bool partyDuel) {
    // Current L2Server 0x00b1f498.
    L2_GUARD_FUNCTION();

    if (!m_DuelUserInfo.IsInFightStatus()) {
        return true;
    }
    if (!m_DuelUserInfo.IsInIndividualDuel()) {
        // The current body performs this query for its side effect and
        // returns false regardless of the result.
        static_cast<void>(m_DuelUserInfo.IsInPartyDuel());
        return false;
    }

    const auto writeDuelCancelAudit = [this](User* const opponent, const int actorReason, const int opponentReason) {
        const int actorZ = runtime::Win64CvttDoubleToInt32(GetPos().z);
        const int actorY = runtime::Win64CvttDoubleToInt32(GetPos().y);
        const int actorX = runtime::Win64CvttDoubleToInt32(GetPos().x);
        const char16_t* const opponentTargetName = opponent->GetName();
        const char16_t* const actorName = GetName();
        const std::uint32_t opponentTargetAccountId = opponent->GetAccountID();
        const std::uint32_t opponentTargetDbId = opponent->GetDBID();
        const std::uint32_t actorAccountId = GetAccountID();
        const std::uint32_t actorDbId = GetDBID();
        std::array<wchar_t, 16> actorAccountStorage{};
        std::array<wchar_t, 16> opponentAccountStorage{};
        // Log.AddT(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        //     L"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
        //     0x377,
        //     actorDbId,
        //     actorAccountId,
        //     opponentTargetDbId,
        //     opponentTargetAccountId,
        //     actorX,
        //     actorY,
        //     actorZ,
        //     0,
        //     actorReason,
        //     actorName,
        //     PrivateStoreAccountName(
        //         m_sAccountName,
        //         actorAccountStorage),
        //     opponentTargetName,
        //     PrivateStoreAccountName(
        //         opponent->m_sAccountName,
        //         opponentAccountStorage))
        Log.AddT(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
            u"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
            0x377, actorDbId, actorAccountId, opponentTargetDbId, opponentTargetAccountId, actorX, actorY, actorZ, 0,
            actorReason, actorName, PrivateStoreAccountName(m_sAccountName, actorAccountStorage), opponentTargetName,
            PrivateStoreAccountName(opponent->m_sAccountName, opponentAccountStorage)
        );

        const int opponentZ = runtime::Win64CvttDoubleToInt32(opponent->GetPos().z);
        const int opponentY = runtime::Win64CvttDoubleToInt32(opponent->GetPos().y);
        const int opponentX = runtime::Win64CvttDoubleToInt32(opponent->GetPos().x);
        const char16_t* const actorTargetName = GetName();
        const char16_t* const opponentActorName = opponent->GetName();
        const std::uint32_t actorTargetAccountId = GetAccountID();
        const std::uint32_t actorTargetDbId = GetDBID();
        const std::uint32_t opponentActorAccountId = opponent->GetAccountID();
        const std::uint32_t opponentActorDbId = opponent->GetDBID();
        std::array<wchar_t, 16> opponentActorAccountStorage{};
        std::array<wchar_t, 16> actorTargetAccountStorage{};
        // Log.AddT(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        //     L"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
        //     0x377,
        //     opponentActorDbId,
        //     opponentActorAccountId,
        //     actorTargetDbId,
        //     actorTargetAccountId,
        //     opponentX,
        //     opponentY,
        //     opponentZ,
        //     0,
        //     opponentReason,
        //     opponentActorName,
        //     PrivateStoreAccountName(
        //         opponent->m_sAccountName,
        //         opponentActorAccountStorage),
        //     actorTargetName,
        //     PrivateStoreAccountName(
        //         m_sAccountName,
        //         actorTargetAccountStorage))
        Log.AddT(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
            u"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
            0x377, opponentActorDbId, opponentActorAccountId, actorTargetDbId, actorTargetAccountId, opponentX, opponentY,
            opponentZ, 0, opponentReason, opponentActorName,
            PrivateStoreAccountName(opponent->m_sAccountName, opponentActorAccountStorage), actorTargetName,
            PrivateStoreAccountName(m_sAccountName, actorTargetAccountStorage)
        );
    };

    if (!m_AreaMod.m_bIsInPvPZone && !m_AreaMod.m_bIsInBattleField) {
        if (!AreaBasedRule::PetKilledByPC(this)) {
            const FVector ssqPosition = GetPos();
            const std::uint32_t ssqInZoneId = GetInZoneID();
            if (CAreaDB::inst().FindArea(static_cast<int>(ssqInZoneId), ssqPosition, AREAT_SSQ, true) == nullptr) {
                const FVector waterPosition = GetPos();
                const std::uint32_t waterInZoneId = GetInZoneID();
                if (CAreaDB::inst().FindArea(static_cast<int>(waterInZoneId), waterPosition, AREAT_WATER, true) == nullptr) {
                    const FVector noRestartPosition = GetPos();
                    const std::uint32_t noRestartInZoneId = GetInZoneID();
                    if (CAreaDB::inst().FindArea(
                            static_cast<int>(noRestartInZoneId), noRestartPosition, AREAT_NO_RESTART, true
                        ) == nullptr) {
                        if (m_bEinhasadeTransformed || m_data->m_nKarma < 0 || m_data->m_cIsGuilty > 0 ||
                            m_bIsInitiativeViolet) {
                            reason |= 7;
                            User* const opponent = m_DuelUserInfo.GetIndividualDuelEnemy();
                            if (opponent != nullptr) {
                                writeDuelCancelAudit(opponent, 6, 0);
                            }
                            return true;
                        }

                        if (partyDuel) {
                            User* const opponent = m_DuelUserInfo.GetIndividualDuelEnemy();
                            if (opponent != nullptr) {
                                const FVector opponentPosition = opponent->GetPos();
                                const FVector actorPosition = GetPos();
                                const double distanceSquared =
                                    (actorPosition.x - opponentPosition.x) * (actorPosition.x - opponentPosition.x) +
                                    (actorPosition.y - opponentPosition.y) * (actorPosition.y - opponentPosition.y);
                                if (distanceSquared > 4000000.0) {
                                    reason = 0;
                                    User* const logOpponent = m_DuelUserInfo.GetIndividualDuelEnemy();
                                    if (logOpponent != nullptr) {
                                        writeDuelCancelAudit(logOpponent, 5, 5);
                                    }
                                    return true;
                                }
                            }
                        }
                        return false;
                    }
                }
            }
        }

        reason |= 7;
        User* const opponent = m_DuelUserInfo.GetIndividualDuelEnemy();
        if (opponent != nullptr) {
            writeDuelCancelAudit(opponent, 4, 0);
        }
        return true;
    }

    reason |= 7;
    User* const opponent = m_DuelUserInfo.GetIndividualDuelEnemy();
    if (opponent != nullptr) {
        writeDuelCancelAudit(opponent, 4, 0);
    }
    return true;
}

bool User::OnCoupleActionAskStart(int actionId, User* user) {
    L2_GUARD_FUNCTION();

    CUserSocket* const socket = GetSocket();
    if (user == nullptr || !user->IsPC()) {
        socket->SendSystemMessage(SystemMessageId::SELECT_TARGET);
        return false;
    }

    CoupleActionErrorType error = CheckCoupleActionStartCondition(this);
    if (error != CAET_SUCCESS) {
        socket->SendSystemMessage_Char(error, GetName());
        return false;
    }

    error = CheckCoupleActionStartCondition(user);
    if (error != CAET_SUCCESS) {
        socket->SendSystemMessage_Char(error, user->GetName2(this));
        return false;
    }

    const double distanceSquared = GetPos().DistCube(user->GetPos());
    if (distanceSquared > 15000.0 || distanceSquared < 200.0) {
        socket->Send(
            "chccS", 0x62, SystemMessageId::REQUEST_FAILED_TARGET_POSITION_REQUIREMENTS_NOT_MET, 1, 0x0c,
            user->CastUser()->GetName2(this)
        );
        return false;
    }

    if (CReplyChecker::IsUserWaitingReply(this) || user->GetTrade() != nullptr) {
        socket->SendSystemMessage(SystemMessageId::WAITING_FOR_ANOTHER_OPERATION_REPLY);
        return false;
    }

    if (!CReplyChecker::AttachReplyChecker(0x0c, this, user, 0x3c)) {
        socket->Send("chccS", 0x62, SystemMessageId::INVITED_CHARACTER_BUSY, 1, 0x0c, user->CastUser()->GetName2(this));
        return false;
    }

    m_bAskCoupleAction = true;
    user->m_bAskCoupleAction = true;
    user->GetSocket()->Send("chdd", 0xfe, 0xbc, actionId, GetServerId());
    socket->SendSystemMessage_Char(SystemMessageId::COUPLE_ACTION_REQUEST_SENT, user->GetName());
    return false;
}

void User::SocialAction(int actionId, int distance, bool) {
    L2_GUARD_FUNCTION();

    if (!IsAlive() || m_data->m_bGMInvisible || m_data->m_StopMode != STP_STAND) {
        return;
    }

    if (m_pFishingController->m_FishingState != FISHINGS_NONE) {
        SendSystemMessage(SystemMessageId::CANNOT_PERFORM_OTHER_ACTIONS_WHILE_FISHING);
        return;
    }
    if (m_bFlyMoving) {
        SendSystemMessage(SystemMessageId::CANNOT_ACT_WHILE_USING_SAYUNE);
        return;
    }

    int parameter = 0;
    if (actionId == 0x13) {
        parameter = !m_IsSheathingWeapon;
        m_data->m_NeedUpdatePacketBitSet.SetBoolValue_IfModifed(m_IsSheathingWeapon, parameter != 0, 0x5a);
    }
    BroadcastSocialAction(actionId, distance, parameter);
}

