void User::ReportCreateDate() {
    // Current L2Server 0x00b63f50.
    L2_GUARD_FUNCTION();

    _SYSTEMTIME current = runtime::crt::LocalSystemTimeNow<_SYSTEMTIME>();
    bool leapDayAdjusted = false;

    // The target initializes only year/month/day in this carrier. Its other
    // SYSTEMTIME lanes remain indeterminate and are copied below, but the
    // reached GetDayDiff owner observes only year/month/day.
    _SYSTEMTIME birthdayThisYear;
    birthdayThisYear.wYear = current.wYear;
    if (m_data->m_tCreateDate.wMonth == 2 && m_data->m_tCreateDate.wDay == 29 &&
        ((current.wYear & 3U) != 0U || current.wYear % 100U == 0U)) {
        birthdayThisYear.wMonth = m_data->m_tCreateDate.wMonth;
        birthdayThisYear.wDay = static_cast<std::uint16_t>(m_data->m_tCreateDate.wDay - 1U);
        leapDayAdjusted = true;
    } else {
        birthdayThisYear.wMonth = m_data->m_tCreateDate.wMonth;
        birthdayThisYear.wDay = m_data->m_tCreateDate.wDay;
    }

    _SYSTEMTIME previousBirthday;
    std::memcpy(&previousBirthday, &birthdayThisYear, sizeof(previousBirthday));
    if (current.wMonth < birthdayThisYear.wMonth ||
        (current.wMonth == birthdayThisYear.wMonth && current.wDay < birthdayThisYear.wDay)) {
        previousBirthday.wYear = static_cast<std::uint16_t>(current.wYear - 1U);
    }

    int daysUntilBirthday = GetDayDiff(&birthdayThisYear, &current);
    if (daysUntilBirthday < 0) {
        daysUntilBirthday += 365;
    }
    const int daysSinceCreation = GetDayDiff(&current, &m_data->m_tCreateDate);
    const std::uint32_t daysSinceBirthday = static_cast<std::uint32_t>(GetDayDiff(&current, &previousBirthday));
    if (daysSinceBirthday < 15U && daysSinceCreation > 364) {
        if (CanGetBirthdayGift(&current)) {
            CelebrateBirthday(static_cast<int>(daysSinceBirthday), leapDayAdjusted);
        }
    } else if (static_cast<std::uint32_t>(daysUntilBirthday) - 1U < 7U) {
        if (leapDayAdjusted) {
            GetSocket()->SendSystemMessage(SystemMessageId::LEAP_DAY_BIRTHDAY_GIFT_DELIVERED_ON_FEBRUARY_28);
        }
        GetSocket()->SendSystemMessage_d(SystemMessageId::BIRTHDAY_DAYS_REMAINING_GIFT_NOTICE, daysUntilBirthday);
        m_nGiftDayIn7Days = birthdayThisYear.wDay;
    }
}

void User::CelebrateBirthday(int daysSinceBirthday, bool leapDayAdjusted) {
    // Current L2Server 0x00b60618.
    L2_GUARD_FUNCTION();

    CFHTML::StrStrMapType parameters;
    const std::u16string title = CFHTML::MakeHTMLFromStrMap(u"g_birthday_message_01.htm", parameters, 0);
    const std::u16string contents = CFHTML::MakeHTMLFromStrMap(u"g_birthday_message_00.htm", parameters, 0);

    if (daysSinceBirthday == 0) {
        GetSocket()->SendSystemMessage(SystemMessageId::BIRTHDAY_GIFT_FROM_ALEGRIA);
        g_ptlUserMap->BroadcastToNeighbor(*this, 0x80000, GetPos(), "chd", 0xfe, 0x90, static_cast<int>(Id()));
        if (leapDayAdjusted) {
            GetSocket()->SendSystemMessage(SystemMessageId::LEAP_DAY_BIRTHDAY_GIFT_DELIVERED_ON_FEBRUARY_28);
        }
    }

    db.RequestWritePostBirth(
        static_cast<std::int32_t>(GetDBID()), title.c_str(), contents.c_str(), g_nBirthdayItemClassID, 3, 1, 0, 0
    );
    m_nGiftDayIn7Days = 0;
}

bool User::CheckCharacterName(const char16_t* const name, const int countryCode, const bool extended) {
    // Current L2Server 0x00b12024.
    L2_GUARD_FUNCTION();
    if (name == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"invalid charname CheckCharacerName NULL")
        L2_LOG_ERROR(Log, u"[character name] Name pointer is null; validation failed.");
        return false;
    }

    const std::u16string_view targetName(name);
    int remaining = static_cast<int>(targetName.size());
    int maximum = extended ? 0x18 : 0x10;
    if (countryCode == 5) {
        maximum = 0x18;
    }
    if (remaining < 1 || remaining > maximum) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[CheckCharacterName] Invalid Length : length=%d",
        //     remaining)
        L2_LOG_ERROR(
            Log, u"[character name] Name '%s' has %d UTF-16 code units; allowed range is 1 through %d for country %d.", name,
            remaining, maximum, countryCode
        );
        return false;
    }

    int count = 0;
    const char16_t* cursor = targetName.data();
    while (remaining > 0) {
        --remaining;
        if (count > maximum) {
            return false;
        }

        const std::uint16_t codeUnit = static_cast<std::uint16_t>(*cursor++);
        const bool ascii = (codeUnit >= 0x0030U && codeUnit <= 0x0039U) || (codeUnit >= 0x0061U && codeUnit <= 0x007aU) ||
            (codeUnit >= 0x0041U && codeUnit <= 0x005aU);
        if (ascii) {
            ++count;
            continue;
        }

        if (g_nFontCheck > 0 && !g_FontCheck.CheckCode(codeUnit)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[CheckCharacterName] Gly FontCheck Failed : "
            //     L"char=%c(%d), name=[%s]",
            //     static_cast<int>(codeUnit),
            //     static_cast<int>(codeUnit),
            //     name)
            L2_LOG_ERROR(
                Log, u"[character name] Font validation rejected code unit '%c' (%d) in name '%s'.",
                static_cast<int>(codeUnit), static_cast<int>(codeUnit), name
            );
            return false;
        }

        bool accepted = false;
        int weight = 2;
        if (countryCode == 0) {
            accepted = codeUnit >= 0xac00U && codeUnit <= 0xd7a3U;
        } else if (countryCode >= 2 && countryCode <= 4) {
            accepted = (codeUnit >= 0x3041U && codeUnit <= 0x3096U) || (codeUnit >= 0x30a1U && codeUnit <= 0x30fcU) ||
                (codeUnit >= 0x4e00U && codeUnit <= 0x9fa5U);
        } else if (countryCode == 5) {
            accepted = (codeUnit >= 0x0e01U && codeUnit <= 0x0e3aU) || (codeUnit >= 0x0e3fU && codeUnit <= 0x0e5bU);
        } else if (countryCode == 8) {
            accepted = codeUnit >= 0x0410U && codeUnit <= 0x044fU;
            weight = 1;
        } else if (countryCode == 10 || countryCode == 11 || countryCode == 13) {
            accepted = codeUnit >= 0x0100U && codeUnit <= 0x017fU;
            weight = 1;
        } else if (countryCode == 12) {
            constexpr std::uint16_t kPolishCharacters[] = {
                0x0104U,
                0x0106U,
                0x0118U,
                0x0141U,
                0x0143U,
                0x00d3U,
                0x015aU,
                0x0179U,
                0x017bU,
                0x0105U,
                0x0107U,
                0x0119U,
                0x0142U,
                0x0144U,
                0x00f3U,
                0x015bU,
                0x017aU,
                0x017cU,
            };
            accepted = std::find(std::begin(kPolishCharacters), std::end(kPolishCharacters), codeUnit) !=
                std::end(kPolishCharacters);
            weight = 1;
        }

        if (!accepted) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[CheckCharacterName] Invalid CodeSet[country=%d] : "
            //     L"char=%c(%d), name=[%s]",
            //     countryCode,
            //     static_cast<int>(codeUnit),
            //     static_cast<int>(codeUnit),
            //     name)
            L2_LOG_ERROR(
                Log, u"[character name] Country %d does not allow code unit '%c' (%d) in name '%s'.", countryCode,
                static_cast<int>(codeUnit), static_cast<int>(codeUnit), name
            );
            return false;
        }
        count += weight;
    }

    if (count <= maximum) {
        return true;
    }
    // Log.Add(
    //     LOG_ERROR,
    //     L"[CheckCharacterName] Invalid Length : length=%d, count=%d",
    //     remaining - 1,
    //     count)
    L2_LOG_ERROR(
        Log, u"[character name] Name '%s' has weighted length %d after validation; maximum is %d for country %d.", name,
        count, maximum, countryCode
    );
    return false;
}

bool User::CheckCharacterNameDual(const char16_t* name, int, bool) {
    L2_GUARD_FUNCTION();
    const int length = static_cast<int>(std::char_traits<char16_t>::length(name));
    bool hasCyrillic = false;
    bool hasLatin = false;
    for (int index = 0; index < length; ++index) {
        const std::uint16_t codeUnit = static_cast<std::uint16_t>(name[index]);
        if ((codeUnit >= 0x0061U && codeUnit <= 0x007aU) || (codeUnit >= 0x0041U && codeUnit <= 0x005aU)) {
            hasLatin = true;
        } else if (codeUnit >= 0x0410U && codeUnit <= 0x044fU) {
            hasCyrillic = true;
        }
        if (hasCyrillic && hasLatin) {
            return false;
        }
    }
    return true;
}

