void User::LoadQuestProgressFromMemo() {
    // Current L2Server.exe 0x00b42834, original owner User.cpp.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(m_questListLock);
        for (MemoStruct& memo : m_data->m_Memo) {
            if (memo.nQuestID == 0) {
                continue;
            }

            UserQuest* const quest = Singleton<QuestManager>::inst().GetQuest(memo.nQuestID);
            if (quest == nullptr) {
                continue;
            }

            if (memo.nJournal < 0) {
                std::uint32_t journalBits = static_cast<std::uint32_t>(memo.nJournal) ^ UINT32_C(0x80000000);
                int bit = 0;
                do {
                    if (journalBits == 1) {
                        break;
                    }
                    ++bit;
                    journalBits = static_cast<std::uint32_t>(static_cast<std::int32_t>(journalBits) >> 1);
                } while (bit < 0x1e);
                memo.nJournal = bit + 1;
            }

            m_acceptedQuest.emplace(memo.nQuestID, UserQuestProgress(quest, memo.nState4, memo.nJournal, 1, 0));
        }
    }
}

