std::uint32_t User::GetPledgeOutTime() {
    const std::uint32_t withdrawTime = static_cast<std::uint32_t>(m_nPledgeWithdrawTime);
    const std::uint32_t oustedTime = static_cast<std::uint32_t>(m_nPledgeOustedTime);
    return withdrawTime <= oustedTime ? oustedTime : withdrawTime;
}

bool User::CanJoinPledge() {
    L2_GUARD_FUNCTION();
    if (m_nPledgeOustedTime == 0 && m_nPledgeWithdrawTime == 0) {
        return true;
    }

    const std::int32_t now = runtime::crt::Time32Now();
    if (runtime::SubtractInt32Wrapping(now, m_nPledgeOustedTime) < BP::_PLEDGE_OUSTED_PENALTY_TIMEOUT) {
        return false;
    }
    return BP::_PLEDGE_WITHDRAW_PENALTY_TIMEOUT <= runtime::SubtractInt32Wrapping(now, m_nPledgeWithdrawTime);
}

bool User::CanCreatePledge() {
    L2_GUARD_FUNCTION();
    const std::int32_t dismissTime = m_nPledgeDismissTime;
    const std::int32_t now = runtime::crt::Time32Now();
    return BP::_PLEDGE_DISMISS_PENALTY_TIMEOUT <= runtime::SubtractInt32Wrapping(now, dismissTime);
}

