bool User::QueryEnemy(int relation) {
    L2_GUARD_FUNCTION();
    if ((relation & 0x40000) != 0) {
        return true;
    }
    if (m_EventMatchUser.m_byEventMatchTeamId != 0 || m_AreaMod.m_bIsInSSQZone) {
        return (relation & 0x20) == 0;
    }
    if ((relation & 1) != 0 && m_AreaMod.m_bIsInPvPZone) {
        return (relation & 0x200020) == 0;
    }
    if ((relation & 0x120) != 0) {
        return false;
    }
    if ((relation & 0x403000) != 0) {
        return true;
    }
    if ((relation & 0x280800) != 0) {
        return false;
    }
    return (relation & 7) != 0;
}

bool User::QueryRealEnemy(int relation) {
    L2_GUARD_FUNCTION();
    if ((relation & 0x80920) != 0) {
        return false;
    }
    return (relation & 0x103000) != 0;
}

