void User::ShowStriderHungryGauge() {
    L2_GUARD_FUNCTION();
    if (!IsRiding() || m_pRidingInfo->IsEventRiding()) {
        return;
    }

    const int consumeAmount = m_pRidingInfo->ConsumeAmount(m_data->m_bIsInCombatMode);
    int gaugeTotal = 3600000;
    if (consumeAmount != 0) {
        gaugeTotal = runtime::MultiplyInt32Wrapping(m_pRidingInfo->MaxMeal() / consumeAmount, 10000);
    }

    int gaugeCurrent = 1000000000;
    if (!m_pRidingInfo->IsMealEmpty()) {
        const int meal = m_pRidingInfo->Meal();
        const int maximumMeal = m_pRidingInfo->MaxMeal();
        gaugeCurrent = runtime::MultiplyInt32Wrapping(maximumMeal, gaugeTotal / meal);
    }

    GetSocket()->Send(
        "cdddd", 0x6b, GetServerId(),
        // 3,
        GaugeType::FOOD, gaugeTotal, gaugeCurrent
    );
}

