void User::SendToDoListHtml(E_TODOLIST_TYPE type, const wchar_t* const name) {
    // Current L2Server 0x00b4798c.
    L2_GUARD_FUNCTION();

    std::u16string fileName(u"None");
    const std::u16string targetName = WideToUtf16(name);
    g_HTMLCache.MakeToDoListHtmlFileName(fileName, type, targetName);

    const std::u16string htmlFileName = SanitizeUtf16(fileName);
    std::u16string html;
    if (g_HTMLCache.GetHTMLFile(htmlFileName.c_str(), html, m_data->m_CountryCode)) {
        GetSocket()->Send(
            "chcSS", 0xfe, 0x1ac, static_cast<int>(static_cast<std::int8_t>(type)), targetName.c_str(), html.c_str()
        );
    } else if (IsBuilder()) {
        SendSystemMessage(u"HTML", htmlFileName);
    }
}

bool User::OnRequestOneDayReceiveReward(const int databaseId) {
    // Current L2Server 0x00b3fdcc.
    L2_GUARD_FUNCTION();

    const auto position = m_DailyMissionByDBIDMap.find(databaseId);
    if (position == m_DailyMissionByDBIDMap.end() || position->second == nullptr) {
        SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_REWARDS_IN_CURRENT_STATE);
        return false;
    }

    ICDailyMission* const mission = position->second;
    {
        L2_GUARD(m_DailyMissionLock);
        const std::int32_t now = runtime::crt::Time32Now();
        if (mission->GetOneDayRewardState(now) == E_ONE_DAY_REWARD_STATE_TYPE_CAN) {
            mission->SetRewardComplete(now);
            int rewardItemCount = 0;
            if (g_ToDoListManager.OnSendReward(this, mission->m_DBID, mission->m_TimeRewarded, rewardItemCount)) {
                SendToDoList(E_TODOLIST_TYPE_DAILY_REWARD, false);
                db.RequestUpdateOneDayRewardInfo(this, 1, mission);

                wchar_t* const empty = const_cast<wchar_t*>(L"");
                CLogFormatter formatter;
                formatter.WriteLog1(
                    0x1fdd, this, nullptr, WideToUtf16(empty), WideToUtf16(empty), WideToUtf16(empty), mission->m_DBID,
                    mission->m_TimeRewarded, mission->m_UpdateCheckTime, mission->m_AccumulateCount, rewardItemCount, 0, 0
                );
            }
        } else {
            SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_REWARDS_IN_CURRENT_STATE);
        }
    }
    return false;
}

