bool User::SetOneDayRewardMapForDB(
    int databaseId,
    std::int32_t timeRewarded,
    std::int32_t updateCheckTime,
    int accumulateCount,
    int stateType,
    const SYSTEMTIME& createTime
) {
    L2_GUARD_FUNCTION();
    CSPointer<COneDayRewardData> reward = g_ToDoListManager.GetOneDayRewardData(databaseId);
    if (!reward) {
        return false;
    }
    if (m_DailyMissionByDBIDMap.find(databaseId) != m_DailyMissionByDBIDMap.end()) {
        return false;
    }

    using Factory = GenericFactory<ICDailyMission, E_DAILY_MISSION_TYPE, DailyMissionCreator>;
    const E_DAILY_MISSION_TYPE missionType = g_ToDoListManager.GetDailyMissionTypeByID(databaseId);
    ICDailyMission* const mission = Singleton<Factory>::inst().CreateObject(missionType);
    if (mission == nullptr) {
        return true;
    }

    mission->m_DailyMissionType = missionType;
    mission->Init(this, reward.get(), databaseId, timeRewarded, updateCheckTime, accumulateCount, stateType);
    mission->InitCreateData(createTime);

    auto* destination = &m_DailyMissionMap;
    if (!g_ToDoListManager.IsRepeatTypeByID(databaseId) && timeRewarded > 0) {
        const std::int32_t now = runtime::crt::Time32Now();
        const std::int32_t resetTime = g_ToDoListManager.GetResetTimeForOneDay(&now);
        if (timeRewarded < resetTime) {
            mission->m_StateType = E_ONE_DAY_REWARD_STATE_TYPE_INVALID;
            destination = &m_InvalidDailyMissionMap;
        } else {
            mission->m_StateType = E_ONE_DAY_REWARD_STATE_TYPE_COMPLETE;
            destination = &m_CompleteDailyMissionMap;
        }
    }
    destination->emplace(missionType, mission);
    m_DailyMissionByDBIDMap.emplace(databaseId, mission);
    return true;
}

int User::_MakeSummonIndex() {
    L2_GUARD_FUNCTION();

    bool used[10]{};
    for (const auto& summon : m_mapSummonSID) {
        const int index = summon.first;
        if (index > 9) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"summon index invalid %d!",
            //     index)
            L2_LOG_ERROR(Log, u"[summons] Summon index %d is invalid; lookup rejected.", index);
        }
        used[index] = true;
    }

    for (int index = 0; index < 10; ++index) {
        if (!used[index]) {
            return index;
        }
    }
    return -1;
}

int User::_GetSummonIndex(int summonServerId) {
    L2_GUARD_FUNCTION();
    for (const auto& summon : m_mapSummonSID) {
        if (static_cast<int>(summon.second) == summonServerId) {
            return summon.first;
        }
    }
    return -1;
}

