void User::ValidateAllOnSIM() {
    L2_GUARD_FUNCTION();
    CCreature::ValidateAllOnSIM();

    if (!HaveSummon() && !HavePet()) {
        return;
    }

    // Current 0x00b42294 has the per-entry "in_code" frame below, but no
    // outer FOR_ALL_SUMMON_PET_IN_SUMMON_LIST frame.
    std::vector<CSummon*> summons;
    GetAllSummonAndPet(summons);
    for (CSummon* summon : summons) {
        if (summon == nullptr) {
            continue;
        }

        GuardHelper inCode(L"in_code", CThreadManager::GetThreadID());
        if (summon->IsActive()) {
            summon->UpdateSummonByPassive();
        }
    }
}

void User::ValidateParameters(int parameter, bool force) {
    // Current L2Server 0x00b1d2a0, original owner User.cpp.
    L2_GUARD_FUNCTION();
    L2_GUARD(m_lockValidate);

    std::uint32_t flags = static_cast<std::uint32_t>(parameter);
    if ((flags & static_cast<std::uint32_t>(VB_MAX)) == 0) {
        if ((flags & static_cast<std::uint32_t>(VB_BASEDATA)) != 0) {
            ValidateBaseData();
        }
        if ((flags & static_cast<std::uint32_t>(VB_BASEATTR | VB_SKILLMOD)) != 0) {
            ValidateBaseAttributeData();
        }
        if ((flags & static_cast<std::uint32_t>(VB_LEVEL)) != 0) {
            flags |= ValidateLevel() ? static_cast<std::uint32_t>(VB_WEAPONARMOR | VB_HPMPCP | VB_SIM)
                                     : static_cast<std::uint32_t>(VB_HPMPCP);
        }
        if ((flags & static_cast<std::uint32_t>(VB_ENV)) != 0) {
            ValidateOrgSpeed();
        }
        if ((flags & static_cast<std::uint32_t>(VB_MOTION)) != 0) {
            flags |= static_cast<std::uint32_t>(VB_HPMPCP | VB_SPEED);
        }
        if ((flags & static_cast<std::uint32_t>(VB_WEAPONARMOR)) != 0) {
            ValidateAllOnWeaponArmors();
        }
        if ((flags & static_cast<std::uint32_t>(VB_ITEMSKILL)) != 0 && ValidateItemSkills()) {
            flags |= static_cast<std::uint32_t>(VB_SKILLLIST | VB_SKILLMOD | VB_SIM);
        }
        if ((flags & static_cast<std::uint32_t>(VB_SKILLLIST)) != 0) {
            ValidateSkillList();
        }
        if ((flags & static_cast<std::uint32_t>(VB_SKILLMOD)) != 0) {
            ValidateSkillMod();
        }
        if ((flags & static_cast<std::uint32_t>(VB_HPMPCP)) != 0) {
            ValidateHPMPCP(force);
        }
        if ((flags & static_cast<std::uint32_t>(VB_SIM)) != 0) {
            ValidateAllOnSIM();
        }
        if ((flags & static_cast<std::uint32_t>(VB_SPEED)) != 0) {
            ValidateOrgSpeed();
        }
    } else {
        ValidateBaseData();
        ValidateBaseAttributeData();
        ValidateLevel();
        ValidateOrgSpeed();
        ValidateAllOnWeaponArmors();
        ValidateItemSkills();
        ValidateSkillList();
        ValidateSkillMod();
        ValidateHPMPCP(force);
        ValidateAllOnSIM();
        ValidateOrgSpeed();
    }

    if ((flags & static_cast<std::uint32_t>(VB_LEVELUP)) != 0) {
        ValidateLevelUP();
    }
    ParamChanged(PCB_USER);
}

void User::OnSummonAbnormalState(int summonClassId, int summonDatabaseId, const unsigned char* packet) {
    L2_GUARD_FUNCTION();
    const unsigned char* cursor = packet;
    FOR_ALL_SUMMON_PET_IN_SUMMON_LIST(this, summon, {
        const int classId = summon->m_data->m_nClassID;
        const int databaseId = summon->IsPet() ? static_cast<int>(summon->GetDBID()) : summon->GetIndexForMaster();
        if (databaseId != summonDatabaseId || classId != summonClassId) {
            continue;
        }

        int abnormalCount = 0;
        cursor = ::Disassemble(cursor, "d", &abnormalCount);
        summon->LoadAbnormalData(static_cast<unsigned long>(abnormalCount), cursor);
        summon->ValidateParameters(VB_SKILLMOD, false);
        CopyUserBuffToNPC(summon);
        if (!IsInvisibleBySkill()) {
            if (!IsVisible()) {
                summon->SetVisible(false);
            }
        } else {
            summon->SetVisibleBySkill(false, true);
        }
    });
}

