bool User::CanResetTimeStamp(PledgeBonus::TimeStamp timeStamp, L2ServerLong currentTime) {
    L2_GUARD_FUNCTION();

    const std::uint32_t adjustedBits = static_cast<std::uint32_t>(currentTime) - 0x5b68U;
    const std::int32_t adjustedTime = runtime::Int32FromBits(adjustedBits);

    std::int32_t savedTime = tPledgeBonusTimeStamp[static_cast<std::size_t>(timeStamp)];
    if (savedTime == 0) {
        return true;
    }
    if (timeStamp == PledgeBonus::ACCESS_MISSION_COMPLETE && savedTime < 0) {
        savedTime = runtime::Int32FromBits(0U - static_cast<std::uint32_t>(savedTime));
    }

    const std::tm* const localTime = runtime::crt::LocalTime32(adjustedTime);
    std::uint32_t deltaBits = 0x186U;
    deltaBits -= static_cast<std::uint32_t>(localTime->tm_hour) * 0x3cU;
    deltaBits -= static_cast<std::uint32_t>(localTime->tm_min);
    deltaBits *= 0x3cU;
    deltaBits -= static_cast<std::uint32_t>(localTime->tm_sec);
    deltaBits -= static_cast<std::uint32_t>(savedTime);
    deltaBits += adjustedBits;
    return runtime::Int32FromBits(deltaBits) >= 0;
}

PledgeBonus::Activity User::GetPledgeActivity() {
    L2_GUARD_FUNCTION();

    const std::int32_t savedTime = tPledgeBonusTimeStamp[PledgeBonus::ACCESS_MISSION_COMPLETE];
    if (savedTime >= 0) {
        return PledgeBonus::NOTHING;
    }

    const std::int32_t currentTime = runtime::crt::Time32Now();
    const std::int32_t newMemberUntil = runtime::Int32FromBits(0U - static_cast<std::uint32_t>(savedTime));
    if (currentTime < newMemberUntil) {
        return PledgeBonus::NEW_MEMBER;
    }

    const std::uint32_t adjustedBits = static_cast<std::uint32_t>(currentTime) - 0x5b68U;
    const std::tm* const localTime = runtime::crt::LocalTime32(runtime::Int32FromBits(adjustedBits));
    std::uint32_t activityBits = 0x186U;
    activityBits -= static_cast<std::uint32_t>(localTime->tm_hour) * 0x3cU;
    activityBits -= static_cast<std::uint32_t>(localTime->tm_min);
    activityBits *= 0x3cU;
    activityBits -= static_cast<std::uint32_t>(localTime->tm_sec);
    activityBits += static_cast<std::uint32_t>(savedTime);
    activityBits += adjustedBits;
    return runtime::Int32FromBits(activityBits) < 0 ? PledgeBonus::MISSION_COMPLETE : PledgeBonus::NOTHING;
}

void User::SendGIPCharacterInfo(const bool force) {
    // Current L2Server 0x00b20e1c.
    L2_GUARD_FUNCTION();
    const std::int64_t now = static_cast<std::int64_t>(std::time(nullptr));
    GIP._Add(
        L"CMD_CharacterInfoData(%d, %d, %d, '%s', %d, %d, %d, %d, %d, %d, %d, %d", GetAccountID(), g_nWorldId, GetDBID(),
        Utf16ToWide(GetName()).c_str(), static_cast<int>(m_data->m_nClass), static_cast<int>(m_data->m_Race),
        m_data->m_nLevel, static_cast<int>(m_data->m_Sex), m_data->m_nPledgeID, m_data->m_nPledgeType, force ? 1 : 0, now
    );
}

