void User::SendLogout() {
    // Current L2Server 0x00b28c24.
    L2_GUARD_FUNCTION();

    db.SendLogout(this);
    CUserSocket* const socket = GetSocket();
    if (!m_bStopTime) {
        socket->ShowRemainTime();
    } else {
        socket->SetEndSitTimeStart();
        m_bStopTime = false;
    }

    int characterUseTime = socket->ClearSocketCharacterUseTime();
    _SYSTEMTIME localTime = runtime::crt::LocalSystemTimeNow<_SYSTEMTIME>();
    if (socket->CheckWeekChanged(&localTime)) {
        socket->ResetRelaxTime(&localTime);
        characterUseTime = socket->ClearSocketCharacterUseTime();
    }
    if (g_nPlayTimeLimit != 0 && socket->m_bIsNew) {
        characterUseTime = -1;
    }

    db.ReqLogoutCharacter(this, characterUseTime, &localTime);
    SendGIPCharacterInfo(false);
}

bool User::OnRequestKalieToken() {
    // Current L2Server 0x00b503ac.
    L2_GUARD_FUNCTION();
    if (IsTokenProcressing()) {
        return false;
    }
    if (m_nKalieToken < 1) {
        GetSocket()->SendSystemMessage(SystemMessageId::NO_LUCKY_COINS_AVAILABLE);
        EndTokenProcress();
        return false;
    }
    if (!m_inv.CheckAddable(0x8d10, static_cast<std::int64_t>(m_nKalieToken), false)) {
        SendSystemMessage(SystemMessageId::INVENTORY_SLOTS_FULL);
        return false;
    }

    KalieEvent& event = KalieEvent::Inst();
    L2_GUARD(event.m_Lock);
    event.m_UserQueue.push(static_cast<int>(Id()));
    return false;
}

// User::OnRequestBalthusToken@0x00b64394.
bool User::OnRequestBalthusToken() {
    L2_GUARD_FUNCTION();
    if (runtime::raw_atomic::ExchangeI32(&m_nBalthusTokenRewarding, 1) != 0) {
        return false;
    }

    const int tokenCount = m_nBalthusTokenCount;
    if (tokenCount < 1) {
        SendSystemMessage(static_cast<unsigned int>(SystemMessageId::NO_LUCKY_COINS_AVAILABLE));
        runtime::raw_atomic::ExchangeI32(&m_nBalthusTokenRewarding, 0);
        return false;
    }
    if (!m_inv.CheckAddable(0xc277, static_cast<std::int64_t>(tokenCount), false)) {
        SendSystemMessage(static_cast<unsigned int>(SystemMessageId::INVENTORY_SLOTS_FULL));
        runtime::raw_atomic::ExchangeI32(&m_nBalthusTokenRewarding, 0);
        return false;
    }

    BalthusEvent::inst().PushTokenWaitingQueue(GetServerId());
    return false;
}

void User::SetKalieToken(std::int32_t token) {
    L2_GUARD_FUNCTION();
    runtime::raw_atomic::ExchangeI32(&m_nKalieToken, token);
}

int User::GetKalieToken() {
    L2_GUARD_FUNCTION();
    return runtime::raw_atomic::LoadI32Relaxed(&m_nKalieToken);
}

