CrystalType User::CalcCrystalEquipPenalty() {
    L2_GUARD_FUNCTION();
    const int originalLevel = m_data->m_nLevel;
    int level = runtime::AddInt32Wrapping(originalLevel, static_cast<int>(m_dCrystalGradeBonus));
    if (level < originalLevel) {
        level = originalLevel;
    }

    if (level < 20) {
        return CRT_NONE;
    }
    if (level < 40) {
        return CRT_D;
    }
    if (level < 52) {
        return CRT_C;
    }
    if (level < 61) {
        return CRT_B;
    }
    if (level < 76) {
        return CRT_A;
    }
    if (level < 80) {
        return CRT_S;
    }
    if (level < 85) {
        return CRT_S84;
    }
    if (level < 95) {
        return CRT_R;
    }
    return level > 98 ? CRT_R99 : CRT_R95;
}

