bool User::IsPremiumUser() {
    L2_GUARD_FUNCTION();
    if (GetPremiumLevel() >= 1 || m_data->m_bPCCafeUser) {
        return true;
    }
    return g_nPremiumUserLevel != -1 && Level() >= g_nPremiumUserLevel;
}

bool User::IsInPremiumGroup() {
    // Current L2Server 0x00b58ccc, original owner User.cpp.
    L2_GUARD_FUNCTION();
    std::vector<User*> users;
    bool premium = GetPremiumLevel() > 0;
    if (!premium) {
        if (GetMPCC() == nullptr) {
            if (GetParty() == nullptr) {
                users.push_back(this);
            } else {
                GetParty()->GetAllMember(users);
            }
        } else {
            GetMPCC()->GetAllMember(users);
        }
        for (User* const user : users) {
            if (user != nullptr) {
                premium = premium | (user->GetPremiumLevel() > 0);
            }
        }
    }
    return premium;
}

