void User::SendQuestList(CUserSocket* socket) {
    L2_GUARD_FUNCTION();

    std::array<char, 0x1e8> questPacket{};
    std::int16_t questCount = 0;
    int questPacketLength = 0;
    const auto appendMemo = [&](const MemoStruct& memo) {
        if (memo.nQuestID <= 0) {
            return;
        }
        if (std::getenv("L2_QUEST_TRACE") != nullptr && memo.nQuestID == 10320) {
            // std::fprintf(
            //     stderr,
            //     "[QUEST_TRACE] User::SendQuestList quest=%d "
            //     "journal=%d state=%d,%d,%d,%d changed=%d\n",
            //     memo.nQuestID,
            //     memo.nJournal,
            //     memo.nState,
            //     memo.nState2,
            //     memo.nState3,
            //     memo.nState4,
            //     memo.bChanged ? 1 : 0)
            // runtime::logging::WriteDirect(
            //     stderr, "l2server", runtime::logging::Level::Info,
            //     "[quest trace] Adding quest %d to the list: journal %d, state (%d, %d, %d, %d), changed: %s.",
            //     memo.nQuestID,
            //     memo.nJournal,
            //     memo.nState,
            //     memo.nState2,
            //     memo.nState3,
            //     memo.nState4,
            //     memo.bChanged ? "yes" : "no")
            L2_LOG_DIRECT(
                stderr, runtime::logging::Level::Info,
                "[quest trace] Adding quest %d to the list: journal %d, state (%d, %d, %d, %d), changed: %s.", memo.nQuestID,
                memo.nJournal, memo.nState, memo.nState2, memo.nState3, memo.nState4, memo.bChanged ? "yes" : "no"
            );
            // std::fflush(stderr), // WriteDirect flushes the complete record.
        }
        questPacketLength += ::Assemble(
            questPacket.data() + questPacketLength, static_cast<int>(questPacket.size()) - questPacketLength, "dd",
            memo.nQuestID, memo.nJournal
        );
        ++questCount;
    };
    for (const MemoStruct& memo : m_data->m_Memo) {
        appendMemo(memo);
    }
    for (const MemoStruct& memo : m_data->m_NRMemo) {
        appendMemo(memo);
    }

    if (std::getenv("L2_QUEST_TRACE") != nullptr) {
        // std::fprintf(
        //     stderr,
        //     "[QUEST_TRACE] User::SendQuestList count=%d bytes=%d\n",
        //     static_cast<int>(questCount),
        //     questPacketLength)
        // runtime::logging::WriteDirect(
        //     stderr, "l2server", runtime::logging::Level::Info,
        //     "[quest trace] Prepared quest-list records: count %d, encoded length %d bytes.",
        //     static_cast<int>(questCount),
        //     questPacketLength)
        L2_LOG_DIRECT(
            stderr, runtime::logging::Level::Info,
            "[quest trace] Prepared quest-list records: count %d, encoded length %d bytes.", static_cast<int>(questCount),
            questPacketLength
        );
        // std::fflush(stderr), // WriteDirect flushes the complete record.
    }

    if (socket == nullptr) {
        std::array<char, 0x100> oneTimeFlags{};
        m_data->GetOneTimeFlagAll(oneTimeFlags.data(), static_cast<int>(oneTimeFlags.size()));
        GetSocket()->Send(
            "chbb", 0x86, static_cast<int>(questCount), questPacketLength, questPacket.data(),
            static_cast<int>(oneTimeFlags.size()), oneTimeFlags.data()
        );
        return;
    }

    std::array<char, 0x640> questItemPacket{};
    std::int16_t questItemCount = 0;
    int questItemPacketLength = 0;
    int depth = 0;

    {
        L2_READ_GUARD(m_inv);
        CSharedItemData* itemData = m_inv.GetFirst();
        while (itemData != nullptr) {
            if (++depth > 0x192) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] User::SendQuestList depth over.",
                //     L"User.cpp",
                //     0x226e)
                L2_LOG_ERROR(
                    Log, u"[quest] Inventory traversal exceeded the quest-list depth limit; remaining entries were skipped."
                );
                return;
            }

            if (itemData->m_Type == IT_QUESTITEM) {
                CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(itemData->index);
                if (item) {
                    questItemPacketLength += ::Assemble(
                        questItemPacket.data() + questItemPacketLength,
                        static_cast<int>(questItemPacket.size()) - questItemPacketLength, "ddQd",
                        static_cast<int>(item->Id()), itemData->m_nClassID, itemData->m_nCount,
                        static_cast<int>(itemData->m_Slot)
                    );
                    ++questItemCount;
                }
            }
            itemData = itemData->Next();
        }
    }

    socket->Send(
        "cShbhb", 0x99, GetName(), static_cast<int>(questCount), questPacketLength, questPacket.data(),
        static_cast<int>(questItemCount), questItemPacketLength, questItemPacket.data()
    );
}

