void User::AddDropRateByRune(int runeType, int amount) {
    L2_GUARD_FUNCTION();
    int& value = m_SkillDurationMod.m_DropRateByRune[runeType];
    const int previous = value;
    value = runtime::AddInt32Wrapping(previous, amount);
    if (value > 500) {
        value = previous;
    }
    if (value <= 0) {
        value = 0;
    }
}

