void User::RequestInquiryGoodsInventory(bool premium) {
    L2_GUARD_FUNCTION();
    if (m_bDoingGoodsInventoryJob) {
        if (!g_GoodsInventory.m_bSendable || !g_GoodsInventory.m_bConnected) {
            GetSocket()->Send(
                "chd", 0xfe, 0x10e,
                // premium ? -4 : -7)
                premium ? GIR_SA_SERVER_DISCONNECTED : GIR_E_OK
            );
            // Log.Add(
            //     LOG_ERROR,
            //     L"[Goods Inventory][%s][%d][%s] User Doing Goods Inventory Job. But SA Server Disconnected.",
            //     L"User.cpp",
            //     0x6c4e,
            //     GetName())
            // L2_LOG_ERROR(Log,
            //     L"[goods inventory] Cannot inquire for '%s': the SA server is disconnected while a goods job is active.",
            //     GetName())
            L2_LOG_ERROR(
                Log,
                u"[goods inventory] Cannot inquire for '%s': the SA server is disconnected while a goods job is active.",
                GetName()
            );
            EndGoodsInventoryJob();
        } else {
            GetSocket()->Send(
                "chd", 0xfe, 0x10e,
                // premium ? -103 : -7)
                premium ? GIR_PREV_REQ_ON_PROCESS : GIR_E_OK
            );
            // Log.Add(
            //     LOG_ERROR,
            //     L"[Goods Inventory][%s][%d][%s] Inquiry Goods Job Fail. User Is Already Doing Goods Inventory Job",
            //     L"User.cpp",
            //     0x6c5f,
            //     GetName())
            // L2_LOG_ERROR(Log,
            //     L"[goods inventory] Cannot start inquiry for '%s': another goods-inventory job is already active.",
            //     GetName())
            L2_LOG_ERROR(
                Log, u"[goods inventory] Cannot start inquiry for '%s': another goods-inventory job is already active.",
                GetName()
            );
        }
        return;
    }

    StartGoodsInventoryJob();
    const GoodsInventoryJobResult result =
        g_GoodsInventory.RequestInquiryGoodsInventory(GetServerId(), GetAccountID(), GetDBID(), premium);
    if (result == GIJR_S_OK) {
        return;
    }
    if (result == GIJR_SA_SERVER_DISCONNECTED) {
        GetSocket()->Send(
            "chd", 0xfe, 0x10e,
            // premium ? -4 : -7)
            premium ? GIR_SA_SERVER_DISCONNECTED : GIR_E_OK
        );
    } else if (result == GIJR_INVALID_JOB) {
        GetSocket()->Send(
            "chd", 0xfe, 0x10e,
            // premium ? -2 : -7)
            premium ? GIR_ETC_SYSTEM_ERROR : GIR_E_OK
        );
    }
    EndGoodsInventoryJob();
}

