bool User::CheckRetrieveGoodsCondition(CUserNewGoods* goods) {
    L2_GUARD_FUNCTION();
    if (IsNowTrade() || m_data->m_nPrivateStoreType != 0) {
        // GetSocket()->Send("chd", 0xfe, 0x10e, -5)
        GetSocket()->Send("chd", 0xfe, 0x10e, GIR_ON_TRADING_ACTION);
        return false;
    }
    if (m_data->m_bGMInvisible) {
        SendSystemMessage(u"", u"You cannot do this action in hide mode.");
        // GetSocket()->Send("chd", 0xfe, 0x10e, -1)
        GetSocket()->Send("chd", 0xfe, 0x10e, GIR_INVLAID_REQ);
        return false;
    }

    const auto result = [&] {
        L2_WRITE_GUARD(m_inv);
        int addedNormalItems = 0;
        int addedArtifactItems = 0;
        int addedWeight = 0;
        for (const auto& entry : goods->m_mapIncludedItem) {
            const UserItemIncludedInNewGoods& included = entry.second;
            CObject* const object = g_ObjectDB.GetObjectW(included.m_nItemClassId, false);
            if (object == nullptr || !object->IsItem()) {
                // GetSocket()->Send("chd", 0xfe, 0x10e, -2)
                return GIR_ETC_SYSTEM_ERROR;
            }
            CItem* const item = static_cast<CItem*>(object);
            if (item->IsArtifact()) {
                addedArtifactItems = runtime::AddInt32Wrapping(addedArtifactItems, 1);
            } else {
                addedNormalItems = runtime::AddInt32Wrapping(addedNormalItems, 1);
            }
            const int weight = item->m_data->m_ItemConsumeType == 3 ? 0 : item->m_const->m_nWeight;
            addedWeight = runtime::AddInt32Wrapping(addedWeight, weight);
        }

        const bool normalFits = static_cast<float>(runtime::AddInt32Wrapping(m_inv.GetTotalCount(), addedNormalItems)) <=
            static_cast<float>(GetInventoryLimit()) * 0.8F;
        const bool artifactsFit =
            static_cast<float>(runtime::AddInt32Wrapping(m_inv.GetArtifactCount(), addedArtifactItems)) <=
            static_cast<float>(GetArtifactInventoryLimit()) * 0.8F;
        if (!normalFits) {
            // artifactsFit ? -3 : -9)
            return artifactsFit ? GIR_INVENTORY_LIMIT_OVER : GIR_TOTAL_INVENTORY_LIMIT_OVER;
        }
        if (!artifactsFit) {
            // GetSocket()->Send("chd", 0xfe, 0x10e, -8)
            return GIR_ARTIFACT_INVENTORY_LIMIT_OVER;
        }

        const int weightLimit = runtime::Win64CvttDoubleToInt32(GetWeightLimit(69000.0));
        const bool weightFits = static_cast<float>(runtime::AddInt32Wrapping(m_inv.GetCarryingWeight(), addedWeight)) <=
            static_cast<float>(weightLimit) * 0.8F;
        if (!weightFits) {
            // GetSocket()->Send("chd", 0xfe, 0x10e, -3)
            return GIR_INVENTORY_LIMIT_OVER;
        }
        return GIR_E_OK;
    }();
    if (result != GIR_E_OK) {
        GetSocket()->Send("chd", 0xfe, 0x10e, result);
        return false;
    }
    return true;
}

void User::RequestRetrieveGoodsInventory(std::int64_t goodsUid) {
    L2_GUARD_FUNCTION();
    if (m_bDoingGoodsInventoryJob) {
        if (!g_GoodsInventory.m_bSendable || !g_GoodsInventory.m_bConnected) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[Goods Inventory][%s][%d][%s] User Doing Goods Inventory Job. But SA Server Disconnected.",
            //     L"User.cpp",
            //     0x6c97,
            //     GetName())
            // L2_LOG_ERROR(Log,
            //     L"[goods inventory] Cannot retrieve goods for '%s': the SA server is disconnected while a goods job is
            //     active.", GetName())
            L2_LOG_ERROR(
                Log,
                u"[goods inventory] Cannot retrieve goods for '%s': the SA server is disconnected while a goods job is "
                u"active.",
                GetName()
            );
            // GetSocket()->Send("chd", 0xfe, 0x10e, -4)
            GetSocket()->Send("chd", 0xfe, 0x10e, GIR_SA_SERVER_DISCONNECTED);
            EndGoodsInventoryJob();
        } else {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[Goods Inventory][%s][%d][%s] Retrieve Goods Job Fail. User Is Already Doing Goods Inventory Job",
            //     L"User.cpp",
            //     0x6ca0,
            //     GetName())
            // L2_LOG_ERROR(Log,
            //     L"[goods inventory] Cannot retrieve goods for '%s': another goods-inventory job is already active.",
            //     GetName())
            L2_LOG_ERROR(
                Log, u"[goods inventory] Cannot retrieve goods for '%s': another goods-inventory job is already active.",
                GetName()
            );
            // GetSocket()->Send("chd", 0xfe, 0x10e, -103)
            GetSocket()->Send("chd", 0xfe, 0x10e, GIR_PREV_REQ_ON_PROCESS);
        }
        return;
    }

    CUserNewGoods* goods = nullptr;
    {
        L2_GUARD(*m_lock);
        const auto found = m_mapNewGoods.find(goodsUid);
        if (found != m_mapNewGoods.end()) {
            goods = &found->second;
        }
    }
    if (goods == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[Goods Inventory][%s][%d][%s] Can Not Find User Goods Info.",
        //     L"User.cpp",
        //     0x6cc0,
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[goods inventory] Cannot retrieve goods for '%s': user goods state is unavailable.",
        //     GetName())
        L2_LOG_ERROR(Log, u"[goods inventory] Cannot retrieve goods for '%s': user goods state is unavailable.", GetName());
        // GetSocket()->Send("chd", 0xfe, 0x10e, -1)
        GetSocket()->Send("chd", 0xfe, 0x10e, GIR_INVLAID_REQ);
        return;
    }
    if (!CheckRetrieveGoodsCondition(goods)) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[Goods Inventory][%s][%d][%s] Can Not Fill Retrieve Goods Condition.",
        //     L"User.cpp",
        //     0x6cb9,
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[goods inventory] Cannot retrieve goods for '%s': retrieval conditions could not be prepared.",
        //     GetName())
        L2_LOG_ERROR(
            Log, u"[goods inventory] Cannot retrieve goods for '%s': retrieval conditions could not be prepared.", GetName()
        );
        return;
    }

    StartGoodsInventoryJob();
    const GoodsInventoryJobResult result =
        g_GoodsInventory.RequestRetrieveGoodsInventory(GetServerId(), GetAccountID(), GetDBID(), goodsUid);
    if (result == GIJR_S_OK) {
        return;
    }
    if (result == GIJR_SA_SERVER_DISCONNECTED) {
        // GetSocket()->Send("chd", 0xfe, 0x10e, -4)
        GetSocket()->Send("chd", 0xfe, 0x10e, GIR_SA_SERVER_DISCONNECTED);
    } else if (result == GIJR_INVALID_JOB) {
        // GetSocket()->Send("chd", 0xfe, 0x10e, -2)
        GetSocket()->Send("chd", 0xfe, 0x10e, GIR_ETC_SYSTEM_ERROR);
    }
    EndGoodsInventoryJob();
}

void User::DeleteNewGoodsInfo(std::int64_t goodsUid) {
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(*m_lock);
        const auto found = m_mapNewGoods.find(goodsUid);
        if (found != m_mapNewGoods.end()) {
            m_mapNewGoods.erase(found);
        }
    }
}

