void User::StartCaptchaConfirm(std::int64_t transactionId, CAPTCHA::JOB_TYPE jobType) {
    L2_GUARD_FUNCTION();
    m_nCaptchaConfirmTransactionId = transactionId;
    if (jobType != CAPTCHA::JT_REFRESH && runtime::raw_atomic::IncrementI32(&m_CaptchaConfirmTimes) == 1) {
        m_tCaptchaConfirmStartTime = runtime::crt::Time32Now();
    }
}

void User::EndCaptchaConfirm() {
    L2_GUARD_FUNCTION();
    m_nCaptchaConfirmTransactionId = 0;
    runtime::raw_atomic::ExchangeI32(&m_CaptchaConfirmTimes, 0);
    m_tCaptchaConfirmStartTime = 0;
    m_nCaptchaConfirmSec = 0;
    m_tCaptchaDelayStartTime = runtime::crt::Time32Now();
    m_nBotReportPoint = 0;
    db.RequestResetBotReport(this);
}

void User::ActivateCaptchaDebuff() {
    // Current L2Server 0x004cfbe0.
    L2_GUARD_FUNCTION();
    if (HasAbnormalStatusSlot(ABNS_BOT_PENALTY)) {
        return;
    }

    const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(CSkillKey(0xd6f7, 1), this);
    if (skillInfo != nullptr) {
        skillInfo->ActivateSkill(this, this, 0.0, nullptr, CSkillInfo::EAT_SUCCESS, false);
        CLogFormatter formatter;
        formatter.WriteLog2(0x1f69, this, nullptr, m_nBotReportPoint, 7, 0, 0, 0, 0, 0);
    }
}

void User::SetCaptchaConfirmSec(int seconds) {
    L2_GUARD_FUNCTION();
    m_nCaptchaConfirmSec = seconds;
    if (g_CaptchaSetting.reportCntSendCaptcha <= m_nBotReportPoint) {
        m_tCaptchaConfirmStartTime = runtime::crt::Time32Now();
    }
}

int User::GetCaptchaConfirmSec() {
    L2_GUARD_FUNCTION();
    if (m_tCaptchaConfirmStartTime == 0) {
        return 0;
    }

    const int elapsed = runtime::AddInt32Wrapping(
        runtime::SubtractInt32Wrapping(m_nCaptchaConfirmSec, m_tCaptchaConfirmStartTime), runtime::crt::Time32Now()
    );
    return elapsed < g_CaptchaSetting.confirmExpiredSeconds ? elapsed : g_CaptchaSetting.confirmExpiredSeconds;
}

void User::CheckCaptchaConfirmExpired() {
    // Current L2Server 0x004d0488.
    L2_GUARD_FUNCTION();
    if (m_nCaptchaConfirmTransactionId == 0 || m_tCaptchaConfirmStartTime == 0 || m_CaptchaConfirmTimes <= 0) {
        return;
    }

    const int elapsed = runtime::AddInt32Wrapping(
        runtime::SubtractInt32Wrapping(m_nCaptchaConfirmSec, m_tCaptchaConfirmStartTime), runtime::crt::Time32Now()
    );
    if (elapsed < g_CaptchaSetting.confirmExpiredSeconds) {
        return;
    }

    GetSocket()->Send("chccdh", 0x62, SystemMessageId::ILLEGAL_PROGRAM_VERIFICATION_FAILURE_PENALTY, 1, 4, 0xd6f7, 1);
    g_CaptchaManager.ConfirmAnswer(m_nCaptchaConfirmTransactionId, -1);
    ActivateCaptchaDebuff();
    EndCaptchaConfirm();

    const int confirmSeconds = GetCaptchaConfirmSec();
    const int delaySeconds = GetCaptchaDelaySec();
    db.RequestSetBotReport(this, m_nBotReportPoint, m_CaptchaConfirmTimes, confirmSeconds, delaySeconds);
    GetSocket()->Send("chc", 0xfe, 0x18c, 0);
}

void User::SaveCaptchaConfirm() {
    L2_GUARD_FUNCTION();
    const int confirmSeconds = GetCaptchaConfirmSec();
    const int delaySeconds = GetCaptchaDelaySec();
    const int decrementedTimes = runtime::SubtractInt32Wrapping(m_CaptchaConfirmTimes, 1);
    const int confirmTimes = decrementedTimes < 0 ? 0 : decrementedTimes;
    db.RequestSetBotReport(this, m_nBotReportPoint, confirmTimes, confirmSeconds, delaySeconds);
}

int User::GetCaptchaDelaySec() {
    L2_GUARD_FUNCTION();
    if (m_tCaptchaDelayStartTime == 0) {
        return 0;
    }

    const int elapsed = runtime::SubtractInt32Wrapping(runtime::crt::Time32Now(), m_tCaptchaDelayStartTime);
    return elapsed > 0 ? elapsed : 0;
}

void User::SetCaptchaDelaySec(int delaySeconds) {
    L2_GUARD_FUNCTION();
    if (delaySeconds != 0) {
        m_tCaptchaDelayStartTime = runtime::SubtractInt32Wrapping(runtime::crt::Time32Now(), delaySeconds);
    }
}

int User::SetChatLimitValue(int value) {
    L2_GUARD_FUNCTION();

    int reduction = 0;
    const int now = runtime::crt::Time32Now();
    const int lastChatTime = nLastChatTime;
    if (lastChatTime == 0) {
        nLastChatTime = now;
    } else if (lastChatTime > 0) {
        const int elapsed = runtime::SubtractInt32Wrapping(now, lastChatTime);
        if (elapsed > 0) {
            nLastChatTime = now;
            reduction = runtime::MultiplyInt32Wrapping(elapsed, 200);
        }
    }

    const int previousLimit = nChatLimitValue;
    int candidate = runtime::AddInt32Wrapping(
        runtime::MultiplyInt32Wrapping(previousLimit, 10) / 100, runtime::MultiplyInt32Wrapping(value, 60)
    );
    candidate = runtime::SubtractInt32Wrapping(candidate, reduction);
    candidate = runtime::AddInt32Wrapping(candidate, 100);
    candidate = runtime::AddInt32Wrapping(candidate, previousLimit);
    nChatLimitValue = candidate > 0 ? candidate : 0;
    return nChatLimitValue;
}

int User::CalcKarma(int newPkCount, int pkPardon) {
    L2_GUARD_FUNCTION();
    int difference = runtime::SubtractInt32Wrapping(newPkCount, pkPardon);
    if (difference < 0) {
        difference = 0;
    }
    const int cappedDifference = difference < 10000 ? difference : 10000;
    if (cappedDifference < 2 && m_data->m_nKarma > 0) {
        return runtime::SubtractInt32Wrapping(0, m_data->m_nKarma);
    }
    if (cappedDifference < 4) {
        return (-1 - cappedDifference) * 0x168;
    }
    return cappedDifference * -0x2d0;
}

void User::IncreaseKarmaByKillingChao() {
    // Current L2Server 0x00b05fc4, original owner User.cpp.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(*m_lock);
        const int previous = m_data->m_nKarma;
        if (previous < 0x7fffb1df) {
            ChangeKarmaByDelta(100, true);
            if (previous < 0 && m_data->m_nKarma > 0 && !IsGuilty()) {
                runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
            }
        }
    }
    SendStatusUpdate(VCP_CRIMINAL_RATE, 0, 0);
    ParamChanged(std::int64_t{PCB_CHAR_KARMAUPDATE});
    SendETCBuffStatusInfo();
    if (m_bConnected && m_data->m_bIsActive) {
        db.SendSaveCharacterInfo(this, false, true);
    }
    CacheMasterInfoToAll();
}

void User::IncreaseDuelCount() {
    // Current L2Server 0x00b0614c, original owner User.cpp.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(*m_lock);
        m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(
            m_data->m_nDuelCount, runtime::AddInt32Wrapping(m_data->m_nDuelCount, 1), 0x1f
        );
    }
    if (m_bConnected && m_data->m_bIsActive) {
        db.SendSaveCharacterInfo(this, false, true);
    }
    CacheMasterInfoToAll();
}

void User::DecreaseKarma(const bool byUser, User* const killer) {
    // Current L2Server 0x00b1c008, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (RaidServerManager::inst().GetPKKarmaPenaltyType() != RSOT_NORMAL) {
        return;
    }

    {
        L2_GUARD(*m_lock);
        if (byUser && ::genrand64_real1() * 100.0 + 0.0 >= m_SkillMod.m_dPKCountIncreaseProb) {
            m_data->m_nPKCount = runtime::AddInt32Wrapping(m_data->m_nPKCount, 1);

            const int pkLimit = F2PConfig::GetPKLimitCount(this);
            if (killer != nullptr && pkLimit != -1) {
                const std::u16string killerName = std::u16string(killer->GetName());
                GetSocket()->Send(
                    "chccScd", 0x62, SystemMessageId::CHARACTER_DEFEATED_BY_PREEMPTIVE_ATTACK_WITH_CHANCES_REMAINING, 2, 0,
                    killerName.c_str(), 1, F2PConfig::GetPKRemainCount(this)
                );

                CLogFormatter formatter;
                formatter.WriteLog2_1(
                    0x1fb0, this, killer, m_data->m_nLevel, GetVitalPoint(), m_data->m_nPKCount, m_data->m_nPKCount,
                    m_data->m_Race, 0, 0
                );
            }

            if (runtime::SubtractInt32Wrapping(m_data->m_nPKCount, m_data->m_nPKPardonCount) >= g_nPKPenaltyCount) {
                GetSocket()->Send(
                    "chccd", 0x62, SystemMessageId::DEATH_ITEM_DROP_PROBABILITY_DEPENDS_ON_REPUTATION_AND_PK_COUNT, 1, 1,
                    g_nPKPenaltyCount
                );
            }
        }

        if (m_data->m_nKarma > -0x7fffb1e0) {
            ChangeKarmaByDelta(CalcKarma(m_data->m_nPKCount, m_data->m_nPKPardonCount), false);
            if (m_data->m_nKarma < 0 && IsGuilty()) {
                m_data->m_nPKTimeStamp = 0;
                SetGuilty(0);
                runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
                m_bIsSkillViolet = false;
            }
        }
    }

    SendStatusUpdate(VCP_CRIMINAL_RATE, 0, 0);
    if (m_bConnected && m_data->m_bIsActive) {
        db.SendSaveCharacterInfo(this, false, true);
    }
    CacheMasterInfoToAll();
}

void User::DecreaseKarma_KillSummon() {
    // Current L2Server 0x00b1c368, original owner User.cpp.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(*m_lock);
        if (m_data->m_nKarma > -0x7fffb1e0) {
            int delta = CalcKarma(m_data->m_nPKCount, m_data->m_nPKPardonCount);
            if (m_data->m_nKarma < 1) {
                // MSVC's signed division by four truncates toward zero.
                delta /= 4;
            }
            ChangeKarmaByDelta(delta, false);
            if (m_data->m_nKarma < 0 && IsGuilty()) {
                m_data->m_nPKTimeStamp = 0;
                SetGuilty(0);
                runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
                m_bIsSkillViolet = false;
            }
        }
    }
    SendStatusUpdate(VCP_CRIMINAL_RATE, 0, 0);
    if (m_bConnected && m_data->m_bIsActive) {
        db.SendSaveCharacterInfo(this, false, true);
    }
    CacheMasterInfoToAll();
}

