bool User::IsHero() { return HeroType_IsHero(m_data->m_nHeroType); }

void User::ValidateHeroSkills() {
    L2_GUARD_FUNCTION();
    std::vector<std::int64_t>* const heroSkills = Singleton<WHeroSystem>::inst().GetHeroSkillListVector();

    if (HeroType_IsHero(m_data->m_nHeroType) && m_data->m_nSubJobId == 0 &&
        Singleton<WOlympiadDefaultSetting>::inst().IsAllowedLevel(m_data->m_nLevel)) {
        int changed = 0;
        L2_GUARD(m_AcquiredSkillsSect);
        for (const std::int64_t packed : *heroSkills) {
            const std::uint64_t bits = static_cast<std::uint64_t>(packed);
            const int skillId = static_cast<int>(bits >> 32);
            const int level = static_cast<int>((bits >> 16) & 0xffffU);
            const int subLevel = static_cast<std::int16_t>(bits & 0xffffU);
            if (_AcquireSkill(skillId, level, subLevel, false, true)) {
                ++changed;
            }
        }
        if (changed != 0) {
            ValidateChanged(VB_MAX);
        }
        return;
    }

    if (m_data->m_nNoblessType != 1 && m_data->m_nNoblessType != 2) {
        return;
    }

    bool changed = false;
    {
        L2_GUARD(*m_lock);
        for (const std::int64_t packed : *heroSkills) {
            const int skillId = static_cast<int>(static_cast<std::uint64_t>(packed) >> 32);
            if (DeleteAcquireSkill(skillId)) {
                SendDeletedSkillToDB(skillId);
                changed = true;
            }
        }
    }
    if (changed) {
        ValidateChanged(VB_MAX);
    }
}

void User::ImpoundHeroWeapon() {
    L2_GUARD_FUNCTION();
    if (CItem* const item = m_inv.GetHeroItem(false)) {
        static_cast<CCreature*>(this)->UnequipItem(item, false);
    }
    if (CItem* const item = m_inv.GetHeroItem(true)) {
        db.RequestDestroyItem(item, 1, this, 0);
    }
}

bool User::IncSociality() {
    L2_GUARD_FUNCTION();
    runtime::raw_atomic::IncrementI32(&m_data->m_nSociality);
    if (m_data->m_nSociality < 0x100) {
        runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
        return true;
    }
    m_data->m_nSociality = 0xff;
    return false;
}

bool User::IsErtheia() {
    L2_GUARD_FUNCTION();
    return m_nBaseClass == CT_ERTHEIA_FIGHTER || m_nBaseClass == CT_ERTHEIA_WIZARD;
}

