bool User::CanCallToChangeClass() {
    // Current L2Server 0x00b22e4c.
    L2_GUARD_FUNCTION();
    return !m_data->m_bIsInCombatMode && IsTransformed(TransformType::Max) == nullptr && !IsInDuel() && !IsRidingWyvern() &&
        !IsInAirShip() && static_cast<std::int32_t>(m_data->m_moveType) != CMT_FLY && !IsInAirShip() &&
        !m_pWOlympiadUser->IsPlaying() && !m_PledgeGameUser.IsPlaying() && m_SkillMod.m_nBlockMoveCount == 0 &&
        m_data->m_bCanMove && m_SkillMod.m_bCanAct && IsAlive() && !m_AreaMod.m_bIsUnderWater && IsInRealWorld() &&
        m_pFishingController->m_FishingState == FISHINGS_NONE && m_pFishingController->m_bIsAutoFishing != true;
}

bool User::CanStartFlyMove() {
    // Current L2Server 0x00b2310c.
    L2_GUARD_FUNCTION();
    if (m_data->m_bIsInCombatMode || GetController()->GetCurrentActionType() == ACT_SKILL ||
        IsTransformed(TransformType::Max) != nullptr || IsInDuel() || IsRidingWyvern() || IsInAirShip() ||
        static_cast<std::int32_t>(m_data->m_moveType) == CMT_FLY || IsInAirShip() || m_pWOlympiadUser->IsPlaying() ||
        m_PledgeGameUser.IsPlaying() || g_PledgeGameSystem.IsRegisteredUser(this) || m_SkillMod.m_nBlockMoveCount != 0 ||
        !m_data->m_bCanMove || !m_SkillMod.m_bCanAct || !IsAlive() || m_AreaMod.m_bIsUnderWater ||
        m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing == true) {
        return false;
    }

    if (!m_bEinhasadeTransformed && m_data->m_nKarma >= 0 && m_data->m_cIsGuilty < 1 && !m_bIsInitiativeViolet) {
        return true;
    }

    ++m_nAreaMessageTick;
    if (m_nAreaMessageTick % 7 == 1) {
        GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_USE_SAYUNE_WHILE_CHAOTIC);
    }
    return false;
}

void User::ProcessFlyMove() {
    // Current L2Server 0x00bc3ef0.
    L2_GUARD_FUNCTION();
    if (m_nFlyMoveReadyCount <= 0 || --m_nFlyMoveReadyCount != 0) {
        return;
    }

    CFlyMoveManager& manager = CFlyMoveManager::Inst();
    CFlyMovePathNode* const currentNode = manager.GetPathNode(m_FlyMoveInfo.path_id, m_FlyMoveInfo.node_id);
    CFlyMovePathNode* const previousNode = manager.GetPathNode(m_FlyMoveInfo.path_id, m_nPrevNode);
    if (currentNode == nullptr || previousNode == nullptr) {
        m_bFlyMoving = false;
        return;
    }

    const int mode = previousNode->GetRelatedNodeList().size() == 1 ? 2 : 1;
    const FVector& previousPosition = previousNode->GetPos();
    const FVector& currentPosition = currentNode->GetPos();
    g_ptlUserMap->BroadcastToNeighborExceptSelf(
        this, 0x80000, GetPos(), "chdddddddddd", 0xfe, 0x108, static_cast<int>(m_nId), mode, previousNode->GetFlyingHeight(),
        static_cast<int>(previousPosition.x), static_cast<int>(previousPosition.y), static_cast<int>(previousPosition.z),
        currentNode->GetFlyingHeight(), static_cast<int>(currentPosition.x), static_cast<int>(currentPosition.y),
        static_cast<int>(currentPosition.z)
    );
    CWorld::Inst().MoveTo(this, currentPosition, true);

    if (currentNode->GetRelatedNodeList().size() > 1 || !currentNode->IsNonLanding()) {
        g_ptlUserMap->BroadcastToNeighborExceptSelf(
            this, 0x80000, GetPos(), "chdddddddddd", 0xfe, 0x108, static_cast<int>(m_nId), 0,
            previousNode->GetFlyingHeight(), static_cast<int>(previousPosition.x), static_cast<int>(previousPosition.y),
            static_cast<int>(previousPosition.z), currentNode->GetFlyingHeight(), static_cast<int>(currentPosition.x),
            static_cast<int>(currentPosition.y), static_cast<int>(currentPosition.z)
        );
    }
}

bool User::CheckWeight(int classId) {
    // Current L2Server 0x00b23374.
    L2_GUARD_FUNCTION();
    const int initialClassType = GetInitialClassType(classId, m_data->m_Race);
    if (initialClassType == -1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"invalid class[%d] at file[%s], line[%d]",
        //     classId,
        //     L"User.cpp",
        //     0x6e81)
        L2_LOG_ERROR(Log, u"[class] Cannot calculate carrying capacity: class ID %d is invalid.", classId);
        return false;
    }

    CSetting& setting = Singleton<CSetting>::inst();
    const double conBonus = g_PCParamDB.GetParamBonus(PC_CON_BONUS, setting.m_recommended_stat[initialClassType].Con);
    return static_cast<double>(m_inv.GetCarryingWeight()) <= conBonus * 69000.0;
}

bool User::CanChangeSubClass(const int classId) {
    // Current L2Server 0x00b234a4.
    L2_GUARD_FUNCTION();
    return CheckWeight(classId);
}

bool User::CanChangeToAwakenClass(const int classId) {
    // Current L2Server 0x00b2c338.
    L2_GUARD_FUNCTION();
    const bool result = CheckWeight(classId);
    if (!result) {
        SendSystemMessage(SystemMessageId::CANNOT_AWAKEN_INVENTORY_WEIGHT_RESTRICTION);
    }
    return result;
}

bool User::CheckSubjobCommon(int classId, bool force) {
    // Current L2Server 0x00b5f7b4.
    L2_GUARD_FUNCTION();
    if (IsInDuel()) {
        return false;
    }

    if (classId < 137) {
        const RaceType classRace = g_PCParamDB.GetRaceByClass(static_cast<ClassType>(classId), m_data->m_Race);
        if ((m_data->m_Race != RT_KAMAEL && classRace == RT_KAMAEL) || classRace == RT_ERTHEIA) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"char(%s)'s race missmatch with subclass in "
            //     L"[create/change/update subjob]",
            //     GetName())
            // L2_LOG_ERROR(Log,
            //     L"[subclass] Cannot change subclass for '%s': the character race is incompatible with the requested
            //     class.", GetName())
            L2_LOG_ERROR(
                Log,
                u"[subclass] Cannot change subclass for '%s': the character race is incompatible with the requested class.",
                GetName()
            );
            return false;
        }
    } else if (!IsInFifthClassGroup(static_cast<ClassType>(classId)) &&
        !IsInSixthClassGroup(static_cast<ClassType>(classId))) {
        return false;
    }

    if (!force && GetController()->GetCurrentActionType() == ACT_SKILL) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_WHILE_USING_SKILL);
        return false;
    }
    if (HaveSummon()) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_WITH_PET_OR_SERVITOR);
        return false;
    }
    if (IsTransformed(TransformType::Max) != nullptr) {
        SendSystemMessage(SystemMessageId::CANNOT_CHANGE_CLASS_WHILE_TRANSFORMED);
        return false;
    }
    if (m_data->m_bIsFakeDeath) {
        SendSystemMessage(SystemMessageId::CANNOT_USE_WHILE_FEIGNING_DEATH);
        return false;
    }

    const int inventoryLimit = g_PCParamDB.GetInventoryLimitToChangeSubjob(static_cast<ClassType>(classId), m_data->m_Race);
    if (inventoryLimit < m_inv.GetTotalCount()) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_INVENTORY_QUANTITY_EXCEEDED);
        return false;
    }

    const int initialClassType = GetInitialClassType(classId, m_data->m_Race);
    if (initialClassType == -1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"invalid class[%d] at file[%s], line[%d]",
        //     classId,
        //     L"User.cpp",
        //     0x5b41)
        L2_LOG_ERROR(Log, u"[subclass] Cannot validate subclass change: class ID %d is invalid.", classId);
        return false;
    }
    if (initialClassType != 0x35 && !CheckWeight(initialClassType)) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_OVERWEIGHT);
        return false;
    }

    const bool acquired = runtime::raw_atomic::CompareExchangeI32(&m_nChangeSubjobFlag, 1, 0) == 0;
    if (!acquired) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] user is changing subjob. user[%s] class[%d]",
        //     L"User.cpp",
        //     0x5b51,
        //     GetName(),
        //     classId)
        // L2_LOG_ERROR(Log,
        //     L"[subclass] Character '%s' already has a class-change request in progress. Class %d rejected.",
        //     GetName(),
        //     classId)
        L2_LOG_ERROR(
            Log, u"[subclass] Character '%s' already has a class-change request in progress; class %d rejected.", GetName(),
            classId
        );
    }
    return acquired;
}

bool User::CheckSubjobCommon(const int npcSid, const int classId) {
    // Current L2Server 0x00b5faa8.
    L2_GUARD_FUNCTION();
    CSPointer<CCreature> npc = CCreatureFactory::Inst().FindObjectSP(npcSid);
    if (npc && npc->IsNPC()) {
        return CheckSubjobCommon(classId, false);
    }
    // Log.Add(
    //     LOG_ERROR,
    //     L"invalid arguments in [create/change/update subjob]")
    L2_LOG_ERROR(Log, u"[subclass] Cannot process subclass request: NPC object %d is missing or is not an NPC.", npcSid);
    return false;
}

bool User::OnNpcCreateSubJobPacket(const int npcSid, const int classId) {
    // Current L2Server 0x00b637f8.
    L2_GUARD_FUNCTION();
    const int userSid = m_data->index;
    if (IsErtheia()) {
        return false;
    }
    if (!CheckSubjobCommon(npcSid, classId)) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"subjob check error file[%s], Line[%d] char_id[%d] subjob[%d]",
        //     L"User.cpp",
        //     0x5a26,
        //     GetDBID(),
        //     classId)
        L2_LOG_ERROR(Log, u"[subclass] Create request rejected for character %d and class %d.", GetDBID(), classId);
        g_npcserver.Send("cddd", 0x43, npcSid, userSid, -1);
        return false;
    }

    int subJobId = 0;
    if (m_data->m_nSubJob1Class == -1) {
        subJobId = 1;
    } else if (m_data->m_nSubJob2Class == -1) {
        subJobId = 2;
    } else if (m_data->m_nSubJob3Class == -1) {
        subJobId = 3;
    } else {
        // Log.Add(
        //     LOG_ERROR,
        //     L"no more empty subjob slot at file[%s], line[%d]",
        //     L"User.cpp",
        //     0x5a2f)
        L2_LOG_ERROR(
            Log, u"[subclass] Cannot create class %d for character %d: all subclass slots are occupied.", classId, GetDBID()
        );
        g_npcserver.Send("cddd", 0x43, npcSid, userSid, -1);
        runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
        return false;
    }

    if (GetSubJobIdByClass(classId) == -1) {
        OnChangeSubJobBegin();
        db.RequestCreateSubJobForNpc(this, npcSid, userSid, subJobId, classId);
        return true;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"duplicated subjob??? at file[%s], line[%d]",
    //     L"User.cpp",
    //     0x5a38)
    L2_LOG_ERROR(
        Log, u"[subclass] Cannot create class %d for character %d: that subclass is already registered.", classId, GetDBID()
    );
    g_npcserver.Send("cddd", 0x43, npcSid, userSid, -1);
    runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
    return false;
}

bool User::OnNpcChangeSubJobPacket(const int npcSid, const int classId) {
    // Current L2Server 0x00b63a68.
    L2_GUARD_FUNCTION();
    const int userSid = m_data->index;
    if (IsErtheia()) {
        return false;
    }
    if (!CheckSubjobCommon(npcSid, classId)) {
        g_npcserver.Send("cdddd", 0x44, npcSid, userSid, -1, -1);
        return false;
    }

    const int subJobId = GetSubJobIdByClass(classId);
    if (subJobId != -1) {
        OnChangeSubJobBegin();
        db.RequestChangeSubJobForNpc(this, npcSid, userSid, subJobId);
        return true;
    }

    g_npcserver.Send("cdddd", 0x44, npcSid, userSid, -1, -1);
    runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
    return false;
}

bool User::OnNpcRenewSubJobPacket(const int npcSid, const int subJobId, const int newClassId, const int renewType) {
    // Current L2Server 0x00b63be4.
    L2_GUARD_FUNCTION();
    const int userSid = m_data->index;
    if (!CheckSubjobCommon(npcSid, newClassId)) {
        g_npcserver.Send("cdddd", 0x45, npcSid, userSid, -1, -1);
        return false;
    }

    if (renewType == 1) {
        if (subJobId != m_data->m_nSubJobId || newClassId != m_data->m_nClass) {
            g_npcserver.Send("cdddd", 0x45, npcSid, userSid, -1, -1);
            runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
            return false;
        }
    } else if (GetSubJobIdByClass(newClassId) != -1) {
        g_npcserver.Send("cdddd", 0x45, npcSid, userSid, -1, -1);
        runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
        return false;
    }

    OnChangeSubJobBegin();
    db.RequestRenewSubJob(this, subJobId, newClassId, renewType, false, npcSid, userSid);
    return true;
}

bool User::CheckDualClassjobCommon(const int npcSid, const int dualClassId) {
    // Current L2Server 0x00b5fc2c.
    L2_GUARD_FUNCTION();
    CSPointer<CCreature> npc = CCreatureFactory::Inst().FindObjectSP(npcSid);
    if (!npc || !npc->IsNPC()) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"invalid arguments in [create/change/update subjob]")
        L2_LOG_ERROR(
            Log, u"[dual class] Cannot process dual-class request: NPC object %d is missing or is not an NPC.", npcSid
        );
        return false;
    }
    if (!IsErtheia() || IsInDuel()) {
        return false;
    }
    if (!IsInFifthClassGroup(static_cast<ClassType>(dualClassId)) &&
        !IsInSixthClassGroup(static_cast<ClassType>(dualClassId))) {
        return false;
    }
    if (GetController()->GetCurrentActionType() == ACT_SKILL) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_WHILE_USING_SKILL);
        return false;
    }
    if (HaveSummon()) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_WITH_PET_OR_SERVITOR);
        return false;
    }
    if (IsTransformed(TransformType::Max) != nullptr) {
        SendSystemMessage(SystemMessageId::CANNOT_CHANGE_CLASS_WHILE_TRANSFORMED);
        return false;
    }

    const int initialClassType = GetInitialClassType(dualClassId, m_data->m_Race);
    if (initialClassType == -1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"invalid class[%d] at file[%s], line[%d]",
        //     dualClassId,
        //     L"User.cpp",
        //     0x5bac)
        L2_LOG_ERROR(Log, u"[dual class] Cannot validate dual-class change: class ID %d is invalid.", dualClassId);
        return false;
    }
    if (initialClassType != 0x35 && !CheckWeight(initialClassType)) {
        SendSystemMessage(SystemMessageId::CANNOT_CREATE_OR_CHANGE_SUBCLASS_OVERWEIGHT);
        return false;
    }

    if (runtime::raw_atomic::CompareExchangeI32(&m_nChangeSubjobFlag, 1, 0) == 0) {
        return true;
    }
    // Log.Add(
    //     LOG_ERROR,
    //     L"[%s][%d] user is changing dualclass. user[%s] class[%d]",
    //     L"User.cpp",
    //     0x5bbc,
    //     GetName(),
    //     dualClassId)
    // L2_LOG_ERROR(Log,
    //     L"[dual class] Character '%s' already has a class-change request in progress. Class %d rejected.",
    //     GetName(),
    //     dualClassId)
    L2_LOG_ERROR(
        Log, u"[dual class] Character '%s' already has a class-change request in progress; class %d rejected.", GetName(),
        dualClassId
    );
    return false;
}

bool User::OnNpcCreateDualJobPacket(const int npcSid, const int dualClassId) {
    // Current L2Server 0x00b63dbc.
    L2_GUARD_FUNCTION();
    const int userSid = m_data->index;
    if (!CheckDualClassjobCommon(npcSid, dualClassId)) {
        g_npcserver.Send("cdddd", 0xba, npcSid, userSid, -1, -1);
        return false;
    }

    if (m_data->m_DualClassID == -1) {
        OnChangeSubJobBegin();
        db.RequestCreateDualJob(this, dualClassId, 1, false, npcSid, userSid);
        return true;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"no more empty dualjob slot at file[%s], line[%d]",
    //     L"User.cpp",
    //     0x5a9e)
    L2_LOG_ERROR(
        Log, u"[dual class] Cannot create class %d for character %d: the dual-class slot is occupied.", dualClassId,
        GetDBID()
    );
    g_npcserver.Send("cddd", 0xba, npcSid, userSid, -1);
    runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
    return false;
}

int User::GetSocialClass() {
    L2_GUARD_FUNCTION();
    if (HasCastle() && IsPledgeMaster()) {
        return 7;
    }
    if (IsPledgeMaster()) {
        return 6;
    }
    if (m_data->m_nPledgeType == 100) {
        return 5;
    }
    if (m_data->m_nNoblessType == 2) {
        return 4;
    }
    if (m_data->m_nNoblessType == 1) {
        return 3;
    }
    if (IsInSixthClassGroup(m_data->m_nClass)) {
        return 2;
    }
    if (IsInFourthClassGroup(m_data->m_nClass) || IsDoneQuest(0x2938)) {
        return 1;
    }
    return 0;
}

bool User::IsFirstOrSecondClassGroup(ClassType classType) {
    L2_GUARD_FUNCTION();
    const int group = CategoryContent::ClassChange::inst().GetGroupId(static_cast<int>(classType));
    return group == 1 || group == 2;
}

bool User::CanJoinAcademyClass(ClassType classType) {
    L2_GUARD_FUNCTION();
    return IsFirstOrSecondClassGroup(classType) || IsInThirdClassGroup(classType) || IsInFourthClassGroup(classType);
}

int User::GetClassGroupNoByClassType(ClassType classType) {
    L2_GUARD_FUNCTION();
    const int group = CategoryContent::ClassChange::inst().GetGroupId(static_cast<int>(classType));
    if (group == -1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"GetClassGroupNoByClassType not exist class group [%d]",
        //     static_cast<int>(classType))
        L2_LOG_ERROR(
            Log, u"[class] No class group is registered for class ID %d; using group 0.", static_cast<int>(classType)
        );
        return 0;
    }
    return group;
}

bool User::HasToGraduateAcademy(ClassType currentClass, ClassType nextClass) {
    L2_GUARD_FUNCTION();
    return IsInFourthClassGroup(currentClass) && (IsInFifthClassGroup(nextClass) || IsInSixthClassGroup(nextClass));
}

void User::SetAcquireSkillListSendClass(EtcSkillAcquireType type) {
    L2_GUARD_FUNCTION();
    const std::uint32_t index = static_cast<std::uint32_t>(type);
    if (index < static_cast<std::uint32_t>(ESAT_MAX)) {
        runtime::raw_atomic::ExchangeI32(
            &m_hAcquireSkillListSendClassByType[index], static_cast<std::int32_t>(m_data->m_nClass)
        );
        return;
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"[%s][%d]SkillAcquireType error[%d]",
    //     L"User.cpp",
    //     0x7ad1,
    //     static_cast<std::int32_t>(type))
    L2_LOG_ERROR(
        Log, u"[skill acquisition] Skill-acquisition type %d is outside the supported range.",
        static_cast<std::int32_t>(type)
    );
}

bool User::IsMatchAcquireSkillListSendClass(EtcSkillAcquireType type) {
    L2_GUARD_FUNCTION();
    const std::uint32_t index = static_cast<std::uint32_t>(type);
    return index < static_cast<std::uint32_t>(ESAT_MAX) &&
        m_hAcquireSkillListSendClassByType[index] == static_cast<std::int32_t>(m_data->m_nClass);
}

bool User::SetHonorsSkillList(int skillId, int level, bool fromDatabase) {
    L2_GUARD_FUNCTION();
    L2_GUARD(m_AcquiredHonorsSkillsLock);

    const CSkillInfo* const skill = g_SkillDB.GetSkillInfo(CSkillKey(skillId, level, 0), this);
    const AcquiredSkillInfo acquired(skillId, level, 0, skill->m_nReuseDelayGroup, false);
    const auto inserted = m_AcquiredHonorsSkills.emplace(skillId, acquired);
    if (!inserted.second) {
        AcquiredSkillInfo& current = inserted.first->second;
        if (level <= current.m_nLevel) {
            return current.m_nLevel == level;
        }
        current.m_nLevel = level;
    }

    if (!fromDatabase) {
        db.RequestSetHonorsSkill(this, skillId, level);
    }
    return true;
}

bool User::DeleteHonorsSkill(int skillId) {
    // Current L2Server 0x00b3faa8.
    L2_GUARD_FUNCTION();
    L2_GUARD(m_AcquiredHonorsSkillsLock);
    const auto skill = m_AcquiredHonorsSkills.find(skillId);
    if (skill == m_AcquiredHonorsSkills.end()) {
        return false;
    }
    m_AcquiredHonorsSkills.erase(skill);
    return true;
}

void User::_AcquireAllHonorsSkill() {
    // Current L2Server 0x00b3a790.
    L2_GUARD_FUNCTION();
    for (const auto& entry : m_AcquiredHonorsSkills) {
        const AcquiredSkillInfo& skill = entry.second;
        _AcquireSkill(skill.m_nId, skill.m_nLevel, skill.m_nSubLevel, false, true);
    }
}

void User::AcquireAllHonorsSkill() {
    L2_GUARD_FUNCTION();
    L2_GUARD(m_AcquiredHonorsSkillsLock);

    if ((m_data->m_nNoblessType == 1 || m_data->m_nNoblessType == 2) &&
        (m_data->m_nSubJobId == 0 || m_data->m_IsDualClass)) {
        for (const auto& entry : m_AcquiredHonorsSkills) {
            const AcquiredSkillInfo& skill = entry.second;
            AcquireSkill(skill.m_nId, skill.m_nLevel, 0, false, true);
        }
        ValidateChanged(std::int64_t{VB_SKILLLIST});
    }
}

