FVector User::GetShelterPos() {
    // Current L2Server 0x00b3eaec, original owner User.cpp.
    L2_GUARD_FUNCTION();
    const FVector currentPosition = m_data->GetPos();
    const std::int32_t zoneX =
        runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(currentPosition.x), 0x50000) >> 15;
    const std::int32_t zoneY =
        runtime::AddInt32Wrapping(runtime::Win64CvttDoubleToInt32(currentPosition.y), 0x40000) >> 15;
    if (zoneX == 10 && zoneY == 15) {
        static const FVector zeroPos{};
        return zeroPos;
    }

    CGeoCell* cell = CWorld::Inst().GetGeo()->GetBaseCell(
        runtime::Win64CvttDoubleToInt32(currentPosition.x), runtime::Win64CvttDoubleToInt32(currentPosition.y),
        runtime::Win64CvttDoubleToInt32(currentPosition.z)
    );

    std::optional<FVector> shelterStorage;
    std::optional<FVector> passingPositionStorage;
    const FVector* const selectedPosition = [&] {
        L2_GUARD(PassingPosSect);
        int passingPositionIndex = static_cast<int>(m_nCurrentPassingPos);
        auto& shelter = shelterStorage.emplace();
        auto& passingPosition = passingPositionStorage.emplace();
        if (cell == nullptr || !g_MapBugDetector.GetBugCellShelter(cell, shelter)) {
            return &shelter;
        }

        do {
            passingPositionIndex = (passingPositionIndex + 14) % 15;
            if (passingPositionIndex == static_cast<int>(m_nCurrentPassingPos)) {
                return &shelter;
            }

            passingPosition = m_vPassingPos[passingPositionIndex];
            cell = CWorld::Inst().GetGeo()->GetBaseCell(
                runtime::Win64CvttDoubleToInt32(passingPosition.x), runtime::Win64CvttDoubleToInt32(passingPosition.y),
                runtime::Win64CvttDoubleToInt32(passingPosition.z)
            );
        } while (cell == nullptr || g_MapBugDetector.GetBugCellShelter(cell, shelter));

        return &passingPosition;
    }();
    return *selectedPosition;
}

