bool User::ConsumeAgathionEnergy(double energy) {
    L2_GUARD_FUNCTION();

    CItem* const item = m_inv.GetByIndex(m_data->m_nSlotIndex[ST_LBRACELET]);
    if (item == nullptr || item->m_const->m_dAgathionMaxEnergy <= 0.0 || item->GetAgathionEnergy() <= 0.0) {
        return false;
    }

    double& remaining = item->m_data->m_dAgathionEnergy;
    const bool consumed = energy <= remaining;
    if (consumed) {
        remaining -= energy;
    }

    const double maximum = item->m_const->m_dAgathionMaxEnergy;
    if (remaining >= 0.0) {
        if (remaining > maximum) {
            remaining = maximum;
        }
    } else {
        remaining = 0.0;
    }
    return consumed;
}

