void User::briefingExDropPorb() {
    L2_GUARD_FUNCTION();
    for (const auto& entry : m_ExDropMap) {
        std::array<char16_t, 256> message{};
        FormatUtf16To(
            message.data(), message.size(),
            u"ExDropProb CountID[%d] DropCount[%d] "
            u"Additional Prob[%.1f]",
            entry.first, entry.second.nCount, entry.second.dAdditionalProb
        );
        GetSocket()->SendSystemMessage(u"SYS", message.data());
    }
}

void User::UpdateExDropCount(ExDropItemData* dropData, bool acquired) {
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(*m_lock);

        const int countId = dropData->getCountId();
        const int countDelta = acquired ? dropData->getGiveCount() : 0;
        const double additionalProbability = acquired ? 0.0 : dropData->getAdditionalProb();
        const double previousProbabilityMultiplier = acquired ? 0.0 : 1.0;

        int currentCount = countDelta;
        auto found = m_ExDropMap.find(countId);
        if (found == m_ExDropMap.end()) {
            m_ExDropMap.emplace(countId, ExDropInfo{countDelta, additionalProbability});
        } else {
            found->second.nCount += countDelta;
            found->second.dAdditionalProb =
                previousProbabilityMultiplier * found->second.dAdditionalProb + additionalProbability;
            currentCount = found->second.nCount;
        }

        if (acquired) {
            CIOObject::SetTimeStamp(&m_tmExDropItemGetTime);
            db.RequestUpdateExDropCount(this, countId, currentCount, m_tmExDropItemGetTime);
            CLogFormatter formatter;
            formatter.WriteLog1_1(
                0x2336, this, nullptr, nullptr, nullptr, nullptr, dropData->getItemId(), countDelta, currentCount,
                dropData->getMaxCount(), 0, 0, 0
            );
        }
    }
}

