void User::MentorSubjobChange() {
    // Current L2Server 0x00b7315c.
    L2_GUARD_FUNCTION();

    if (IsAlreadyHaveMentor()) {
        runtime::raw_atomic::ExchangeI32(&m_Mentee.m_nInfectedSkillByMentor, 0);
        m_Mentee.SubjobChange();
        AcquireMentorMenteeSkills(ESAT_MENTEE);
    } else if (IsHaveMentee()) {
        runtime::raw_atomic::IncrementI32(&m_Mentor.m_nSomethingChanged);
        m_Mentor.m_nInfectedSkillByMentee = 0;
        AcquireMentorMenteeSkills(ESAT_MENTOR);
    }

    int reason;
    if (CanBeMentee(reason) || IsAlreadyHaveMentor()) {
        if (m_data->m_nSubJobId == 0) {
            if (!IsAlreadyHaveMentor()) {
                g_MenteeWaitingList.AddWaitingList(this, true);
            }
        } else if (!IsAlreadyHaveMentor()) {
            g_MenteeWaitingList.DeleteWaitingList(this);
        }
    }
}

void User::SendMentorList() {
    L2_GUARD_FUNCTION();
    const int penaltyTime = std::max(GetMentorPenaltyEndTimeLeft(), 0);
    CPacketHelperEx<20480> packet;
    if (IsHaveMentee()) {
        m_Mentor.MakeMenteeList(packet);
        GetSocket()->Send(
            "chdddb", 0xfe, 0x11b, 1, penaltyTime, packet.GetAssembledCount(), packet.GetLength(), packet.GetPacket()
        );
        return;
    }
    if (IsAlreadyHaveMentor()) {
        m_Mentee.MakeMentorList(packet);
        GetSocket()->Send("chdddb", 0xfe, 0x11b, 2, 0, packet.GetAssembledCount(), packet.GetLength(), packet.GetPacket());
        return;
    }
    GetSocket()->Send("chdd", 0xfe, 0x11b, 0, penaltyTime);
}

