void User::LoadWorldChat() {
    L2_GUARD_FUNCTION();
    if (g_WorldChat.eAccount == WorldChat::NONE) {
        runtime::raw_atomic::ExchangeI32(&m_nUsedWorldChatPoint, 0);
        return;
    }
    if (g_WorldChat.eAccount == WorldChat::PREMIUM) {
        if (CheckPremiumType(PremiumUserType::PUT_FREE_USER)) {
            m_nUsedWorldChatPoint = 0;
            return;
        }
    } else if (g_WorldChat.eAccount != WorldChat::ALL) {
        return;
    }
    db.RequestLoadWorldChatPoint(this);
}

int User::GetWorldChatCount() {
    L2_GUARD_FUNCTION();
    const std::int32_t totalPoints =
        runtime::AddInt32Wrapping(m_SkillDurationMod.m_nAdditionalWorldChatCnt, g_WorldChat.nMaxChatCnt);
    const std::int32_t remainingPoints = runtime::SubtractInt32Wrapping(totalPoints, m_nUsedWorldChatPoint);
    const std::int32_t pointCost = CheckPremiumType(PremiumUserType::PUT_FREE_USER) ? g_WorldChat.nComsumePointForFree
                                                                                    : g_WorldChat.nComsumePointForPremium;
    std::int32_t count = 0;
    if (pointCost > 0) {
        count = remainingPoints / pointCost;
    }
    return count > 0 ? count : 0;
}

int User::IncUsedWorldChatPoint() {
    L2_GUARD_FUNCTION();
    if (CheckPremiumType(PremiumUserType::PUT_FREE_USER)) {
        runtime::raw_atomic::ExchangeI32(
            &m_nUsedWorldChatPoint, runtime::AddInt32Wrapping(m_nUsedWorldChatPoint, g_WorldChat.nComsumePointForFree)
        );
        return g_WorldChat.nComsumePointForFree;
    }
    runtime::raw_atomic::ExchangeI32(
        &m_nUsedWorldChatPoint, runtime::AddInt32Wrapping(m_nUsedWorldChatPoint, g_WorldChat.nComsumePointForPremium)
    );
    return g_WorldChat.nComsumePointForPremium;
}

bool User::CanWorldSay() {
    L2_GUARD_FUNCTION();
    if (g_WorldChat.eAccount == WorldChat::NONE ||
        (g_WorldChat.eAccount == WorldChat::PREMIUM && CheckPremiumType(PremiumUserType::PUT_FREE_USER))) {
        return false;
    }
    if (m_dwStopWorldSay != 0) {
        SendSystemMessage(SystemMessageId::WORLD_CHAT_BANNED);
        return false;
    }

    const std::int32_t now = runtime::crt::Time32Now();
    const bool freeUser = CheckPremiumType(PremiumUserType::PUT_FREE_USER);
    const std::int32_t minimumLevel = freeUser ? g_WorldChat.nMinLevForFree : g_WorldChat.nMinLevForPremium;
    if (m_data->m_nLevel < minimumLevel) {
        SendSystemMessage_d(SystemMessageId::WORLD_CHAT_MINIMUM_LEVEL_REQUIREMENT, minimumLevel);
        return false;
    }

    const std::int32_t pointCost = freeUser ? g_WorldChat.nComsumePointForFree : g_WorldChat.nComsumePointForPremium;
    const std::int32_t pointLimit =
        runtime::AddInt32Wrapping(m_SkillDurationMod.m_nAdditionalWorldChatCnt, g_WorldChat.nMaxChatCnt);
    const std::int32_t nextPointTotal = runtime::AddInt32Wrapping(m_nUsedWorldChatPoint, pointCost);
    if (pointLimit < nextPointTotal) {
        SendSystemMessage(SystemMessageId::DAILY_WORLD_CHAT_QUOTA_EXHAUSTED);
        return false;
    }

    const std::int32_t interval = freeUser ? g_WorldChat.nIntervalForFree : g_WorldChat.nIntervalForPremium;
    if (runtime::SubtractInt32Wrapping(now, m_tWorldSayTimeStamp) < interval) {
        SendSystemMessage_d(
            SystemMessageId::WORLD_CHAT_AVAILABLE_IN_SECONDS,
            runtime::AddInt32Wrapping(runtime::SubtractInt32Wrapping(m_tWorldSayTimeStamp, now), interval)
        );
        return false;
    }
    return true;
}

bool User::IsHeroEntry(bool olympiadEntry) {
    L2_GUARD_FUNCTION();
    const ClassType classType = m_data->m_nClass;
    const char16_t* const name = GetName();
    SharedOlympiadInfo* const olympiad = SharedOlympiadInfo::GetInfo();

    std::u16string targetName = std::u16string(name);
    const int rank = olympiad->GetRankByName(classType, targetName.data());

    if (!olympiadEntry) {
        return rank == 2 || rank == 3;
    }
    return rank == 1;
}

void User::SendCompletedDailyQuestListClear() {
    L2_GUARD_FUNCTION();
    CUserSocket* const socket = GetSocket();
    if (runtime::client_protocol::UsesNorthAmericanProtocol(socket)) {
        // Portable P152 compatibility extension. Current P162 assigns 0x1ff
        // to S_EX_COMPLETED_DAILY_QUEST_LIST, but Etina's Fate P152 assigns
        // the same wire opcode to EX_DRESS_ROOM_UI_OPEN. P152 has no daily
        // quest-list equivalent, so sending this payload would open/parse an
        // unrelated UI packet. Preserve the exact current send for P162.
        return;
    }
    socket->Send("chd", 0xfe, 0x1ff, 0);
}

void User::SendQuestNPCLogList(int questId, CUserSocket* socket) {
    // Current L2Server 0x00b07e24.
    L2_GUARD_FUNCTION();
    std::array<char, 0x5000> packet;
    int packetSize = 0;
    std::uint8_t logCount = 0;

    for (const MemoStruct& memo : m_data->m_Memo) {
        if (memo.nQuestID != questId) {
            continue;
        }
        for (const UserNPCLog& log : memo.NPCLog) {
            if (log.nNPCID == 0) {
                continue;
            }
            const int assembled = ::Assemble(
                packet.data() + packetSize, static_cast<int>(packet.size()) - packetSize, "dcd", log.nNPCID,
                static_cast<int>(log.userLogType), log.nCount
            );
            if (assembled > 0) {
                packetSize += assembled;
            }
            ++logCount;
        }
    }

    if (socket == nullptr) {
        socket = GetSocket();
    }
    socket->Send("chdcb", 0xfe, 0xc6, questId, static_cast<int>(logCount), packetSize, packet.data());
}

