int User::IncreaseQuestNPCLog(const int questId, const UserNPCLogType userLogType, const int npcId, const int maximum) {
    // Current L2Server.exe 0x00b08090, original owner User.cpp.
    L2_GUARD_FUNCTION();
    int result = 0;
    for (MemoStruct& memo : m_data->m_Memo) {
        if (memo.nQuestID != questId) {
            continue;
        }
        result = memo.IncreaseNPCLog(userLogType, npcId, maximum);
        SendQuestNPCLogList(questId, nullptr);
    }
    return result;
}

void User::SendItemIncreaseSystemMessage(int itemClassId, std::int64_t count, int enchant) {
    L2_GUARD_FUNCTION();
    if (itemClassId == 0x39) {
        GetSocket()->Send("chccQ", 0x62, SystemMessageId::EARNED_ADENA, 1, 6, count);
    } else if (count < 2) {
        if (itemClassId == 0x115a || enchant < 1) {
            GetSocket()->Send("chccd", 0x62, SystemMessageId::OBTAINED_ITEM, 1, 3, itemClassId);
        } else {
            GetSocket()->Send(
                "chccccd", 0x62, SystemMessageId::OBTAINED_ENCHANTED_ITEM, 2, 0x13,
                static_cast<int>(runtime::Int8FromBits(static_cast<std::uint8_t>(enchant))), 3, itemClassId
            );
        }
    } else {
        GetSocket()->Send("chccdcQ", 0x62, SystemMessageId::EARNED_MULTIPLE_ITEMS, 2, 3, itemClassId, 6, count);
    }
    SendAdenaInvenCount();
}

void User::SendItemDecreaseSystemMessage(int itemClassId, std::int64_t count, int enchant, bool showAdenaMessage) {
    L2_GUARD_FUNCTION();
    if (showAdenaMessage && itemClassId == 0x39) {
        GetSocket()->Send("chccQ", 0x62, SystemMessageId::ADENA_DISAPPEARED, 1, 6, runtime::AbsoluteInt64Wrapping(count));
        return;
    }

    const std::int64_t absoluteCount = runtime::AbsoluteInt64Wrapping(count);
    if (absoluteCount < 2) {
        if (itemClassId == 0x115a || enchant < 1) {
            GetSocket()->Send("chccd", 0x62, SystemMessageId::ITEM_DISAPPEARED, 1, 3, itemClassId);
        } else {
            GetSocket()->Send(
                "chccccd", 0x62, SystemMessageId::ENCHANTED_ITEM_DISAPPEARED, 2, 0x13,
                static_cast<int>(runtime::Int8FromBits(static_cast<std::uint8_t>(enchant))), 3, itemClassId
            );
        }
    } else {
        GetSocket()->Send("chccdcQ", 0x62, SystemMessageId::MULTIPLE_ITEMS_DISAPPEARED, 2, 3, itemClassId, 6, absoluteCount);
    }
}

