void User::SendRemainTime(int remainTime, eSMsgType messageType, int value1, int value2, int value3, int value4) {
    L2_GUARD_FUNCTION();

    const int messageOffset = value4 < 0
        ? (SystemMessageId::DAILY_RESET_REUSE_TIME_SECONDS_REMAINING - SystemMessageId::REUSE_TIME_SECONDS_REMAINING)
        : 0;
    const std::int32_t packedSkill =
        runtime::Int32FromBits((static_cast<std::uint32_t>(value3) << 16U) | static_cast<std::uint32_t>(value2));

    if (remainTime < 61) {
        if (remainTime == 0) {
            remainTime = 1;
        }
        const int seconds = static_cast<int>(runtime::Int8FromBits(static_cast<std::uint8_t>(remainTime)));
        if (messageType == EST_SKILLID) {
            GetSocket()->Send(
                "chccddcc", 0x62, messageOffset + SystemMessageId::REUSE_TIME_SECONDS_REMAINING, 2, EST_SKILLID, value1,
                packedSkill, 0x14, seconds
            );
        } else if (messageType == EST_ITEMID) {
            GetSocket()->Send(
                "chccdcc", 0x62, messageOffset + SystemMessageId::REUSE_TIME_SECONDS_REMAINING, 2, EST_ITEMID, value1, 0x14,
                seconds
            );
        }
        return;
    }

    if (remainTime < 3601) {
        const std::int8_t minutes = runtime::Int8FromBits(static_cast<std::uint8_t>(remainTime / 60));
        const std::int8_t seconds =
            runtime::Int8FromBits(static_cast<std::uint8_t>(remainTime - static_cast<int>(minutes) * 60));
        if (messageType == EST_SKILLID) {
            GetSocket()->Send(
                "chccddcccc", 0x62, messageOffset + SystemMessageId::REUSE_TIME_MINUTES_SECONDS_REMAINING, 3, EST_SKILLID,
                value1, packedSkill, 0x14, static_cast<int>(minutes), 0x14, static_cast<int>(seconds)
            );
        } else if (messageType == EST_ITEMID) {
            GetSocket()->Send(
                "chccdcccc", 0x62, messageOffset + SystemMessageId::REUSE_TIME_MINUTES_SECONDS_REMAINING, 3, EST_ITEMID,
                value1, 0x14, static_cast<int>(minutes), 0x14, static_cast<int>(seconds)
            );
        }
        return;
    }

    const int remainder = remainTime % 3600;
    const std::int8_t minutes = runtime::Int8FromBits(static_cast<std::uint8_t>(remainder / 60));
    const std::int8_t seconds =
        runtime::Int8FromBits(static_cast<std::uint8_t>(remainder - static_cast<int>(minutes) * 60));
    const std::int16_t hours = runtime::Int16FromBits(static_cast<std::uint16_t>(remainTime / 3600));
    if (messageType == EST_SKILLID) {
        GetSocket()->Send(
            "chccddchcccc", 0x62, messageOffset + SystemMessageId::REUSE_TIME_HOURS_MINUTES_SECONDS_REMAINING, 4,
            EST_SKILLID, value1, packedSkill, 0x15, static_cast<int>(hours), 0x14, static_cast<int>(minutes), 0x14,
            static_cast<int>(seconds)
        );
    } else if (messageType == EST_ITEMID) {
        GetSocket()->Send(
            "chccdchcccc", 0x62, messageOffset + SystemMessageId::REUSE_TIME_HOURS_MINUTES_SECONDS_REMAINING, 4, EST_ITEMID,
            value1, 0x15, static_cast<int>(hours), 0x14, static_cast<int>(minutes), 0x14, static_cast<int>(seconds)
        );
    }
}

