void User::StartTraining() {
    // Current L2Server 0x00b2cec0.
    if (IsRiding() || IsInVehicle() || IsTransformed(TransformType::Max) != nullptr) {
        GetSocket()->Send("cd", 0x62, 0x1818);
        return;
    }
    if (GetParty() != nullptr) {
        GetSocket()->Send("cd", 0x62, 0x1817);
        return;
    }
    if (CReplyChecker::IsUserWaitingReply(this) || GetTrade() != nullptr) {
        GetSocket()->Send("cd", 0x62, 0xa4);
        return;
    }
    if (m_AreaMod.m_bIsInTrainingZone) {
        GetSocket()->Send("cd", 0x62, 0x180c);
        const int z = runtime::Win64CvttDoubleToInt32(GetPos().z);
        const int y = runtime::Win64CvttDoubleToInt32(GetPos().y);
        const int x = runtime::Win64CvttDoubleToInt32(GetPos().x);
        // Log.Add(
        //     LOG_ERROR,
        //     L"trainingzone invalid enter : %d, %d [%d,%d,%d]",
        //     m_data->m_TrainingState,
        //     static_cast<int>(GetDBID()),
        //     x,
        //     y,
        //     z)
        L2_LOG_ERROR(
            Log,
            u"[training zone] Character %d requested entry while already inside the zone: state %d, position (%d, %d, %d).",
            static_cast<int>(GetDBID()), m_data->m_TrainingState, x, y, z
        );
        return;
    }
    db.RequestStartTraniningZone(this);
}

