bool User::TradeDivideAdena(User* const user, const int objectId, const std::int64_t amount, const bool update) {
    // Current L2Server 0x00b1cff0.
    L2_GUARD_FUNCTION();
    std::optional<std::array<char, 0x1000>> packetStorage;
    const int packetLength = [&] {
        L2_WRITE_GUARD(m_inv);
        L2_WRITE_GUARD(user->m_inv);

        CItem* const sourceAdena = m_inv.GetFirstItemByClassID(0x39, false, false);
        if (sourceAdena == nullptr || sourceAdena->m_data->m_nCount < amount) {
            return -1;
        }

        CItem* const targetAdena = user->m_inv.GetFirstItemByClassID(0x39, false, false);
        auto& packet = packetStorage.emplace();
        return targetAdena == nullptr
            ? ::Assemble(
                  packet.data(), static_cast<int>(packet.size()), "ddddddQdc", 1, sourceAdena->GetDBID(), sourceAdena->Id(),
                  2, 0, 0, amount, objectId, update
              )
            : ::Assemble(
                  packet.data(), static_cast<int>(packet.size()), "ddddddQdc", 1, sourceAdena->GetDBID(), sourceAdena->Id(),
                  1, targetAdena->GetDBID(), targetAdena->Id(), amount, objectId, update
              );
    }();
    if (packetLength < 1) {
        runtime::raw_atomic::ExchangeI32(&m_nWaitGetItemOnce, 0);
        return false;
    }

    db.TradeDivideAdenaCommit(this, static_cast<int>(user->GetDBID()), packetLength, packetStorage->data());
    return true;
}

void User::SendCompletedDailyQuest(int questId) {
    L2_GUARD_FUNCTION();
    CUserSocket* const socket = GetSocket();
    if (runtime::client_protocol::UsesNorthAmericanProtocol(socket)) {
        // Portable P152 compatibility extension. Current P162 opcode 0x200
        // is S_EX_COMPLETED_DAILY_QUEST. P152 interprets it as the unrelated
        // EX_DRESS_HANGER_LIST and has no daily-quest completion equivalent.
        return;
    }
    protocol::S_EX_COMPLETED_DAILY_QUEST packet{};
    packet.questId = questId;
    socket->Send(S_EX, S_EX_COMPLETED_DAILY_QUEST, packet);
}

void User::SendCompletedDailyQuestList() {
    L2_GUARD_FUNCTION();
    CUserSocket* const socket = GetSocket();
    if (runtime::client_protocol::UsesNorthAmericanProtocol(socket)) {
        // See SendCompletedDailyQuestListClear: P152 wire opcode 0x1ff is
        // EX_DRESS_ROOM_UI_OPEN, not a daily-quest list.
        return;
    }
    protocol::S_EX_COMPLETED_DAILY_QUEST_LIST packet{};
    const std::vector<int> questIds =
        m_data->GetCompletedDailyQuestsAfterBindTime(runtime::SubtractInt32Wrapping(m_tNextBindTime, 0x15180));
    for (const int questId : questIds) {
        packet.vQuestIds.push_back(questId);
    }
    socket->Send(S_EX, S_EX_COMPLETED_DAILY_QUEST_LIST, packet);
}

