bool User::OnNpcShowBuySellPagePacket(
    CNPC& npc, const std::int64_t itemNpcSellListId, const std::int64_t itemNpcBuyBanListId, const double ratio
) {
    // Current L2Server 0x00b9d070, original owner user_packet.cpp.
    L2_GUARD_FUNCTION();
    if (npc.m_data == nullptr) {
        return false;
    }

    const BuySellListCache::Key sellKey{npc.m_data->m_nResidenceID, static_cast<int>(npc.GetInZoneID()), itemNpcSellListId};
    if (BuySellListCache::Inst().GetList(sellKey) == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"Not a cached sell-list[%s][%I64d]",
        //     npc.GetName(),
        //     itemNpcSellListId)
        // L2_LOG_ERROR(Log,
        //     L"[merchant] NPC '%s' has no cached sell list with ID %I64d.",
        //     npc.GetName(),
        //     itemNpcSellListId)
        L2_LOG_ERROR(Log, u"[merchant] NPC '%s' has no cached sell list with ID %I64d.", npc.GetName(), itemNpcSellListId);
        return false;
    }

    const BuySellListCache::Key banKey{npc.m_data->m_nResidenceID, static_cast<int>(npc.GetInZoneID()), itemNpcBuyBanListId};
    if (BuySellListCache::Inst().GetList(banKey) == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"Not a cached ban-list[%s][%I64d]",
        //     npc.GetName(),
        //     itemNpcBuyBanListId)
        // L2_LOG_ERROR(Log,
        //     L"[merchant] NPC '%s' has no cached buy-ban list with ID %I64d.",
        //     npc.GetName(),
        //     itemNpcBuyBanListId)
        L2_LOG_ERROR(
            Log, u"[merchant] NPC '%s' has no cached buy-ban list with ID %I64d.", npc.GetName(), itemNpcBuyBanListId
        );
        return false;
    }

    static_cast<void>(CBuySell::SetBuySell(*this, npc, itemNpcSellListId, itemNpcBuyBanListId, ratio));
    m_bOpenedNpcStoreUI = true;
    ShowBuySellList(0);
    return false;
}

void User::SendUIEventPacket(const unsigned char* packet) {
    L2_GUARD_FUNCTION();

    int value1 = 0;
    int value2 = 0;
    int value3 = 0;
    std::array<char16_t, 20> shortText1{};
    std::array<char16_t, 20> shortText2{};
    std::array<char16_t, 20> shortText3{};
    std::array<char16_t, 20> shortText4{};
    std::array<char16_t, 20> shortText5{};
    int value4 = 0;
    std::array<char16_t, 256> longText1{};
    std::array<char16_t, 256> longText2{};
    std::array<char16_t, 256> longText3{};
    std::array<char16_t, 256> longText4{};
    std::array<char16_t, 256> longText5{};

    ::Disassemble(
        packet, "dddSSSSSdSSSSS", &value1, &value2, &value3, 0x28, shortText1.data(), 0x28, shortText2.data(), 0x28,
        shortText3.data(), 0x28, shortText4.data(), 0x28, shortText5.data(), &value4, 0x200, longText1.data(), 0x200,
        longText2.data(), 0x200, longText3.data(), 0x200, longText4.data(), 0x200, longText5.data()
    );

    GetSocket()->Send(
        "chddddSSSSSdSSSSS", 0xfe, 0x8f, runtime::Int32FromBits(GetServerId()), value1, value2, value3, shortText1.data(),
        shortText2.data(), shortText3.data(), shortText4.data(), shortText5.data(), value4, longText1.data(),
        longText2.data(), longText3.data(), longText4.data(), longText5.data()
    );
}

