void User::SendVoiceEventPacket(const unsigned char* packet) {
    L2_GUARD_FUNCTION();

    std::array<char16_t, 1000> targetVoiceName{};
    int value1 = 0;
    int value2 = 0;
    int value3 = 0;
    int value4 = 0;
    int value5 = 0;
    int mode = 0;
    int inZoneId = 0;
    int value6 = 0;
    ::Disassemble(
        packet, "Sdddddddd", 2000, targetVoiceName.data(), &value1, &value2, &value3, &value4, &value5, &mode, &inZoneId,
        &value6
    );

    if (inZoneId != 0 && static_cast<std::uint32_t>(inZoneId) != GetInZoneID()) {
        return;
    }

#if defined(_WIN32)
    static_assert(sizeof(wchar_t) == sizeof(char16_t));
    const wchar_t* const voiceName = reinterpret_cast<const wchar_t*>(targetVoiceName.data());
#else
    const std::wstring hostVoiceName = ::Utf16ToWide(std::u16string_view(targetVoiceName.data()));
    const wchar_t* const voiceName = hostVoiceName.c_str();
#endif

    if (mode == 0) {
        PlaySound(voiceName, value1, value2, value3, value4, value5);
    } else if (mode == 2 || mode == 3) {
        PlayVoice(targetVoiceName.data(), value1, value2, value3, value4, value5, value6, mode == 2);
    }
}

