double User::GetDefaultExpDownValue(const int level) {
    // Current L2Server 0x00b1d74c.
    L2_GUARD_FUNCTION();
    if (level > 0x78) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] level[%d] is bigger than MAX_LEVEL[%d]",
        //     L"User.cpp",
        //     0x2564,
        //     level,
        //     0x78)
        L2_LOG_ERROR(
            Log, u"[equipment preview] Requested level %d exceeds maximum level %d; preview rejected.", level, 0x78
        );
    }

    const bool transformedOrChaotic = m_bEinhasadeTransformed || m_data->m_nKarma < 0;
    double maximum;
    double minimum;
    double decrement;
    if (level < 0x4c) {
        if (transformedOrChaotic) {
            decrement = static_cast<double>(level - 1) * 0.25;
            maximum = 20.0;
            minimum = 10.0;
        } else {
            decrement = static_cast<double>(level - 1) * 0.125;
            maximum = 10.0;
            minimum = 4.0;
        }
    } else if (level < 99) {
        decrement = static_cast<double>(level - 0x4b) * 0.5;
        if (transformedOrChaotic) {
            maximum = 10.0;
            minimum = 5.0;
        } else {
            maximum = 3.0;
            minimum = 1.0;
        }
    } else {
        decrement = static_cast<double>(level - 99) * 0.01;
        if (transformedOrChaotic) {
            maximum = 1.5;
            minimum = 1.0;
        } else {
            maximum = 0.2;
            minimum = 0.1;
        }
    }

    double percentage = maximum - decrement;
    if (percentage <= minimum) {
        percentage = minimum;
    }
    const std::int64_t levelExperience = runtime::Int64FromBits(
        static_cast<std::uint64_t>(ExpByLevel[level + 1]) - static_cast<std::uint64_t>(ExpByLevel[level])
    );
    return 0.0 - static_cast<double>(levelExperience) * (percentage / 100.0);
}

std::int64_t User::ExpDown(std::int64_t experience) {
    // Current L2Server 0x00b08364. Current indexing differs
    // from the older donor: it uses ExpByLevel[level], not level - 1.
    L2_GUARD_FUNCTION();
    const int level = m_data->m_nLevel;
    if (runtime::AddInt64Wrapping(m_data->m_nExp, experience) < ExpByLevel[level]) {
        if (level < 0x56) {
            experience = runtime::Int64FromBits(
                static_cast<std::uint64_t>(ExpByLevel[level]) - static_cast<std::uint64_t>(m_data->m_nExp)
            );
        }
        m_nDownExp = experience;
    }
    if (experience == 0) {
        m_nDownExp = 0;
        return m_data->m_nExp;
    }
    const std::int64_t result = ExpInc(experience, false);
    ParamChanged(std::int64_t{PCB_USER});
    return result;
}

