void User::SendDominionRenamedToParty(bool) {
    L2_GUARD_FUNCTION();
    CParty* const party = GetParty();
    if (!party) {
        return;
    }

    std::vector<User*> users;
    party->GetAllMember(users);
    for (User* const user : users) {
        if (user && user != this) {
            user->GetSocket()->Send(
                "chddd", 0xfe, 0xa7, runtime::Int32FromBits(m_nId), m_bDominionRenamed, m_nDominionRenamedID
            );
        }
    }
}

void User::CameraMode(bool enabled) {
    L2_GUARD_FUNCTION();
    m_data->m_bGMInvisible = true;

    if (!enabled) {
        m_bCameraMode = false;
        const FVector position = GetPos();
        GetSocket()->Send("cd", 0xf7, 0);
        TeleportToLocation(
            static_cast<int>(position.x), static_cast<int>(position.y), static_cast<int>(position.z), GetInZoneID(), 0x10000,
            TeleportSourceType::UserCameraModeOff, nullptr, 0
        );
    } else {
        m_bCameraMode = true;
        const FVector position = GetPos();
        GetSocket()->Send("cd", 0xf7, 1);
        TeleportToLocation(
            static_cast<int>(position.x), static_cast<int>(position.y), static_cast<int>(position.z), GetInZoneID(), 0x10000,
            TeleportSourceType::UserCameraModeOn, nullptr, 0
        );
    }

    char16_t systemContext[] = u"SYS";
    SendSystemMessage(systemContext, enabled ? u"cammera mode on" : u"cammera mode off");
}

void User::ShowPreview(const int itemCount, int itemIds[]) {
    // Current L2Server 0x00b0b1fc, original owner User.cpp.
    L2_GUARD_FUNCTION();

    std::uint64_t totalPrice = 0;
    std::array<int, 64> previewSlots;
    // Current clears only the 63 published slots and leaves the
    // unused final lane uninitialized.
    std::memset(previewSlots.data(), 0, 63 * sizeof(previewSlots[0]));

    if (itemCount < 1) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] show preview error. [%s]",
        //     "User.cpp",
        //     0x3a1d,
        //     GetName())
        // L2_LOG_ERROR(Log,
        //     L"[equipment preview] Cannot show preview for character '%s': no valid item entries were supplied.",
        //     GetName())
        L2_LOG_ERROR(
            Log, u"[equipment preview] Cannot show preview for character '%s': no valid item entries were supplied.",
            GetName()
        );
        return;
    }

    int acceptedItemCount = 0;
    for (int itemIndex = 0; itemIndex < itemCount; ++itemIndex) {
        const int itemClassId = itemIds[itemIndex];
        CObject* const object = g_ObjectDB.GetObjectW(itemClassId, false);
        if (object == nullptr || !object->IsItem()) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"invalid item(classid : %d) at [%S], [%d]",
            //     itemClassId,
            //     "User.cpp",
            //     0x3a29)
            L2_LOG_ERROR(
                Log, u"[equipment preview] Item class %d is missing or is not an item; entry skipped.", itemClassId
            );
            continue;
        }

        auto* const item = static_cast<CItem*>(object);
        if (static_cast<int>(item->m_const->GetCrystalType()) > static_cast<int>(GetMaxCrystal())) {
            continue;
        }

        if (item->m_data->m_Type != IT_WEAPON && item->m_data->m_Type != IT_ARMOR) {
            int basicSlot = 0;
            while (basicSlot < 16 && (ST2SBT[basicSlot] & item->m_data->m_Slot) == 0) {
                ++basicSlot;
            }
            if (basicSlot != 16) {
                continue;
            }
        }

        const std::int64_t previewPrice = item->GetPreviewPrice();
        int slot = 0;
        while (slot < ST_MAX && (ST2SBT[slot] & item->m_data->m_Slot) == 0) {
            ++slot;
        }

        bool conflict = false;
        switch (slot) {
            case 6:
                conflict = previewSlots[6] > 0;
                break;
            case 7:
                conflict = previewSlots[14] > 0 || previewSlots[7] > 0;
                break;
            case 8:
                conflict = previewSlots[14] > 0 || previewSlots[8] > 0;
                break;
            case 10:
                conflict = previewSlots[15] > 0 || previewSlots[10] > 0;
                break;
            case 11:
                conflict = previewSlots[15] > 0 || previewSlots[11] > 0;
                break;
            case 14:
                conflict = previewSlots[7] > 0 || previewSlots[8] > 0 || previewSlots[14] > 0;
                if (!conflict) {
                    previewSlots[7] = itemClassId;
                    previewSlots[14] = itemClassId;
                }
                break;
            case 15:
                conflict = previewSlots[10] > 0 || previewSlots[11] > 0 || previewSlots[15] > 0;
                if (!conflict) {
                    previewSlots[10] = itemClassId;
                    previewSlots[15] = itemClassId;
                }
                break;
            case 16:
                conflict = previewSlots[16] > 0 || previewSlots[19] > 0;
                break;
            case 18:
                conflict = previewSlots[18] > 0 || previewSlots[19] > 0;
                break;
            case 19:
                conflict = previewSlots[16] > 0 || previewSlots[18] > 0 || previewSlots[19] > 0;
                break;
            default:
                break;
        }

        if (conflict) {
            SendSystemMessage(SystemMessageId::CANNOT_TRY_ON_ITEMS_TOGETHER);
            // ActionFailed(0)
            ActionFailed(AF_DEFAULT);
            return;
        }
        if (slot < ST_MAX && slot != 14 && slot != 15) {
            previewSlots[slot] = itemClassId;
        }

        totalPrice += static_cast<std::uint64_t>(previewPrice);
        ++acceptedItemCount;
    }

    if (acceptedItemCount < 1) {
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        return;
    }

    const std::int64_t adenaAmount = m_inv.GetAdenaAmount();
    if (totalPrice > UINT64_C(999999999999)) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"invalid price at file[%s], line[%d]",
        //     L"User.cpp",
        //     0x3ac9)
        L2_LOG_ERROR(
            Log, u"[equipment preview] Total preview price %I64u exceeds the supported limit.",
            static_cast<std::uint64_t>(totalPrice)
        );
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        return;
    }
    if (static_cast<std::int64_t>(totalPrice) > adenaAmount) {
        SendSystemMessage(SystemMessageId::NOT_ENOUGH_ADENA);
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        return;
    }

    std::array<char, 0x5000> packet;
    int packetLength = 0;
    int publishedSlotCount = 0;
    for (int slot = 0; slot < ST_MAX; ++slot) {
        const int assembled = ::Assemble(
            packet.data() + packetLength, static_cast<int>(packet.size()) - packetLength, "d", previewSlots[slot]
        );
        if (assembled > 0) {
            packetLength += assembled;
            ++publishedSlotCount;
        }
    }

    static_cast<void>(DeleteItemInInventory(0x39, static_cast<std::int64_t>(totalPrice), nullptr, false, false));
    if (m_nPreviewTimeStamp > 0) {
        m_nPreviewTimeStamp = 0;
        SendSystemMessage(SystemMessageId::EQUIPMENT_TRY_ON_CANCELLED);
        ParamChanged(std::int64_t{PCB_USER});
    }
    CIOObject::SetTimeStamp(&m_nPreviewTimeStamp);
    GetSocket()->Send("cdb", 0xf6, publishedSlotCount, packetLength, packet.data());
}

