void User::LevelDownSkillWhenLevelIsTooHigh() {
    // Current L2Server 0x00b1c51c.
    L2_GUARD_FUNCTION();
    const int userLevel = m_data->m_nLevel;
    const CSkillAcquireDB::SkillAcquireInfoVector& skills = g_SkillAcquireDB.GetAcquirableSkills(m_data->m_nClass);
    for (SkillAcquireInfo* const info : skills) {
        if (!IsPC() || IsBuilder() || runtime::AddInt32Wrapping(userLevel, 10) >= info->nGetLevel) {
            continue;
        }

        const int acquiredLevel = GetAcquiredSkillLevel(info->nSkillID);
        int acquiredSubLevel = GetAcquiredSkillSubLevel(info->nSkillID);
        if (acquiredLevel == -1 || info->nSkillLevel > acquiredLevel || acquiredSubLevel < 0) {
            continue;
        }

        if (info->nSkillLevel == 1) {
            static_cast<void>(DeleteAcquireSkill(info->nSkillID));
            SendDeletedSkillToDB(info->nSkillID);
            continue;
        }
        if (!HaveSkill(info->nSkillID, info->nSkillLevel)) {
            continue;
        }

        const int destinationLevel = runtime::AddInt32Wrapping(info->nSkillLevel, -1);
        if (g_SkillEnchantDB.GetSkillEnchantInfo(info->nSkillID, destinationLevel, acquiredSubLevel) == nullptr) {
            acquiredSubLevel = 0;
        }
        if (AcquireSkill(info->nSkillID, destinationLevel, acquiredSubLevel, true, true)) {
            SendAcquiredSkillToDB(info->nSkillID, destinationLevel, acquiredSubLevel, true);
        }
    }
}

void User::CheckCompassRegion() {
    // Current L2Server 0x00b1c73c.
    L2_GUARD_FUNCTION();

    FVector position = GetPos();
    const int x = runtime::Win64CvttDoubleToInt32(position.x);
    const int y = runtime::Win64CvttDoubleToInt32(position.y);
    CGeoZone* const zone = CWorld::Inst().GetGeo()->GetZone(
        (runtime::AddInt32Wrapping(x, 0x50000) >> 15) + 10, (runtime::AddInt32Wrapping(y, 0x40000) >> 15) + 10
    );
    if (zone == nullptr) {
        return;
    }

    CGeoSector* const sector = zone->GetSector((x >> 7) & 0xff, (y >> 7) & 0xff);
    if (sector == nullptr) {
        return;
    }

    const std::uint16_t field = static_cast<std::uint16_t>(sector->m_Field);
    const auto hasField = [field](const GeoFieldTypeEnum type) {
        const std::uint16_t mask = GeoFieldMask[type];
        return (field & mask) == mask;
    };

    if (hasField(GEO_FIELD_INSTANT)) {
        CArea* const damage = CAreaDB::inst().FindAllArea(position, AREAT_DAMAGE);
        CArea* const poison = CAreaDB::inst().FindAllArea(position, AREAT_POISON);
        CArea* const instant = CAreaDB::inst().FindAllArea(position, AREAT_INSTANT_SKILL);
        if (damage != nullptr || poison != nullptr || instant != nullptr) {
            SendCompassRegionCode(CRCE_DEBUFF, true, false);
        }
    }

    if (hasField(GEO_FIELD_STATUS_CHANGE)) {
        CArea* const swamp = CAreaDB::inst().FindArea(static_cast<int>(GetInZoneID()), position, AREAT_SWAMP, true);
        if (swamp != nullptr) {
            SendCompassRegionCode(CRCE_DEBUFF, true, false);
        }

        CArea* const motherTree =
            CAreaDB::inst().FindArea(static_cast<int>(GetInZoneID()), position, AREAT_MOTHER_TREE, true);
        if (motherTree != nullptr && motherTree->m_vAffectRace[static_cast<std::size_t>(m_data->m_Race)]) {
            SendCompassRegionCode(CRCE_BUFF, true, false);
        }
    }

    const bool peace = AreaBasedRule::CompassPeace(sector, GetInZoneID(), &position);
    if (peace) {
        SendCompassRegionCode(CRCE_PEACE, true, false);
    }

    const bool vehicle = IsVehicle();
    if (vehicle) {
        SendCompassRegionCode(CRCE_PEACE, true, false);
    }

    const double z = m_data->m_Pos.z;
    const bool insideSectorHeight =
        static_cast<double>(sector->m_TerritoryMinZ) <= z && z <= static_cast<double>(sector->m_TerritoryMaxZ);
    if (hasField(GEO_FIELD_SSQ) && insideSectorHeight) {
        SendCompassRegionCode(CRCE_SSQ, true, false);
    }

    if (!vehicle && !peace && insideSectorHeight) {
        if (hasField(GEO_FIELD_BATTLE_RESIDENCE)) {
            SendCompassRegionCode(CRCE_SIEGE, true, false);
        } else if (hasField(GEO_FIELD_BATTLE_PVP)) {
            SendCompassRegionCode(CRCE_PVP, true, false);
        }
    }
}

