void User::_SendShortBuffStatusInfo() {
    L2_GUARD_FUNCTION();
    int skillId = 0;
    int level = 0;
    int subLevel = 0;
    int remainingTime = 0;

    const CSkillInfo* const skillInfo = m_InstantDurationSkill.pSkillInfo;
    if (skillInfo != nullptr) {
        std::int32_t now = 0;
        CIOObject::SetTimeStamp(&now);
        skillId = skillInfo->m_nSkillId;
        level = skillInfo->m_nLevel;
        subLevel = skillInfo->m_nSubLevel;
        if (skillInfo->m_nAbnormalTime == -1) {
            remainingTime = -1;
        } else {
            const std::int32_t elapsed = runtime::SubtractInt32Wrapping(now, m_InstantDurationSkill.nStartTime);
            remainingTime = runtime::SubtractInt32Wrapping(GetAbnormalTime(skillInfo, false), elapsed);
            if (remainingTime < 0) {
                remainingTime = 0;
            }
        }
    }

    const std::uint32_t packedLevel =
        (static_cast<std::uint32_t>(subLevel) << 16U) | (static_cast<std::uint32_t>(level) & 0xffffU);
    GetSocket()->Send("cddd", 0xfa, skillId, packedLevel, remainingTime);
}

void User::SendShortBuffStatusInfo() {
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(m_InstantDurationSect);
        _SendShortBuffStatusInfo();
    }
}

