bool User::_DelEquipDurationItem(CItem* item) {
    L2_GUARD_FUNCTION();
    if (item == nullptr) {
        return false;
    }

    const int itemClassId = item->m_data->m_nClassID;
    const int itemDbId = item->m_data->m_nDBID;
    const auto matchingItems = m_mmapEquipDurationItem.equal_range(itemClassId);
    for (auto position = matchingItems.first; position != matchingItems.second; ++position) {
        if (position->second == itemDbId) {
            m_mmapEquipDurationItem.erase(position);
            return true;
        }
    }
    return false;
}

int User::GetPeriodLeft(int itemDbId) {
    L2_GUARD_FUNCTION();
    L2_GUARD(m_PeriodicItemLock);
    const auto item = m_periodicItemMap.find(itemDbId);
    if (item == m_periodicItemMap.end()) {
        return -9999;
    }
    return runtime::SubtractInt32Wrapping(item->second.expireTime, runtime::crt::Time32Now());
}

int User::GetPeriodLeft(CItem& item) {
    L2_GUARD_FUNCTION();
    if (item.m_data->GetShapeShiftedClassId() < 1) {
        return GetPeriodLeft(runtime::Int32FromBits(item.GetDBID()));
    }
    return GetPeriodLeftForShapeShiftedItem(runtime::Int32FromBits(item.GetDBID()));
}

