bool User::CanUseShot(const CSkillInfo* skillInfo) {
    L2_GUARD_FUNCTION();
    const int skillId = skillInfo->m_nSkillId;

    const bool requiresSoulShot = skillId == 0x7f7 || (skillId >= 0x866 && skillId <= 0x86a);
    const bool requiresSpiritShot = skillId == 0x7ff || skillId == 0x80d || (skillId >= 0x86b && skillId <= 0x874);
    if ((requiresSoulShot && !m_bWaitSoulShotUse) || (requiresSpiritShot && !m_bWaitSpiritShotUse)) {
        return false;
    }

    if (m_pFishingController == nullptr) {
        if (skillId == 0x7f1 && !m_bWaitSummonSoulShotUse) {
            return false;
        }
        if ((skillId == 0x7d8 || skillId == 0x7d9) && !m_bWaitSummonSpiritShotUse) {
            return false;
        }
    } else if (((skillId >= 0x885 && skillId <= 0x88a) || (skillId >= 0x9509 && skillId <= 0x950a)) &&
        !m_bWaitFishingShotUse) {
        return false;
    }

    if (skillId >= 0x65cc && skillId <= 0x65d0 && !m_bWaitSoulShotUse) {
        return false;
    }
    if (skillId >= 0x65c2 && skillId <= 0x65cb) {
        return m_bWaitSpiritShotUse;
    }
    return true;
}

bool User::BotReport(User* target) {
    // Current L2Server 0x00b21794.
    L2_GUARD_FUNCTION();

    if (target == nullptr || target == this || target->GetSocket() == nullptr) {
        return false;
    }

    if (!AreaBasedRule::BotReport(target) || target->m_AreaMod.m_bIsInPvPZone || target->m_AreaMod.m_bIsInBattleField) {
        SendSystemMessage(SystemMessageId::CANNOT_REPORT_CHARACTER_IN_THIS_AREA);
        return false;
    }
    if (CheckMyPledgeDeclareWar(target)) {
        SendSystemMessage(SystemMessageId::CANNOT_REPORT_DURING_DECLARED_CLAN_WAR);
        return false;
    }
    if (m_nBotReportPoint > 100) {
        SendSystemMessage(SystemMessageId::CANNOT_REPORT_OTHER_USERS_AFTER_BOT_REPORT);
        return false;
    }

    if (target->m_pFishingController->m_FishingState != FISHINGS_NONE || target->m_pFishingController->m_bIsAutoFishing) {
        SendSystemMessage(SystemMessageId::CANNOT_REPORT_FISHING_CHARACTER);
        return false;
    }

    if (g_CaptchaSetting.enable) {
        if (target->HasAbnormalStatusSlot(static_cast<AbnormalStatusSlotType>(0x11a))) {
            SendSystemMessage(SystemMessageId::TARGET_ALREADY_VERIFIED_OR_PENALIZED_REPORT_REUSE_RESTRICTION);
            return false;
        }
        if (target->m_nBotReportPoint >= g_CaptchaSetting.reportCntSendCaptcha) {
            SendSystemMessage(SystemMessageId::CANNOT_REPORT_CHARACTER_WITH_VERIFICATION_IN_PROGRESS);
            return false;
        }
        const int captchaDelay = target->GetCaptchaDelaySec();
        if (captchaDelay != 0 && captchaDelay < g_CaptchaSetting.reportDelaySeconds) {
            SendSystemMessage(SystemMessageId::TARGET_ALREADY_VERIFIED_OR_PENALIZED_REPORT_REUSE_RESTRICTION);
            return false;
        }

        const int privateStoreType = target->m_data->m_nPrivateStoreType;
        if (privateStoreType != 0) {
            if (!g_CaptchaSetting.canBotReportCraft && privateStoreType == 5) {
                SendSystemMessage(SystemMessageId::CANNOT_REPORT_CHARACTER_IN_STORE_WORKSHOP_OR_DUEL);
                return false;
            }
            if (!g_CaptchaSetting.canBotReportPrivateStore &&
                (privateStoreType == 1 || privateStoreType == 3 || privateStoreType == 8)) {
                SendSystemMessage(SystemMessageId::CANNOT_REPORT_CHARACTER_IN_STORE_WORKSHOP_OR_DUEL);
                return false;
            }
        }
        if (target->IsInDuel()) {
            SendSystemMessage(SystemMessageId::CANNOT_REPORT_CHARACTER_IN_STORE_WORKSHOP_OR_DUEL);
            return false;
        }
    }

    CUserSocket* const reporterSocket = GetSocket();
    CUserSocket* const targetSocket = target->GetSocket();
    const std::uint32_t reporterAddress = reporterSocket->GetAddress().s_addr;
    const std::uint32_t targetAddress = targetSocket->GetAddress().s_addr;

    CBotReportAgent* const agent = CBotReportAgent::Inst();
    const std::uint32_t accountId = GetAccountID();
    const int result = agent->CheckRestrainAndUpdate(
        accountId, reporterAddress, static_cast<int>(m_data->m_nPledgeID), static_cast<int>(target->GetDBID())
    );
    if (result == CBotReportAgent::BCRT_OK) {
        reporterSocket->SendSystemMessage_S_d(
            SystemMessageId::REPORT_POINT_USED_ON_CHARACTER_WITH_REMAINING_POINTS, target->GetName(),
            agent->GetAvailablePoint(accountId)
        );

        std::array<char16_t, 20> reporterAddressText{};
        std::array<char16_t, 20> targetAddressText{};
        std::array<char16_t, 24> reporterPledge{};
        std::array<char16_t, 24> targetPledge{};
        FormatBotReportAddress(reporterAddress, reporterAddressText);
        FormatBotReportAddress(targetAddress, targetAddressText);
        CopyBotReportPledgeName(GetPledge(), reporterPledge);
        CopyBotReportPledgeName(target->GetPledge(), targetPledge);
        agent->Report(
            this, target, reporterAddressText.data(), reporterPledge.data(), targetAddressText.data(), targetPledge.data()
        );
        return true;
    }

    if (result == CBotReportAgent::BCRT_FAILED_BY_PLEDGE || result == CBotReportAgent::BCRT_FAILED_BY_IP) {
        SendSystemMessage(SystemMessageId::CANNOT_REPORT_TARGET_ALREADY_REPORTED_BY_CLAN_ALLIANCE_OR_IP);
    } else if (result == CBotReportAgent::BCRT_FAILED_BY_ACCOUNT) {
        SendSystemMessage(SystemMessageId::CANNOT_REPORT_TARGET_ALREADY_REPORTED_BY_ACCOUNT);
    } else if (result == CBotReportAgent::BCRT_FAILED_BY_NOT_ENOUGH_POINT) {
        SendSystemMessage(SystemMessageId::REPORT_POINTS_EXHAUSTED_RESET_TIME_NOTICE);
    } else if (result == CBotReportAgent::BCRT_FAILED_BY_REUSE_DELAY) {
        const int remain = agent->GetRemainDelay(accountId);
        const int available = agent->GetAvailablePoint(accountId);
        if (remain < 61) {
            const int seconds = static_cast<int>(static_cast<std::int16_t>(agent->GetRemainDelay(accountId)));
            reporterSocket->Send(
                "chcchcc", 0x62, SystemMessageId::REPORT_AVAILABLE_IN_SECONDS_WITH_POINTS_REMAINING, 2, 0x15, seconds, 0x14,
                static_cast<int>(static_cast<std::int8_t>(available))
            );
        } else {
            reporterSocket->Send(
                "chcchcc", 0x62, SystemMessageId::REPORT_AVAILABLE_IN_MINUTES_WITH_POINTS_REMAINING, 2, 0x15,
                static_cast<int>(static_cast<std::int16_t>(remain / 60)), 0x14,
                static_cast<int>(static_cast<std::int8_t>(available))
            );
        }
    }
    return false;
}

