bool User::IsDuelEnemy(CCreature* creature) {
    L2_GUARD_FUNCTION();
    if (creature == nullptr || creature->m_nId == m_nId) {
        return false;
    }

    if (IsMySummonOrPet(creature)) {
        CSummon* const summon = creature->CastSummon();
        return summon->m_betrayOwnMaster;
    }

    User* target = creature->GetUserOrMaster();
    if (creature->IsNPC()) {
        CNPC* const npc = creature->CastNPC();
        target = npc->GetMaster();
    }
    return target != nullptr && target->IsInDuel() && m_DuelUserInfo.IsEnemy(target);
}

