void User::SetInCombatMode(bool inCombat) {
    m_data->m_bIsInCombatMode = inCombat;
    if (inCombat) {
        if (m_nStartCombatTime == 0) {
            m_nStartCombatTime = runtime::crt::Time32Now();
        }
        return;
    }

    if (m_nStartCombatTime != 0) {
        const std::int32_t now = runtime::crt::Time32Now();
        m_nTotalCombatTime = runtime::Int32FromBits(
            static_cast<std::uint32_t>(m_nTotalCombatTime) + static_cast<std::uint32_t>(now) -
            static_cast<std::uint32_t>(m_nStartCombatTime)
        );
        m_nStartCombatTime = 0;
    }
}

