bool User::DeclareLord() {
    // Current L2Server 0x00b9fa10.
    L2_GUARD_FUNCTION();
    CPledge* const pledge = GetPledge();
    if (pledge == nullptr) {
        return false;
    }
    CCastle* const castle = pledge->GetCastle();
    if (castle == nullptr || !castle->IsAllChildFortressRelated()) {
        return false;
    }
    const bool canDeclare = castle->m_pDominion != nullptr;
    if (canDeclare) {
        castle->m_pDominion->ExtendDominion();
    }
    return canDeclare;
}

