bool User::UpdateChar(
    const std::int64_t sp,
    const std::int64_t experience,
    const int karma,
    const int pkCount,
    const std::uint32_t pkPardonCount,
    const std::uint32_t duelCount
) {
    // Current L2Server 0x00b06f8c, original owner User.cpp.
    L2_GUARD_FUNCTION();

    {
        L2_GUARD(*m_lock);
        m_data->m_NeedUpdatePacketBitSet.SetInt64Value_IfModifed(m_data->m_nSP, sp, 0x0e);
        if (m_data->m_nExp != experience) {
            m_data->m_NeedUpdatePacketBitSet.SetInt64Value_IfModifed(m_data->m_nExp, experience, 6);
            m_data->m_NeedUpdatePacketBitSet.SetBit(7);
        }
        m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(m_data->m_nPKCount, pkCount, 0x1e);
        m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(
            m_data->m_nPKPardonCount, static_cast<std::int32_t>(pkPardonCount), 0x1d
        );
        m_data->m_NeedUpdatePacketBitSet.SetIntValue_IfModifed(
            m_data->m_nDuelCount, static_cast<std::int32_t>(duelCount), 0x1f
        );
    }

    SetKarma(karma);
    return true;
}

bool User::SetStopLogin(std::uint32_t duration) {
    L2_GUARD_FUNCTION();
    db.RequestSetPunish(*this, 1, 0, static_cast<int>(duration / 60000U));
    return true;
}

bool User::SetStopSay(std::uint32_t duration, bool save) {
    L2_GUARD_FUNCTION();

    if (duration == 0) {
        m_dwStopSay = 0;
        SendSystemMessage(SystemMessageId::CHAT_ENABLED);
        if (save) {
            db.RequestSetPunish(*this, 2, 1, 0);
            SendPunishmentHistoryToDB(0x16);
        }
        return true;
    }

    m_dwStopSay = runtime::GetTickCount() + duration;
    const std::uint32_t durationMinutes = duration / 60000U;
    if (durationMinutes < 0x23280U) {
        SendSystemMessage(SystemMessageId::CHAT_DISABLED);
        GetSocket()->SendSystemMessage_d(
            SystemMessageId::CHAT_RESTRICTION_MINUTES_REMAINING, static_cast<int>(durationMinutes)
        );
    } else {
        SendSystemMessage(SystemMessageId::CHAT_BANNED_AFTER_REPEATED_BLOCKS);
    }
    if (save) {
        db.RequestSetPunish(*this, 2, 1, static_cast<int>(durationMinutes));
        SendPunishmentHistoryToDB(0x0c);
    }
    return true;
}

bool User::SetStopWorldSay(std::uint32_t duration, bool save) {
    L2_GUARD_FUNCTION();

    if (duration == 0) {
        m_dwStopWorldSay = 0;
        SendSystemMessage(SystemMessageId::WORLD_CHAT_AVAILABLE);
        if (save) {
            db.RequestSetPunish(*this, 6, 1, 0);
            SendPunishmentHistoryToDB(0x84);
        }
        return true;
    }

    m_dwStopWorldSay = runtime::GetTickCount() + duration;
    const std::uint32_t durationMinutes = duration / 60000U;
    GetSocket()->SendSystemMessage_d(
        SystemMessageId::WORLD_CHAT_STOPPED_WITH_MINUTES_UNTIL_AVAILABLE, static_cast<int>(durationMinutes)
    );
    if (save) {
        db.RequestSetPunish(*this, 6, 1, static_cast<int>(durationMinutes));
        SendPunishmentHistoryToDB(0x83);
    }
    return true;
}

