bool User::SetStopBotReport(std::uint32_t duration, bool save) {
    // Current L2Server 0x00b1d548.
    L2_GUARD_FUNCTION();
    CBotReportAgent::Inst()->SetStopBotReport(GetAccountID(), static_cast<int>(duration / 1000U));
    if (save || duration == 0) {
        db.RequestSetPunish(*this, 3, 1, static_cast<int>(duration / 60000U));
    }
    return true;
}

std::uint32_t User::ReducePunishTime() {
    L2_GUARD_FUNCTION();

    if (m_dwStopSay != 0 && m_dwStopSay < runtime::GetTickCount()) {
        SetStopSay(0, true);
    }
    if (m_dwStopHeroSay != 0 && m_dwStopHeroSay < runtime::GetTickCount()) {
        SetStopHeroSay(0, true);
    }
    if (m_dwStopWorldSay != 0 && m_dwStopWorldSay < runtime::GetTickCount()) {
        SetStopWorldSay(0, true);
    }
    if (m_dwStopPartyMatch != 0 && m_dwStopPartyMatch < runtime::GetTickCount()) {
        SetStopPartyMatch(0, true);
    }
    return 0;
}

bool User::SavePunishTime() {
    L2_GUARD_FUNCTION();
    const std::uint32_t currentTick = runtime::GetTickCount();
    if (currentTick < m_dwStopSay) {
        db.RequestSetPunish(*this, 2, 1, static_cast<int>((m_dwStopSay - currentTick) / 60000U));
    }
    if (currentTick < m_dwStopHeroSay) {
        db.RequestSetPunish(*this, 4, 1, static_cast<int>((m_dwStopHeroSay - currentTick) / 60000U));
    }
    if (currentTick < m_dwStopWorldSay) {
        db.RequestSetPunish(*this, 6, 1, static_cast<int>((m_dwStopWorldSay - currentTick) / 60000U));
    }
    if (currentTick < m_dwStopPartyMatch) {
        db.RequestSetPunish(*this, 5, 1, static_cast<int>((m_dwStopWorldSay - currentTick) / 60000U));
    }
    return true;
}

bool User::CheckCreatePartyMatchLevelLimit() {
    L2_GUARD_FUNCTION();
    return m_data->m_nLevel >= g_nCreatePartyMatchLevelLimit;
}

int User::GetQuestNPCLog(int questId, UserNPCLogType userLogType, int npcId) {
    L2_GUARD_FUNCTION();
    int count = 0;
    for (const MemoStruct& memo : m_data->m_Memo) {
        if (memo.nQuestID != questId) {
            continue;
        }
        for (const UserNPCLog& log : memo.NPCLog) {
            count = log.userLogType == userLogType && log.nNPCID == npcId ? log.nCount : 0;
            if (count != 0) {
                break;
            }
        }
    }
    return count;
}

bool User::IsDoneQuest(int questId) {
    L2_GUARD_FUNCTION();
    return m_data->GetOneTimeFlag(questId);
}

void User::CheckTutorialEvent(TutorialClientEventEnum event) {
    L2_GUARD_FUNCTION();
    const std::int32_t eventBits = static_cast<std::int32_t>(event);
    if ((eventBits & m_TutorialEventSet) == 0) {
        return;
    }

    m_TutorialEventSet &= ~eventBits;
    g_npcserver.Send("cdd", 0x34, m_data->index, eventBits);
}

void User::SendLevelUpNPCEvent() {
    L2_GUARD_FUNCTION();
    g_npcserver.Send("cdd", 0x87, m_data->index, m_data->m_nLevel);
}

void User::SendUserConnectedEvent() {
    L2_GUARD_FUNCTION();
    if (!m_bNpcNotified) {
        m_bNpcNotified = true;
        g_npcserver.Send("cddd", 0x30, runtime::Int32FromBits(m_nId), 0, 1);
    }
}

