void User::SendEquipedHennaListForUnequip() {
    // Current L2Server 0x00b09688.
    L2_GUARD_FUNCTION();

    const int enableHenna = static_cast<int>(static_cast<std::int8_t>(m_data->m_cEnableHenna));
    int expectedCount = GetEquipedHennaCount();
    const int classId = static_cast<int>(m_data->m_nClass);
    std::array<char, 0x5000> packet;
    int packetLength = 0;
    int assembledCount = 0;

    const int hennaIds[3] = {
        m_data->m_HennaId_1,
        m_data->m_HennaId_2,
        m_data->m_HennaId_3,
    };
    [[maybe_unused]] const int missingHennaLines[3] = {
        0x3453,
        0x346b,
        0x3483,
    };

    for (int index = 0; index < 3; ++index) {
        const int hennaId = hennaIds[index];
        if (hennaId <= 0) {
            continue;
        }

        CHenna* const henna = g_HennaDB.Find(hennaId);
        if (henna == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%S][%d]",
            //     "User.cpp",
            //     missingHennaLines[index])
            L2_LOG_ERROR(
                Log, u"[henna] Equipped henna ID %d in slot %d is missing; unequip list not sent.", hennaId, index + 1
            );
            return;
        }

        const int canUse = henna->CanUse(classId, nullptr) ? 1 : 0;
        const int assembled = ::Assemble(
            packet.data() + packetLength, static_cast<int>(packet.size()) - packetLength, "ddQQdd", hennaId,
            henna->m_nItemClassId, henna->m_CancelCount, henna->m_CancelFee, canUse, 0
        );
        if (assembled > 0) {
            packetLength += assembled;
            ++assembledCount;
        }
    }

    if (m_HennaId_premium > 0) {
        CHenna* const henna = g_HennaDB.Find(m_HennaId_premium);
        if (henna == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%S][%d]",
            //     "User.cpp",
            //     0x349e)
            L2_LOG_ERROR(Log, u"[henna] Equipped premium henna ID %d is missing; unequip list not sent.", m_HennaId_premium);
            return;
        }

        const int canUse = henna->CanUse(classId, nullptr) ? 1 : 0;
        const int assembled = ::Assemble(
            packet.data() + packetLength, static_cast<int>(packet.size()) - packetLength, "ddQQdd", m_HennaId_premium,
            henna->m_nItemClassId, henna->m_CancelCount, henna->m_CancelFee, canUse,
            static_cast<int>(henna->m_bIsPremiumHenna)
        );
        if (assembled > 0) {
            packetLength += assembled;
            ++assembledCount;
            ++expectedCount;
        }
    }

    if (expectedCount != assembledCount) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d]",
        //     "User.cpp",
        //     0x34b2)
        L2_LOG_ERROR(
            Log, u"[henna] Unequip list is incomplete: expected %d entries, assembled %d.", expectedCount, assembledCount
        );
        return;
    }
    if (packetLength == 0) {
        return;
    }

    GetSocket()->Send("cQddb", 0xe6, m_inv.GetAdenaAmount(), enableHenna, assembledCount, packetLength, packet.data());
}

void User::SendHennaUnequipInfo(const int hennaId) {
    // Current L2Server 0x00b09ae4.
    L2_GUARD_FUNCTION();

    CStats remainingBonus;
    bool found = false;

    const int firstHennaId = m_data->m_HennaId_1;
    if (firstHennaId > 0) {
        if (!found && firstHennaId == hennaId) {
            found = true;
        } else {
            CHenna* const other = g_HennaDB.Find(firstHennaId);
            if (other != nullptr && other->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
                remainingBonus += other->m_HennaBonus;
            }
        }
    }

    const int secondHennaId = m_data->m_HennaId_2;
    if (secondHennaId > 0) {
        if (!found && secondHennaId == hennaId) {
            found = true;
        } else {
            CHenna* const other = g_HennaDB.Find(secondHennaId);
            if (other != nullptr && other->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
                remainingBonus += other->m_HennaBonus;
            }
        }
    }

    const int thirdHennaId = m_data->m_HennaId_3;
    if (thirdHennaId > 0) {
        if (!found && thirdHennaId == hennaId) {
            found = true;
        } else {
            CHenna* const other = g_HennaDB.Find(thirdHennaId);
            if (other != nullptr && other->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
                remainingBonus += other->m_HennaBonus;
            }
        }
    }

    const int premiumHennaId = m_HennaId_premium;
    if (premiumHennaId > 0) {
        if (!found && premiumHennaId == hennaId) {
            found = true;
        } else {
            CHenna* const other = g_HennaDB.Find(premiumHennaId);
            if (other != nullptr && other->CanUse(static_cast<int>(m_data->m_nClass), nullptr)) {
                remainingBonus += other->m_HennaBonus;
            }
        }
    }

    if (!found) {
        SendSystemMessage(SystemMessageId::SYMBOL_INFORMATION_NOT_FOUND);
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] cannot find henna. [%d][%d]",
        //     "User.cpp",
        //     0x3532,
        //     GetDBID(),
        //     hennaId)
        L2_LOG_ERROR(
            Log, u"[henna] Character %d cannot preview unequip for henna ID %d because it is not equipped.", GetDBID(),
            hennaId
        );
        return;
    }

    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr) {
        SendSystemMessage(SystemMessageId::SYMBOL_INFORMATION_NOT_FOUND);
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] henna id is invalid [%d][%d]",
        //     "User.cpp",
        //     0x353a,
        //     GetDBID(),
        //     hennaId)
        L2_LOG_ERROR(Log, u"[henna] Character %d requested unequip preview for invalid henna ID %d.", GetDBID(), hennaId);
        return;
    }

    CObject* const object = g_ObjectDB.GetObjectW(henna->m_nItemClassId, false);
    CItem* const item = object != nullptr && object->IsItem() ? static_cast<CItem*>(object) : nullptr;
    if (item == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Item[%d] is not exist.",
        //     L"User.cpp",
        //     0x3541,
        //     henna->m_nItemClassId)
        L2_LOG_ERROR(Log, u"[henna] Dye item class %d for the selected henna is missing.", henna->m_nItemClassId);
        return;
    }

    const int hennaClassId = henna->m_nClassId;
    const int itemClassId = henna->m_nItemClassId;
    const std::int64_t cancelCount = henna->m_CancelCount;
    const std::int64_t cancelFee = henna->m_CancelFee;
    const bool canUse = henna->CanUse(static_cast<int>(m_data->m_nClass), item);
    const std::int64_t adena = m_inv.GetAdenaAmount();
    const CStats currentStats = m_data->m_Stat;
    std::array<std::int16_t, 8> projectedStats{};
    for (std::size_t index = 0; index < projectedStats.size(); ++index) {
        const std::int32_t cappedBonus = remainingBonus.m_N[index] < 0x24 ? remainingBonus.m_N[index] : 0x24;
        const std::int32_t projected = runtime::AddInt32Wrapping(
            runtime::SubtractInt32Wrapping(cappedBonus, m_SkillMod.m_HennaBonus.m_N[index]), currentStats.m_N[index]
        );
        projectedStats[index] = projected < 2 ? std::int16_t{1} : static_cast<std::int16_t>(projected);
    }

    GetSocket()->Send(
        "cddQQdQdhdhdhdhdhdhdhdhd", 0xe7, hennaClassId, itemClassId, cancelCount, cancelFee, canUse, adena,
        currentStats.m_N[0], static_cast<int>(projectedStats[0]), currentStats.m_N[1], static_cast<int>(projectedStats[1]),
        currentStats.m_N[2], static_cast<int>(projectedStats[2]), currentStats.m_N[3], static_cast<int>(projectedStats[3]),
        currentStats.m_N[4], static_cast<int>(projectedStats[4]), currentStats.m_N[5], static_cast<int>(projectedStats[5]),
        currentStats.m_N[6], static_cast<int>(projectedStats[6]), currentStats.m_N[7], static_cast<int>(projectedStats[7]),
        henna->m_bIsPremiumHenna
    );
}

void User::UnequipHenna(const int hennaId) {
    // Current L2Server 0x00b2fd50.
    L2_GUARD_FUNCTION();

    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] henna id is invalid [%d][%d]",
        //     "User.cpp",
        //     0x3583,
        //     GetDBID(),
        //     hennaId)
        L2_LOG_ERROR(Log, u"[henna] Character %d requested invalid henna ID %d for unequip.", GetDBID(), hennaId);
        return;
    }

    // Current 0x00b2fe6e checks CHenna::m_nClassId, not the item class.
    if (CItemRestrict::Inst().CheckItemRestrict(henna->m_nClassId)) {
        // Current 0x00b2fe80 prints GetDBID() through the only value slot
        // and leaves m_nClassId as an extra variadic argument.
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] Item Restrict on. ItemClassID[%d]",
        //     "User.cpp",
        //     0x3589,
        //     GetDBID(),
        //     henna->m_nClassId)
        L2_LOG_ERROR(Log, u"[henna] Character %d cannot unequip restricted henna class %d.", GetDBID(), henna->m_nClassId);
        return;
    }

    if (IsNowTrade()) {
        TradeCancel(false);
    }

    const int itemClassId = henna->m_nItemClassId;
    const std::int64_t cancelCount = henna->m_CancelCount;
    const std::int64_t cancelFee = henna->m_CancelFee;
    if (m_inv.GetAdenaAmount() < cancelFee) {
        SendSystemMessage(SystemMessageId::NOT_ENOUGH_ADENA);
        return;
    }

    const bool premium = henna->m_bIsPremiumHenna;
    if (m_data->m_HennaId_1 != hennaId && m_data->m_HennaId_2 != hennaId && m_data->m_HennaId_3 != hennaId &&
        m_HennaId_premium != hennaId) {
        return;
    }

    const FVector position = GetPos();
#if defined(_WIN32)
    const wchar_t* const accountName = reinterpret_cast<const wchar_t*>(m_sAccountName.data());
#else
    std::array<wchar_t, 16> accountNameBuffer{};
    const wchar_t* const accountName = CopyUtf16ToWide(m_sAccountName.data(), m_sAccountName.size(), accountNameBuffer);
#endif
    // Log.AddT(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,%I64d,,,%s,%s,,,%I64d",
    //     0x3bc,
    //     GetDBID(),
    //     GetAccountID(),
    //     runtime::Win64CvttDoubleToInt32(position.x),
    //     runtime::Win64CvttDoubleToInt32(position.y),
    //     runtime::Win64CvttDoubleToInt32(position.z),
    //     static_cast<int>(m_data->m_Race),
    //     static_cast<int>(m_data->m_Sex),
    //     static_cast<int>(m_data->m_nClass),
    //     m_data->m_nLevel,
    //     cancelFee,
    //     cancelCount,
    //     itemClassId,
    //     GetName(),
    //     accountName,
    //     hennaId)
    Log.AddT(
        LOG_BOTH, u"%I64d,%I64d,%I64d,,,%I64d,%I64d,%I64d,,,,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,%I64d,,,%s,%s,,,%I64d",
        0x3bc, GetDBID(), GetAccountID(), runtime::Win64CvttDoubleToInt32(position.x),
        runtime::Win64CvttDoubleToInt32(position.y), runtime::Win64CvttDoubleToInt32(position.z),
        static_cast<int>(m_data->m_Race), static_cast<int>(m_data->m_Sex), static_cast<int>(m_data->m_nClass),
        m_data->m_nLevel, cancelFee, cancelCount, itemClassId, GetName(), accountName, hennaId
    );
    db.UnequipHenna(this, itemClassId, cancelCount, cancelFee, hennaId, premium);
}

void User::SendUserHennaInfo(CUserSocket* socket) {
    L2_GUARD_FUNCTION();

    const int enableHenna = static_cast<int>(static_cast<std::int8_t>(m_data->m_cEnableHenna));
    const int expectedCount = GetEquipedHennaCount();
    const int classId = static_cast<int>(m_data->m_nClass);

    const CStats& bonus = m_SkillMod.m_HennaBonus;
    std::array<char, 0x5000> packet{};
    int packetLength = 0;
    int assembledCount = 0;

    const int hennaIds[3] = {
        m_data->m_HennaId_1,
        m_data->m_HennaId_2,
        m_data->m_HennaId_3,
    };
    [[maybe_unused]] const int missingHennaLines[3] = {0x35ef, 0x3601, 0x3613};

    for (int index = 0; index < 3; ++index) {
        const int hennaId = hennaIds[index];
        if (hennaId <= 0) {
            continue;
        }

        CHenna* const henna = g_HennaDB.Find(hennaId);
        if (henna == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%S][%d]",
            //     "User.cpp",
            //     missingHennaLines[index])
            L2_LOG_ERROR(
                Log, u"[henna] Equipped henna ID %d in slot %d is missing; user henna packet not sent.", hennaId, index + 1
            );
            return;
        }

        const int canUse = henna->CanUse(classId, nullptr) ? 1 : 0;
        const int assembled =
            ::Assemble(packet.data() + packetLength, static_cast<int>(packet.size()) - packetLength, "dd", hennaId, canUse);
        if (assembled > 0) {
            packetLength += assembled;
            ++assembledCount;
        }
    }

    const int remainingPeriod = runtime::SubtractInt32Wrapping(m_HennaExpireTime, runtime::crt::Time32Now());
    int premiumCanUse = 0;
    if (m_HennaId_premium > 0) {
        CHenna* const premiumHenna = g_HennaDB.Find(m_HennaId_premium);
        if (premiumHenna != nullptr) {
            premiumCanUse = premiumHenna->CanUse(classId, nullptr) ? 1 : 0;
        }
    }

    if (expectedCount != assembledCount) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d]",
        //     "User.cpp",
        //     0x3635)
        L2_LOG_ERROR(
            Log, u"[henna] User henna packet is incomplete: expected %d entries, assembled %d.", expectedCount,
            assembledCount
        );
        return;
    }

    CUserSocket* const destination = socket != nullptr ? socket : GetSocket();
    const int opcode = socket != nullptr ? 0xf0 : 0xe5;

    const int stat0 = static_cast<std::int16_t>(bonus.m_N[0]);
    const int stat1 = static_cast<std::int16_t>(bonus.m_N[1]);
    const int stat2 = static_cast<std::int16_t>(bonus.m_N[2]);
    const int stat3 = static_cast<std::int16_t>(bonus.m_N[3]);
    const int stat4 = static_cast<std::int16_t>(bonus.m_N[4]);
    const int stat5 = static_cast<std::int16_t>(bonus.m_N[5]);
    const int stat6 = static_cast<std::int16_t>(bonus.m_N[6]);
    const int stat7 = static_cast<std::int16_t>(bonus.m_N[7]);

    if (packetLength != 0) {
        destination->Send(
            "chhhhhhhhddbddd", opcode, stat0, stat1, stat2, stat3, stat4, stat5, stat6, stat7, enableHenna, assembledCount,
            packetLength, packet.data(), m_HennaId_premium, remainingPeriod, premiumCanUse
        );
        return;
    }

    destination->Send(
        "chhhhhhhhddddd", opcode, stat0, stat1, stat2, stat3, stat4, stat5, stat6, stat7, enableHenna, assembledCount,
        m_HennaId_premium, remainingPeriod, premiumCanUse
    );
}

void User::InitHenna() {
    L2_GUARD_FUNCTION();
    m_data->m_HennaId_1 = 0;
    m_data->m_HennaId_2 = 0;
    m_data->m_HennaId_3 = 0;
    m_HennaId_premium = 0;
    m_HennaExpireTime = 0;
}

void User::AddHennaFromBD(int hennaId, bool periodic, int expireTime) {
    L2_GUARD_FUNCTION();

    if (periodic) {
        m_HennaId_premium = hennaId;
        m_HennaExpireTime = expireTime;
        return;
    }

    if (m_data->m_HennaId_1 == 0) {
        m_data->m_HennaId_1 = hennaId;
    } else if (m_data->m_HennaId_2 == 0) {
        m_data->m_HennaId_2 = hennaId;
    } else if (m_data->m_HennaId_3 == 0) {
        m_data->m_HennaId_3 = hennaId;
    } else {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] add henna fail. [%d][%d]",
        //     "User.cpp",
        //     0x36c1,
        //     GetDBID(),
        //     hennaId)
        L2_LOG_ERROR(
            Log, u"[henna] Cannot load henna ID %d for character %d: all normal henna slots are occupied.", hennaId,
            GetDBID()
        );
    }
}

void User::DelHennaFromBD(int hennaId, bool periodic) {
    L2_GUARD_FUNCTION();

    if (periodic) {
        m_HennaId_premium = 0;
        m_HennaExpireTime = 0;
        return;
    }

    if (m_data->m_HennaId_1 == hennaId) {
        m_data->m_HennaId_1 = 0;
    } else if (m_data->m_HennaId_2 == hennaId) {
        m_data->m_HennaId_2 = 0;
    } else if (m_data->m_HennaId_3 == hennaId) {
        m_data->m_HennaId_3 = 0;
    } else {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] Del henna fail. [%d][%d]",
        //     "User.cpp",
        //     0x36e6,
        //     GetDBID(),
        //     hennaId)
        L2_LOG_ERROR(Log, u"[henna] Cannot remove henna ID %d for character %d: it is not equipped.", hennaId, GetDBID());
    }
}

void User::OnLoadPeriodicHennaInfo(const std::uint8_t* const packet) {
    // Current L2Server 0x00b0aa10.
    L2_GUARD_FUNCTION();

    std::int32_t hennaId = 0;
    std::int32_t expireTime = 0;
    ::Disassemble(packet, "dd", &hennaId, &expireTime);
    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr) {
        m_HennaId_premium = 0;
        m_HennaExpireTime = 0;
        GetSocket()->Send("chddd", 0xfe, 0x164, 0, 0, 0);
        return;
    }
    if (!henna->IsPremiumHenna()) {
        return;
    }

    m_HennaId_premium = hennaId;
    m_HennaExpireTime = expireTime;
    // Current 0x00b0ab12 writes the periodic-item timer, not the
    // adjacent periodic-Henna timer at +0x6394.
    m_periodicItemManageStart = runtime::AddInt32Wrapping(runtime::crt::Time32Now(), 10);
    const bool canUse = henna->CanUse(static_cast<int>(m_data->m_nClass), nullptr);
    GetSocket()->Send("chddd", 0xfe, 0x164, hennaId, expireTime, canUse);
}

void User::OnPremiumHennaExpired() {
    // Current L2Server 0x00b3782c.
    L2_GUARD_FUNCTION();
    AcquireUnEquipHennaSkill(m_HennaId_premium);
    DeleteAcquireHennaSkill(m_HennaId_premium);
    DelHennaFromBD(m_HennaId_premium, true);
    ValidateHenna();
    ValidateChanged(VB_SKILLLIST);
}

void User::CheckPremiumHennaConditionOnTick() {
    // Current L2Server 0x00b30450.
    L2_GUARD_FUNCTION();
    if (m_HennaId_premium > 0) {
        CHenna* const henna = g_HennaDB.Find(m_HennaId_premium);
        if (henna != nullptr && !henna->CheckHennaCondition(this)) {
            AcquireUnEquipHennaSkill(m_HennaId_premium);
        }
    }
}

void User::CheckPeriodicHennaOnTick() {
    // Current L2Server 0x00b1e0bc.
    L2_GUARD_FUNCTION();
    if (m_HennaId_premium <= 0) {
        return;
    }

    const std::int32_t currentTime = runtime::crt::Time32Now();
    if (m_periodicHennaManageStart > 0 && currentTime < m_periodicHennaManageStart) {
        return;
    }

    // Current 0x00b1e162 clears User+0x6200.
    m_periodicItemManageStart = 0;
    CHenna* const henna = g_HennaDB.Find(m_HennaId_premium);
    if (henna != nullptr && henna->IsPeriodicHenna()) {
        _CheckPeriodicHennaOnTick(currentTime);
        if (m_nTickCount % 15 == 0) {
            SendPeriodicHennaInfo(m_HennaId_premium);
        }
    }
}

void User::_CheckPeriodicHennaOnTick(const int currentTime) {
    // Current L2Server 0x00b0abb4.
    L2_GUARD_FUNCTION();

    const std::int32_t hennaId = m_HennaId_premium;
    const std::int32_t expireTime = m_HennaExpireTime;
    if (currentTime < expireTime) {
        const std::int32_t remaining = runtime::SubtractInt32Wrapping(expireTime, currentTime);
        const std::int32_t nonNegativeRemaining = remaining < 0 ? 0 : remaining;
        if (static_cast<std::uint32_t>(runtime::SubtractInt32Wrapping(nonNegativeRemaining, 0x253)) < 10U) {
            GetSocket()->Send("chccdcd", 0x62, SystemMessageId::OWNERSHIP_EXPIRES_IN_MINUTES, 2, 0x16, hennaId, 1, 10);
        }
    } else {
        db.RemoveExpiredPeriodicHenna(this, hennaId);
    }
}

void User::SendPeriodicHennaInfo(const int hennaId) {
    // Current L2Server 0x00b0acec.
    L2_GUARD_FUNCTION();

    CHenna* const henna = g_HennaDB.Find(hennaId);
    if (henna == nullptr) {
        return;
    }
    const std::int32_t currentTime = runtime::crt::Time32Now();
    const std::int32_t remaining = runtime::SubtractInt32Wrapping(m_HennaExpireTime, currentTime);
    const bool canUse = henna->CanUse(static_cast<int>(m_data->m_nClass), nullptr);
    GetSocket()->Send("chddd", 0xfe, 0x164, hennaId, remaining, canUse);
}

bool User::SetHennaPeriod(int, int period) {
    L2_GUARD_FUNCTION();
    db.AddHennaPeriod(this, static_cast<std::uint32_t>(m_HennaId_premium), period);
    return true;
}

