bool User::CanSoulCollectByExp(std::int64_t experience) const {
    L2_GUARD_FUNCTION();
    return m_SkillMod.m_BarExpForSoulCollect != -1 && m_SkillMod.m_BarExpForSoulCollect < experience;
}

void User::_OnAbnormalStatusChanged(
    const CSkillInfo& skillInfo, CCreature* const caster, const SkillPumpStartType startType, const bool needSendVisualEffect
) {
    // Current L2Server 0x00b0ec8c.
    L2_GUARD_FUNCTION();
    CCreature::_OnAbnormalStatusChanged(skillInfo, caster, startType, needSendVisualEffect);
    if (skillInfo.m_OperateType != SKILL_AURA_ACTIVITY && skillInfo.m_OperateType != SKILL_AURA_ACTIVITY2) {
        const std::uint32_t encodedLevel = (static_cast<std::uint32_t>(skillInfo.m_nSubLevel) << 16U) |
            (static_cast<std::uint32_t>(skillInfo.m_nLevel) & 0xffffU);
        GetSocket()->Send("chccdd", 0x62, SystemMessageId::EFFECT_APPLIED, 1, 4, skillInfo.m_nSkillId, encodedLevel);
    }
}

void User::_OnAbnormalStatusDeleted(
    const CSkillInfo& skillInfo, CCreature* const caster, const SkillPumpEndType endType, const int sourceCreatureId
) {
    // Current L2Server 0x00b0edc0.
    L2_GUARD_FUNCTION();
    CCreature::_OnAbnormalStatusDeleted(skillInfo, caster, endType, sourceCreatureId);
    if (skillInfo.m_OperateType != SKILL_AURA_ACTIVITY && skillInfo.m_OperateType != SKILL_AURA_ACTIVITY2) {
        const std::uint32_t encodedLevel = (static_cast<std::uint32_t>(skillInfo.m_nSubLevel) << 16U) |
            (static_cast<std::uint32_t>(skillInfo.m_nLevel) & 0xffffU);
        GetSocket()->Send(
            "chccdd", 0x62,
            endType == SPET_TIMEOUT ? SystemMessageId::EFFECT_WORN_OFF : SystemMessageId::NAMED_EFFECT_REMOVED, 1, 4,
            skillInfo.m_nSkillId, encodedLevel
        );
    }
    ParamChanged(std::int64_t{PCB_USER | PCB_CHAR_ABNORMALSTATUS});
}

