int User::OnRequestVipAttendanceCheck() {
    // Current L2Server 0x00b5d510, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (GetSocket() == nullptr) {
        return -3;
    }

    ItemAmountDataStruct rewards;
    const int result = VipAttendanceSystem::Inst().GetVipAttendanceReward(this, rewards);
    if (result != 1) {
        if (result == -3) {
            SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_ATTENDANCE_REWARD_SYSTEM_ERROR);
        } else if (result == -1) {
            SendSystemMessage(SystemMessageId::VIP_RANK_TOO_LOW_FOR_REWARD);
        } else if (result == 0) {
            SendSystemMessage(SystemMessageId::NO_MORE_ATTENDANCE_REWARDS_AVAILABLE);
        }
        return result;
    }
    if (!m_inv.CheckAddableMulti(rewards, false)) {
        SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_ATTENDANCE_REWARD_INVENTORY_WEIGHT_OR_QUANTITY_EXCEEDED);
        return -2;
    }
    return VipAttendanceSystem::Inst().ProgressCheckAttendanceData(this) ? 1 : -3;
}

void User::OnRequestVipAttendanceReward(char result) {
    L2_GUARD_FUNCTION();
    int response = -5;
    if (result > 0) {
        response = VipAttendanceSystem::Inst().CheckAndRequestVipAttendanceReward(this);
        if (response == 1) {
            return;
        }
    }
    CUserSocket* const socket = GetSocket();
    if (socket != nullptr) {
        socket->Send("chccdd", 0xfe, 0x17f, static_cast<int>(static_cast<char>(response)), 0, 0, 0);
    }
    VipAttendanceSystem::Inst().ReleaseVIPAttendanceFlag(GetAccountID());
}

void User::RequestSendVipAttendanceResult() {
    L2_GUARD_FUNCTION();
    CUserSocket* const socket = GetSocket();
    if (socket == nullptr) {
        return;
    }
    if (!VipAttendanceSystem::Inst().SendVipAttendanceResult(this)) {
        SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_ATTENDANCE_REWARD_SYSTEM_ERROR);
        socket->Send("chccdd", 0xfe, 0x17f, -3, 0, 0, 0);
    }
}

void User::RequestAccountStamp(const int stampType, const bool checkCanSend, const bool force) {
    L2_GUARD_FUNCTION();
    if (stampType != 0) {
        return;
    }

    CEvent* const baseEvent = Singleton<CEventManager>::inst().GetEvent(GAME_EVENT::ET_ACCOUNT_EVENT);
    auto* const event = static_cast<CEvent_AccountEvent*>(baseEvent);
    if (event == nullptr || !event->InEventTime()) {
        return;
    }
    if (checkCanSend && !event->CanSendMsg(static_cast<int>(GetAccountID()))) {
        return;
    }
    if (m_nTickCount <= 0xa8b && !force) {
        return;
    }

    bool eligible = false;
    if (!force) {
        eligible = m_data != nullptr && event->m_nAttendMinLevel <= m_data->m_nLevel;
        if (event->m_bPremiumOnly) {
            eligible = eligible && IsPremiumUser();
        }
    }

    CPacketHelperEx<20480> packet;
    packet.Assemble(
        "ddddd", event->m_nMaxStamp, event->m_nResetInterval, runtime::crt::Time32Now(),
        event->m_EventPeriod.m_nStartTime, event->m_EventPeriod.m_nEndTime
    );
    db.RequestAccountStamp(this, 0, eligible, packet);
}

