void User::BeTransInfectedSkills(
    User*,
    const AbnormalStatusSlotType abnormalType,
    const int maximumSlots,
    std::vector<InfectedSkillType>& transferredSkills
) {
    // Current L2Server 0x00b67d2c.
    L2_GUARD_FUNCTION();
    bool transferred = false;
    {
        L2_GUARD(m_InfectedSkillsSect);
        for (int index = static_cast<int>(m_InfectedSkills.size()) - 1; index >= 0; --index) {
            InfectedSkillType& infectedSkill = runtime::CheckedVectorAt(m_InfectedSkills, static_cast<std::size_t>(index));
            if (!IsTransferSkillMatched(infectedSkill, abnormalType)) {
                continue;
            }
            if (static_cast<std::uint64_t>(static_cast<std::int64_t>(maximumSlots)) <= transferredSkills.size()) {
                break;
            }
            transferredSkills.push_back(infectedSkill);
            _DeleteAbnormalStatus(index, this, nullptr, false, SPET_TRANSFER, true);
            transferred = true;
        }
    }
    if (transferred) {
        ValidateChanged(VB_WEAPONARMOR | VB_SKILLMOD | VB_HPMPCP | VB_SIM);
    }
}

void User::BeStealedInfectedSkills(
    User* const source,
    const int slotGroup,
    const int maximumSlots,
    const int probability,
    const CSkillInfo* const skillInfo,
    std::vector<InfectedSkillType>& stolenSkills
) {
    // Current L2Server 0x00b67efc.
    L2_GUARD_FUNCTION();
    bool stolen = false;
    {
        L2_GUARD(m_InfectedSkillsSect);
        int matchedSlots = 0;
        for (int index = static_cast<int>(m_InfectedSkills.size()) - 1; index >= 0; --index) {
            InfectedSkillType& infectedSkill = runtime::CheckedVectorAt(m_InfectedSkills, static_cast<std::size_t>(index));
            if (!IsInfectedSkillMatched(infectedSkill, slotGroup)) {
                continue;
            }
            if (maximumSlots <= matchedSlots ||
                static_cast<std::uint64_t>(static_cast<std::int64_t>(maximumSlots)) <= stolenSkills.size()) {
                break;
            }

            double chance = 100.0;
            if (probability != 100 && skillInfo != nullptr) {
                chance = CreatureCommonFunc::GetDispelProbability(
                    static_cast<double>(probability), skillInfo, infectedSkill.pSkillInfo, m_SkillMod, Level()
                );
                if (!(0.0 <= chance)) {
                    chance = 0.0;
                } else if (chance > 50.0) {
                    chance = 50.0;
                }
            }

            const double random = ::genrand64_real1() * 100.0 + 0.0;
            if (random <= chance && chance != random) {
                stolenSkills.push_back(infectedSkill);
                _DeleteAbnormalStatus(index, source, nullptr, false, SPET_STEAL, true);
                stolen = true;
            }
            ++matchedSlots;
        }
    }
    if (stolen) {
        ValidateChanged(VB_WEAPONARMOR | VB_SKILLMOD | VB_HPMPCP | VB_SIM | VB_SPEED);
    }
}

void User::TransInfectedSkills(User* const target, const AbnormalStatusSlotType abnormalType, const int maximumSlots) {
    // Current L2Server 0x00b68540.
    L2_GUARD_FUNCTION();
    std::vector<InfectedSkillType> transferredSkills;
    BeTransInfectedSkills(target, abnormalType, maximumSlots, transferredSkills);
    for (InfectedSkillType& infectedSkill : transferredSkills) {
        target->InfectedSkillBy(
            this, infectedSkill.pSkillInfo, infectedSkill.m_pChannellingSkillInfo, infectedSkill.nStartTime
        );
    }
}

void User::StealInfectedSkills(
    User* const target, const int slotGroup, const int maximumSlots, const int probability, const CSkillInfo* const skillInfo
) {
    // Current L2Server 0x00b6865c.
    L2_GUARD_FUNCTION();
    std::vector<InfectedSkillType> stolenSkills;
    target->BeStealedInfectedSkills(this, slotGroup, maximumSlots, probability, skillInfo, stolenSkills);
    for (InfectedSkillType& infectedSkill : stolenSkills) {
        InfectedSkillBy(target, infectedSkill.pSkillInfo, infectedSkill.m_pChannellingSkillInfo, infectedSkill.nStartTime);
    }
}

void User::SetReturnValue(const int skillId, const int expireTime) {
    // Current L2Server 0x00a9e88c. Original inline owner User.h:0x1248.
    L2_GUARD_FUNCTION();
    L2_GUARD(m_ReturnLock);
    m_ReturnSkillPosMap.emplace(skillId, GetPos());
    m_ReturnTimeSkillMap.emplace(skillId, expireTime);
}

void User::CheckAndDeleteReturnValue() {
    // Current L2Server 0x00b3b83c. Original inline owner User.h:0x124f.
    L2_GUARD(m_ReturnLock);
    const std::int32_t now = runtime::crt::Time32Now();
    for (auto position = m_ReturnTimeSkillMap.begin(); position != m_ReturnTimeSkillMap.end(); ++position) {
        if (position->second >= now) {
            continue;
        }
        const auto returnPosition = m_ReturnSkillPosMap.find(position->first);
        if (returnPosition != m_ReturnSkillPosMap.end()) {
            m_ReturnSkillPosMap.erase(returnPosition);
        }
        m_ReturnTimeSkillMap.erase(position);
        break;
    }
}

FVector User::FindReturnValue(const int skillId) {
    // Current L2Server 0x00a80a58. Original inline owner User.h:0x126e.
    L2_GUARD(m_ReturnLock);
    const auto position = m_ReturnSkillPosMap.find(skillId);
    if (position == m_ReturnSkillPosMap.end()) {
        return FVector{};
    }
    return position->second;
}

