std::int64_t User::CalcShapeShiftingFee(CItem* shapeShiftingItem, CItem* targetItem) const {
    L2_GUARD_FUNCTION();
    if (shapeShiftingItem == nullptr || targetItem == nullptr) {
        return -1;
    }

    switch (shapeShiftingItem->m_const->m_EtcitemType) {
        case EIT_SHAPE_SHIFTING_WP:
        case EIT_BLESS_SHAPE_SHIFTING_WP:
        case EIT_SHAPE_SHIFTING_WP_FIXED:
        case EIT_SHAPE_SHIFTING_AM:
        case EIT_SHAPE_SHIFTING_AM_FIXED:
        case EIT_SHAPE_SHIFTING_HAIRACC:
            break;
        default:
            return 0;
    }

    const CrystalType crystalType = targetItem->m_const->GetCrystalType();
    if (targetItem->IsWeapon()) {
        switch (crystalType) {
            case CRT_D:
                return 2500;
            case CRT_C:
                return 5500;
            case CRT_B:
                return 25000;
            case CRT_A:
                return 90000;
            case CRT_S:
            case CRT_S80:
            case CRT_S84:
                return 250000;
            case CRT_R:
            case CRT_R95:
            case CRT_R99:
                return 800000;
            default:
                return 0;
        }
    }

    if (!targetItem->IsArmor()) {
        return -1;
    }

    const std::uint64_t slotMask = static_cast<std::uint64_t>(targetItem->m_data->m_Slot);
    SlotType slotType = ST_MAX;
    for (int slot = ST_UNDERWEAR; slot < ST_MAX; ++slot) {
        if ((slotMask & (std::uint64_t{1} << slot)) != 0) {
            slotType = static_cast<SlotType>(slot);
            break;
        }
    }
    if (slotType == ST_HAIR || slotType == ST_HAIR2) {
        return 125000;
    }
    if (slotType == ST_HAIRALL) {
        return 200000;
    }

    switch (crystalType) {
        case CRT_D:
            return 600;
        case CRT_C:
            return 1500;
        case CRT_B:
            return 8000;
        case CRT_A:
            return 24000;
        case CRT_S:
        case CRT_S80:
        case CRT_S84:
            return 50000;
        case CRT_R:
        case CRT_R95:
        case CRT_R99:
            return 125000;
        default:
            return 0;
    }
}

