void User::SendMagicSkill(
    const int& parameter1,
    const CWorldObject* target,
    const SkillUseInfo& skill,
    const int& parameter2,
    const int& parameter3,
    const int& parameter4,
    const int& parameter5,
    const int& parameter6,
    char* buffer
) {
    L2_GUARD_FUNCTION();

    const FVector sourcePosition = GetPos();
    const FVector targetPosition = target->GetPos();
    CUserSocket* const socket = GetSocket();
    const std::uint32_t skillLevel =
        (static_cast<std::uint32_t>(skill.m_skillSubLevel) << 16U) | static_cast<std::uint16_t>(skill.m_skillLevel);

    if (buffer == nullptr) {
        socket->Send(
            "cdddddddddddhhddddd", 0x48, parameter1, runtime::Int32FromBits(m_nId),
            runtime::Int32FromBits(target->m_nId), skill.m_skillID, runtime::Int32FromBits(skillLevel), parameter2,
            parameter3, parameter4, static_cast<int>(sourcePosition.x), static_cast<int>(sourcePosition.y),
            static_cast<int>(sourcePosition.z), 0, 0, static_cast<int>(targetPosition.x), static_cast<int>(targetPosition.y),
            static_cast<int>(targetPosition.z), skill.m_type, skill.m_param1
        );
        return;
    }

    socket->Send(
        "cdddddddddddhbddddd", 0x48, parameter1, runtime::Int32FromBits(m_nId), runtime::Int32FromBits(target->m_nId),
        skill.m_skillID, runtime::Int32FromBits(skillLevel), parameter2, parameter3, parameter4,
        static_cast<int>(sourcePosition.x), static_cast<int>(sourcePosition.y), static_cast<int>(sourcePosition.z),
        parameter5, parameter6, buffer, static_cast<int>(targetPosition.x), static_cast<int>(targetPosition.y),
        static_cast<int>(targetPosition.z), skill.m_type, skill.m_param1
    );
}

void User::SendSystemMessageEquipItem(CItem* item) {
    L2_GUARD_FUNCTION();

    SlotType requestedSlot = ST_MAX;
    const std::uint64_t slotMask = static_cast<std::uint64_t>(item->m_data->m_Slot);
    for (int slot = ST_UNDERWEAR; slot < ST_MAX; ++slot) {
        if ((slotMask & (std::uint64_t{1} << slot)) != 0) {
            requestedSlot = static_cast<SlotType>(slot);
            break;
        }
    }
    const SlotType equippedSlot = IsEquiped(item->m_data->index, requestedSlot);

    const auto sendWithoutEnchant = [this, item](int messageId) {
        CUserSocket* const socket = GetSocket();
        const int hasVariation =
            item->m_itemOption.itemOptionKey.variationOption1 > 0 && item->m_itemOption.itemOptionKey.variationOption2 > 0;
        socket->Send("chccdc", 0x62, messageId, 1, 8, item->m_nClassId, hasVariation);
    };
    const auto sendWithEnchant = [this, item](int messageId) {
        CUserSocket* const socket = GetSocket();
        const int hasVariation =
            item->m_itemOption.itemOptionKey.variationOption1 > 0 && item->m_itemOption.itemOptionKey.variationOption2 > 0;
        const int enchantment = static_cast<int>(static_cast<std::int8_t>(item->m_data->GetEnchanted()));
        socket->Send("chccccdc", 0x62, messageId, 2, 0x13, enchantment, 8, item->m_nClassId, hasVariation);
    };

    if (equippedSlot == ST_AGATHION_MAIN) {
        if (item->m_data->GetEnchanted() < 1) {
            sendWithoutEnchant(SystemMessageId::PRIMARY_AGATHION_SUMMONED);
            sendWithoutEnchant(SystemMessageId::AGATHION_ALL_ABILITIES_ACTIVATED);
        } else {
            sendWithEnchant(SystemMessageId::ENCHANTED_PRIMARY_AGATHION_SUMMONED);
            sendWithEnchant(SystemMessageId::ENCHANTED_AGATHION_ALL_ABILITIES_ACTIVATED);
        }
        return;
    }
    if (equippedSlot >= ST_AGATHION_SUB1 && equippedSlot <= ST_AGATHION_SUB4) {
        if (item->m_data->GetEnchanted() < 1) {
            sendWithoutEnchant(SystemMessageId::SECONDARY_AGATHION_SUMMONED);
            sendWithoutEnchant(SystemMessageId::AGATHION_UNIQUE_ABILITY_ONLY_ACTIVATED);
        } else {
            sendWithEnchant(SystemMessageId::ENCHANTED_SECONDARY_AGATHION_SUMMONED);
            sendWithEnchant(SystemMessageId::ENCHANTED_AGATHION_UNIQUE_ABILITY_ONLY_ACTIVATED);
        }
        return;
    }
    if (item->m_data->GetEnchanted() < 1) {
        sendWithoutEnchant(SystemMessageId::EQUIPPED_ITEM);
    } else {
        sendWithEnchant(SystemMessageId::EQUIPPED_ENCHANTED_ITEM);
    }
}

void User::SendSystemMessageUnEquipItem(CItem* item, SlotType slot) {
    L2_GUARD_FUNCTION();

    const bool isAgathion = slot >= ST_AGATHION_MAIN && slot <= ST_AGATHION_SUB4;
    CUserSocket* const socket = GetSocket();
    const int hasVariation =
        item->m_itemOption.itemOptionKey.variationOption1 > 0 && item->m_itemOption.itemOptionKey.variationOption2 > 0;

    if (item->m_data->GetEnchanted() < 1) {
        socket->Send(
            "chccdc", 0x62, isAgathion ? SystemMessageId::NAMED_ITEM_POWER_SEALED : SystemMessageId::UNEQUIPPED_ITEM, 1, 8,
            item->m_nClassId, hasVariation
        );
        return;
    }

    socket->Send(
        "chccccdc", 0x62,
        isAgathion ? SystemMessageId::ENCHANTED_ITEM_POWER_SEALED : SystemMessageId::UNEQUIPPED_ENCHANTED_ITEM, 2, 0x13,
        static_cast<int>(static_cast<std::int8_t>(item->m_data->GetEnchanted())), 8, item->m_nClassId, hasVariation
    );
}

