int User::ValidateFactionLevel(int factionId) {
    L2_GUARD_FUNCTION();

    const std::uint32_t factionIndexBits = static_cast<std::uint32_t>(factionId) - 1U;
    const int factionIndex = runtime::Int32FromBits(factionIndexBits);
    const int previousLevel = m_data->m_nFactionLevel[factionIndex];
    if (factionIndexBits < 16U) {
        const std::uint64_t pointBits = static_cast<std::uint64_t>(m_data->m_nFactionPoint[factionIndex]);
        const int currentLevel =
            m_data->FindUpperBoundIndex(factionIndex, runtime::Int32FromBits(static_cast<std::uint32_t>(pointBits)));
        m_data->m_nFactionLevel[factionIndex] = currentLevel;
        return runtime::SubtractInt32Wrapping(currentLevel, previousLevel);
    }

    // Log.Add(
    //     LOG_ERROR,
    //     L"[%s][%d] Invalid Faction ID",
    //     L"User.cpp",
    //     0x820e)
    L2_LOG_ERROR(Log, u"[faction] Faction ID %d is outside the supported range.", factionId);
    return 0;
}

