void User::SetNeedUpdateFriendsInfo(FriendsEnum::Enum type, int worldId, unsigned int characterId) {
    if (type != FriendsEnum::FRIEND_LEVEL_CHANGED && type != FriendsEnum::FRIEND_CLASS_CHANGED) {
        return;
    }

    L2_GUARD(m_UpdateFriendsDequeLock);
    m_UpdateFriendsDeque.push_back(UpdateFriendData{type, worldId, characterId});
}

void User::UpdateFriendsInfo() {
    L2_GUARD_FUNCTION();

    CSPointer<CFriends> friends = GetFriends();
    if (!friends) {
        return;
    }

    std::deque<UpdateFriendData> updates;
    {
        L2_GUARD(m_UpdateFriendsDequeLock);
        updates = m_UpdateFriendsDeque;
        m_UpdateFriendsDeque.clear();
    }

    for (const UpdateFriendData& update : updates) {
        CSPointer<User> friendUser =
            g_UserDBIDMap.FindObject(std::CDualKey<int, int>(update.nWorldID, static_cast<int>(update.nDBID)));
        if (!friendUser) {
            continue;
        }

        if (update.eType == FriendsEnum::FRIEND_CLASS_CHANGED) {
            friends->UpdateFriendClass(update.nDBID, friendUser->GetClass());
            CUserSocket* const socket = GetSocket();
            if (socket != nullptr) {
                const int classId = friendUser->GetClass();
                const std::u16string packetName = std::u16string(friendUser->GetName());
                const std::u16string targetName{std::u16string_view(packetName)};
                socket->Send("cdSd", 0x59, FriendsEnum::FRIEND_CLASS_CHANGED, targetName.c_str(), classId);
            }
        } else if (update.eType == FriendsEnum::FRIEND_LEVEL_CHANGED) {
            friends->UpdateFriendLevel(update.nDBID, friendUser->Level());
            CUserSocket* const socket = GetSocket();
            if (socket != nullptr) {
                const int level = friendUser->Level();
                const std::u16string packetName = std::u16string(friendUser->GetName());
                const std::u16string targetName{std::u16string_view(packetName)};
                socket->Send("cdSd", 0x59, FriendsEnum::FRIEND_LEVEL_CHANGED, targetName.c_str(), level);
            }
        }
    }
}

