AtomicMonsterBookReward::AtomicMonsterBookReward(
    const std::int32_t userSid, const std::int32_t cardId, const std::int32_t cardLevel, const std::int32_t factionIndex
) :
    m_userSid(userSid), m_cardId(cardId), m_cardLevel(cardLevel), m_factionIndex(factionIndex) {
    // Current constructor is inlined into User::TryGetMonsterBookReward at
    // 0x00b6771f. Original physical owner is User.cpp.
    tmTime = runtime::crt::Time32Now();
    eType = AtomicType::MonsterBookReward;
    nLine = 0xd41;
}

bool User::CheckMonsterBookRewardJob() {
    // Current L2Server 0x00b15c84.
    L2_GUARD_FUNCTION();
    // Both variation and item jobs must be idle before giving the reward.
    return m_data->m_nPrivateStoreType < 1 && IsItemUsable(0) && !IsFrozen(true) &&
        m_pFishingController->m_FishingState == FISHINGS_NONE && m_pFishingController->m_bIsAutoFishing != true &&
        m_data->m_StopMode == STP_STAND && m_lWaitVariation != 1;
}

void User::TryGetMonsterBookReward(const int cardId) {
    // Current L2Server 0x00b67490, original owner User.cpp.
    L2_GUARD_FUNCTION();
    if (CheckMonsterBookRewardJob() && runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 1) != 1) {
        if (runtime::raw_atomic::CompareExchangeI32(&m_nChangeSubjobFlag, 1, 0) != 0) {
            runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
            SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_REWARD_DURING_CLASS_CHANGE);
            return;
        }

        const auto clearPendingFlags = [this]() {
            runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
            runtime::raw_atomic::ExchangeI32(&m_nChangeSubjobFlag, 0);
        };

        MonsterBook::Script::Card* const card = MonsterBook::Script::inst().GetCard(cardId);
        if (card == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[MonsterBook][TryGetMonsterBookReward]user[%s][%d] "
            //     L"req invalid card id[%d]",
            //     GetName(),
            //     GetDBID(),
            //     cardId)
            // L2_LOG_ERROR(Log,
            //     L"[monster book] Character '%s' (%u) requested reward for unknown card %d.",
            //     GetName(),
            //     GetDBID(),
            //     cardId)
            L2_LOG_ERROR(
                Log, u"[monster book] Character '%s' (%u) requested reward for unknown card %d.", GetName(), GetDBID(),
                cardId
            );
            clearPendingFlags();
            return;
        }

        const int requiredLevel = card->m_pFactionInfo->m_nRewardLevelBound;
        if (Level() < requiredLevel) {
            GetSocket()->Send(
                "chcch", 0x62, SystemMessageId::REWARD_MINIMUM_LEVEL_REQUIREMENT, 1, 0x15,
                static_cast<int>(static_cast<std::int16_t>(requiredLevel))
            );
            clearPendingFlags();
            return;
        }

        MonsterBook::UserCard& userCard = m_monsterBook.GetCard(cardId);
        const std::uint32_t cardLevel = static_cast<std::uint32_t>(userCard.m_nLevel);
        if (cardLevel > 3U) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[MonsterBook][TryReward] invalid card lev[%d] user[%d]",
            //     cardLevel,
            //     GetDBID())
            L2_LOG_ERROR(
                Log, u"[monster book] Character %u has invalid level %u for card %d; reward request rejected.", GetDBID(),
                cardLevel, cardId
            );
            clearPendingFlags();
            return;
        }

        if (userCard.m_nKillCount != card->m_pTrophyTable->GetKillCount(static_cast<int>(cardLevel))) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[MonsterBook][TryReward] invalid kill cnt[%d] user[%d]",
            //     userCard.m_nKillCount,
            //     GetDBID())
            L2_LOG_ERROR(
                Log,
                u"[monster book] Character %u has kill count %d for card %d, which does not match level %u reward "
                u"requirements.",
                GetDBID(), userCard.m_nKillCount, cardId, cardLevel
            );
            clearPendingFlags();
            return;
        }

        const int factionIndex = card->m_pFactionInfo != nullptr ? card->m_pFactionInfo->m_nFactionId : -1;
        AtomicJob* const job = new AtomicMonsterBookReward(m_data->m_nId, cardId, static_cast<int>(cardLevel), factionIndex);
        const std::vector<ItemAmountData>& rewardItems = card->m_reward.m_vItem[cardLevel];
        if (rewardItems.empty()) {
            job->Do();
            job->Destroy();
            return;
        }

        std::array<ItemManip, 100> requests{};
        int requestCount = 0;
        for (const ItemAmountData& reward : rewardItems) {
            ItemManip& request = requests[static_cast<std::size_t>(requestCount)];
            request.mClassId = reward.m_nItemClassId;
            request.mCount = reward.m_nItemAmount;
            ++requestCount;
        }

        CPacketHelperEx<20480> packet;
        L2_GUARD(m_ManipulateQueueLock);
        etcMsg message = SaveEtcMsg(false, false, 0, 0, 0, std::u16string(), std::u16string(), 0);
        message.nParamFirst = 4;
        ManipulateQueue queue = SaveManipulateQueue(
            ManipulateType::MANI_MONSTER_BOOK_REWARD, 0, requestCount, requests.data(), job, 0, packet, false,
            ItemGetReason::MonsterBook, message
        );

        const ManiItemResultType result = _SetManiItemJob(queue);
        if (result == MRT_NOJOB) {
            if (!_HandleItemManipulation(queue)) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[MonsterBook][%s][%d] ManiItemQueue fail",
                //     L"User.cpp",
                //     0x8199)
                // L2_LOG_ERROR(Log,
                //     L"[MonsterBook][%s][%d] ManiItemQueue fail",
                //     L"User.cpp",
                //     0x8199)
                L2_LOG_ERROR(
                    Log,
                    "[items] Manipulation failed for character %u, operation %d, request %d; requested item entries %d.",
                    static_cast<unsigned int>(GetDBID()), static_cast<int>(queue.eType), queue.nId, queue.nCount
                );
                SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_ITEM_INVENTORY_WEIGHT_OR_QUANTITY_EXCEEDED);
                job->Destroy();
                clearPendingFlags();
            }
        } else if (result == MRT_JOBMAP) {
            SendSystemMessage(SystemMessageId::PREVIOUS_REQUEST_NOT_COMPLETED);
            job->Destroy();
            clearPendingFlags();
        } else if (result == MRT_JOBNOTMAP) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue Insert",
            //     L"User.cpp",
            //     0x81ae)
            // Noise: normal deferral behind a pending item operation. Not a failure.
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue Insert",
            //     L"User.cpp",
            //     0x81ae)
        } else {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue ERROR",
            //     L"User.cpp",
            //     0x81b3)
            // L2_LOG_ERROR(Log,
            //     L"[NO_ERROR][%s][%d] ManiItemQueue ERROR",
            //     L"User.cpp",
            //     0x81b3)
            L2_LOG_ERROR(
                Log,
                "[items] Operation %d, request %d, character %u: unexpected queue result %d; item operation not started.",
                static_cast<int>(queue.eType), queue.nId, static_cast<unsigned int>(GetDBID()), static_cast<int>(result)
            );
            job->Destroy();
            clearPendingFlags();
        }
        return;
    }

    SendSystemMessage(SystemMessageId::CANNOT_RECEIVE_REWARDS_IN_CURRENT_STATE);
}

bool User::SendFactionInfoList(const int requestType) {
    // Current L2Server 0x00b4e404, original owner User.cpp.
    L2_GUARD_FUNCTION();
    protocol::S_EX_FACTION_INFO packet{};
    packet.nUserID = static_cast<std::int32_t>(Id());
    packet.nRequestType = static_cast<char>(requestType);
    for (int index = 0; index < 16; ++index) {
        const int factionId = index + 1;
        const int level = m_data->m_nFactionLevel[index];
        const std::int64_t point = m_data->m_nFactionPoint[index];
        if (level <= 0 && point <= 0) {
            continue;
        }
        protocol::FactionInfo info{};
        info.nFactionType = static_cast<char>(factionId);
        info.nFactionLevel = static_cast<char>(level);
        info.cIsLevelLimited = static_cast<char>(m_data->IsLevelLimited(factionId));
        info.fFactionRate = m_data->GetFactionPercentageForCurrentLevel(factionId);
        packet.lFactionInfoList.push_back(info);
    }
    GetSocket()->Send(S_EX, S_EX_FACTION_INFO, packet);
    return false;
}

void User::OnResponseLockedItem(const unsigned char* packet) {
    L2_GUARD_FUNCTION();

    std::int32_t result = 0;
    char lock = 0;
    protocol::S_EX_LOCKED_RESULT response{};
    packet = Disassemble(packet, "dc", &result, &lock);
    response.lock = lock;
    response.result = static_cast<char>(result);

    if (response.result == 0) {
        SetPendingUseETCItem(nullptr, PUIT_HLOCKED);
        GetSocket()->Send(static_cast<S_PROTOCOL>(0xfe), static_cast<S_EX_PROTOCOL>(0x1f8), response);
        runtime::raw_atomic::ExchangeI32(&m_lWaitVariation, 0);
        return;
    }

    std::int32_t scrollItemSid = 0;
    std::int32_t targetItemSid = 0;
    Disassemble(packet, "dd", &scrollItemSid, &targetItemSid);

    CItem* const scrollItem = m_inv.GetByServerID(scrollItemSid);
    CItem* const targetItem = m_inv.GetByServerID(targetItemSid);
    if (scrollItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] OnResponseLockedItem ScrollItem is nullptr ItemSID[%d]",
        //     L"User.cpp",
        //     0x7f86,
        //     scrollItemSid)
        L2_LOG_ERROR(Log, u"[item lock] Scroll item %d is missing from inventory.", scrollItemSid);
    }
    if (targetItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] OnResponseLockedItem pTargetItem is nullptr ItemSID[%d]",
        //     L"User.cpp",
        //     0x7f8b,
        //     targetItemSid)
        L2_LOG_ERROR(Log, u"[item lock] Target item %d is missing from inventory.", targetItemSid);
    }

    const bool deleteScrollItem = [&] {
        L2_WRITE_GUARD(m_inv);
        bool deleteScrollItem = false;
        if (scrollItem->AddAmount(-1)) {
            if (scrollItem->m_data->m_nCount == 0) {
                m_inv.Pop(scrollItem->m_data->index, false);
                m_inv.SetInventoryChanged(scrollItem, IUT_DELETE);
                deleteScrollItem = true;
            } else {
                m_inv.SetInventoryChanged(scrollItem, IUT_UPDATE);
            }
        }
        targetItem->m_data->SetLocked(lock == 0 ? 1 : 0);
        m_inv.SetInventoryChanged(targetItem, IUT_UPDATE);

        return deleteScrollItem;
    }();

    if (deleteScrollItem) {
        scrollItem->Delete();
    }
    SendItemList(true, true, nullptr);
    SetPendingUseETCItem(nullptr, PUIT_HLOCKED);
    runtime::raw_atomic::ExchangeI32(&m_lWaitVariation, 0);
    GetSocket()->Send(static_cast<S_PROTOCOL>(0xfe), static_cast<S_EX_PROTOCOL>(0x1f8), response);
}

void User::OnResponseUpgradeSystem(const unsigned char* packet) {
    // Current L2Server 0x00b4e5f0, original owner User.cpp.
    L2_GUARD_FUNCTION();

    protocol::S_EX_UPGRADE_SYSTEM_RESULT response;
    response.nID = 0;
    packet = Disassemble(packet, "d", &response.nResult);
    if (response.nResult == 0) {
        response.nID = 0x1179;
        GetSocket()->Send(S_EX, S_EX_UPGRADE_SYSTEM_RESULT, response);
        runtime::raw_atomic::ExchangeI32(&m_lWaitVariation, 0);
        return;
    }

    packet = Disassemble(packet, "d", &response.nID);
    CItem* upgradeItem = m_inv.GetByServerID(response.nID);
    if (upgradeItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] OnResponseUpgradeSystem UpgradeItem is nullptr ItemSID[%d]",
        //     L"User.cpp",
        //     0x7fd4,
        //     response.nID)
        L2_LOG_ERROR(Log, u"[item upgrade] Source item %d is missing from inventory.", response.nID);
    } else if (UnequipItem(upgradeItem, true) != ST_NONE) {
        {
            L2_WRITE_GUARD(m_inv);
            m_inv.Pop(upgradeItem->m_data->index, false);
            m_inv.SetInventoryChanged(upgradeItem, IUT_DELETE);
        }
        if (upgradeItem->IsPeriodicShapeShiftedItem(this)) {
            OnRestorePeriodicShapeShiftedItem(upgradeItem);
        }
        upgradeItem->Delete();
    }

    std::int32_t materialCount = 0;
    packet = Disassemble(packet, "d", &materialCount);
    std::int32_t materialClassId = 0;
    std::int64_t materialAmount = 0;
    for (std::int32_t index = 0; index < materialCount; ++index) {
        packet = Disassemble(packet, "dQ", &materialClassId, &materialAmount);
        CItem* const materialItem = m_inv.GetFirstItemByClassID(materialClassId, false, false);
        if (materialItem == nullptr) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] OnResponseUpgradeSystem MaterialItem is nullptr ItemClassID[%d]",
            //     L"User.cpp",
            //     0x8008,
            //     materialClassId)
            L2_LOG_ERROR(
                Log, u"[item upgrade] Material item class %d is missing from inventory; entry skipped.", materialClassId
            );
            continue;
        }

        const bool deleteMaterial = [&] {
            L2_WRITE_GUARD(m_inv);
            bool deleteMaterial = false;
            if (materialItem->AddAmount(runtime::NegateInt64Wrapping(materialAmount))) {
                if (materialItem->m_data->m_nCount == 0) {
                    m_inv.Pop(materialItem->m_data->index, false);
                    m_inv.SetInventoryChanged(materialItem, IUT_DELETE);
                    deleteMaterial = true;
                } else {
                    m_inv.SetInventoryChanged(materialItem, IUT_UPDATE);
                }
            }

            return deleteMaterial;
        }();
        if (deleteMaterial) {
            materialItem->Delete();
        }
    }

    std::int64_t adenaAmount = 0;
    packet = Disassemble(packet, "Q", &adenaAmount);
    CItem* const adena = m_inv.GetByDBID(m_inv.GetAdenaDBID());
    if (adena == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] OnResponseUpgradeSystem Adena is nullptr",
        //     L"User.cpp",
        //     0x802d)
        L2_LOG_ERROR(Log, u"[item upgrade] Adena item is missing from inventory.");
    } else {
        const bool deleteAdena = [&] {
            L2_WRITE_GUARD(m_inv);
            bool deleteAdena = false;
            if (adena->AddAmount(runtime::NegateInt64Wrapping(adenaAmount))) {
                if (adena->m_data->m_nCount == 0) {
                    m_inv.Pop(adena->m_data->index, false);
                    m_inv.SetInventoryChanged(adena, IUT_DELETE);
                    deleteAdena = true;
                } else {
                    m_inv.SetInventoryChanged(adena, IUT_UPDATE);
                }
            }

            return deleteAdena;
        }();
        if (deleteAdena) {
            adena->Delete();
        }
    }

    std::uint32_t resultAmount = 0;
    std::int32_t resultItemClassId = 0;
    std::int32_t resultEnchant = 0;
    packet = Disassemble(packet, "ddd", &resultAmount, &resultItemClassId, &resultEnchant);
    CItem* const resultItem = g_ObjectDB.CreateItem(resultItemClassId);
    if (resultItem == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] OnResponseUpgradeSystem ResultItem is nullptr ItemClassID[%d]",
        //     L"User.cpp",
        //     0x8051,
        //     resultItemClassId)
        L2_LOG_ERROR(Log, u"[item upgrade] Result item class %d could not be created.", resultItemClassId);
        response.nResult = 0;
        response.nID = 0;
    } else {
        std::int32_t variationOption1 = 0;
        std::int32_t variationOption2 = 0;
        std::uint32_t intensiveItemClassId = 0;
        BaseAttribute attribute{};
        std::int32_t shapeShiftClassId = 0;
        std::map<int, EnsoulOptionData*> ensoulOptions[3];
        std::int32_t shapeShiftPeriod = 0;

        packet = Disassemble(packet, "ddd", &variationOption1, &variationOption2, &intensiveItemClassId);
        packet = CItem::DisassembleAttribute(packet, attribute);
        packet = CItem::DisassembleShapeShift(packet, shapeShiftClassId);
        packet = Disassemble(packet, "d", &shapeShiftPeriod);
        CItem::DisassembleEnsoul(packet, ensoulOptions);

        resultItem->SetDBID(resultAmount);
        resultItem->SetEnchanted(resultEnchant);
        ItemOptionKey optionKey{};
        optionKey.variationOption1 = variationOption1;
        optionKey.variationOption2 = variationOption2;
        resultItem->SetVariation(optionKey, intensiveItemClassId);
        resultItem->SetAttribute(attribute);
        resultItem->SetShapeShiftingClassId(shapeShiftClassId);
        resultItem->SetEnsoulOptionData(ensoulOptions, true);
        if (!m_inv.Push(resultItem->m_data->index)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] OnResponseUpgradeSystem ResultItem Push Error index[%d]",
            //     L"User.cpp",
            //     0x806f,
            //     resultItem->m_data->index)
            L2_LOG_ERROR(
                Log, u"[item upgrade] Result item index %d could not be inserted into inventory.", resultItem->m_data->index
            );
        }
        m_inv.SetInventoryChanged(resultItem, IUT_ADD);
        if (shapeShiftPeriod >= 0) {
            OnGetPeriodicShapeShiftedItem(resultItem, shapeShiftPeriod);
            SendPeriodicShapeShiftedItemList();
        }
        response.nID = resultItem->m_data->m_nClassID;
    }

    SendItemList(true, true, nullptr);
    runtime::raw_atomic::ExchangeI32(&m_lWaitVariation, 0);
    GetSocket()->Send(S_EX, S_EX_UPGRADE_SYSTEM_RESULT, response);

    class CTLMGatherUserIdInDist final : public CTLMFunc {
    public:
        explicit CTLMGatherUserIdInDist(std::set<unsigned int>& userIds) : userIds_(userIds) {}

        bool CanDo(CObject* object, double) override {
            if (object->IsCreature() && !object->IsDeleting() && object->m_Deleted == 0) {
                userIds_.insert(object->Id());
            }
            return true;
        }

    private:
        std::set<unsigned int>& userIds_;
    };

    const FVector position = GetPos();
    std::set<unsigned int> userIds;
    CTLMGatherUserIdInDist gather(userIds);
    CTLMFilterDist filter(static_cast<int>(GetInZoneID()), position, static_cast<double>(GetBroadcastDist(0x1000)));
    FOR_ALL_NEIGHBOR_CREATURE_DIST(&filter, &gather);
    BroadcastWithConstBuffer(userIds, "chccScd", 0x62, 0x1178, 2, 0x0c, GetName(), 3, resultItemClassId);
    ValidateSetItem(ST_MAX);
    ValidateNewSetItem();
    ValidateShapeShiftedSetItem();
    ValidateChanged(VB_MAX);
    ValidateParameters(VB_MAX, false);
    m_data->m_NeedUpdatePacketBitSet.SetBit(0x49);
    ParamChanged(std::int64_t{PCB_CHAR_SHAPESHIFT});
}

