// User::OnActionPacket@0x00b624c8.
bool User::OnActionPacket(const int objectId, const bool shiftPressed) {
    L2_GUARD_FUNCTION();
    const std::uint32_t objectBits = static_cast<std::uint32_t>(objectId);
    // if (((objectBits >> 27U) - 4U) < 12U) {
    if (((objectBits >> CLASS_SHIFT) - SCLS_MIN) < (SCLS_MAX - SCLS_MIN)) {
        if (objectId == -1 || objectId == 0) {
            g_invalidActionObjectCount = runtime::AddInt32Wrapping(g_invalidActionObjectCount, 1);
        } else {
            CObject* const object = CObject::GetObjectW(objectBits);
            if (object != nullptr && !m_bIsRestarting) {
                SetAvoidAgroFalse();
                Action(object, false, shiftPressed);
                return false;
            }
        }
    } else {
        LogAbnormalAction(AUA_INVALID_SERVER_ID, true, 0, 0, 0, 0);
    }
    // ActionFailed(0)
    ActionFailed(AF_DEFAULT);
    return false;
}

bool User::OnMoveToLocationPacket(int targetX, int targetY, int targetZ, int originX, int originY, int originZ, int) {
    // Current L2Server 0x00b625fc.
    L2_GUARD_FUNCTION();
    if (runtime::runtime_timing::Matches(this)) {
        runtime::runtime_timing::Record(
            "user_move_ingress", this, nullptr,
            "target=%d,%d,%d origin=%d,%d,%d current_action=%d "
            "next_action=%d active=%d alive=%d can_act=%d "
            "block_move=%d can_move=%d stop_mode=%d",
            targetX, targetY, targetZ, originX, originY, originZ, static_cast<int>(GetController()->GetCurrentActionType()),
            static_cast<int>(GetController()->GetNextActionType()), m_data->m_bIsActive ? 1 : 0,
            m_data->m_bIsAlive != 0 ? 1 : 0, m_SkillMod.m_bCanAct ? 1 : 0, m_SkillMod.m_nBlockMoveCount,
            m_data->m_bCanMove ? 1 : 0, static_cast<int>(m_data->m_StopMode)
        );
    }
    if (IsFrozen(true)) {
        if (runtime::runtime_timing::Matches(this)) {
            runtime::runtime_timing::Record(
                "user_move_reject_frozen", this, nullptr, "target=%d,%d,%d", targetX, targetY, targetZ
            );
        }
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_ACT_WHILE_FROZEN);
        return false;
    }
    if (m_PledgeGameUser.IsWaiting()) {
        if (runtime::runtime_timing::Matches(this)) {
            runtime::runtime_timing::Record(
                "user_move_reject_pledge_wait", this, nullptr, "target=%d,%d,%d", targetX, targetY, targetZ
            );
        }
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_MOVE_IN_CURRENT_STATE);
        return false;
    }
    if (m_bIsRestarting) {
        if (runtime::runtime_timing::Matches(this)) {
            runtime::runtime_timing::Record(
                "user_move_reject_restarting", this, nullptr, "target=%d,%d,%d", targetX, targetY, targetZ
            );
        }
        return false;
    }

    const FVector current = GetPos();
    if (m_bShowClickPos) {
        char16_t message[0x400]{};
        FormatUtf16To(
            message, std::size(message), u"click (%d, %d, %d)->(%d, %d, %d)", static_cast<int>(current.x),
            static_cast<int>(current.y), static_cast<int>(current.z), targetX, targetY, targetZ
        );
        SendSystemMessage(u"SYS", message);
    }

    if (m_bInstantMoveReady) {
        m_bInstantMoveReady = false;
        TeleportToLocation(
            targetX, targetY, runtime::AddInt32Wrapping(targetZ, 0x28), GetInZoneID(), 0x10000,
            TeleportSourceType::UserOnMoveToLocationPacket, nullptr, 0
        );
        return false;
    }

    if (m_bFindDistanceReady) {
        const double x = current.x - static_cast<double>(targetX);
        const double y = current.y - static_cast<double>(targetY);
        const double z = current.z - static_cast<double>(targetZ);
        char16_t message[0x100]{};
        FormatUtf16To(
            message, std::size(message), u"(%d, %d, %d)->(%d, %d, %d) distance : %d", static_cast<int>(current.x),
            static_cast<int>(current.y), static_cast<int>(current.z), targetX, targetY, targetZ,
            static_cast<int>(std::sqrt(x * x + y * y + z * z))
        );
        SendSystemMessage(u"SYS", message);
        m_bFindDistanceReady = false;
        // ActionFailed(0)
        ActionFailed(AF_DEFAULT);
        return false;
    }

    if (m_data->m_moveType == CMT_FLY && !IsRidingWyvern()) {
        targetZ = std::clamp(targetZ, -1000, 6000);
        originZ = std::clamp(originZ, -1000, 6000);
    }

    CGeoData* const geo = CWorld::Inst().GetGeo();
    const auto zoneFor = [geo](int x, int y) {
        return geo->GetZone(
            (runtime::AddInt32Wrapping(x, 0x50000) >> 15) + 10, (runtime::AddInt32Wrapping(y, 0x40000) >> 15) + 10
        );
    };
    const bool targetValid = zoneFor(targetX, targetY) != nullptr;
    const bool originValid = zoneFor(originX, originY) != nullptr;

    if (m_ShowPosTarget != 0) {
        std::vector<FVector> points;
        points.push_back(targetValid ? FVector{targetX, targetY, targetZ} : FVector{originX, originY, originZ});
        ShowTraceEmiter(0, points, 30000);
    }

    SetAvoidAgroFalse();
    if (!targetValid) {
        if (!originValid) {
            if (runtime::runtime_timing::Matches(this)) {
                runtime::runtime_timing::Record(
                    "user_move_reject_invalid_geo", this, nullptr, "target=%d,%d,%d origin=%d,%d,%d", targetX, targetY,
                    targetZ, originX, originY, originZ
                );
            }
            LogAbnormalAction(AUA_TRY_TO_INVALID_TELEPORT, true, 0, 0, 0, 0);
            return false;
        }
        targetX = originX;
        targetY = originY;
        targetZ = originZ;
    }
    if (runtime::runtime_timing::Matches(this)) {
        runtime::runtime_timing::Record(
            "user_move_forward", this, nullptr, "target=%d,%d,%d target_valid=%d origin_valid=%d pathfind=%d", targetX,
            targetY, targetZ, targetValid ? 1 : 0, originValid ? 1 : 0, static_cast<int>(UsePathFind)
        );
    }
    MoveToLocation(targetX, targetY, targetZ, UsePathFind);
    return false;
}

bool User::OnRequestUserCommand(const int command) {
    // Current L2Server 0x00b57350.
    L2_GUARD_FUNCTION();
    CUserSocket* const socket = GetSocket();
    if (socket == nullptr) {
        return true;
    }

    switch (command) {
        case 0: {
            const FVector position = m_data->m_Pos;
            const int restartPoint = Singleton<CSetting>::inst().GetRestartPointSys(RT_HUMAN, position, 2);
            socket->Send(
                "chccdcdcd", 0x62, static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(restartPoint))), 3,
                1, runtime::Win64CvttDoubleToInt32(position.x), 1, runtime::Win64CvttDoubleToInt32(position.y), 1,
                runtime::Win64CvttDoubleToInt32(position.z)
            );
            break;
        }

        case 0x34: {
            if (IsInAirShip() || HasFlagOfSiege()) {
                break;
            }

            SkillUseInfo skill;
            skill.m_skillID = 0x833;
            skill.m_skillLevel = 1;
            skill.m_skillSubLevel = 0;
            skill.m_castRange = 0;
            skill.m_type = 0;
            skill.m_param1 = 0;

            if (g_nEscapeMode == 1) {
                const FVector shelter = GetShelterPos();
                if (!shelter.IsZero()) {
                    TeleportToLocation(
                        runtime::Win64CvttDoubleToInt32(shelter.x), runtime::Win64CvttDoubleToInt32(shelter.y),
                        runtime::Win64CvttDoubleToInt32(shelter.z), GetInZoneID(), 0x10000,
                        TeleportSourceType::OnRequestUserCommand, nullptr, 0
                    );
                    break;
                }
            } else if (g_nEscapeMode == 2) {
                break;
            } else if (g_nEscapeMode == 3) {
                SendSystemMessage(SystemMessageId::UNSTUCK_COMMAND_UNAVAILABLE_SUBMIT_PETITION);
                break;
            } else if (g_nEscapeMode != 4) {
                break;
            }

            if (m_pWOlympiadUser->IsPlayer()) {
                socket->SendSystemMessage(SystemMessageId::SKILL_CANNOT_BE_USED_IN_OLYMPIAD);
            } else if (m_PledgeGameUser.IsPlayer()) {
                socket->SendSystemMessage(SystemMessageId::SKILL_CANNOT_BE_USED_IN_MATCH);
            } else {
                GetController()->Skill(skill, false, true, 0);
            }
            break;
        }

        case 0x3d:
            if (!IsRiding()) {
                BasicAction(STUA_RIDE, false, true, STP_MAX);
            }
            break;

        case 0x3e:
            if (IsRiding()) {
                BasicAction(STUA_RIDE, false, true, STP_MAX);
            }
            break;

        case 0x4d: {
            const int time = g_L2Time.GetTime();
            const int hour = (time / 60) % 24;
            const int minute = time % 60;
            std::array<char16_t, 32> fullTime{};
            std::array<char16_t, 3> hourText{};
            std::array<char16_t, 3> minuteText{};
            FormatUtf16To(fullTime.data(), fullTime.size(), u"%02d:%02d", hour, minute);
            FormatUtf16To(hourText.data(), hourText.size(), u"%02d", hour);
            FormatUtf16To(minuteText.data(), minuteText.size(), u"%02d", minute);
            socket->Send(
                "chccScS", 0x62,
                g_L2Time.m_bIsNight ? SystemMessageId::CURRENT_NIGHTTIME_HOUR_AND_MINUTE
                                    : SystemMessageId::CURRENT_DAYTIME_HOUR_AND_MINUTE,
                2, 0, hourText.data(), 0, minuteText.data()
            );
            break;
        }

        case 0x51: {
            socket->SendSystemMessage(SystemMessageId::PARTY_INFORMATION_HEADING);
            CParty* const party = GetParty();
            if (party != nullptr) {
                int routingMessage = 0;
                switch (party->GetRoutingType()) {
                    case IRT_PICKER_FIRST:
                        routingMessage = SystemMessageId::LOOTING_METHOD_FINDERS_KEEPERS;
                        break;
                    case IRT_RANDOMLY:
                        routingMessage = SystemMessageId::LOOTING_METHOD_RANDOM;
                        break;
                    case IRT_RANDOMLY_INCLUDING_SPOIL:
                        routingMessage = SystemMessageId::LOOTING_METHOD_RANDOM_INCLUDING_SPOIL;
                        break;
                    case IRT_ORDERLY:
                        routingMessage = SystemMessageId::LOOTING_METHOD_BY_TURN;
                        break;
                    case IRT_ORDERLY_INCLUDING_SPOIL:
                        routingMessage = SystemMessageId::LOOTING_METHOD_BY_TURN_INCLUDING_SPOIL;
                        break;
                    default:
                        break;
                }
                if (routingMessage != 0) {
                    socket->SendSystemMessage(routingMessage);
                }
            }
            socket->SendSystemMessage(SystemMessageId::PARTY_INFORMATION_FOOTER);
            break;
        }

        case 0x58: {
            CPledge* const pledge = GetPledge();
            if (pledge == nullptr) {
                socket->SendSystemMessage(SystemMessageId::NOT_IN_CLAN);
                break;
            }
            std::vector<CPledge*> declared;
            pledge->GetBothDeclareList(declared);
            if (declared.empty()) {
                socket->SendSystemMessage(SystemMessageId::NO_OUTGOING_CLAN_WAR_DECLARATIONS);
                break;
            }
            socket->SendSystemMessage(SystemMessageId::OUTGOING_CLAN_WAR_DECLARATIONS_HEADING);
            for (CPledge* const enemy : declared) {
                CAlliance* const alliance = enemy->GetAlliance();
                if (alliance == nullptr) {
                    socket->SendSystemMessage_S(
                        SystemMessageId::CLAN_WITH_NO_ALLIANCE_ENTRY, std::u16string(enemy->GetPledgeName()).c_str()
                    );
                } else {
                    socket->Send(
                        "chccScS", 0x62, SystemMessageId::CLAN_AND_ALLIANCE_ENTRY, 2, 0, enemy->GetPledgeName(), 0,
                        alliance->m_data->m_sAllianceName
                    );
                }
            }
            socket->SendSystemMessage(SystemMessageId::ALLIANCE_OR_CLAN_WAR_LIST_FOOTER);
            break;
        }

        case 0x59: {
            CPledge* const pledge = GetPledge();
            if (pledge == nullptr) {
                socket->SendSystemMessage(SystemMessageId::NOT_IN_CLAN);
                break;
            }
            std::vector<CPledge*> targeted;
            pledge->GetTargetedList(targeted);
            if (targeted.empty()) {
                socket->SendSystemMessage(SystemMessageId::NO_INCOMING_CLAN_WAR_DECLARATIONS);
                break;
            }
            socket->SendSystemMessage(SystemMessageId::INCOMING_CLAN_WAR_DECLARATIONS_HEADING);
            for (CPledge* const enemy : targeted) {
                CAlliance* const alliance = enemy->GetAlliance();
                if (alliance == nullptr) {
                    socket->SendSystemMessage_S(
                        SystemMessageId::CLAN_WITH_NO_ALLIANCE_ENTRY, std::u16string(enemy->GetPledgeName()).c_str()
                    );
                } else {
                    socket->Send(
                        "chccScS", 0x62, SystemMessageId::CLAN_AND_ALLIANCE_ENTRY, 2, 0, enemy->GetPledgeName(), 0,
                        alliance->m_data->m_sAllianceName
                    );
                }
            }
            socket->SendSystemMessage(SystemMessageId::ALLIANCE_OR_CLAN_WAR_LIST_FOOTER);
            break;
        }

        case 0x5a: {
            CPledge* const pledge = GetPledge();
            if (pledge == nullptr) {
                socket->SendSystemMessage(SystemMessageId::NOT_IN_CLAN);
                break;
            }
            std::vector<CPledge*> declared;
            pledge->GetBothDeclareList(declared);
            if (declared.empty()) {
                socket->SendSystemMessage(SystemMessageId::NO_MUTUAL_CLAN_WAR_DECLARATIONS);
                break;
            }
            socket->SendSystemMessage(SystemMessageId::MUTUAL_CLAN_WARS_HEADING);
            for (CPledge* const enemy : declared) {
                CAlliance* const alliance = enemy->GetAlliance();
                if (alliance == nullptr) {
                    socket->SendSystemMessage_S(
                        SystemMessageId::CLAN_WITH_NO_ALLIANCE_ENTRY, std::u16string(enemy->GetPledgeName()).c_str()
                    );
                } else {
                    socket->Send(
                        "chccScS", 0x62, SystemMessageId::CLAN_AND_ALLIANCE_ENTRY, 2, 0, enemy->GetPledgeName(), 0,
                        alliance->m_data->m_sAllianceName
                    );
                }
            }
            socket->SendSystemMessage(SystemMessageId::ALLIANCE_OR_CLAN_WAR_LIST_FOOTER);
            break;
        }

        case 0x5d: {
            CMultiPartyCommandChannelManager manager;
            CSPointer<User> self(this, ObjectRefType::FunctionChain);
            manager.Close(self);
            break;
        }

        case 0x60: {
            CMultiPartyCommandChannelManager manager;
            CSPointer<User> self(this, ObjectRefType::FunctionChain);
            manager.Withdraw(self);
            break;
        }

        case 0x61: {
            CMultiPartyCommandChannelManager manager;
            CSPointer<User> self(this, ObjectRefType::FunctionChain);
            manager.Identify(self);
            break;
        }

        case 99: {
            CPledge* const pledge = GetPledge();
            if ((m_data->m_nPledgeType == 1 || m_data->m_nPledgeType == 2) && IsPledgeMaster() && pledge != nullptr) {
                pledge->SendWarReport(socket);
            } else {
                socket->SendSystemMessage(SystemMessageId::SIEGE_USE_REQUIRES_NOBLESSE_OR_EXALTED_CLAN_LEADER);
            }
            break;
        }

        case 100: {
            CPledgePenaltyViewer viewer(this);
            viewer.Show();
            break;
        }

        case 0x66:
            socket->ShowFatigueStatus_china();
            break;

        case 0x6d: {
            User* target = m_spTarget.GetUser();
            if (target == nullptr) {
                target = this;
            }
            CSPointer<User> targetPointer(target, ObjectRefType::FunctionChain);

            if (!WOlympiadStuff::IsAllowedUser(targetPointer)) {
                socket->SendSystemMessage(SystemMessageId::COMMAND_REQUIRES_TARGET_WORLD_OLYMPIAD_ELIGIBILITY);
            } else if (!Singleton<WOlympiadServiceConfig>::inst().IsHost()) {
                SharedNoblessInfo* const nobless = target->GetNoblessInfo();
                if (nobless != nullptr) {
                    socket->Send(
                        "chcchchchcd", 0x62, SystemMessageId::CURRENT_OLYMPIAD_RECORD_AND_POINTS, 4, 0x15,
                        static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(nobless->nMatchCount))), 0x15,
                        static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(nobless->nOlympiadWinCount))),
                        0x15,
                        static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(nobless->nOlympiadLoseCount))),
                        1, nobless->nOlympiadPoint
                    );
                }
                CSPointer<User> self(this, ObjectRefType::FunctionChain);
                Singleton<WOlympiadServiceProxy>::inst().SendMatchCountToUser(self, targetPointer);
            } else {
                // Log.Add(
                //     LOG_ERROR,
                //     const_cast<wchar_t*>(
                //         L"[WORLD_OLYMPIAD][%s][%d]NOT IMPLEMENTED!!!!!"),
                //     L"User.cpp",
                //     0x5230)
                L2_LOG_ERROR(Log, u"[world Olympiad] Host-side record lookup is not implemented for this request.");
            }

            if (Singleton<WOlympiadServiceConfig>::inst().IsHost()) {
                SendSystemMessage(SystemMessageId::CANNOT_OPEN_OLYMPIAD_WINDOW_WHILE_PARTICIPATING_OR_OBSERVING);
            } else {
                CSPointer<User> self(this, ObjectRefType::FunctionChain);
                Singleton<WOlympiadServiceProxy>::inst().SendOlympiadRecordTo(self);
            }
            break;
        }

        case 0x6e:
            if (m_data->m_nPledgeID != 0) {
                db.RequestAcademyGraduateList(*this, m_data->m_nPledgeID);
            }
            break;

        case 0x72: {
            CGeneralObject* const object =
                CGeneralObject::GetObjectW(static_cast<std::uint32_t>(m_nAssociatedInstantZoneId));
            CInstantZone* instantZone = nullptr;
            if (object != nullptr && object->IsInZone()) {
                instantZone = object->CastInZone();
            }
            if (instantZone != nullptr && instantZone->m_nTypeId != 0) {
                socket->Send(
                    "chcch", 0x62, SystemMessageId::CURRENT_INSTANCE_NAME, 1, 10,
                    static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(instantZone->m_nTypeId)))
                );
            }

            InZoneRestrictionMap restrictions;
            GroupInZoneRestrictionMap groupRestrictions;
            GetAllInZoneRestriction(restrictions, &groupRestrictions);

            for (const auto& entry : groupRestrictions) {
                socket->Send(
                    "chcchchch", 0x62, SystemMessageId::NAMED_FEATURE_USE_COUNT_AND_LIMIT, 3, 10,
                    static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(entry.first))), 0x15,
                    static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(entry.second.max))), 0x15,
                    static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(entry.second.current)))
                );
            }

            if (restrictions.empty()) {
                SendSystemMessage(SystemMessageId::NO_INSTANCE_REENTRY_RESTRICTIONS);
                break;
            }

            SendSystemMessage(SystemMessageId::INSTANCE_REENTRY_RESTRICTIONS_HEADING);
            for (const auto& entry : restrictions) {
                const int secondsWithinHour = entry.second % 3600;
                int minuteValue = secondsWithinHour / 60;
                if (secondsWithinHour % 60 > 0) {
                    ++minuteValue;
                }
                const std::int8_t minutes = runtime::Int8FromBits(static_cast<std::uint8_t>(minuteValue));
                const std::int16_t hours = runtime::Int16FromBits(static_cast<std::uint16_t>(entry.second / 3600));
                socket->Send(
                    "chcchchcc", 0x62, SystemMessageId::INSTANCE_AVAILABLE_AFTER_HOURS_AND_MINUTES, 3, 10,
                    static_cast<int>(runtime::Int16FromBits(static_cast<std::uint16_t>(entry.first))), 0x15,
                    static_cast<int>(hours), 0x14, static_cast<int>(minutes)
                );
            }
            break;
        }

        case 0x7e: {
            CUserSocket* const currentSocket = GetSocket();
            const std::int8_t day = runtime::Int8FromBits(static_cast<std::uint8_t>(m_data->m_tCreateDate.wDay));
            const std::int8_t month = runtime::Int8FromBits(static_cast<std::uint8_t>(m_data->m_tCreateDate.wMonth));
            const std::uint16_t year = m_data->m_tCreateDate.wYear;
            const char16_t* const name = GetName();
            currentSocket->Send(
                "chccScdcccc", 0x62, SystemMessageId::CHARACTER_BIRTH_DATE, 4, 0x0c, name, 0x11, static_cast<int>(year),
                0x14, static_cast<int>(month), 0x14, static_cast<int>(day)
            );
            break;
        }

        default:
            break;
    }

    return false;
}

bool User::OnRequestAcquireSkillPacket(
    const int skillId, const int packedSkillLevel, const EtcSkillAcquireType acquireType, const std::uint8_t*
) {
    // Current L2Server 0x00b62b3c.
    L2_GUARD_FUNCTION();
    GuardHelper requestGuard(L"RequestAcquireSkill 1", CThreadManager::GetThreadID());

    const std::uint32_t packedBits = static_cast<std::uint32_t>(packedSkillLevel);
    const int skillLevel = static_cast<int>(packedBits & 0xffffU);
    const std::uint32_t subLevelBits = packedBits >> 16U;
    int skillSubLevel = subLevelBits <= 0x7fffU ? static_cast<int>(subLevelBits) : static_cast<int>(subLevelBits) - 0x10000;

    if (!IsMatchAcquireSkillListSendClass(acquireType)) {
        if (acquireType < ESAT_NORMAL || acquireType >= ESAT_MAX) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d][SkillAcquirePacket][%d][%d][%d][%d]",
            //     L"User.cpp",
            //     0x4b60,
            //     skillId,
            //     skillLevel,
            //     skillSubLevel,
            //     static_cast<int>(acquireType))
            L2_LOG_ERROR(
                Log, u"[skill acquisition] Invalid request: skill %d, level %d, sublevel %d, acquisition type %d.", skillId,
                skillLevel, skillSubLevel, static_cast<int>(acquireType)
            );
        }
        return false;
    }

    if (GetController()->GetCurrentActionType() == ACT_SKILL) {
        return false;
    }

    if (acquireType == ESAT_NORMAL) {
        const int acquiredSubLevel = GetAcquiredSkillSubLevel(skillId);
        if (skillSubLevel != acquiredSubLevel) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] sublev diff id[%d] lev[%d] "
            //     L"org[%d] packet[%d]",
            //     L"User.cpp",
            //     0x4b8b,
            //     skillId,
            //     skillLevel,
            //     acquiredSubLevel,
            //     skillSubLevel)
            L2_LOG_ERROR(
                Log, u"[skill acquisition] Skill %d level %d sublevel mismatch: acquired %d, packet %d.", skillId,
                skillLevel, acquiredSubLevel, skillSubLevel
            );
            skillSubLevel = acquiredSubLevel;
        }
    } else {
        CNPC* const talkTarget = m_spTalkTarget.GetNPC();
        if (talkTarget == nullptr) {
            LogAbnormalAction(AUA_INVALID_NPC_OR_CHANNEL, false, 0, 0, 0, 0);
            return true;
        }

        if (!TalkChannelCache::inst().mChannels[0].IsValidChannel(Id(), m_spTalkTarget.Sid(), 0xfa, 0)) {
            LogAbnormalAction(AUA_INVALID_NPC_OR_CHANNEL, false, 0, 0, 0, 0);
            return false;
        }

        if (skillSubLevel != 0) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] sublev diff id[%d] lev[%d] sublev[%d]",
            //     L"User.cpp",
            //     0x4b82,
            //     skillId,
            //     skillLevel,
            //     skillSubLevel)
            L2_LOG_ERROR(
                Log, u"[skill acquisition] Skill %d level %d has unexpected sublevel %d.", skillId, skillLevel, skillSubLevel
            );
        }
    }

    SkillAcquireInfo* const acquireInfo =
        g_SkillAcquireDB.GetSkillAcquireInfo(acquireType, m_data->m_nClass, skillId, skillLevel);
    if (acquireInfo == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] hacking? user[%s] class[%d] "
        //     L"skill_id[%d] skill_level[%d]",
        //     L"User.cpp",
        //     0x4b98,
        //     GetName(),
        //     m_data->m_nClass,
        //     skillId,
        //     skillLevel)
        // L2_LOG_ERROR(Log,
        //     L"[skill acquisition] Rejected unregistered request from '%s': class %d, skill %d level %d.",
        //     GetName(),
        //     m_data->m_nClass,
        //     skillId,
        //     skillLevel)
        L2_LOG_ERROR(
            Log, u"[skill acquisition] Rejected unregistered request from '%s': class %d, skill %d level %d.", GetName(),
            m_data->m_nClass, skillId, skillLevel
        );
        return false;
    }

    if (acquireInfo->m_bResidenceSkill) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"It's residence Skill. [%s][%d] hacking? user[%s] "
        //     L"class[%d] skill_id[%d] skill_level[%d]",
        //     L"User.cpp",
        //     0x4b9f,
        //     GetName(),
        //     m_data->m_nClass,
        //     skillId,
        //     skillLevel)
        // L2_LOG_ERROR(Log,
        //     L"[skill acquisition] Rejected residence skill request from '%s': class %d, skill %d level %d.",
        //     GetName(),
        //     m_data->m_nClass,
        //     skillId,
        //     skillLevel)
        L2_LOG_ERROR(
            Log, u"[skill acquisition] Rejected residence skill request from '%s': class %d, skill %d level %d.", GetName(),
            m_data->m_nClass, skillId, skillLevel
        );
        return false;
    }

    const CSkillKey key(skillId, skillLevel, skillSubLevel);
    const CSkillInfo* const skillInfo = g_SkillDB.GetSkillInfo(key, this);
    if (skillInfo == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Invalid Skill [%d][%d][%d], "
        //     L"Failed to get skillinfo",
        //     L"User.cpp",
        //     0x4ba7,
        //     skillId,
        //     skillLevel,
        //     skillSubLevel)
        L2_LOG_ERROR(
            Log, u"[skill acquisition] Skill %d level %d sublevel %d is missing from the skill database.", skillId,
            skillLevel, skillSubLevel
        );
        return false;
    }

    if (acquireType != ESAT_SUB_PLEDGE) {
        if (HaveSkill(skillId, skillLevel)) {
            return false;
        }

        if (acquireType != ESAT_BISHOP_SHARING && acquireType != ESAT_ELDER_SHARING &&
            acquireType != ESAT_SILEN_ELDER_SHARING && skillInfo->m_pPrevLevel != nullptr &&
            !HaveSkill(skillInfo->m_pPrevLevel->m_nSkillId, skillInfo->m_pPrevLevel->m_nLevel)) {
            CUserSocket* const socket = GetSocket();
            std::array<wchar_t, 16> accountNameStorage{};
            const wchar_t* const accountName = CopyUtf16ToWide(socket->GetAccountName(), 15, accountNameStorage);
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] trying to acquire skill abnormally: "
            //     L"account[%s] user[%s] subjob_id[%d] class[%d] "
            //     L"skill[%d.%d] prev[%d.%d]",
            //     L"User.cpp",
            //     0x4bbb,
            //     accountName,
            //     GetName(),
            //     m_data->m_nSubJobId,
            //     m_data->m_nClass,
            //     skillId,
            //     skillLevel,
            //     skillInfo->m_pPrevLevel->m_nSkillId,
            //     skillInfo->m_pPrevLevel->m_nLevel)
            // L2_LOG_ERROR(Log,
            //     L"[skill acquisition] Rejected abnormal progression for account '%s', character '%s': "
            //     L"subclass %d, class %d, requested skill %d level %d, required previous skill %d level %d.",
            //     accountName,
            //     GetName(),
            //     m_data->m_nSubJobId,
            //     m_data->m_nClass,
            //     skillId,
            //     skillLevel,
            //     skillInfo->m_pPrevLevel->m_nSkillId,
            //     skillInfo->m_pPrevLevel->m_nLevel)
            L2_LOG_ERROR(
                Log,
                u"[skill acquisition] Rejected abnormal progression for account '%s', character '%s': "
                u"subclass %d, class %d, requested skill %d level %d, required previous skill %d level %d.",
                accountName, GetName(), m_data->m_nSubJobId, m_data->m_nClass, skillId, skillLevel,
                skillInfo->m_pPrevLevel->m_nSkillId, skillInfo->m_pPrevLevel->m_nLevel
            );
            return true;
        }
    }

    GuardHelper acquireGuard(L"RequestAcquireSkill 2", CThreadManager::GetThreadID());
    if (acquireType == ESAT_PLEDGE || acquireType == ESAT_SUB_PLEDGE) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[PLEDGE][%s][%d]DEPRECATED!!!!!",
        //     L"User.cpp",
        //     0x4bca)
        L2_LOG_WARN(Log, u"[clan] Deprecated clan-skill acquisition path was invoked.");
        return false;
    }

    if (acquireType == ESAT_SUBJOB && m_data->m_nSubJobId != 0) {
        SendSystemMessage(SystemMessageId::CANNOT_LEARN_SKILL_ON_SUBCLASS_SWITCH_TO_MAIN);
        return false;
    }

    const int requiredMainDualLevel = acquireInfo->m_GetMainDualClassLevel;
    if (requiredMainDualLevel > 0 &&
        (m_data->m_MainClassLevel < requiredMainDualLevel || m_data->m_DualClassLevel < requiredMainDualLevel)) {
        return false;
    }

    if (IsLearnableSkill(*acquireInfo, true)) {
        GuardHelper itemGuard(L"RequestAcquireSkill 2-1", CThreadManager::GetThreadID());
        if (acquireInfo->vNeededItem.empty()) {
            {
                L2_GUARD(*m_lock);
                m_data->SetSP(runtime::SubtractInt64Wrapping(m_data->m_nSP, acquireInfo->nLevelUP_SP));
                const bool acquired = AcquireSkill(skillId, skillLevel, skillSubLevel, false, true);
                if (acquired && !acquireInfo->bAutoGet) {
                    for (const CSkillInfo* const replaceable : acquireInfo->m_ReplaceableSkills) {
                        if (DeleteAcquireSkill(replaceable->m_nSkillId)) {
                            SendDeletedSkillToDB(replaceable->m_nSkillId);
                        }
                    }
                    SendAcquiredSkillToDB(skillId, skillLevel, skillSubLevel, false);
                }
            }

            ValidateChanged(VB_MAX);
            SetMaxMagicLevel();
            ParamChanged(PCB_USER);
            if (!skillInfo->m_bIsDoubleCasting) {
                const int correctedPackedLevel = runtime::Int32FromBits(
                    (static_cast<std::uint32_t>(skillSubLevel) << 16U) | static_cast<std::uint32_t>(skillLevel)
                );
                GetSocket()->Send("chccdd", 0x62, SystemMessageId::SKILL_LEARNED, 1, 4, skillId, correctedPackedLevel);
                SendSkillList(nullptr, true, skillId);
            }
        } else {
            if (runtime::raw_atomic::ExchangeI32(&m_nWaitGetItemOnce, 1) != 0) {
                return false;
            }

            for (std::size_t index = 0; index < acquireInfo->vNeededItem.size(); ++index) {
                AtomicItemDelete* const atomicJob =
                    new AtomicItemDelete(static_cast<int>(Id()), skillId, skillLevel, skillSubLevel, acquireType);
                if (!DeleteItemInInventory(
                        runtime::CheckedVectorAt(acquireInfo->vNeededItem, index),
                        runtime::CheckedVectorAt(acquireInfo->vNeededItemCount, index), atomicJob, false, false
                    )) {
                    atomicJob->Destroy();
                    runtime::raw_atomic::ExchangeI32(&m_nWaitGetItemOnce, 0);
                    return false;
                }
            }
        }
    }

    SendSkillAcquireList(acquireType, false);
    return false;
}

bool User::OnMoveToLocationAirShipPacket(const std::uint8_t* packet) {
    // Current L2Server.exe 0x00b0e5a4.
    L2_GUARD_FUNCTION();
    CAirShip* const airShip = GetMyAirShip();
    if (airShip != nullptr) {
        airShip->OnMoveToLocationPacket(this, packet);
    }
    return airShip != nullptr;
}

void User::SetAvoidAgroFalse() {
    // Current L2Server 0x00b128b0.
    L2_GUARD_FUNCTION();
    if (!m_AvoidAgroWhenEnterWorld) {
        return;
    }

    m_AvoidAgroWhenEnterWorld = false;
    PushSerializedMessage(new CSerializedLookNeighborMessage(this, true, GetPos()));
    SendSystemMessage(SystemMessageId::PROTECTION_FROM_AGGRESSIVE_MONSTERS_ENDED);
    SummonAllPending();
}

bool User::OnStartRotating(int angle, int side) {
    // Current L2Server 0x00b44884.
    L2_GUARD_FUNCTION();
    CAirShip* const airShip = GetMyAirShip();
    if (airShip != nullptr && airShip->IsDriver(this)) {
        airShip->OnStartRotating(angle, side);
        return true;
    }
    if (!m_bIsRestarting) {
        return false;
    }

    StopMove();
    if (!IsGMInvisible()) {
        g_ptlUserMap->BroadcastToNeighborDist(
            this, 0x5000, GetPos(), 0x800, "cdddd", 0x7a, static_cast<int>(m_nId), angle, side, 0
        );
    } else {
        GetSocket()->Send("cdddd", 0x7a, static_cast<int>(m_nId), angle, side, 0);
    }
    return true;
}

bool User::OnFinishRotating(int angle) {
    // Current L2Server 0x00b44a28.
    L2_GUARD_FUNCTION();
    CAirShip* const airShip = GetMyAirShip();
    if (airShip != nullptr && airShip->IsDriver(this)) {
        airShip->OnFinishRotating(angle);
        return true;
    }

    m_data->SetDirByInt(angle);
    if (!IsGMInvisible()) {
        g_ptlUserMap->BroadcastToNeighborDist(
            this, 0x5000, GetPos(), 0x800, "cdddd", 0x61, static_cast<int>(m_nId), angle, 0
        );
    } else {
        GetSocket()->Send("cdddd", 0x61, static_cast<int>(m_nId), angle, 0);
    }
    return true;
}

void User::DeleteBeautyItem(const std::int64_t adenaCost, const std::int64_t beautyCoinCost) {
    // Current L2Server 0x00b227cc.
    L2_GUARD_FUNCTION();
    {
        L2_WRITE_GUARD(m_inv);

        if (adenaCost != 0) {
            CItem* const item = m_inv.GetFirstItemByClassID(0x39, false, false);
            if (item != nullptr) {
                const std::int64_t remaining = runtime::SubtractInt64Wrapping(item->m_data->m_nCount, adenaCost);
                if (remaining < 1) {
                    m_inv.Pop(item->m_data->index, false);
                    m_inv.SetInventoryChanged(item, IUT_DELETE);
                    item->Delete();
                } else {
                    {
                        L2_GUARD(*item->m_lock);
                        if (!item->SetAmount(remaining)) {
                            // Log.Add(
                            //     LOG_ERROR,
                            //     L"[%S][%d] item amount is invalid[%I64d][%I64d]",
                            //     "User.cpp",
                            //     0x6999,
                            //     item->m_data->m_nCount,
                            //     remaining)
                            L2_LOG_ERROR(
                                Log, u"[commission] Cannot change item amount from %I64d to %I64d.", item->m_data->m_nCount,
                                remaining
                            );
                        }
                    }
                    m_inv.SetInventoryChanged(item, IUT_UPDATE);
                }
            }
        }

        if (beautyCoinCost != 0) {
            CItem* const item = m_inv.GetFirstItemByClassID(0x8dd4, false, false);
            if (item != nullptr) {
                const std::int64_t remaining = runtime::SubtractInt64Wrapping(item->m_data->m_nCount, beautyCoinCost);
                if (remaining < 1) {
                    m_inv.Pop(item->m_data->index, false);
                    m_inv.SetInventoryChanged(item, IUT_DELETE);
                    item->Delete();
                } else {
                    {
                        L2_GUARD(*item->m_lock);
                        if (!item->SetAmount(remaining)) {
                            // Log.Add(
                            //     LOG_ERROR,
                            //     L"[%S][%d] item amount is invalid[%I64d][%I64d]",
                            //     "User.cpp",
                            //     0x69ba,
                            //     item->m_data->m_nCount,
                            //     remaining)
                            L2_LOG_ERROR(
                                Log, u"[commission] Cannot change item amount from %I64d to %I64d.", item->m_data->m_nCount,
                                remaining
                            );
                        }
                    }
                    m_inv.SetInventoryChanged(item, IUT_UPDATE);
                }
            }
        }
    }
    SendItemList(true, true, nullptr);
}

