void User::GetCommissionHistory(
    CItem* const item,
    int& itemClassId,
    std::int64_t& itemPrice,
    std::int64_t& itemAmount,
    CommissionExpired::Enum& expiredType,
    CommissionDiscountInfo::Enum& discountType
) {
    // Current L2Server 0x00b3edcc.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(m_CommissionHistoryLock);
        const int classId = item->m_data->m_nClassID;
        const auto found = m_CommissionHistory.find(classId);
        if (found != m_CommissionHistory.end()) {
            itemClassId = found->first;
            itemPrice = found->second.m_nItemPrice;
            itemAmount = found->second.m_nItemAmount;
            expiredType = found->second.m_eExpiredType;
            discountType = found->second.m_eDiscountType;
        }
    }
}

void User::RegisterCommissionHistory(
    const int itemClassId,
    const std::int64_t itemPrice,
    const std::int64_t itemAmount,
    const CommissionExpired::Enum expiredType,
    const CommissionDiscountInfo::Enum discountType
) {
    // Current L2Server 0x00b4a1e8.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(m_CommissionHistoryLock);
        const auto found = m_CommissionHistory.find(itemClassId);
        if (found == m_CommissionHistory.end()) {
            m_CommissionHistory.emplace(itemClassId, CommissionHistory{itemPrice, itemAmount, expiredType, discountType});
        } else {
            found->second.m_nItemPrice = itemPrice;
            found->second.m_nItemAmount = itemAmount;
            found->second.m_eExpiredType = expiredType;
            found->second.m_eDiscountType = discountType;
        }
    }
}

void User::InsertCommissionItem(const unsigned char*& packet, int& itemLane, int& itemClassId) {
    // Current L2Server 0x00b4ceac.
    L2_GUARD_FUNCTION();
    CItemDisassemblerFromCacheD itemData;
    packet = itemData.DisassembleItemInfo(packet);

    CItem* item = m_inv.GetByDBID(itemData.m_nDBID);
    if (item == nullptr) {
        item = g_ObjectDB.CreateItem(itemData.m_nClassID);
        if (item == nullptr) {
            // Log.Add(LOG_ERROR, L"CreateItem fail.")
            L2_LOG_ERROR(
                Log, u"[commission] Cannot restore database item %d: item class %d could not be created.", itemData.m_nDBID,
                itemData.m_nClassID
            );
            return;
        }
        if (item->IsDuration()) {
            item->SetDuration(itemData.m_nDuration);
        }
        if (!m_inv.Push(item->m_data->m_nInventorySlotIndex)) {
            // Log.Add(
            //     LOG_ERROR,
            //     "inven push failed at file[%s], line[%d]",
            //     L"User.cpp",
            //     0x6a5a)
            L2_LOG_ERROR(
                Log, "[commission] Cannot insert restored item %d into the inventory slot index.", itemData.m_nDBID
            );
        }
        m_inv.SetInventoryChanged(item, IUT_ADD);
    }

    {
        L2_GUARD(*item->m_lock);
        item->SetDBID(static_cast<unsigned int>(itemData.m_nDBID));
        if (!item->SetAmount(itemData.m_nAmount)) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] item amount is invalid[%I64d][%I64d]",
            //     L"User.cpp",
            //     0x6a66,
            //     item->m_data->m_nCount,
            //     itemData.m_nAmount)
            L2_LOG_ERROR(
                Log, u"[commission] Restored item amount differs from the database value: current %I64d, database %I64d.",
                item->m_data->m_nCount, itemData.m_nAmount
            );
        }
        item->SetEnchanted(itemData.m_nEnchanted);
        item->m_Useable = CheckUseable(item);
        item->m_data->m_nDamaged = itemData.m_nDamaged;
        item->m_data->m_bBlessed = itemData.m_nIsBlessed;
        item->SetVariation(
            ItemOptionKey{itemData.m_nVariation1, itemData.m_nVariation2},
            static_cast<std::uint32_t>(itemData.m_nIntensiveItemClassID)
        );
        item->SetAttribute(itemData.m_Attribute);
        item->SetShapeShiftingClassId(itemData.m_nShapeShiftedClassID);
        item->SetEnsoulOptionData(itemData.m_mEnsoulInfo, true);
        item->m_data->SetLocked(itemData.m_hLocked);
        item->m_data->SetUseCount(itemData.m_hUseCount);
    }
    m_inv.SetInventoryChanged(item, IUT_UPDATE);

    itemLane = itemData.m_nEnchanted;
    itemClassId = itemData.m_nClassID;
    SendItemList(true, true, nullptr);
}

