bool User::StopStore(const bool stand, const bool force) {
    // Current L2Server 0x00b299a4.
    L2_GUARD_FUNCTION();

    if (m_data->m_StopMode != STP_STORE && !force) {
        return false;
    }

    bool stopped = false;
    if (IsShopOpen() || IsShopManaging()) {
        QuitPrivateStore(false);
        stopped = true;
    } else {
        const int storeType = m_data->m_nPrivateStoreType;
        if (storeType == PST_RECIPE_SHOP_OPEN || storeType == PST_RECIPE_SHOP_MANAGE) {
            QuitRecipeStore();
            stopped = true;
        } else if (!force) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"StopStore error. GetPrivateStoreType() = %d",
            //     storeType)
            L2_LOG_ERROR(
                Log, u"[private store] Cannot stop store: current store type %d is not open or being managed.", storeType
            );
        }
    }

    if (stand) {
        m_data->m_StopMode = STP_STAND;
    }
    return stopped;
}

void User::InitCoupleAction() {
    // Current L2Server 0x00b2a5a8.
    if (m_nCoupleOption == 0) {
        return;
    }

    CCreature* const creature = g_CreatureSmartIdManager.GetObjectW(m_nCoupleID);
    User* const partner = creature != nullptr && creature->IsPC() ? creature->CastUser() : nullptr;
    if (partner != nullptr) {
        partner->DoNothing();
        partner->InitCoupleParam();
        partner->GetSocket()->SendSystemMessage(SystemMessageId::COUPLE_ACTION_CANCELLED);
    }

    InitCoupleParam();
    GetSocket()->SendSystemMessage(SystemMessageId::COUPLE_ACTION_CANCELLED);
}

bool User::OnDuelAcceptStart(const DuelType duelType, const int reply, const int result) {
    // Current L2Server 0x00b2aa1c.
    L2_GUARD_FUNCTION();

    if (static_cast<std::uint32_t>(duelType) > static_cast<std::uint32_t>(DT_PARTY)) {
        CReplyChecker::FinishWaitingReplyByReplier(this);
        return false;
    }

    User* const requester = CReplyChecker::GetRequesterFromReplier(this).get();
    if (requester == nullptr || !requester->IsPC()) {
        CReplyChecker::FinishWaitingReplyByReplier(this);
        return false;
    }

    int rejectionResult = -1;
    if (reply == 1) {
        requester->GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_DECLINED_DUEL_CHALLENGE, GetName());
        rejectionResult = 6;
    } else if (reply == 0) {
        if (result == 1) {
            if (CDuelManager::inst().StartDuel(requester, this, duelType)) {
                if (duelType == DT_INDIVIDUAL) {
                    requester->GetSocket()->SendSystemMessage_S(
                        SystemMessageId::CHARACTER_ACCEPTED_YOUR_DUEL_CHALLENGE, GetName()
                    );
                    GetSocket()->SendSystemMessage_S(
                        SystemMessageId::ACCEPTED_CHARACTER_DUEL_CHALLENGE, requester->GetName()
                    );
                } else if (duelType == DT_PARTY) {
                    requester->GetSocket()->SendSystemMessage_S(SystemMessageId::PARTY_DUEL_ACCEPTED, GetName());
                    GetSocket()->SendSystemMessage_S(SystemMessageId::ACCEPTED_PARTY_DUEL_CHALLENGE, requester->GetName());
                }

                const int z = runtime::Win64CvttDoubleToInt32(GetPos().z);
                const int y = runtime::Win64CvttDoubleToInt32(GetPos().y);
                const int x = runtime::Win64CvttDoubleToInt32(GetPos().x);
                const char16_t* const requesterName = requester->GetName();
                const char16_t* const userName = GetName();
                const std::uint32_t requesterAccountId = requester->GetAccountID();
                const std::uint32_t requesterDbId = requester->GetDBID();
                const std::uint32_t userAccountId = GetAccountID();
                const std::uint32_t userDbId = GetDBID();
                std::array<wchar_t, 16> userAccountStorage{};
                std::array<wchar_t, 16> requesterAccountStorage{};
                // Log.AddT(
                //     LOG_BOTH,
                //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
                //     L"%I64d,,,,,,,,,,%s,%s,%s,%s,",
                //     0x375,
                //     userDbId,
                //     userAccountId,
                //     requesterDbId,
                //     requesterAccountId,
                //     x,
                //     y,
                //     z,
                //     duelType,
                //     userName,
                //     PrivateStoreAccountName(
                //         m_sAccountName,
                //         userAccountStorage),
                //     requesterName,
                //     PrivateStoreAccountName(
                //         requester->m_sAccountName,
                //         requesterAccountStorage))
                Log.AddT(
                    LOG_BOTH,
                    u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
                    u"%I64d,,,,,,,,,,%s,%s,%s,%s,",
                    0x375, userDbId, userAccountId, requesterDbId, requesterAccountId, x, y, z, duelType, userName,
                    PrivateStoreAccountName(m_sAccountName, userAccountStorage), requesterName,
                    PrivateStoreAccountName(requester->m_sAccountName, requesterAccountStorage)
                );
            }
        } else if (result == -1) {
            requester->GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_REFUSES_DUEL_REQUESTS, GetName());
        } else {
            requester->GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_DECLINED_DUEL_CHALLENGE, GetName());
            rejectionResult = 0;
        }
    }

    if (rejectionResult >= 0) {
        const int z = runtime::Win64CvttDoubleToInt32(GetPos().z);
        const int y = runtime::Win64CvttDoubleToInt32(GetPos().y);
        const int x = runtime::Win64CvttDoubleToInt32(GetPos().x);
        const char16_t* const requesterName = requester->GetName();
        const char16_t* const userName = GetName();
        const std::uint32_t requesterAccountId = requester->GetAccountID();
        const std::uint32_t requesterDbId = requester->GetDBID();
        const std::uint32_t userAccountId = GetAccountID();
        const std::uint32_t userDbId = GetDBID();
        std::array<wchar_t, 16> userAccountStorage{};
        std::array<wchar_t, 16> requesterAccountStorage{};
        // Log.AddT(
        //     LOG_BOTH,
        //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        //     L"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
        //     0x376,
        //     userDbId,
        //     userAccountId,
        //     requesterDbId,
        //     requesterAccountId,
        //     x,
        //     y,
        //     z,
        //     duelType,
        //     rejectionResult,
        //     userName,
        //     PrivateStoreAccountName(
        //         m_sAccountName,
        //         userAccountStorage),
        //     requesterName,
        //     PrivateStoreAccountName(
        //         requester->m_sAccountName,
        //         requesterAccountStorage))
        Log.AddT(
            LOG_BOTH,
            u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
            u"%I64d,%I64d,,,,,,,,,%s,%s,%s,%s,",
            0x376, userDbId, userAccountId, requesterDbId, requesterAccountId, x, y, z, duelType, rejectionResult, userName,
            PrivateStoreAccountName(m_sAccountName, userAccountStorage), requesterName,
            PrivateStoreAccountName(requester->m_sAccountName, requesterAccountStorage)
        );
    }

    CReplyChecker::FinishWaitingReplyByReplier(this);
    return false;
}

bool User::OnTargetUnselectedPacket(const std::int16_t request) {
    // Current L2Server 0x00b2b028.
    L2_GUARD_FUNCTION();

    {
        L2_GUARD(m_BotCheckTimeLock);
        if (m_spTarget.Sid() == static_cast<std::uint32_t>(m_nLastKillNpcSId)) {
            const std::int32_t elapsed = runtime::Int32FromBits(runtime::GetTickCount() - m_dwLastKillTime);
            if (elapsed <= g_dBotUnseleteTime) {
                const std::u16string ipAddress = GetSocket()->GetIPAddressString();
                const std::u16string targetIp = std::u16string(ipAddress.c_str());
                const int z = runtime::Win64CvttDoubleToInt32(GetPos().z);
                const int y = runtime::Win64CvttDoubleToInt32(GetPos().y);
                const int x = runtime::Win64CvttDoubleToInt32(GetPos().x);
                const std::u16string actorName = std::u16string(GetName());
                const int classId = Level();
                const std::uint32_t accountId = GetAccountID();
                const std::uint32_t databaseId = GetDBID();
                CLogFormatter formatter;
                formatter.WriteAuditLog(
                    0x585, databaseId, accountId, 0, 0, x, y, z, targetIp.c_str(), u"", u"", 0x0b, 0, elapsed, 0, 0, 0, 0, 0,
                    0, classId, actorName.c_str(), m_sAccountName.data(), u"", u"", 0
                );
            }
        }
    }

    if (request == 0) {
        CCreatureController* const controller = GetController();
        if (controller->GetCurrentActionType() == ACT_SKILL) {
            controller->LostTarget(runtime::Int32FromBits(m_spTarget.Sid()), true);
            CLogFormatter formatter;
            formatter.WriteLog2_1(0x195, CastUser(), nullptr, controller->GetCurrentActionSkillId(), 1, 0, 0, 0, 0, 0);
            return false;
        }
    }

    ChangeTarget(nullptr, CTR_BY_USER);
    return false;
}

