double User::EquipedArmorsValidate(const VALIDATE::Enum type) const {
    // Current L2Server 0x00b39654.
    L2_GUARD_FUNCTION();

    double result = 0.0;
    const int onePieceIndex = m_data->m_nSlotIndex[ST_ONEPIECE];
    for (int slot = 0; slot < ST_MAX; ++slot) {
        CSharedItemData* const armor = CItemFactory::Inst().GetData(m_data->m_nSlotIndex[slot]);
        if (armor != nullptr && (armor->m_Type == IT_ARMOR || armor->m_Type == IT_ACCESSARY) && slot != ST_ONEPIECE) {
            CSharedItemConstant* const constant = armor->GetConstant();
            CSPointer<CItem> item = CItemFactory::Inst().FindObjectSP(armor->index);
            if (!item) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"[%s][%d] EquipedArmorsPDefend failed. "
                //     L"because CItemFactory::Inst().GetObjectSP "
                //     L"failed. Name[%s]/Slot[%d]/ArmorIndex[%d]/"
                //     L"ArmorDBID[%d]",
                //     "User.cpp",
                //     0x5f4c,
                //     GetName(),
                //     slot,
                //     armor->m_nClassID,
                //     armor->m_nDBID)
                // L2_LOG_ERROR(Log,
                //     L"[equipment] Cannot calculate armor defense for '%s': item object missing at slot %d, class %d, DB ID
                //     %d.", GetName(), slot, armor->m_nClassID, armor->m_nDBID)
                L2_LOG_ERROR(
                    Log,
                    u"[equipment] Cannot calculate armor defense for '%s': item object missing at slot %d, class %d, DB ID "
                    u"%d.",
                    GetName(), slot, armor->m_nClassID, armor->m_nDBID
                );
                return 0.0;
            }

            const int crystal = static_cast<int>(constant->GetCrystalType());
            result += item->GetValidateParam(type);
            if (crystal >= 0 && crystal < CRT_MAX) {
                result += item->EnchantAddValue(type);
            }
        } else if (ArraySTToPC[slot] != PCBODY::NONE && m_data->m_nBaseParam[type] != 0 &&
            (onePieceIndex == -1 || slot != ST_LEGS)) {
            const double baseParameter = static_cast<double>(m_data->m_nBaseParam[type]);
            const double bodyPart =
                g_PCParamDB.GetBodyPart(m_data->m_Sex, m_data->m_nClass, ArraySTToPC[slot], type, m_data->m_Race);
            result += (bodyPart / baseParameter) * baseParameter;
        }
    }
    return result;
}

void User::ChangeInventorySlot(std::map<int, int>& slotIndices) {
    // Current L2Server 0x00b399b8, original owner User.cpp.
    L2_GUARD_FUNCTION();

    L2_WRITE_GUARD(m_inv);
    m_inv.InitSlotInfo();
    for (const auto& slot : slotIndices) {
        CItem* const item = m_inv.GetByServerID(slot.first);
        if (item == nullptr || item->IsQuestItem() || IsEquipedItem(item->GetIndex())) {
            return;
        }
        m_inv.AddSlotInfo(slot.second, item);
    }
}

bool User::CheckSwapEquippedAgathionItemJob(CItem* const sourceItem, CItem* const targetItem) {
    // Current L2Server 0x00b3a89c. Direct User-only dependency of
    // User::SwapAgathionSlotItems@0x00b401c8.
    L2_GUARD_FUNCTION();

    if (sourceItem == nullptr || targetItem == nullptr || !CanUseItem(sourceItem) || !CanUseItem(targetItem)) {
        return false;
    }
    if (m_pFishingController != nullptr &&
        (m_pFishingController->m_FishingState != FISHINGS_NONE || m_pFishingController->m_bIsAutoFishing)) {
        SendSystemMessage(SystemMessageId::CANNOT_EQUIP_UNEQUIP_DESTROY_OR_DROP_ITEMS_WHILE_FISHING);
        return false;
    }

    const ActionType action = GetController()->GetCurrentActionType();
    if (action == ACT_SKILL || action == ACT_ATTACK) {
        SendSystemMessage(SystemMessageId::CANNOT_CHANGE_WEAPONS_DURING_ATTACK);
        return false;
    }

    CTransform* const transform = IsTransformed(TransformType::Max);
    if (transform != nullptr &&
        (!transform->CanUseItem(sourceItem->m_data->m_nClassID) || !transform->CanUseItem(targetItem->m_data->m_nClassID))) {
        SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_USED_IN_CURRENT_TRANSFORMATION);
        return false;
    }

    if (m_data->m_bIsFakeDeath) {
        GetController()->Stand(0x9f6);
    }

    if (m_EventMatchUser.m_byEventMatchTeamId != 0) {
        CSPointer<CEventMatch> eventMatch = m_EventMatchUser.GetEventMatch();
        if (eventMatch &&
            (eventMatch->m_ItemRule.IsAllow(sourceItem->m_data->m_nClassID) == 0 ||
                eventMatch->m_ItemRule.IsAllow(targetItem->m_data->m_nClassID) == 0)) {
            return false;
        }
    }

    if (m_pWOlympiadUser->IsPlayer() &&
        (!sourceItem->m_const->m_bCanOlympiadUse || !targetItem->m_const->m_bCanOlympiadUse)) {
        SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_USED_IN_OLYMPIAD);
        return false;
    }
    if (m_PledgeGameUser.IsPlayer() &&
        (sourceItem->m_const->m_bCanNotPledgeGameUse || targetItem->m_const->m_bCanNotPledgeGameUse)) {
        SendSystemMessage(SystemMessageId::ITEM_CANNOT_BE_USED_IN_MATCH);
        return false;
    }

    const auto checkUseCondition = [this](CItem* const item) {
        if (item->CheckItemUseCondition(this)) {
            return true;
        }
        GetSocket()->Send("chccd", 0x62, SystemMessageId::NAMED_ACTION_CONDITIONS_NOT_MET, 1, 3, item->m_data->m_nClassID);
        if (!m_ItemMasterBuilder) {
            return false;
        }
        GetSocket()->SendSystemMessage(u"SYS", u"use item because you are Item Master");
        return true;
    };
    if (!checkUseCondition(sourceItem) || !checkUseCondition(targetItem)) {
        return false;
    }
    if (HasEquipped(sourceItem) && HasEquipped(targetItem)) {
        return true;
    }

    SendSystemMessage(SystemMessageId::CANNOT_EQUIP_ITEM_REQUIREMENTS_NOT_MET);
    return false;
}

void User::WriteLogSwapAgathionSlotItems(CItem* const item, const SlotType slot) {
    // Current L2Server 0x00b16988.
    L2_GUARD_FUNCTION();

    std::array<char16_t, 256> attributeInfo{};
    std::array<char16_t, 256> optionInfo{};
    std::array<char16_t, 256> ensoulInfo{};
    if (item != nullptr) {
        item->m_itemBaseAttribute.GetLogString(attributeInfo.data());
        FormatUtf16To(
            optionInfo.data(), optionInfo.size(), u"%d:%d:%d", item->m_itemOption.intensiveItemClassID,
            item->m_itemOption.itemOptionKey.variationOption1, item->m_itemOption.itemOptionKey.variationOption2
        );
    }
    item->MakeEnsoulLogInfo(ensoulInfo.data());

    CLogFormatter formatter;
    formatter.WriteLog1_1(
        0x338, this, nullptr, ensoulInfo.data(), attributeInfo.data(), optionInfo.data(), 0, item->m_nClassId,
        static_cast<int>(slot), item->GetDBID(), item->m_data->GetEnchanted(), 0, item->GetDBID()
    );
    if (item->IsDuration()) {
        formatter.WriteLog4(
            0x3d4, this, nullptr, nullptr, nullptr, nullptr, item->m_nClassId, item->GetDuration(), 0, 0, 0, 0, 0, 0, 0, 0,
            item->GetDBID()
        );
    }
}

void User::SendAbnormalStatusInfo() {
    // Current L2Server 0x00b3bf54.
    L2_GUARD_FUNCTION();

    std::array<char, 0x5000> buffer;
    int length = static_cast<int>(buffer.size());
    int count = PrepareSpelledInfoChangedBuffer(buffer.data(), length);

    {
        L2_GUARD(m_SkillListSect);
        const auto appendSkill = [&](const CSkillInfo* const skill) {
            const std::uint32_t levelAndSubLevel = static_cast<std::uint32_t>(static_cast<std::uint16_t>(skill->m_nLevel)) |
                (static_cast<std::uint32_t>(static_cast<std::uint16_t>(skill->m_nSubLevel)) << 16U);
            const int assembled = ::Assemble(
                buffer.data() + length, static_cast<int>(buffer.size()) - length, "dddh", skill->m_nSkillId,
                levelAndSubLevel, 0, -1
            );
            if (assembled > 0) {
                length += assembled;
                ++count;
            }
        };

        for (const auto& entry : m_ToggleSkills) {
            if (entry.second.second) {
                appendSkill(entry.second.first);
            }
        }
        for (const auto& entry : m_AuraSkills) {
            if (entry.second.second) {
                appendSkill(entry.second.first);
            }
        }
    }

    GetSocket()->Send("chb", 0x85, count, length, buffer.data());
}

bool User::SpelledInfoChangedBuffer(
    char* const retainedBuffer,
    int& retainedLength,
    int& retainedCount,
    char* const deletedBuffer,
    int& deletedLength,
    int& deletedCount
) {
    // Current L2Server 0x00b49a04. The two maps are deltas: deletions are
    // serialized first, while newly inserted entries are omitted from the
    // kept-status list. Both maps survive any assembly failure.
    L2_GUARD_FUNCTION();

    int retainedWritten = 0;
    int deletedWritten = 0;
    L2_GUARD(m_InfectedSkillsSect);

    int infectedSkillCount = static_cast<int>(m_InfectedSkills.size());
    if (infectedSkillCount > 108) {
        // Log.Add(
        //     LOG_ERROR,
        //     "abnormal status exceeds MAX_ABNORMAL_STATUS at file[%s], "
        //     "line[%d]",
        //     "User.cpp",
        //     0x1cab)
        L2_LOG_ERROR(Log, "[abnormal status] Status count exceeds MAX_ABNORMAL_STATUS; remaining entries were skipped.");
        infectedSkillCount = 108;
    }

    L2_GUARD(m_ModifySkillLock);

    for (const auto& entry : m_DeleteSkill) {
        const ModifySkillList& deleted = entry.second;
        const CSkillInfo* const skill =
            g_SkillDB.GetSkillInfo(CSkillKey(deleted.nSkillID, deleted.nSkillLevel, deleted.nSkillSubLevel), nullptr);
        const int sourceId = skill != nullptr && static_cast<int>(skill->m_nSubAbnormal) >= 0 &&
                static_cast<int>(skill->m_nSubAbnormal) < ABNS_MAX
            ? deleted.nSourceId
            : 0;
        const std::uint32_t levelAndSubLevel = static_cast<std::uint32_t>(static_cast<std::uint16_t>(deleted.nSkillLevel)) |
            (static_cast<std::uint32_t>(static_cast<std::uint16_t>(deleted.nSkillSubLevel)) << 16U);
        const int assembled = ::Assemble(
            deletedBuffer + deletedWritten, deletedLength - deletedWritten, "ddd", deleted.nSkillID, levelAndSubLevel,
            sourceId
        );
        if (assembled < 1) {
            return false;
        }
        deletedWritten += assembled;
        ++deletedCount;
    }

    std::int32_t now = 0;
    CIOObject::SetTimeStamp(&now);
    for (int index = 0; index < infectedSkillCount; ++index) {
        const InfectedSkillType& infected = runtime::CheckedVectorAt(m_InfectedSkills, static_cast<std::size_t>(index));
        CSkillInfo* const skill = infected.pSkillInfo;
        if (IsLockedBuff(skill->m_nSkillId)) {
            continue;
        }

        int remaining = -1;
        if (skill->m_nAbnormalTime != -1 && skill->m_OperateType != SKILL_AURA_ACTIVITY &&
            skill->m_OperateType != SKILL_AURA_ACTIVITY2) {
            const int elapsed = runtime::SubtractInt32Wrapping(now, infected.nStartTime);
            const int duration = skill->m_nAbnormalTime == -2 ? infected.nDuration : GetAbnormalTime(skill, false);
            remaining = runtime::SubtractInt32Wrapping(duration, elapsed);
            if (remaining < 0) {
                remaining = 0;
            }
        }

        const int sourceId =
            static_cast<int>(skill->m_nSubAbnormal) >= 0 && static_cast<int>(skill->m_nSubAbnormal) < ABNS_MAX
            ? runtime::Int32FromBits(infected.nSourceCreatureId)
            : 0;
        const std::CTriKey<AbnormalStatusSlotType, int, int> key(skill->m_nAbnormalType, skill->m_nSkillId, sourceId);
        if (m_InsertSkill.find(key) != m_InsertSkill.end()) {
            continue;
        }

        const std::uint32_t levelAndSubLevel = static_cast<std::uint32_t>(static_cast<std::uint16_t>(skill->m_nLevel)) |
            (static_cast<std::uint32_t>(static_cast<std::uint16_t>(skill->m_nSubLevel)) << 16U);
        const int assembled = remaining < 0x8000
            ? ::Assemble(
                  retainedBuffer + retainedWritten, retainedLength - retainedWritten, "dddh", skill->m_nSkillId,
                  levelAndSubLevel, sourceId, remaining
              )
            : ::Assemble(
                  retainedBuffer + retainedWritten, retainedLength - retainedWritten, "dddhd", skill->m_nSkillId,
                  levelAndSubLevel, sourceId, 0x7fff, remaining
              );
        if (assembled < 1) {
            return false;
        }
        retainedWritten += assembled;
        ++retainedCount;
    }

    m_InsertSkill.clear();
    m_DeleteSkill.clear();
    deletedLength = deletedWritten;
    retainedLength = retainedWritten;
    return true;
}

bool User::SwapAgathionSlotItems(
    CItem* const firstItem, const SlotType firstSlot, CItem* const secondItem, const SlotType secondSlot
) {
    // Current L2Server 0x00b401c8.
    L2_GUARD_FUNCTION();

    if (!CheckSwapEquippedAgathionItemJob(firstItem, secondItem)) {
        return false;
    }
    if (runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 1) == 1) {
        return false;
    }

    bool swapped = false;
    if (CCreature::SwapAgathionSlotItems(firstItem, firstSlot, secondItem, secondSlot)) {
        {
            L2_WRITE_GUARD(m_inv);
            m_inv.SetInventoryChanged(firstItem, IUT_UPDATE);
            m_inv.SetInventoryChanged(secondItem, IUT_UPDATE);
            if (firstItem->IsDuration()) {
                firstItem->SetDurationCommitTick(static_cast<int>(m_nLastTick));
                firstItem->DecreaseDurationOneUnit();
                SaveDurationItem(firstItem);
                _AddEquipDurationItem(firstItem);
            }
            if (secondItem->IsDuration()) {
                secondItem->SetDurationCommitTick(static_cast<int>(m_nLastTick));
                secondItem->DecreaseDurationOneUnit();
                SaveDurationItem(secondItem);
                _AddEquipDurationItem(secondItem);
            }
        }

        SetAllOverPointToDefault();
        m_data->m_NeedUpdatePacketBitSet.SetBit(0x49);
        WriteLogSwapAgathionSlotItems(firstItem, secondSlot);
        WriteLogSwapAgathionSlotItems(secondItem, firstSlot);
        swapped = true;
    }

    runtime::raw_atomic::ExchangeI32(&m_lWaitItemJob, 0);
    if (!swapped) {
        return false;
    }

    if (IsBuilder() && m_ShowEquipItemInfo) {
        firstItem->ShowEquipItemInfo(this);
        secondItem->ShowEquipItemInfo(this);
    }
    db.SaveCharacterSlotInfo(this);
    ValidateChanged(VB_MAX);
    SendUserInfo(nullptr, nullptr);
    ParamChanged(std::int64_t{PCB_CHAR_EQUIPSLOT});
    SendETCBuffStatusInfo();
    SendItemList(true, true, nullptr);
    return true;
}

void User::BroadcastHP(const int reason, const std::uint32_t objectId) {
    // Current L2Server 0x00b419e4.
    L2_GUARD_FUNCTION();

    const FVector position = GetPos();
    g_ptlUserMap->BroadcastToNeighborParty(
        this, 0x80000, position, g_nDistanceBroadcastingHPMP, "cddcccd", 0x18, runtime::Int32FromBits(m_nId),
        static_cast<int>(objectId), static_cast<int>(static_cast<std::int8_t>(reason)), 1, 9,
        runtime::Win64CvttDoubleToInt32(m_data->m_dHP)
    );
}

void User::BroadcastHPMP(const int reason, const std::uint32_t objectId) {
    // Current L2Server 0x00b41b28.
    L2_GUARD_FUNCTION();

    const FVector position = GetPos();
    g_ptlUserMap->BroadcastToNeighborParty(
        this, 0x80000, position, g_nDistanceBroadcastingHPMP, "cddcccdcd", 0x18, runtime::Int32FromBits(m_nId),
        static_cast<int>(objectId), static_cast<int>(static_cast<std::int8_t>(reason)), 2, 9,
        runtime::Win64CvttDoubleToInt32(m_data->m_dHP), 0x0b, runtime::Win64CvttDoubleToInt32(m_data->m_dMP)
    );
}

bool User::OnMagicSkillUsePacket(const int skillId, const bool forceAttack, const bool stand) {
    // Current L2Server 0x00b44b9c.
    L2_GUARD_FUNCTION();
    // Portable opt-in diagnostic. The guarded observations do not replace
    // or reinterpret any current-machine branch.
    const bool magicTrace = std::getenv("L2_MAGIC_TRACE") != nullptr;
    const auto traceReject = [&](const char* const reason) {
        if (!magicTrace) {
            return;
        }
        // std::fprintf(
        //     stderr,
        //     "[MAGIC_TRACE] user-reject sid=%u dbid=%d skill=%d "
        //     "target=%u reason=%s\n",
        //     Id(),
        //     static_cast<int>(GetDBID()),
        //     skillId,
        //     m_spTarget.Sid(),
        //     reason)
        // runtime::logging::WriteDirect(
        //     stderr, "l2server", runtime::logging::Level::Info,
        //     "[magic trace] Rejected skill %d for character object %u (DB ID %u), target %u: %s.",
        //     skillId,
        //     Id(),
        //     GetDBID(),
        //     m_spTarget.Sid(),
        //     reason)
        L2_LOG_DIRECT(
            stderr, runtime::logging::Level::Info,
            "[magic trace] Rejected skill %d for character object %u (DB ID %u), target %u: %s.", skillId, Id(), GetDBID(),
            m_spTarget.Sid(), reason
        );
        // std::fflush(stderr), // WriteDirect flushes the complete record.
    };
    if (magicTrace) {
        // std::fprintf(
        //     stderr,
        //     "[MAGIC_TRACE] user-enter sid=%u dbid=%d class=%d level=%d "
        //     "skill=%d target=%u force=%d stand=%d active=%d alive=%d "
        //     "can-act=%d restarting=%d\n",
        //     Id(),
        //     static_cast<int>(GetDBID()),
        //     static_cast<int>(m_data->m_nClass),
        //     m_data->m_nLevel,
        //     skillId,
        //     m_spTarget.Sid(),
        //     forceAttack ? 1 : 0,
        //     stand ? 1 : 0,
        //     m_data->m_bIsActive ? 1 : 0,
        //     m_data->m_bIsAlive != 0 ? 1 : 0,
        //     m_SkillMod.m_bCanAct ? 1 : 0,
        //     m_bIsRestarting ? 1 : 0)
        // runtime::logging::WriteDirect(
        //     stderr, "l2server", runtime::logging::Level::Info,
        //     "[magic trace] Checking skill %d for character object %u (DB ID %u), class %d, level %d, target %u. Force
        //     attack: %s, stand: %s, active: %s, alive: %s, can act: %s, restarting: %s.", skillId, Id(), GetDBID(),
        //     static_cast<int>(m_data->m_nClass),
        //     m_data->m_nLevel,
        //     m_spTarget.Sid(),
        //     forceAttack ? "yes" : "no",
        //     stand ? "yes" : "no",
        //     m_data->m_bIsActive ? "yes" : "no",
        //     m_data->m_bIsAlive != 0 ? "yes" : "no",
        //     m_SkillMod.m_bCanAct ? "yes" : "no",
        //     m_bIsRestarting ? "yes" : "no")
        L2_LOG_DIRECT(
            stderr, runtime::logging::Level::Info,
            "[magic trace] Checking skill %d for character object %u (DB ID %u), class %d, level %d, target %u; force "
            "attack: %s, stand: %s, active: %s, alive: %s, can act: %s, restarting: %s.",
            skillId, Id(), GetDBID(), static_cast<int>(m_data->m_nClass), m_data->m_nLevel, m_spTarget.Sid(),
            forceAttack ? "yes" : "no", stand ? "yes" : "no", m_data->m_bIsActive ? "yes" : "no",
            m_data->m_bIsAlive != 0 ? "yes" : "no", m_SkillMod.m_bCanAct ? "yes" : "no", m_bIsRestarting ? "yes" : "no"
        );
        // std::fflush(stderr), // WriteDirect flushes the complete record.
    }

    if (m_EventMatchUser.m_byEventMatchTeamId != 0) {
        CSPointer<CEventMatch> eventMatch = m_EventMatchUser.GetEventMatch();
        if (eventMatch && eventMatch->m_SkillRule.IsAllow(skillId) == 0) {
            // traceReject("event-rule")
            traceReject("the event rules prohibit this skill");
            return false;
        }
    }

    const CSkillInfo* const skill = GetUsableSkill(skillId);
    if (magicTrace) {
        // std::fprintf(
        //     stderr,
        //     "[MAGIC_TRACE] user-lookup sid=%u skill=%d usable=%p "
        //     "resolved=%d/%d/%d without-action=%d operate=%d target-type=%d\n",
        //     Id(),
        //     skillId,
        //     static_cast<const void*>(skill),
        //     skill != nullptr ? skill->m_nSkillId : -1,
        //     skill != nullptr ? skill->m_nLevel : -1,
        //     skill != nullptr ? skill->m_nSubLevel : -1,
        //     skill != nullptr && skill->m_bWithoutAction ? 1 : 0,
        //     skill != nullptr
        //         ? static_cast<int>(skill->m_OperateType)
        //         : -1,
        //     skill != nullptr
        //         ? static_cast<int>(skill->m_TargetType)
        //         : -1)
        // Noise: Raw addresses add no skill-state explanation. Report presence instead.
        // runtime::logging::WriteDirect(
        //     stderr, "l2server", runtime::logging::Level::Info,
        //     "[magic trace] Usable-skill lookup for character object %u, requested skill %d: found %s. Resolved skill %d,
        //     level %d, sublevel %d. Without action: %s, operation type %d, target type %d.", Id(), skillId, skill !=
        //     nullptr ? "yes" : "no", skill != nullptr ? skill->m_nSkillId : -1, skill != nullptr ? skill->m_nLevel : -1,
        //     skill != nullptr ? skill->m_nSubLevel : -1,
        //     skill != nullptr && skill->m_bWithoutAction ? "yes" : "no",
        //     skill != nullptr
        //                 ? static_cast<int>(skill->m_OperateType)
        //                 : -1,
        //     skill != nullptr
        //                 ? static_cast<int>(skill->m_TargetType)
        //                 : -1)
        L2_LOG_DIRECT(
            stderr, runtime::logging::Level::Info,
            "[magic trace] Usable-skill lookup for character object %u, requested skill %d: found %s; resolved skill %d, "
            "level %d, sublevel %d; without action: %s, operation type %d, target type %d.",
            Id(), skillId, skill != nullptr ? "yes" : "no", skill != nullptr ? skill->m_nSkillId : -1,
            skill != nullptr ? skill->m_nLevel : -1, skill != nullptr ? skill->m_nSubLevel : -1,
            skill != nullptr && skill->m_bWithoutAction ? "yes" : "no",
            skill != nullptr ? static_cast<int>(skill->m_OperateType) : -1,
            skill != nullptr ? static_cast<int>(skill->m_TargetType) : -1
        );
        // std::fflush(stderr), // WriteDirect flushes the complete record.
    }
    SkillUseInfo useInfo{};

    if (m_pWOlympiadUser->IsPlayer() && skill != nullptr && skill->m_nOlympiadUse != 1) {
        SendSystemMessage(SystemMessageId::SKILL_CANNOT_BE_USED_IN_OLYMPIAD);
        // traceReject("olympiad-rule")
        traceReject("the skill is prohibited in the Olympiad");
        return false;
    }

    if (m_PledgeGameUser.IsPlayer() && skill != nullptr) {
        if (skill->m_nPledgeGameUse != 1) {
            SendSystemMessage(SystemMessageId::SKILL_CANNOT_BE_USED_IN_MATCH);
            // traceReject("pledge-game-rule")
            traceReject("the skill is prohibited in this pledge match");
            return false;
        }
        CWorldObject* const pledgeTarget = m_spTarget.GetWorldObject();
        if (pledgeTarget != nullptr && pledgeTarget->IsCreature() && skill->m_nEffectPoint > 0 &&
            skill->m_TargetType == STGT_TARGET) {
            if (!IsMySummonOrPet(/* exact repeated current */ pledgeTarget->CastCreature()) &&
                runtime::Int32FromBits(m_nId) != runtime::Int32FromBits(pledgeTarget->CastCreature()->m_nId)) {
                SendSystemMessage(SystemMessageId::SKILL_CANNOT_BE_USED_IN_MATCH);
                // traceReject("pledge-game-target")
                traceReject("the selected target is prohibited for this skill in the pledge match");
                return false;
            }
        }
    }

    if (m_data->m_TrainingState == 1) {
        SendSystemMessage(SystemMessageId::CANNOT_TAKE_OTHER_ACTIONS_WHILE_IN_TRAINING_CAMP);
        // traceReject("training-state")
        traceReject("the character is in training");
        return false;
    }

    CUserSocket* const socket = GetSocket();
    bool fullFatigue = false;
    if (socket->IsApplyChinaFatigueSystem()) {
        fullFatigue = g_ChinaFullFatigueTime * 0xe10 < socket->GetPlayTime_china();
    }
    if (fullFatigue) {
        SendSystemMessage(SystemMessageId::CANNOT_ACT_DUE_TO_FATIGUE);
        // traceReject("china-fatigue")
        traceReject("the China fatigue limit has been exceeded");
        return false;
    }
    if (m_bIsRestarting) {
        // traceReject("restarting")
        traceReject("the character is restarting");
        return false;
    }

    SetAvoidAgroFalse();
    if (skill == nullptr || !skill->m_bWithoutAction) {
        const bool dispatched = CCreature::OnMagicSkillUsePacket(skillId, forceAttack, stand);
        if (magicTrace) {
            // std::fprintf(
            //     stderr,
            //     "[MAGIC_TRACE] user-action-dispatch sid=%u skill=%d "
            //     "usable=%d result=%d\n",
            //     Id(),
            //     skillId,
            //     skill != nullptr ? 1 : 0,
            //     dispatched ? 1 : 0)
            // runtime::logging::WriteDirect(
            //     stderr, "l2server", runtime::logging::Level::Info,
            //     "[magic trace] Creature skill handler returned for object %u, skill %d: usable skill found %s, handler
            //     result %s.", Id(), skillId, skill != nullptr ? "yes" : "no", dispatched ? "yes" : "no")
            L2_LOG_DIRECT(
                stderr, runtime::logging::Level::Info,
                "[magic trace] Creature skill handler returned for object %u, skill %d: usable skill found %s, handler "
                "result %s.",
                Id(), skillId, skill != nullptr ? "yes" : "no", dispatched ? "yes" : "no"
            );
            // std::fflush(stderr), // WriteDirect flushes the complete record.
        }
        return false;
    }

    CWorldObject* const selectedTarget = m_spTarget.GetWorldObject();
    useInfo.m_skillID = skill->m_nSkillId;
    useInfo.m_skillLevel = skill->m_nLevel;
    useInfo.m_skillSubLevel = skill->m_nSubLevel;
    if (!m_SkillMod.m_bCanAct) {
        const bool conditionAllowsSkill = [&] {
            L2_GUARD(m_SkillDurationMod.m_Lock);
            return m_SkillDurationMod.m_SkillCondMap.find(skillId) != m_SkillDurationMod.m_SkillCondMap.end();
        }();
        if (!conditionAllowsSkill) {
            // traceReject("without-action-can-act")
            traceReject("actions are disabled and this skill has no condition-map exception");
            return false;
        }
    }

    CWorldObject* target = this;
    if (skill->m_TargetType != STGT_SELF && skill->m_TargetType != STGT_GROUND) {
        target = selectedTarget;
    }
    CSPointer<User> mentor;
    if (skill->m_TargetType == STGT_MY_MENTOR && IsAlreadyHaveMentor()) {
        mentor = g_UserDBIDMap.FindObject(
            std::CDualKey<int, int>(runtime::process::CurrentWorldId(), m_Mentee.m_Mentor.nCharDBId)
        );
        if (mentor) {
            target = mentor->CastCreature();
        }
    }

    if (!skill->IsValidTarget(this, target, forceAttack)) {
        if (IsPC()) {
            SendSystemMessage(SystemMessageId::INVALID_TARGET);
        }
        // traceReject("without-action-invalid-target")
        traceReject("the target is invalid for this skill");
        return false;
    }
    const int operateCondition = skill->CheckOperateCond(this, target, CSkillInfo::OCT_BOTH);
    if (operateCondition != -2) {
        if (magicTrace) {
            // std::fprintf(
            //     stderr,
            //     "[MAGIC_TRACE] user-reject sid=%u skill=%d "
            //     "reason=without-action-operate-cond result=%d\n",
            //     Id(),
            //     skillId,
            //     operateCondition)
            // runtime::logging::WriteDirect(
            //     stderr, "l2server", runtime::logging::Level::Info,
            //     "[magic trace] Rejected immediate skill %d for object %u: operation-condition result %d, required -2.",
            //     skillId,
            //     Id(),
            //     operateCondition)
            L2_LOG_DIRECT(
                stderr, runtime::logging::Level::Info,
                "[magic trace] Rejected immediate skill %d for object %u: operation-condition result %d, required -2.",
                skillId, Id(), operateCondition
            );
            // std::fflush(stderr), // WriteDirect flushes the complete record.
        }
        return false;
    }

    const double remainReuseDelay = GetRemainReuseDelaySec(skill->m_nSkillId, skill->m_nLevel, skill->m_nSubLevel);
    if (remainReuseDelay > 0.0) {
        SendRemainTime(
            static_cast<int>(remainReuseDelay), EST_SKILLID, skill->m_nSkillId, skill->m_nLevel, skill->m_nSubLevel,
            static_cast<int>(skill->m_nReuseDelay)
        );
        // traceReject("without-action-reuse")
        traceReject("the skill reuse delay has not expired");
        return false;
    }

    CSkillInfo* const mutableSkill = const_cast<CSkillInfo*>(skill);
    const int reuseDelay = SetSkillReuseDelay(*mutableSkill);
    const double consumeFactor = mutableSkill->GetConsumeFactor(this);
    const int consumeMp =
        CSkillAction2::CalcConsumeMP(this, mutableSkill, skill->m_nMpConsume1 + skill->m_nMpConsume2, consumeFactor);
    if (!ConsumeMP(static_cast<double>(consumeMp))) {
        SendSystemMessage(SystemMessageId::NOT_ENOUGH_MP);
        // traceReject("without-action-mp")
        traceReject("the MP consumption check failed");
        return false;
    }

    const int parameter1 = 0;
    const int parameter2 = 0;
    const int parameter3 = -1;
    const int parameter5 = 0;
    const int parameter6 = 0;
    if (!IsGMInvisible()) {
        const int broadcastDistance = GetBroadcastDist(0x1000);
        m_data->m_NeedUpdatePacketBitSet.SetBoolValue_IfModifed(m_IsSheathingWeapon, false, 0x5a);
        if (!IsInAirShip()) {
            DefaultIOBuffer* const packet = MakePacketForMagicSkillUse(
                parameter1, target, useInfo, parameter2, parameter3, reuseDelay, parameter5, parameter6, nullptr
            );
            g_ptlUserMap->BroadcastToNeighborDist(this, 0x5000, GetPos(), broadcastDistance, packet);
            packet->Release();
        } else {
            const FVector relativePosition = m_RelPos;
            const std::uint32_t skillLevel =
                (static_cast<std::uint32_t>(skill->m_nSubLevel) << 16U) | static_cast<std::uint16_t>(skill->m_nLevel);
            g_ptlUserMap->BroadcastToNeighborDist(
                this, 0x5000, GetPos(), broadcastDistance, "chddddddddddddhh", 0xfe, 0x74, 0,
                runtime::Int32FromBits(m_nId), runtime::Int32FromBits(target->m_nId), skill->m_nSkillId,
                runtime::Int32FromBits(skillLevel), parameter2, parameter3, reuseDelay,
                runtime::Win64CvttDoubleToInt32(relativePosition.x),
                runtime::Win64CvttDoubleToInt32(relativePosition.y),
                runtime::Win64CvttDoubleToInt32(relativePosition.z), static_cast<int>(GetMyAirShipID()), 0, 0
            );
        }
    } else {
        CUserSocket* const invisibleSocket = GetSocket();
        if (invisibleSocket != nullptr) {
            m_data->m_NeedUpdatePacketBitSet.SetBoolValue_IfModifed(m_IsSheathingWeapon, false, 0x5a);
            if (!IsInAirShip()) {
                if (User* const user = CastUser()) {
                    user->SendMagicSkill(
                        parameter1, target, useInfo, parameter2, parameter3, reuseDelay, parameter5, parameter6, nullptr
                    );
                }
            } else {
                const FVector relativePosition = m_RelPos;
                const std::uint32_t skillLevel =
                    (static_cast<std::uint32_t>(skill->m_nSubLevel) << 16U) | static_cast<std::uint16_t>(skill->m_nLevel);
                invisibleSocket->Send(
                    "chddddddddddddhh", 0xfe, 0x74, 0, runtime::Int32FromBits(m_nId),
                    runtime::Int32FromBits(target->m_nId), skill->m_nSkillId, runtime::Int32FromBits(skillLevel),
                    parameter2, parameter3, reuseDelay, runtime::Win64CvttDoubleToInt32(relativePosition.x),
                    runtime::Win64CvttDoubleToInt32(relativePosition.y),
                    runtime::Win64CvttDoubleToInt32(relativePosition.z), static_cast<int>(GetMyAirShipID()), 0, 0
                );
            }
        }
    }

    const bool activated = skill->ActivateSkill(this, target, 0.0, nullptr, CSkillInfo::EAT_SUCCESS, false);
    if (magicTrace) {
        // std::fprintf(
        //     stderr,
        //     "[MAGIC_TRACE] user-without-action-complete sid=%u skill=%d "
        //     "target=%u consume-mp=%d reuse=%d activated=%d\n",
        //     Id(),
        //     skillId,
        //     target != nullptr ? target->Id() : 0,
        //     consumeMp,
        //     reuseDelay,
        //     activated ? 1 : 0)
        // runtime::logging::WriteDirect(
        //     stderr, "l2server", runtime::logging::Level::Info,
        //     "[magic trace] Finished immediate skill path for object %u, skill %d, target %u: consumed MP %d, reuse delay
        //     value %d, activation result %s.", Id(), skillId, target != nullptr ? target->Id() : 0, consumeMp, reuseDelay,
        //     activated ? "yes" : "no")
        L2_LOG_DIRECT(
            stderr, runtime::logging::Level::Info,
            "[magic trace] Finished immediate skill path for object %u, skill %d, target %u: consumed MP %d, reuse delay "
            "value %d, activation result %s.",
            Id(), skillId, target != nullptr ? target->Id() : 0, consumeMp, reuseDelay, activated ? "yes" : "no"
        );
        // std::fflush(stderr), // WriteDirect flushes the complete record.
    }
    return false;
}

bool User::OnPledgeCrest(const std::uint32_t crestId, const std::uint32_t pledgeSid) {
    // Current L2Server 0x00b46964.
    L2_GUARD_FUNCTION();

    CPledge* const pledge = CPledge::GetObjectW(pledgeSid);
    if (pledge == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"OnPledgeCrest::Can not Find Pledge "
        //     L"PledgeSid[%d]",
        //     pledgeSid)
        L2_LOG_ERROR(Log, u"[pledge crest] Cannot find pledge runtime ID %u for crest %u.", pledgeSid, crestId);
        return false;
    }

    const std::uint32_t worldId = static_cast<std::uint32_t>(pledge->GetWorldId());
    CPledgeCrestSP crest =
        g_PledgeCrestMap.FindObject(CPledgeCrestKey(static_cast<int>(worldId), static_cast<int>(crestId)));
    if (!crest) {
        if (crestId < 2000000U) {
            db.RequestGetPledgeCrest(this, crestId, worldId);
        } else {
            const int random = ::LegacyCrtRand();
            if (random == (random / 10) * 10) {
                // Log.Add(
                //     LOG_ERROR,
                //     L"OnPledgeCrest Error crest_id[%d], "
                //     L"db_crest[%d], db_pledge[%d]",
                //     crestId,
                //     m_nPledgeCrestDbId,
                //     m_data->m_nPledgeID)
                L2_LOG_ERROR(
                    Log,
                    u"[pledge crest] Crest %u is outside the database range; character stores crest DB ID %d and pledge DB "
                    u"ID %d.",
                    crestId, m_nPledgeCrestDbId, m_data->m_nPledgeID
                );
            }
            GetSocket()->Send("cddd", 0x6a, worldId, crestId, 0);
        }
    } else {
        const int bitmapSize = crest->bitmapSize();
        GetSocket()->SafeSend(0x80000, "cdddb", 0x6a, worldId, crestId, bitmapSize, bitmapSize, crest->bitmap());
    }
    return false;
}

bool User::OnDuelAskStart(const wchar_t* targetName, const DuelType duelType) {
    // Current L2Server 0x00b45544.
    L2_GUARD_FUNCTION();

    if (static_cast<std::uint32_t>(duelType) > static_cast<std::uint32_t>(DT_PARTY)) {
        return false;
    }

    CParty* const requesterParty = GetParty();
    if (requesterParty != nullptr && requesterParty->IsLootingTypeModifyInProgress()) {
        SendSystemMessage(SystemMessageId::CANNOT_MAKE_ONE_TO_ONE_REQUEST_DURING_PARTY_LOOT_CHANGE);
        return false;
    }

    std::array<SharedUtilsWideChar, 25> loweredName{};
#if defined(_WIN32)
    static_assert(sizeof(wchar_t) == sizeof(SharedUtilsWideChar));
    ToLowerCase(reinterpret_cast<const SharedUtilsWideChar*>(targetName), loweredName.data());
    wchar_t* const lookupName = reinterpret_cast<wchar_t*>(loweredName.data());
#else
    const std::u16string targetNameUtf16 = WideToUtf16(targetName);
    ToLowerCase(targetNameUtf16.c_str(), loweredName.data());
    std::wstring lookupNameStorage = Utf16ToWide(reinterpret_cast<const char16_t*>(loweredName.data()));
    wchar_t* const lookupName = lookupNameStorage.data();
#endif

    CSPointer<User> targetReference = GetUserFromNameMap(m_data->GetWorldId(), WideToUtf16(lookupName));
    User* duelTarget = targetReference.get();
    if (duelTarget == nullptr || !duelTarget->IsPC()) {
        GetSocket()->SendSystemMessage(SystemMessageId::NO_DUEL_CHALLENGE_TARGET);
        return false;
    }

    CParty* const targetParty = duelTarget->GetParty();
    if (targetParty != nullptr && targetParty->IsLootingTypeModifyInProgress()) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::CHARACTER_CHANGING_PARTY_LOOT, duelTarget->GetName());
        return false;
    }

    if (m_data->m_bGMInvisible || duelTarget->m_data->m_bGMInvisible) {
        GetSocket()->SendSystemMessage(SystemMessageId::NO_DUEL_CHALLENGE_TARGET);
        return false;
    }

    if (!IsTalkableDistance(duelTarget)) {
        GetSocket()->Send(
            "chccS", 0x62, SystemMessageId::CHARACTER_TOO_FAR_FOR_DUEL_CHALLENGE, 1, 0x0c,
            duelTarget->CastUser()->GetName2(this)
        );
        return false;
    }

    if (IsInAirShip()) {
        GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_ACT_WHILE_ABOARD);
        return false;
    }
    if (duelTarget->IsInAirShip()) {
        return false;
    }

    if (duelType == DT_PARTY) {
        if (targetParty == nullptr) {
            GetSocket()->SendSystemMessage(SystemMessageId::CANNOT_REQUEST_DUEL_CONDITIONS_NOT_MET);
            return false;
        }
        if (targetParty->IsAnyOneIsInAirShip()) {
            return false;
        }
        duelTarget = targetParty->GetMaster();
    }

    if (!CDuelManager::inst().CheckDuelStartCondition(this, duelTarget, duelType)) {
        return false;
    }

    if (CReplyChecker::IsUserWaitingReply(this)) {
        GetSocket()->SendSystemMessage(SystemMessageId::WAITING_FOR_ANOTHER_OPERATION_REPLY);
        return false;
    }

    if (!CReplyChecker::AttachReplyChecker(0x0b, this, duelTarget, 0x3c)) {
        GetSocket()->Send(
            "chccS", 0x62, SystemMessageId::INVITED_CHARACTER_BUSY, 1, 0x0c, duelTarget->CastUser()->GetName2(this)
        );
        return false;
    }

    duelTarget->GetSocket()->Send("chSd", 0xfe, 0x4d, GetName(), duelType);
    if (duelType == DT_INDIVIDUAL) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::DUEL_CHALLENGE_SENT_TO_CHARACTER, duelTarget->GetName());
    } else if (duelType == DT_PARTY) {
        GetSocket()->SendSystemMessage_S(SystemMessageId::PARTY_DUEL_CHALLENGE_SENT, duelTarget->GetName());
    }

    const int z = runtime::Win64CvttDoubleToInt32(GetPos().z);
    const int y = runtime::Win64CvttDoubleToInt32(GetPos().y);
    const int x = runtime::Win64CvttDoubleToInt32(GetPos().x);
    const char16_t* const targetLogName = duelTarget->GetName();
    const char16_t* const requesterName = GetName();
    const std::uint32_t targetAccountId = duelTarget->GetAccountID();
    const std::uint32_t targetDbId = duelTarget->GetDBID();
    const std::uint32_t requesterAccountId = GetAccountID();
    const std::uint32_t requesterDbId = GetDBID();
    std::array<wchar_t, 16> requesterAccountStorage{};
    std::array<wchar_t, 16> targetAccountStorage{};
    // Log.AddT(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,,,,,,,,,,%s,%s,%s,%s,",
    //     0x374,
    //     requesterDbId,
    //     requesterAccountId,
    //     targetDbId,
    //     targetAccountId,
    //     x,
    //     y,
    //     z,
    //     duelType,
    //     requesterName,
    //     PrivateStoreAccountName(
    //         m_sAccountName,
    //         requesterAccountStorage),
    //     targetLogName,
    //     PrivateStoreAccountName(
    //         duelTarget->m_sAccountName,
    //         targetAccountStorage))
    Log.AddT(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        u"%I64d,,,,,,,,,,%s,%s,%s,%s,",
        0x374, requesterDbId, requesterAccountId, targetDbId, targetAccountId, x, y, z, duelType, requesterName,
        PrivateStoreAccountName(m_sAccountName, requesterAccountStorage), targetLogName,
        PrivateStoreAccountName(duelTarget->m_sAccountName, targetAccountStorage)
    );
    return false;
}

bool User::VoteSociality(const int targetServerId) {
    // Current L2Server 0x00b4c088. Direct User-only dependency of
    // User::OnVoteSocialityPacket@0x00b4cd10.
    L2_GUARD_FUNCTION();

    const CSPointer<User> targetReference = g_UserMap.FindObject(targetServerId);
    User* const target = targetReference.get();
    if (target == nullptr) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] Cannot find Socaility vote target. "
        //     L"vote char [%d], target server id[%d]",
        //     "User.cpp",
        //     0x3299,
        //     GetDBID(),
        //     targetServerId)
        L2_LOG_ERROR(Log, u"[sociality] Character %d selected missing vote target object %d.", GetDBID(), targetServerId);
        return false;
    }

    CheckSocailityFaint();
    target->CheckSocailityFaint();

    const bool voted = [&] {
        L2_GUARD(*m_lock);
        if (std::find(m_vUsedVoteTarget.begin(), m_vUsedVoteTarget.end(), targetServerId) != m_vUsedVoteTarget.end()) {
            SendSystemMessage(SystemMessageId::CHARACTER_ALREADY_RECOMMENDED);
            return false;
        }

        if (GetRemainSulffrageCount() < 1) {
            SendSystemMessage(
                m_data->m_nLevel > 9 ? SystemMessageId::RECOMMENDATIONS_EXHAUSTED_DAILY_RESET_NOTICE
                                     : SystemMessageId::RECOMMENDING_REQUIRES_LEVEL_TEN
            );
            return false;
        }
        if (target->GetSocialityCount() < 0) {
            return false;
        }
        if (!target->IncSociality()) {
            SendSystemMessage(SystemMessageId::TARGET_CANNOT_RECEIVE_MORE_RECOMMENDATIONS);
            return false;
        }

        m_data->m_nSulffrageUsedCount =
            runtime::Int16FromBits(static_cast<std::uint16_t>(m_data->m_nSulffrageUsedCount) + std::uint16_t{1});
        m_vUsedVoteTarget.push_back(targetServerId);

        return true;
    }();
    if (!voted) {
        return false;
    }

    db.RequestUpdateSociality(*target, static_cast<int>(target->m_data->m_nSulffrageUsedCount), &m_tmLastSocialityCheck);
    db.RequestUpdateSociality(*this, static_cast<int>(m_data->m_nSulffrageUsedCount), &m_tmLastSocialityCheck);

    const FVector position = GetPos();
    const int x = runtime::Win64CvttDoubleToInt32(position.x);
    const int y = runtime::Win64CvttDoubleToInt32(position.y);
    const int z = runtime::Win64CvttDoubleToInt32(position.z);
    std::array<wchar_t, 16> voterAccountStorage{};
    std::array<wchar_t, 16> targetAccountStorage{};

    // Log.AddT(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,%s,%s,%s,%s,",
    //     0x349,
    //     GetDBID(),
    //     GetAccountID(),
    //     target->GetDBID(),
    //     target->GetAccountID(),
    //     x,
    //     y,
    //     z,
    //     m_data->m_Race,
    //     m_data->m_Sex,
    //     m_data->m_nClass,
    //     m_data->m_nLevel,
    //     GetRemainSulffrageCount(),
    //     GetName(),
    //     PrivateStoreAccountName(
    //         m_sAccountName,
    //         voterAccountStorage),
    //     target->GetName(),
    //     PrivateStoreAccountName(
    //         target->m_sAccountName,
    //         targetAccountStorage))
    Log.AddT(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        u"%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,%s,%s,%s,%s,",
        0x349, GetDBID(), GetAccountID(), target->GetDBID(), target->GetAccountID(), x, y, z, m_data->m_Race, m_data->m_Sex,
        m_data->m_nClass, m_data->m_nLevel, GetRemainSulffrageCount(), GetName(),
        PrivateStoreAccountName(m_sAccountName, voterAccountStorage), target->GetName(),
        PrivateStoreAccountName(target->m_sAccountName, targetAccountStorage)
    );

    // Log.AddT(
    //     LOG_BOTH,
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
    //     L"%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,%s,%s,%s,%s,",
    //     0x34a,
    //     target->GetDBID(),
    //     target->GetAccountID(),
    //     GetDBID(),
    //     GetAccountID(),
    //     x,
    //     y,
    //     z,
    //     target->m_data->m_Race,
    //     target->m_data->m_Sex,
    //     target->m_data->m_nClass,
    //     target->m_data->m_nLevel,
    //     target->GetSocialityCount(),
    //     target->GetName(),
    //     PrivateStoreAccountName(
    //         target->m_sAccountName,
    //         targetAccountStorage),
    //     GetName(),
    //     PrivateStoreAccountName(
    //         m_sAccountName,
    //         voterAccountStorage))
    Log.AddT(
        LOG_BOTH,
        u"%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,%I64d,,,,"
        u"%I64d,%I64d,%I64d,%I64d,%I64d,,,,,,%s,%s,%s,%s,",
        0x34a, target->GetDBID(), target->GetAccountID(), GetDBID(), GetAccountID(), x, y, z, target->m_data->m_Race,
        target->m_data->m_Sex, target->m_data->m_nClass, target->m_data->m_nLevel, target->GetSocialityCount(),
        target->GetName(), PrivateStoreAccountName(target->m_sAccountName, targetAccountStorage), GetName(),
        PrivateStoreAccountName(m_sAccountName, voterAccountStorage)
    );

    target->GetSocket()->SendSystemMessage_S(SystemMessageId::RECOMMENDATION_RECEIVED_FROM_CHARACTER, GetName2(target));
    GetSocket()->Send(
        "chccScc", 0x62, SystemMessageId::CHARACTER_RECOMMENDED_WITH_RECOMMENDATIONS_REMAINING, 2, 0x0c,
        target->CastUser()->GetName2(this), 0x14, static_cast<int>(static_cast<std::int8_t>(GetRemainSulffrageCount()))
    );
    runtime::raw_atomic::CompareExchangeI32(&m_nRelationChanged, 1, 0);
    return true;
}

bool User::OnVoteSocialityPacket(const int targetServerId) {
    // Current L2Server 0x00b4cd10.
    L2_GUARD_FUNCTION();

    if (m_PledgeGameUser.IsPlayer()) {
        return false;
    }

    const CSPointer<User> target = g_UserMap.FindObject(targetServerId);
    if (!target) {
        SendSystemMessage(SystemMessageId::INCORRECT_TARGET);
        return false;
    }
    const unsigned int voterDbId = GetDBID();
    const unsigned int targetDbId = target->GetDBID();
    if (targetDbId == voterDbId) {
        SendSystemMessage(SystemMessageId::CANNOT_RECOMMEND_SELF);
        return false;
    }
    if (GetRemainSulffrageCount() < 1) {
        SendSystemMessage(
            m_data->m_nLevel < 10 ? SystemMessageId::RECOMMENDING_REQUIRES_LEVEL_TEN
                                  : SystemMessageId::RECOMMENDATIONS_EXHAUSTED_DAILY_RESET_NOTICE
        );
        return false;
    }

    VoteSociality(targetServerId);
    return false;
}

